window.WORD_AI_EXAMPLE_LIBRARY = {"source":"DeepSeek one-time offline generation with a separate review pass","model":"deepseek-v4-pro","generatedAt":"2026-08-08T14:01:30.204726+00:00","entries":{"pace":{"examples":[{"sentence":"Although the team worked at a rapid pace, they still failed to meet the deadline because of unforeseen technical issues.","translation":"尽管团队以快速节奏工作，但由于不可预见的技术问题，他们仍未能按时完成。"},{"sentence":"The pace of urbanization in developing countries often outstrips the capacity of infrastructure, which leads to congestion and pollution.","translation":"发展中国家城市化的速度常常超过基础设施的承载能力，从而导致拥堵和污染。"},{"sentence":"When students maintain a consistent study pace, they are more likely to retain information and avoid burnout.","translation":"当学生保持稳定的学习节奏时，他们更有可能记住信息并避免倦怠。"},{"sentence":"Because the economy is growing at a sluggish pace, policymakers are considering stimulus measures to boost demand.","translation":"由于经济增长缓慢，政策制定者正在考虑刺激措施以提振需求。"},{"sentence":"To ensure sustainable development, cities must manage the pace of expansion while preserving green spaces.","translation":"为确保可持续发展，城市必须在保护绿地的同时控制扩张的速度。"}]},"beef":{"examples":[{"sentence":"Although beef is a staple in many diets, its production generates significant greenhouse gas emissions.","translation":"尽管牛肉是许多饮食中的主食，但其生产会产生大量温室气体排放。"},{"sentence":"Because grass-fed beef contains higher levels of omega-3 fatty acids, it is often marketed as a healthier option.","translation":"由于草饲牛肉含有更高水平的欧米伽-3脂肪酸，它常被宣传为更健康的选择。"},{"sentence":"The restaurant decided to source its beef from local farms, thereby supporting the regional economy.","translation":"该餐厅决定从当地农场采购牛肉，从而支持了地区经济。"},{"sentence":"While beef consumption is declining in some Western countries, it is rising rapidly in emerging markets.","translation":"尽管牛肉消费在一些西方国家正在下降，但在新兴市场却迅速增长。"},{"sentence":"To ensure food safety, the government has implemented a traceability system for all beef products.","translation":"为了确保食品安全，政府已对所有牛肉产品实施了可追溯系统。"}]},"elite":{"examples":[{"sentence":"Although the political elite often resist reform, public pressure can compel them to enact progressive policies.","translation":"尽管政治精英常常抵制改革，但公众压力可以迫使他们制定进步政策。"},{"sentence":"Because elite athletes undergo rigorous training from a young age, they often sacrifice normal childhood experiences.","translation":"由于精英运动员从小接受严格训练，他们常常牺牲正常的童年经历。"},{"sentence":"The academic elite are expected to contribute to public discourse, which helps bridge the gap between research and society.","translation":"学术精英被期望为公共讨论做出贡献，这有助于弥合研究与社会之间的鸿沟。"},{"sentence":"While elite universities provide exceptional resources, they can also perpetuate social stratification through selective admissions.","translation":"尽管精英大学提供了卓越的资源，但它们也可能通过选择性录取延续社会分层。"},{"sentence":"The business elite often influence government policy through lobbying, thereby shaping regulations to their advantage.","translation":"商业精英经常通过游说影响政府政策，从而使法规对他们有利。"}]},"local":{"examples":[{"sentence":"Although local traditions are often overshadowed by globalization, they remain vital for preserving cultural identity.","translation":"尽管地方传统常常被全球化所掩盖，但它们对于保护文化认同仍然至关重要。"},{"sentence":"Because local businesses create jobs and retain wealth within the community, supporting them is essential for sustainable development.","translation":"由于本地企业创造就业机会并将财富留在社区内，支持它们对于可持续发展至关重要。"},{"sentence":"The local government introduced a recycling program, which significantly reduced the amount of waste sent to landfills.","translation":"当地政府推出了一项回收计划，这显著减少了送往垃圾填埋场的废物量。"},{"sentence":"While local news outlets struggle to compete with national media, they provide crucial coverage of community issues.","translation":"尽管地方新闻媒体难以与全国性媒体竞争，但它们提供了对社区问题的重要报道。"},{"sentence":"To ensure public safety, the local council installed additional streetlights in high-crime areas.","translation":"为了确保公共安全，地方议会在高犯罪率地区安装了额外的路灯。"}]},"dull":{"examples":[{"sentence":"Although the lecture was dull, the professor's occasional anecdotes provided brief moments of engagement.","translation":"尽管讲座很无趣，教授偶尔的轶事提供了短暂的专注时刻。"},{"sentence":"A dull blade not only makes cutting difficult but also increases the risk of injury, which is why chefs sharpen their knives daily.","translation":"钝刀不仅使切割困难，还增加受伤风险，这就是厨师每天磨刀的原因。"},{"sentence":"Because the novel's dull beginning failed to capture readers' interest, many abandoned it before reaching the compelling later chapters.","translation":"由于小说无趣的开头未能吸引读者，许多人在读到引人入胜的后几章之前就放弃了。"},{"sentence":"The overcast sky cast a dull light over the landscape, which muted the vibrant colors of the autumn leaves.","translation":"阴沉的天空给风景投下阴暗的光线，使秋叶的鲜艳色彩变得暗淡。"},{"sentence":"When students are forced to memorize facts without context, their natural curiosity can become dull, thereby stifling intellectual growth.","translation":"当学生被迫脱离语境死记硬背时，他们天生的好奇心会变得迟钝，从而抑制智力发展。"}]},"reproach":{"examples":[{"sentence":"Although the manager's reproach was delivered privately, it prompted the team to revise their strategy before the deadline.","translation":"尽管经理的责备是私下进行的，但它促使团队在截止日期前修改了策略。"},{"sentence":"The scientist faced widespread reproach because he had manipulated data to support his hypothesis.","translation":"这位科学家面临广泛的责备，因为他篡改数据以支持自己的假设。"},{"sentence":"While the reproach from her mentor stung, it ultimately guided her toward a more rigorous research methodology.","translation":"虽然导师的责备让她难受，但最终引导她采用了更严谨的研究方法。"},{"sentence":"The company's failure to address safety concerns brought reproach upon its leadership, which damaged investor confidence.","translation":"公司未能解决安全问题给其领导层带来了耻辱，这损害了投资者的信心。"},{"sentence":"Through his reproach of the outdated policy, the activist inspired a movement that demanded legislative reform.","translation":"通过对过时政策的责备，这位活动家激发了一场要求立法改革的运动。"}]},"evade":{"examples":[{"sentence":"Because the suspect attempted to evade capture by crossing the border, the authorities issued an international warrant.","translation":"由于嫌疑人试图通过越境来逃脱抓捕，当局发布了国际通缉令。"},{"sentence":"The corporation used offshore accounts to evade taxes, thereby depriving the government of essential revenue for public services.","translation":"该公司利用离岸账户逃避税收，从而使政府失去了用于公共服务的基本收入。"},{"sentence":"When journalists asked about the scandal, the spokesperson tried to evade the question by discussing unrelated achievements.","translation":"当记者问及丑闻时，发言人试图通过讨论无关的成就来规避问题。"},{"sentence":"To evade the heavy traffic, commuters increasingly rely on real-time navigation apps that suggest alternative routes.","translation":"为了避开交通拥堵，通勤者越来越依赖实时导航应用来推荐替代路线。"},{"sentence":"The new regulations aim to close loopholes that allow financial institutions to evade oversight and engage in risky behavior.","translation":"新法规旨在堵住允许金融机构逃避监管并从事高风险行为的漏洞。"}]},"glory":{"examples":[{"sentence":"Although the team sought glory in the championship, their true achievement lay in the unity they built.","translation":"尽管这支队伍在锦标赛中追求荣耀，但他们真正的成就在于建立的团结。"},{"sentence":"The ancient civilization, which once basked in glory, left behind architectural wonders that still inspire awe.","translation":"这个曾经沐浴在荣耀中的古代文明留下了至今仍令人敬畏的建筑奇迹。"},{"sentence":"Because the artist valued creative expression over commercial glory, her work remained authentic and influential.","translation":"由于这位艺术家重视创造性表达而非商业荣耀，她的作品保持了真实性和影响力。"},{"sentence":"The restoration project not only revived the cathedral's former glory but also strengthened the community's cultural identity.","translation":"修复工程不仅恢复了这座大教堂昔日的辉煌，还增强了社区的文化认同感。"},{"sentence":"While personal glory can be fleeting, the impact of selfless service endures through generations.","translation":"虽然个人荣耀可能转瞬即逝，但无私服务的影响却能代代相传。"}]},"lick":{"examples":[{"sentence":"The child gave the lollipop a slow lick, savoring the sweetness while watching the parade pass by.","translation":"孩子慢慢舔着棒棒糖，一边品味甜味，一边看着游行队伍经过。"},{"sentence":"With a quick lick of the envelope, she sealed the letter that contained her university application.","translation":"她迅速舔了一下信封，封好了那封包含大学申请的信。"},{"sentence":"The cat's gentle lick on the kitten's fur not only cleaned it but also strengthened their bond.","translation":"母猫轻轻舔着小猫的毛，不仅清洁了它，还加强了它们之间的纽带。"},{"sentence":"Although a single lick of paint cannot fix the wall, it is the first step toward a complete renovation.","translation":"尽管一笔涂料不能修好墙壁，但这是全面翻新的第一步。"},{"sentence":"The chef added a lick of honey to the sauce, which balanced the acidity and enhanced the dish's flavor.","translation":"厨师在酱汁中加入少许蜂蜜，这平衡了酸度并提升了菜肴的风味。"}]},"courtesy":{"examples":[{"sentence":"Although the interview was highly competitive, the panel treated every candidate with professional courtesy.","translation":"尽管面试竞争非常激烈，评审小组仍以专业的礼貌对待每一位候选人。"},{"sentence":"Because the professor extended the courtesy of a detailed feedback session, the student was able to significantly improve the thesis.","translation":"因为教授给予了详细反馈的礼遇，学生得以显著改进论文。"},{"sentence":"While digital communication often lacks nuance, a simple courtesy such as acknowledging receipt of an email can prevent misunderstandings.","translation":"虽然数字通信往往缺乏细微之处，但像确认收到邮件这样的简单礼貌可以避免误解。"},{"sentence":"The conference organizers provided simultaneous interpretation as a courtesy to international attendees, thereby fostering inclusive dialogue.","translation":"会议组织者提供同声传译作为对国际与会者的礼遇，从而促进了包容性对话。"},{"sentence":"If researchers do not observe the courtesy of obtaining informed consent, their study risks ethical and legal repercussions.","translation":"如果研究人员不遵守获取知情同意的礼节，他们的研究可能面临伦理和法律后果。"}]},"torture":{"examples":[{"sentence":"Because the testimony was obtained under torture, the court deemed it inadmissible as evidence.","translation":"由于证词是通过酷刑获取的，法庭裁定其不可作为证据采纳。"},{"sentence":"Although the regime officially banned torture, human rights groups documented its continued use in secret detention centers.","translation":"尽管该政权正式禁止酷刑，人权组织记录到其在秘密拘留中心仍被继续使用。"},{"sentence":"The psychological torture of solitary confinement can cause lasting mental damage, which often goes unrecognized in legal systems.","translation":"单独监禁的心理折磨会造成持久的精神损害，而这在法律体系中往往未被认识到。"},{"sentence":"When survivors of torture seek asylum, they require specialized medical and psychological support to rebuild their lives.","translation":"当酷刑幸存者寻求庇护时，他们需要专门的医疗和心理支持来重建生活。"},{"sentence":"The memoir describes how the author endured physical torture without betraying his comrades, demonstrating extraordinary resilience.","translation":"这本回忆录描述了作者如何在不背叛同志的情况下忍受身体折磨，展现了非凡的韧性。"}]},"painting":{"examples":[{"sentence":"Because the painting was created during the artist's blue period, it conveys a profound sense of melancholy through its monochromatic palette.","translation":"由于这幅画创作于艺术家的蓝色时期，它通过单色调色板传达出深刻的忧郁感。"},{"sentence":"Although the painting appears abstract at first glance, a closer examination reveals subtle references to classical mythology.","translation":"尽管这幅画乍看之下很抽象，但仔细观察会发现其中对古典神话的微妙引用。"},{"sentence":"The art historian argued that the painting's use of chiaroscuro was revolutionary, which influenced generations of Baroque artists.","translation":"艺术史学家认为，这幅画对明暗对照法的运用是革命性的，这影响了几代巴洛克艺术家。"},{"sentence":"When the painting was loaned to the international exhibition, it was transported in a climate-controlled crate to ensure its preservation.","translation":"当这幅画被借给国际展览时，它被放置在恒温箱中运输以确保其保存。"},{"sentence":"The restoration of the ancient cave painting required not only chemical analysis but also a deep respect for its cultural significance.","translation":"修复这幅古代洞穴壁画不仅需要化学分析，还需要对其文化意义的深深尊重。"}]},"cloud":{"examples":[{"sentence":"A dark cloud on the horizon often signals that a storm is approaching, prompting sailors to secure their vessels.","translation":"地平线上的乌云常常预示着暴风雨即将来临，促使水手们加固船只。"},{"sentence":"The factory's emissions created a thick cloud of pollution that hung over the town for days.","translation":"工厂的排放物形成了一团浓厚的污染云，笼罩在小镇上空数日。"},{"sentence":"Although a cloud of uncertainty surrounds the new policy, experts believe it will ultimately benefit the economy.","translation":"尽管新政策笼罩着一团不确定性的疑云，但专家认为它最终将有利于经济。"},{"sentence":"When the cloud of dust settled after the demolition, the old building had been reduced to rubble.","translation":"当拆除后的尘埃云消散时，旧建筑已化为瓦砾。"},{"sentence":"Personal biases can cloud one's judgment, leading to decisions that are neither fair nor rational.","translation":"个人偏见会蒙蔽一个人的判断，导致既不公正也不理性的决定。"}]},"drunk":{"examples":[{"sentence":"Although he was drunk, he still managed to deliver a coherent speech that impressed the audience.","translation":"尽管他喝醉了，但他仍然发表了一篇条理清晰的演讲，给听众留下了深刻印象。"},{"sentence":"Because he was drunk, he failed to notice the warning signs and walked into a restricted area.","translation":"因为他喝醉了，所以没有注意到警示标志，走进了禁区。"},{"sentence":"The witness testified that the defendant was clearly drunk when he left the bar that night.","translation":"证人作证说，被告当晚离开酒吧时明显喝醉了。"},{"sentence":"Getting drunk at a company event can damage your professional reputation in ways that you might not anticipate.","translation":"在公司活动中喝醉可能会以你意想不到的方式损害你的职业声誉。"},{"sentence":"The study found that individuals who are drunk are more likely to engage in risky behavior, such as driving without a seatbelt.","translation":"研究发现，喝醉的人更有可能从事危险行为，比如不系安全带驾驶。"}]},"immediate":{"examples":[{"sentence":"The immediate consequence of the new regulation was a sharp decline in plastic waste, which pleased environmental groups.","translation":"新规定的直接后果是塑料垃圾急剧减少，这让环保组织感到高兴。"},{"sentence":"When the earthquake struck, the immediate priority was to evacuate the building rather than to retrieve personal belongings.","translation":"当地震发生时，当务之急是疏散大楼，而不是取回个人物品。"},{"sentence":"Although the medication provided immediate relief, the doctor warned that it was not a long-term solution.","translation":"尽管这种药物能立即缓解症状，但医生警告说这不是长期的解决办法。"},{"sentence":"The manager demanded an immediate explanation for the budget discrepancy, which had caused delays in the project.","translation":"经理要求立即解释预算差异，因为这导致了项目延误。"},{"sentence":"Because the threat was immediate, the security team acted without waiting for further instructions.","translation":"由于威胁迫在眉睫，安全团队没有等待进一步指示就采取了行动。"}]},"melody":{"examples":[{"sentence":"A simple melody can evoke profound emotions when it is paired with meaningful lyrics.","translation":"当简单的旋律与有意义的歌词结合时，可以唤起深刻的情感。"},{"sentence":"The composer crafted a haunting melody that lingers in the listener's mind long after the performance ends.","translation":"作曲家创作了一段萦绕心头的旋律，在演出结束后仍久久回荡在听众脑海中。"},{"sentence":"Because the melody is based on a traditional folk tune, it resonates deeply with audiences across generations.","translation":"由于这段旋律基于传统民谣，它能引起不同年代观众的深刻共鸣。"},{"sentence":"Although the melody is deceptively simple, its subtle variations reveal a sophisticated musical structure.","translation":"尽管这段旋律看似简单，但其微妙的变化揭示出复杂的音乐结构。"},{"sentence":"Researchers have found that a familiar melody can stimulate memory recall in patients with cognitive decline.","translation":"研究人员发现，熟悉的旋律可以刺激认知衰退患者的记忆回忆。"}]},"betray":{"examples":[{"sentence":"Although he swore loyalty, his decision to betray the organization for personal safety shocked everyone.","translation":"尽管他发誓忠诚，但他为了个人安全而背叛组织的决定震惊了所有人。"},{"sentence":"When a trusted official chooses to betray state secrets, national security is severely compromised.","translation":"当一位受信任的官员选择泄露国家机密时，国家安全受到严重损害。"},{"sentence":"Because his nervous laughter seemed to betray his guilt, the investigators pressed him further.","translation":"因为他紧张的笑声似乎暴露了他的内疚，调查人员进一步追问了他。"},{"sentence":"To betray the confidence of a close friend is to damage a relationship that may never fully recover.","translation":"背叛密友的信任就是损害一段可能永远无法完全恢复的关系。"},{"sentence":"Historical accounts reveal that those who betray their comrades for profit often face lifelong remorse.","translation":"历史记载表明，那些为了利益而背叛同志的人往往面临终生的悔恨。"}]},"kind":{"examples":[{"sentence":"This kind of collaborative research, which integrates multiple disciplines, often leads to groundbreaking discoveries.","translation":"这种整合多个学科的协作研究，往往能带来突破性的发现。"},{"sentence":"A community that embraces every kind of cultural diversity is more likely to thrive in a globalized world.","translation":"一个拥抱各种文化多样性的社区，更有可能在全球化世界中蓬勃发展。"},{"sentence":"Because this kind of educational approach emphasizes critical thinking, students become better problem solvers.","translation":"由于这种教育方法强调批判性思维，学生成为更好的问题解决者。"},{"sentence":"The kind of leadership that inspires trust and collaboration is essential for organizational success.","translation":"那种激发信任与合作的领导力，对于组织成功至关重要。"},{"sentence":"Although this kind of investment carries high risk, it can yield substantial returns if managed wisely.","translation":"尽管这种投资风险很高，但如果管理得当，可以带来可观的回报。"}]},"game":{"examples":[{"sentence":"Although the game was initially designed for entertainment, researchers later adapted it to study cooperative behavior.","translation":"尽管这款游戏最初是为娱乐而设计，但研究人员后来将其用于研究合作行为。"},{"sentence":"Because the game requires strategic thinking and rapid decision-making, it has been incorporated into leadership training programs.","translation":"由于该游戏需要战略思维和快速决策，它已被纳入领导力培训项目。"},{"sentence":"The game, which simulates real-world economic transactions, helps students understand market dynamics more intuitively.","translation":"这款模拟现实经济交易的游戏，帮助学生更直观地理解市场动态。"},{"sentence":"When the game introduced a new scoring system, participants became more motivated to collaborate rather than compete.","translation":"当游戏引入新的计分系统后，参与者更倾向于合作而非竞争。"},{"sentence":"The educational game not only reinforces vocabulary acquisition but also cultivates critical thinking through problem-solving tasks.","translation":"这款教育游戏不仅强化词汇习得，还通过解决问题的任务培养批判性思维。"}]},"fell":{"examples":[{"sentence":"Although the lumberjack managed to fell the towering pine with a single precise cut, the surrounding saplings remained unharmed.","translation":"尽管伐木工人用一次精准的砍伐就击倒了那棵高耸的松树，但周围的树苗却毫发无损。"},{"sentence":"Because the old oak posed a risk to the power lines during storms, the utility company decided to fell it before the hurricane season.","translation":"由于那棵老橡树在暴风雨中对电线构成威胁，电力公司决定在飓风季节前将其砍倒。"},{"sentence":"The forestry team used a coordinated approach to fell the diseased trees, thereby preventing the spread of the infestation to healthy areas.","translation":"林业团队采用协调一致的方法砍伐病树，从而防止了虫害向健康区域蔓延。"},{"sentence":"When the developers proposed to fell the ancient woodland for a shopping complex, environmentalists launched a campaign to protect the ecosystem.","translation":"当开发商提议砍伐这片古老林地以建造购物中心时，环保主义者发起了一场保护生态系统的运动。"},{"sentence":"The skilled carpenter demonstrated how to fell a tree safely, emphasizing that proper technique not only ensures efficiency but also minimizes accidents.","translation":"这位熟练的木匠演示了如何安全地砍倒一棵树，并强调正确的技术不仅能确保效率，还能最大限度地减少事故。"}]},"eyesight":{"examples":[{"sentence":"Because excessive screen time can strain eyesight, experts recommend following the 20-20-20 rule to reduce digital eye fatigue.","translation":"由于过度使用屏幕会使视力疲劳，专家建议遵循20-20-20规则以减轻数字眼疲劳。"},{"sentence":"Although his eyesight began to decline in his fifties, he maintained his reading habit by using large-print books and adequate lighting.","translation":"尽管他的视力在五十多岁时开始下降，但他通过使用大字版书籍和充足的照明来保持阅读习惯。"},{"sentence":"The study revealed that children who spend more time outdoors have better eyesight, which suggests that natural light plays a protective role.","translation":"研究表明，户外活动时间较长的儿童视力更好，这表明自然光起着保护作用。"},{"sentence":"Regular eye examinations are crucial for detecting conditions that can impair eyesight, such as glaucoma, before irreversible damage occurs.","translation":"定期眼科检查对于在发生不可逆损伤之前发现青光眼等可能损害视力的疾病至关重要。"},{"sentence":"While modern surgery can correct many eyesight problems, preventive care through a healthy lifestyle remains the most effective long-term strategy.","translation":"虽然现代手术可以矫正许多视力问题，但通过健康的生活方式进行预防性护理仍然是最有效的长期策略。"}]},"copyright":{"examples":[{"sentence":"Scholars who publish in open-access journals often retain copyright, which allows them to share their work freely with colleagues around the world.","translation":"在开放获取期刊上发表论文的学者通常保留版权，这使他们能够与世界各地的同事自由分享研究成果。"},{"sentence":"Because copyright law grants creators exclusive rights for a limited time, it provides an incentive for artists to produce original works.","translation":"由于版权法在有限时间内赋予创作者专有权利，它激励艺术家创作原创作品。"},{"sentence":"Although digital technology has made copying effortless, copyright remains essential for protecting the economic interests of content creators.","translation":"尽管数字技术使复制变得毫不费力，但版权对于保护内容创作者的经济利益仍然至关重要。"},{"sentence":"Educational institutions must navigate complex copyright regulations when they digitize library collections for remote learning.","translation":"教育机构在为远程学习数字化图书馆馆藏时，必须应对复杂的版权法规。"},{"sentence":"The court ruled that the defendant had infringed copyright by reproducing substantial portions of the novel without permission.","translation":"法院裁定，被告未经许可复制了小说的实质性部分，侵犯了版权。"}]},"destructive":{"examples":[{"sentence":"Although economic growth is necessary, it can become destructive when it ignores environmental sustainability.","translation":"尽管经济增长是必要的，但当它忽视环境可持续性时，就可能变得具有破坏性。"},{"sentence":"Because destructive criticism focuses on personal attacks rather than constructive feedback, it rarely leads to improvement.","translation":"由于破坏性的批评侧重于人身攻击而非建设性反馈，它很少能带来改进。"},{"sentence":"The invasive species proved destructive to the native ecosystem, which had evolved without natural predators for centuries.","translation":"这种入侵物种对本地生态系统具有破坏性，该系统几个世纪以来在没有天敌的情况下进化。"},{"sentence":"While some insects are beneficial, others have a destructive effect on crops, thereby threatening food security.","translation":"虽然有些昆虫是有益的，但其他昆虫对农作物有破坏性影响，从而威胁粮食安全。"},{"sentence":"To prevent destructive wildfires, forest managers use controlled burns, which reduce accumulated dry vegetation.","translation":"为了防止破坏性的野火，森林管理者使用计划烧除，这减少了积累的干燥植被。"}]},"participant":{"examples":[{"sentence":"Because each participant in the study signed a consent form, the researchers could ethically collect sensitive data.","translation":"由于研究中的每位参与者都签署了同意书，研究人员可以合乎道德地收集敏感数据。"},{"sentence":"As an active participant in the debate club, she honed her critical thinking skills, which later proved invaluable in law school.","translation":"作为辩论俱乐部的积极参与者，她磨练了批判性思维能力，这在后来的法学院中被证明是无价的。"},{"sentence":"The workshop required every participant to contribute a case study, thereby ensuring a diverse range of perspectives.","translation":"研讨会要求每位参与者贡献一个案例研究，从而确保了多样化的视角。"},{"sentence":"Although he was a reluctant participant at first, he gradually embraced the collaborative project and became a key contributor.","translation":"尽管起初他是不情愿的参与者，但他逐渐接受了这个合作项目，并成为关键贡献者。"},{"sentence":"A participant who withdraws from the trial without notifying the coordinator may compromise the validity of the results.","translation":"未通知协调员就退出试验的参与者可能会损害结果的有效性。"}]},"facility":{"examples":[{"sentence":"Although the new sports facility was expensive to build, it has significantly improved community health by encouraging regular exercise.","translation":"尽管新的体育设施造价高昂，但它通过鼓励定期锻炼显著改善了社区健康。"},{"sentence":"The laboratory's advanced imaging facility, which was donated by an alumnus, enables researchers to observe cellular processes in real time.","translation":"实验室的先进成像设备由一位校友捐赠，使研究人员能够实时观察细胞过程。"},{"sentence":"Because she demonstrated remarkable facility in learning new software, her manager assigned her to train the entire department.","translation":"因为她在学习新软件方面表现出非凡的灵巧，经理指派她培训整个部门。"},{"sentence":"The manufacturing facility operates under strict safety protocols to ensure that all workers are protected from potential hazards.","translation":"制造工厂按照严格的安全规程运作，以确保所有工人免受潜在危害。"},{"sentence":"While the old facility lacked modern equipment, the newly renovated center provides state-of-the-art resources for vocational training.","translation":"虽然旧设施缺乏现代设备，但新装修的中心为职业培训提供了最先进的资源。"}]},"elegant":{"examples":[{"sentence":"The mathematician proposed an elegant proof that simplified a decades-old problem, thereby earning widespread acclaim in the academic community.","translation":"这位数学家提出了一个巧妙的证明，简化了一个存在数十年的问题，从而在学术界赢得了广泛赞誉。"},{"sentence":"Although the dress was simple in design, its elegant cut and high-quality fabric made it stand out at the formal event.","translation":"尽管这条裙子设计简单，但其优雅的剪裁和高质量的面料使它在正式场合中脱颖而出。"},{"sentence":"The software's elegant user interface, which minimizes unnecessary steps, allows even novice users to complete complex tasks efficiently.","translation":"该软件简洁优雅的用户界面最大限度地减少了不必要的步骤，使新手用户也能高效完成复杂任务。"},{"sentence":"Because the author employs an elegant writing style that avoids jargon, her book appeals to both experts and general readers.","translation":"由于作者采用了一种避免使用术语的优美写作风格，她的书对专家和普通读者都有吸引力。"},{"sentence":"The engineer developed an elegant solution that reduced energy consumption by 30% while maintaining the machine's performance.","translation":"工程师开发了一个巧妙的解决方案，在保持机器性能的同时将能耗降低了30%。"}]},"crust":{"examples":[{"sentence":"Although the bread's crust was thick and hard, the inside remained soft and warm.","translation":"尽管面包的外皮又厚又硬，里面却依然柔软温暖。"},{"sentence":"Because a thick crust of ice had formed on the road, driving conditions became extremely hazardous.","translation":"因为路面上结了一层厚厚的冰壳，驾驶条件变得极其危险。"},{"sentence":"The Earth's crust, which is composed of several tectonic plates, constantly shifts and reshapes the continents.","translation":"地壳由多个构造板块组成，不断移动并重塑着大陆。"},{"sentence":"When the pie was finally served, its golden crust crackled invitingly under the fork.","translation":"当馅饼终于端上桌时，它金黄的外皮在叉子下发出诱人的脆响。"},{"sentence":"Without a protective crust, the soft lava beneath would rapidly cool and solidify.","translation":"如果没有一层保护性的硬壳，下面的软熔岩会迅速冷却并凝固。"}]},"rigid":{"examples":[{"sentence":"Because the material is extremely rigid, it is often used in the construction of aircraft frames.","translation":"由于这种材料极其坚硬，它常被用于制造飞机骨架。"},{"sentence":"Although the company's rigid hierarchy ensures order, it often stifles innovation and open communication.","translation":"尽管公司严格的等级制度确保了秩序，但它常常扼杀创新和开放沟通。"},{"sentence":"A rigid curriculum, which leaves no room for creative exploration, can demotivate even the most enthusiastic students.","translation":"刻板的课程设置没有给创造性探索留下空间，即使是最热情的学生也会失去动力。"},{"sentence":"When faced with a rigid deadline, the team worked overtime to ensure the project was completed on time.","translation":"面对严格的截止日期，团队加班加点以确保项目按时完成。"},{"sentence":"His rigid posture, while conveying confidence, also made him appear unapproachable to his colleagues.","translation":"他僵硬的姿势虽然传达出自信，但也让他在同事面前显得难以接近。"}]},"enter":{"examples":[{"sentence":"When students enter university, they must adapt to a more independent learning environment, which fosters critical thinking.","translation":"当学生进入大学时，他们必须适应更独立的学习环境，这能培养批判性思维。"},{"sentence":"Although the company plans to enter the Asian market, it must first navigate complex regulatory requirements.","translation":"尽管公司计划进入亚洲市场，但它必须首先应对复杂的监管要求。"},{"sentence":"To enter the medical profession, one must complete rigorous training and pass licensing exams, which ensure competence.","translation":"要进入医学行业，必须完成严格的培训并通过执照考试，这确保了能力。"},{"sentence":"Because data accuracy is crucial, analysts must double-check figures before they enter them into the database.","translation":"因为数据准确性至关重要，分析师在将数据输入数据库之前必须仔细核对。"},{"sentence":"As more women enter politics, policies increasingly reflect diverse perspectives, thereby improving governance.","translation":"随着更多女性进入政界，政策越来越反映多元视角，从而改善治理。"}]},"finite":{"examples":[{"sentence":"Because fossil fuels are a finite resource, governments must invest in renewable alternatives to ensure long-term energy security.","translation":"由于化石燃料是一种有限资源，政府必须投资于可再生替代能源以确保长期能源安全。"},{"sentence":"Although human knowledge is finite, the systematic application of the scientific method allows us to approach truth with increasing confidence.","translation":"尽管人类知识是有限的，但科学方法的系统应用使我们能够越来越自信地接近真理。"},{"sentence":"Managers should allocate the finite budget in a way that maximizes the overall benefit to the organization.","translation":"管理者应当以最大化组织整体效益的方式分配有限预算。"},{"sentence":"The study demonstrates that even a finite set of simple rules can generate remarkably complex patterns in biological systems.","translation":"该研究表明，即使是一组有限的简单规则也能在生物系统中产生极为复杂的模式。"},{"sentence":"Recognizing that attention is a finite cognitive resource helps educators design more effective learning activities.","translation":"认识到注意力是一种有限的认知资源，有助于教育者设计更有效的学习活动。"}]},"rubber":{"examples":[{"sentence":"Although synthetic rubber can be produced in laboratories, natural rubber remains indispensable for its unique elasticity.","translation":"尽管合成橡胶可以在实验室生产，天然橡胶因其独特的弹性仍然不可或缺。"},{"sentence":"The factory installed rubber flooring to reduce noise, which significantly improved the working environment.","translation":"工厂安装了橡胶地板以减少噪音，这显著改善了工作环境。"},{"sentence":"Because rubber is resistant to water and many chemicals, it is widely used in protective clothing.","translation":"由于橡胶耐水和多种化学品，它被广泛用于防护服。"},{"sentence":"When rubber is vulcanized, its strength and durability increase, making it suitable for demanding applications.","translation":"当橡胶被硫化时，其强度和耐久性提高，使其适用于要求苛刻的应用。"},{"sentence":"The demand for rubber gloves surged during the pandemic, thereby highlighting the material's critical role in healthcare.","translation":"疫情期间对橡胶手套的需求激增，从而凸显了该材料在医疗保健中的关键作用。"}]},"enormous":{"examples":[{"sentence":"Although the company faced enormous financial losses last quarter, its strategic restructuring plan helped it recover quickly.","translation":"尽管该公司上个季度面临巨大的财务损失，但其战略重组计划帮助它迅速恢复。"},{"sentence":"Because the construction of the new airport required an enormous amount of land, the government had to relocate thousands of residents.","translation":"由于新机场的建设需要大量土地，政府不得不重新安置数千名居民。"},{"sentence":"The enormous popularity of online education has transformed traditional teaching methods, which now increasingly incorporate digital tools.","translation":"在线教育的巨大普及已经改变了传统的教学方法，如今这些方法越来越多地融入数字工具。"},{"sentence":"While the benefits of artificial intelligence are enormous, we must also address the ethical concerns that arise from its widespread use.","translation":"虽然人工智能的好处是巨大的，但我们也必须解决因其广泛使用而产生的伦理问题。"},{"sentence":"The research team made an enormous breakthrough in cancer treatment, thereby offering new hope to patients worldwide.","translation":"研究团队在癌症治疗方面取得了巨大突破，从而为全世界的患者带来了新的希望。"}]},"camel":{"examples":[{"sentence":"Because a camel can survive for weeks without water, it remains an essential companion for travelers crossing the Sahara.","translation":"因为骆驼可以在没有水的情况下存活数周，它仍然是穿越撒哈拉的旅行者必不可少的伙伴。"},{"sentence":"Although the camel is often associated with arid deserts, it also thrives in the cold steppes of Central Asia.","translation":"尽管骆驼常与干旱沙漠联系在一起，但它在中亚寒冷的草原上也能茁壮成长。"},{"sentence":"The camel's thick eyelashes and closable nostrils protect it from sandstorms, which are common in its native habitat.","translation":"骆驼浓密的睫毛和可闭合的鼻孔保护它免受沙尘暴的侵袭，沙尘暴在其原生栖息地很常见。"},{"sentence":"While a camel can carry heavy loads over long distances, its pace is much slower than that of a horse.","translation":"虽然骆驼可以长距离搬运重物，但它的速度比马慢得多。"},{"sentence":"In many traditional societies, the camel is valued not only for transportation but also for its milk, which is highly nutritious.","translation":"在许多传统社会中，骆驼不仅因其运输能力而受到重视，还因其营养丰富的奶而受到珍视。"}]},"commonplace":{"examples":[{"sentence":"Although online shopping is now a commonplace, it has profoundly transformed consumer behavior and retail industries.","translation":"尽管网上购物如今已是寻常事，但它深刻地改变了消费者行为和零售业。"},{"sentence":"The use of artificial intelligence in daily life is becoming a commonplace, which raises important ethical questions.","translation":"人工智能在日常生活中的使用正变得司空见惯，这引发了重要的伦理问题。"},{"sentence":"That technology can both connect and isolate people is a commonplace, yet its psychological effects are still not fully understood.","translation":"技术既能连接人也能孤立人，这虽是老生常谈，但其心理影响仍未完全被理解。"},{"sentence":"While electric cars were once a novelty, they have become a commonplace in many cities due to environmental concerns.","translation":"尽管电动汽车曾经是新奇事物，但由于环境问题，它们已在许多城市变得司空见惯。"},{"sentence":"The idea that exercise improves mental health is a commonplace, but many people still struggle to incorporate it into their routines.","translation":"锻炼改善心理健康的观念虽是老生常谈，但许多人仍难以将其融入日常生活。"}]},"money":{"examples":[{"sentence":"Although money cannot buy happiness directly, it can provide access to resources that improve quality of life.","translation":"尽管金钱不能直接买到幸福，但它可以提供改善生活质量的资源。"},{"sentence":"Because the project lacked sufficient money, the team had to scale back its ambitious plans for expansion.","translation":"由于项目缺乏足够的资金，团队不得不缩减其雄心勃勃的扩张计划。"},{"sentence":"Effective allocation of public money is crucial for ensuring that essential services such as healthcare and education are maintained.","translation":"公共资金的有效分配对于确保医疗和教育等基本服务的维持至关重要。"},{"sentence":"While some people believe that money is the root of all evil, others argue that it is merely a tool whose impact depends on its use.","translation":"虽然有些人认为金钱是万恶之源，但其他人则认为它只是一种工具，其影响取决于如何使用。"},{"sentence":"The government invested a significant amount of money in renewable energy, thereby reducing the country's dependence on fossil fuels.","translation":"政府在可再生能源上投入了大量资金，从而减少了该国对化石燃料的依赖。"}]},"submit":{"examples":[{"sentence":"Before you submit your thesis, ensure that all citations conform to the required academic style guide.","translation":"在提交论文之前，请确保所有引用都符合要求的学术格式指南。"},{"sentence":"Although the deadline was tight, the team managed to submit a comprehensive grant proposal that secured funding for their research.","translation":"尽管截止日期很紧，团队还是设法提交了一份全面的资助申请，为他们的研究争取到了资金。"},{"sentence":"To participate in the conference, scholars must submit an abstract that clearly outlines their research question and methodology.","translation":"要参加会议，学者必须提交一份清晰概述其研究问题和方法的摘要。"},{"sentence":"The committee requires that all applicants submit their portfolios electronically, which streamlines the evaluation process.","translation":"委员会要求所有申请人以电子方式提交作品集，这简化了评估过程。"},{"sentence":"If you wish to appeal the decision, you must submit a written request within thirty days of receiving the notification.","translation":"如果你希望对决定提出上诉，必须在收到通知后三十天内提交书面请求。"}]},"puzzle":{"examples":[{"sentence":"Solving a complex puzzle requires both logical reasoning and creative thinking, which are essential skills in many professions.","translation":"解决复杂的谜题既需要逻辑推理，也需要创造性思维，这些是许多职业中必不可少的技能。"},{"sentence":"Although the puzzle seemed unsolvable at first, persistent effort eventually led to a breakthrough.","translation":"尽管这个谜题起初看似无解，但坚持不懈的努力最终带来了突破。"},{"sentence":"The origin of the universe remains a profound puzzle that scientists have yet to fully unravel.","translation":"宇宙的起源仍然是一个深奥的谜题，科学家尚未完全解开。"},{"sentence":"For many researchers, the puzzle of consciousness is one of the most challenging questions in neuroscience, because it involves subjective experience.","translation":"对许多研究者来说，意识的谜题是神经科学中最具挑战性的问题之一，因为它涉及主观体验。"},{"sentence":"The puzzle of how to balance economic growth with environmental protection demands innovative policy solutions, rather than simplistic approaches.","translation":"如何平衡经济增长与环境保护的难题需要创新的政策解决方案，而不是简单化的方法。"}]},"solitary":{"examples":[{"sentence":"A solitary walk in the park can provide a valuable opportunity for introspection, which is often neglected in busy modern life.","translation":"在公园里独自散步可以提供一个宝贵的机会进行内省，这在忙碌的现代生活中常常被忽视。"},{"sentence":"Although he enjoyed solitary activities, he also recognized the importance of social connections for emotional well-being.","translation":"尽管他喜欢独处的活动，但他也认识到社交联系对情感健康的重要性。"},{"sentence":"The solitary confinement of prisoners has been criticized for its severe psychological effects, which can include anxiety and depression.","translation":"囚犯的单独监禁因其严重的心理影响而受到批评，这些影响可能包括焦虑和抑郁。"},{"sentence":"In many species, solitary individuals may face greater risks from predators than those in groups, because they lack collective vigilance.","translation":"在许多物种中，独居个体可能比群居个体面临更大的捕食者风险，因为它们缺乏集体警惕性。"},{"sentence":"Her solitary research in the remote field station yielded groundbreaking insights, thereby advancing our understanding of the species.","translation":"她在偏远野外站进行的独自研究产生了突破性的见解，从而推进了我们对这一物种的理解。"}]},"fortune":{"examples":[{"sentence":"He amassed a fortune through strategic investments in technology startups, which yielded high returns.","translation":"他通过对科技初创公司的战略投资积累了一笔财富，这些投资带来了高回报。"},{"sentence":"The company's fortune declined sharply after the scandal, because consumers lost trust in its products.","translation":"丑闻发生后，公司的命运急剧下滑，因为消费者对其产品失去了信任。"},{"sentence":"A nation's fortune often depends on its educational system, which cultivates future innovators.","translation":"一个国家的命运往往取决于其教育体系，该体系培养未来的创新者。"},{"sentence":"She spent a small fortune on her graduate studies, believing that the degree would enhance her career prospects.","translation":"她在研究生学习上花了一大笔钱，相信这个学位会提升她的职业前景。"},{"sentence":"The fortune of the research team improved when they secured a major grant, which allowed them to expand their project.","translation":"研究团队的命运在获得一笔重大资助后得到了改善，这使他们能够扩展项目。"}]},"cruise":{"examples":[{"sentence":"The cruise industry must adopt sustainable practices, because its environmental impact has drawn increasing scrutiny.","translation":"邮轮行业必须采取可持续的做法，因为其环境影响已受到越来越多的审查。"},{"sentence":"A Mediterranean cruise offers a unique opportunity to explore ancient ruins, which are inaccessible by land.","translation":"地中海巡游提供了一个探索古代遗址的独特机会，这些遗址从陆路无法到达。"},{"sentence":"The research vessel embarked on a scientific cruise to collect samples from deep-sea vents, which host unique ecosystems.","translation":"科考船开始了科学巡航，从深海热液喷口收集样本，这些喷口孕育着独特的生态系统。"},{"sentence":"During the Antarctic cruise, passengers observed penguin colonies, which thrive in the harsh environment.","translation":"在南极巡游期间，乘客们观察了在恶劣环境中繁衍生息的企鹅群落。"},{"sentence":"The cruise missile's guidance system relies on satellite navigation, which ensures pinpoint accuracy.","translation":"巡航导弹的制导系统依赖于卫星导航，这确保了精确的命中率。"}]},"plot":{"examples":[{"sentence":"Although the plot of the film was complex, the director used flashbacks to ensure that the audience could follow the story.","translation":"尽管电影情节复杂，导演运用了闪回手法以确保观众能跟上故事。"},{"sentence":"The detective discovered a plot to steal confidential data, which involved several high-level employees.","translation":"侦探发现了一个窃取机密数据的阴谋，其中涉及几名高级员工。"},{"sentence":"Because the plot of land was located near a commercial district, its value increased significantly over the years.","translation":"因为这块土地靠近商业区，其价值多年来显著增长。"},{"sentence":"The scientist used a computer program to plot the trajectory of the asteroid, thereby predicting its closest approach to Earth.","translation":"科学家使用计算机程序绘制了小行星的轨迹，从而预测了它最接近地球的时刻。"},{"sentence":"A compelling plot not only entertains readers but also prompts them to reflect on moral dilemmas.","translation":"一个引人入胜的情节不仅娱乐读者，还促使他们反思道德困境。"}]},"hypocrisy":{"examples":[{"sentence":"Politicians who advocate for environmental protection while investing in polluting industries reveal a profound hypocrisy that undermines public trust.","translation":"那些一边倡导环境保护一边投资污染行业的政客，暴露了一种严重破坏公众信任的虚伪。"},{"sentence":"The hypocrisy of demanding transparency from others while concealing one's own mistakes often leads to a toxic organizational culture.","translation":"要求他人透明却隐瞒自身错误，这种虚伪往往会导致有害的组织文化。"},{"sentence":"When a company claims to value employee well-being yet ignores widespread burnout, its hypocrisy becomes evident through high turnover rates.","translation":"当一家公司声称重视员工福祉却忽视普遍的倦怠时，其虚伪便通过高离职率显现出来。"},{"sentence":"Although the charity's mission statement emphasized compassion, the director's lavish lifestyle exposed a glaring hypocrisy that alienated donors.","translation":"尽管该慈善机构的使命宣言强调同情心，但主管奢华的生活方式暴露了明显的虚伪，疏远了捐赠者。"},{"sentence":"In academic settings, the hypocrisy of promoting critical thinking while punishing dissent stifles intellectual growth and innovation.","translation":"在学术环境中，提倡批判性思维却惩罚异议的虚伪做法，会扼杀智力成长和创新。"}]},"descent":{"examples":[{"sentence":"Although the pilot initiated a controlled descent, the sudden loss of cabin pressure forced an emergency landing.","translation":"尽管飞行员启动了受控下降，但机舱压力的突然丧失迫使飞机紧急着陆。"},{"sentence":"Because she could trace her descent from a long line of scholars, she felt a deep responsibility to pursue academic excellence.","translation":"因为她能追溯到自己出身于一个学者世家，她深感有责任追求学术卓越。"},{"sentence":"The unexpected descent of a violent storm disrupted the outdoor ceremony, which had to be moved indoors at the last minute.","translation":"一场猛烈风暴的突然侵袭打乱了户外仪式，仪式不得不在最后一刻移至室内。"},{"sentence":"While researching his family history, he discovered a fascinating descent from a medieval knight, which inspired him to write a novel.","translation":"在研究家族史时，他发现了一位中世纪骑士的迷人血统，这激发了他写一部小说。"},{"sentence":"The mountaineers began their descent at dawn, using ropes to navigate the icy slope that had become dangerously slick overnight.","translation":"登山者在黎明时分开始下撤，利用绳索穿越因一夜之间变得异常光滑而危险的冰坡。"}]},"rash":{"examples":[{"sentence":"Because the manager made a rash promise to deliver the project early, the team had to work overtime for weeks.","translation":"由于经理轻率地承诺提前交付项目，团队不得不加班数周。"},{"sentence":"The child developed a red, bumpy rash after playing in the garden, which the doctor attributed to poison ivy exposure.","translation":"孩子在花园玩耍后身上起了红色凹凸皮疹，医生将其归因于接触了毒藤。"},{"sentence":"Although the investment seemed promising, his rash decision to put all his savings into it resulted in a devastating loss.","translation":"尽管这项投资看似前景光明，但他轻率地决定将所有积蓄投入其中，导致了毁灭性的损失。"},{"sentence":"A rash of burglaries in the neighborhood prompted residents to install security cameras, thereby deterring further crimes.","translation":"附近一连串的入室盗窃案促使居民安装监控摄像头，从而阻止了进一步的犯罪。"},{"sentence":"When she noticed a persistent rash on her hands, she consulted a dermatologist, who recommended a specialized cream.","translation":"当她注意到手上持续不退的皮疹时，她咨询了皮肤科医生，医生推荐了一种专用药膏。"}]},"postage":{"examples":[{"sentence":"Because the package exceeded the standard weight limit, the postage was significantly higher than expected.","translation":"由于包裹超过了标准重量限制，邮资比预期高得多。"},{"sentence":"The online store offers free postage on orders over fifty dollars, which encourages customers to buy more items.","translation":"这家网店对超过五十美元的订单提供免邮资，这鼓励顾客购买更多商品。"},{"sentence":"When sending the wedding invitations, she carefully calculated the postage to ensure that each envelope had sufficient stamps.","translation":"在寄送婚礼请柬时，她仔细计算了邮资，以确保每个信封都有足够的邮票。"},{"sentence":"Rising postage costs have led many companies to adopt electronic billing, thereby reducing their reliance on traditional mail.","translation":"不断上涨的邮资成本导致许多公司采用电子账单，从而减少了对传统邮件的依赖。"},{"sentence":"Although the book was inexpensive, the international postage made the total cost prohibitive for overseas buyers.","translation":"尽管这本书价格便宜，但国际邮资使得总成本对海外买家来说高得令人望而却步。"}]},"when":{"examples":[{"sentence":"When students engage in collaborative projects, they develop communication skills that are essential for future careers.","translation":"当学生参与合作项目时，他们会培养对未来职业至关重要的沟通技能。"},{"sentence":"The policy becomes effective when it receives approval from the regulatory committee.","translation":"该政策在获得监管委员会批准后生效。"},{"sentence":"When a society invests in renewable energy, it reduces its dependence on fossil fuels and mitigates environmental damage.","translation":"当一个社会投资于可再生能源时，它会减少对化石燃料的依赖并减轻环境破坏。"},{"sentence":"Researchers must exercise caution when interpreting data that may be influenced by external variables.","translation":"研究人员在解释可能受外部变量影响的数据时必须谨慎行事。"},{"sentence":"When individuals set clear goals, they are more likely to maintain motivation and achieve long-term success.","translation":"当个人设定明确的目标时，他们更有可能保持动力并取得长期成功。"}]},"clay":{"examples":[{"sentence":"Although clay is abundant in many regions, its quality varies significantly, which affects its suitability for pottery.","translation":"尽管黏土在许多地区都很丰富，但其质量差异很大，这影响了它是否适合制陶。"},{"sentence":"Because clay particles are extremely fine, they can form an impermeable layer that prevents water from draining properly.","translation":"由于黏土颗粒极其细小，它们能形成不透水层，从而阻碍水分正常排出。"},{"sentence":"When artists work with clay, they often rely on a potter's wheel to achieve symmetrical shapes that are difficult to create by hand.","translation":"当艺术家用黏土创作时，他们通常依靠陶轮来实现手工难以完成的对称形状。"},{"sentence":"The ancient civilization used clay tablets to record laws and transactions, which has provided historians with invaluable insights into their society.","translation":"这个古代文明使用黏土板记录法律和交易，这为历史学家提供了对其社会的宝贵见解。"},{"sentence":"Engineers often mix clay with other materials to enhance its strength, thereby creating durable bricks for construction.","translation":"工程师经常将黏土与其他材料混合以增强其强度，从而制造出耐用的建筑用砖。"}]},"push":{"examples":[{"sentence":"The government's push for digital transformation has led to significant improvements in public service efficiency, although it also raised concerns about data privacy.","translation":"政府对数字化转型的推动显著提高了公共服务效率，尽管也引发了数据隐私方面的担忧。"},{"sentence":"Despite the initial push to adopt renewable energy, the project faced setbacks because of inconsistent policy support and technological limitations.","translation":"尽管最初推动采用可再生能源，但由于政策支持不一致和技术限制，该项目遭遇了挫折。"},{"sentence":"A concerted push from environmental groups eventually persuaded the corporation to reduce its carbon emissions, which set a precedent for the industry.","translation":"环保团体的共同努力最终说服了该公司减少碳排放，这为行业树立了先例。"},{"sentence":"The final push before the election included a series of televised debates, which allowed candidates to clarify their positions on key issues.","translation":"选举前的最后冲刺包括一系列电视辩论，使候选人能够澄清他们在关键问题上的立场。"},{"sentence":"Historians argue that the push for industrialization in the 19th century often came at the expense of workers' rights, thereby sparking labor movements.","translation":"历史学家认为，19世纪对工业化的推动往往以牺牲工人权利为代价，从而引发了劳工运动。"}]},"hierarchy":{"examples":[{"sentence":"In many traditional organizations, a rigid hierarchy can slow down decision-making because every proposal must pass through multiple layers of approval.","translation":"在许多传统组织中，严格的等级制度会减慢决策速度，因为每个提案都必须经过多层审批。"},{"sentence":"Although a clear hierarchy provides structure, it may also discourage junior employees from sharing innovative ideas with senior management.","translation":"尽管清晰的等级制度提供了结构，但它也可能阻碍初级员工与高级管理层分享创新想法。"},{"sentence":"The hierarchy of needs proposed by Maslow suggests that individuals must satisfy basic physiological requirements before pursuing higher-level goals such as self-actualization.","translation":"马斯洛提出的需求层次理论表明，个体在追求自我实现等更高层次目标之前，必须先满足基本的生理需求。"},{"sentence":"To improve efficiency, the company flattened its hierarchy, enabling teams to collaborate more directly without waiting for managerial directives.","translation":"为了提高效率，公司扁平化了等级制度，使团队能够更直接地协作，而无需等待管理层的指令。"},{"sentence":"In academic research, the hierarchy of evidence places systematic reviews at the top because they synthesize findings from multiple rigorous studies.","translation":"在学术研究中，证据等级体系将系统综述置于顶端，因为它们综合了多项严谨研究的发现。"}]},"song":{"examples":[{"sentence":"The song that the choir performed at the ceremony moved many listeners to reflect on their own experiences.","translation":"合唱团在典礼上演唱的那首歌让许多听众反思自己的经历。"},{"sentence":"Because the song incorporates traditional instruments, it preserves cultural heritage while appealing to modern audiences.","translation":"由于这首歌融入了传统乐器，它在吸引现代听众的同时也保留了文化遗产。"},{"sentence":"Although the song was originally written for a film, it has since become an anthem for social movements worldwide.","translation":"尽管这首歌最初是为一部电影创作的，但它后来成为了全球社会运动的颂歌。"},{"sentence":"Researchers found that listening to a familiar song can significantly reduce stress by lowering cortisol levels.","translation":"研究人员发现，听一首熟悉的歌曲可以通过降低皮质醇水平来显著减轻压力。"},{"sentence":"The song, which blends folk melodies with electronic beats, demonstrates how artists can bridge generational divides.","translation":"这首融合了民谣旋律和电子节拍的歌曲，展示了艺术家如何弥合代际鸿沟。"}]},"misery":{"examples":[{"sentence":"Although the medication alleviated his physical pain, the emotional misery lingered for months after the accident.","translation":"尽管药物缓解了他的身体疼痛，但事故后的情感痛苦持续了数月。"},{"sentence":"The documentary exposed the misery of factory workers who endure hazardous conditions without adequate legal protection.","translation":"这部纪录片揭露了工厂工人的苦难，他们在没有足够法律保护的情况下忍受危险的工作条件。"},{"sentence":"Because the charity focused on alleviating the misery of homeless families, it gained widespread support from local businesses.","translation":"由于该慈善机构专注于减轻无家可归家庭的苦难，它获得了当地企业的广泛支持。"},{"sentence":"The novel portrays the protagonist's inner misery with such vivid detail that readers cannot help but empathize with her plight.","translation":"这部小说以如此生动的细节描绘了主人公内心的痛苦，以至于读者不禁同情她的困境。"},{"sentence":"While economic growth can reduce material misery, it often fails to address the psychological misery stemming from social isolation.","translation":"虽然经济增长可以减少物质上的贫困，但它往往无法解决源于社会孤立的心理痛苦。"}]},"democracy":{"examples":[{"sentence":"A functioning democracy depends on an educated citizenry that can critically evaluate competing policy proposals.","translation":"一个运转良好的民主制度依赖于能够批判性地评估不同政策提案的受过教育的公民群体。"},{"sentence":"Although democracy is often associated with majority rule, constitutional protections for minority rights are equally essential.","translation":"尽管民主常与多数统治联系在一起，但宪法对少数群体权利的保护同样至关重要。"},{"sentence":"The transition to democracy requires not only free elections but also the gradual development of independent institutions.","translation":"向民主的过渡不仅需要自由选举，还需要独立机构的逐步发展。"},{"sentence":"In a healthy democracy, public debate should be informed by evidence rather than shaped solely by partisan interests.","translation":"在一个健康的民主制度中，公共辩论应以证据为依据，而不是仅仅由党派利益所左右。"},{"sentence":"Because democracy grants citizens the power to choose their leaders, widespread political literacy becomes a fundamental necessity.","translation":"由于民主赋予公民选择领导人的权力，广泛的政治素养就成为了一项基本需求。"}]},"desirable":{"examples":[{"sentence":"Although a high salary is desirable, many professionals now prioritize work-life balance when choosing a career.","translation":"尽管高薪是令人向往的，但许多专业人士在选择职业时现在更看重工作与生活的平衡。"},{"sentence":"Because bilingual education fosters cognitive flexibility, it is a highly desirable component of modern school curricula.","translation":"由于双语教育能培养认知灵活性，它是现代学校课程中一个非常可取的组成部分。"},{"sentence":"While remote work offers desirable flexibility, it can blur the boundaries between professional and personal life.","translation":"虽然远程工作提供了令人向往的灵活性，但它可能模糊职业与个人生活之间的界限。"},{"sentence":"A desirable outcome of urban renewal projects is the creation of public spaces that encourage community interaction.","translation":"城市更新项目的一个可取成果是创造鼓励社区互动的公共空间。"},{"sentence":"If a policy is to be widely accepted, it must demonstrate desirable effects on both economic growth and social equity.","translation":"如果一项政策要被广泛接受，它必须展示出对经济增长和社会公平的可取效果。"}]},"speculate":{"examples":[{"sentence":"Although economists often speculate about future market trends, their predictions are frequently proven wrong by unforeseen events.","translation":"尽管经济学家经常推测未来的市场趋势，但他们的预测常常被不可预见的事件证明是错误的。"},{"sentence":"Rather than speculate on the cause of the failure, the team conducted a thorough analysis to identify the root problem.","translation":"团队没有去推测失败的原因，而是进行了彻底的分析以找出根本问题。"},{"sentence":"Because the evidence was inconclusive, the detective refused to speculate about the suspect's motive during the press conference.","translation":"由于证据不确凿，侦探拒绝在新闻发布会上推测嫌疑人的动机。"},{"sentence":"Some investors choose to speculate in volatile stocks, which can yield high returns but also carry substantial risk.","translation":"一些投资者选择在波动性股票中投机，这可以带来高回报，但也伴随着巨大风险。"},{"sentence":"While it is tempting to speculate about the outcome of the negotiation, it is more productive to focus on preparing a strong case.","translation":"虽然推测谈判结果很诱人，但专注于准备有力的论据会更有成效。"}]},"cab":{"examples":[{"sentence":"Although the subway is cheaper, I often take a cab when I am running late for an important meeting.","translation":"尽管地铁更便宜，但当我要赶一个重要会议时，我经常乘坐出租车。"},{"sentence":"Because the conference venue was far from the hotel, the organizers arranged a cab for each participant.","translation":"由于会议地点离酒店很远，组织者为每位与会者安排了一辆出租车。"},{"sentence":"While waiting for a cab in the rain, she realized that she had left her presentation notes at the office.","translation":"在雨中等待出租车时，她意识到她把演示笔记忘在了办公室。"},{"sentence":"If you are unfamiliar with the city, hailing a cab can be a safer option than navigating public transport alone.","translation":"如果你对这座城市不熟悉，叫一辆出租车可能比独自乘坐公共交通更安全。"},{"sentence":"The researcher used a cab to transport the fragile equipment, thereby avoiding potential damage on the bus.","translation":"那位研究员用出租车运送易碎设备，从而避免了在公交车上可能造成的损坏。"}]},"level":{"examples":[{"sentence":"To ensure a high level of accuracy, the data must be cross-checked by multiple independent analysts.","translation":"为了确保高水平的准确性，数据必须由多名独立分析师交叉核对。"},{"sentence":"Although the government has raised the minimum wage, the level of poverty in rural areas remains unchanged.","translation":"尽管政府提高了最低工资，但农村地区的贫困水平仍未改变。"},{"sentence":"A moderate level of competition can stimulate innovation, whereas excessive rivalry may lead to unethical behavior.","translation":"适度的竞争水平可以刺激创新，而过度的竞争可能导致不道德行为。"},{"sentence":"The level of air pollution in megacities has become a pressing concern, which requires immediate policy intervention.","translation":"大城市的空气污染水平已成为一个紧迫的问题，这需要立即的政策干预。"},{"sentence":"Because the level of trust between the two parties was low, the negotiation process was prolonged and difficult.","translation":"由于双方之间的信任水平很低，谈判过程漫长而艰难。"}]},"renaissance":{"examples":[{"sentence":"Although the term originally referred to a historical period, a renaissance of interest in classical music has recently emerged among young audiences.","translation":"尽管这个词最初指一个历史时期，但最近年轻观众对古典音乐的兴趣出现了复兴。"},{"sentence":"Because the city invested in public art and green spaces, it experienced a cultural renaissance that attracted tourists from around the world.","translation":"由于该市投资于公共艺术和绿地，它经历了一场文化复兴，吸引了来自世界各地的游客。"},{"sentence":"The renaissance of traditional crafts, which had nearly vanished during industrialization, now provides sustainable livelihoods for rural communities.","translation":"传统手工艺的复兴，在工业化期间几乎消失，现在为农村社区提供了可持续的生计。"},{"sentence":"While some scholars debate its exact boundaries, the Harlem Renaissance remains a pivotal moment in African American cultural history.","translation":"虽然一些学者争论其确切界限，哈莱姆文艺复兴仍然是非裔美国人文化史上的一个关键时刻。"},{"sentence":"A renaissance in scientific inquiry during the 17th century laid the groundwork for modern physics, thereby transforming our understanding of the universe.","translation":"17世纪科学探究的复兴为现代物理学奠定了基础，从而改变了我们对宇宙的理解。"}]},"stubborn":{"examples":[{"sentence":"Stubborn resistance to change, which often stems from fear of the unknown, can prevent organizations from adopting innovative practices.","translation":"顽固抵制变革，往往源于对未知的恐惧，会阻碍组织采用创新做法。"},{"sentence":"Although the stubborn stain seemed impossible to remove, a combination of enzymatic cleaners eventually restored the fabric.","translation":"尽管顽固的污渍似乎无法去除，但酶清洁剂的组合最终恢复了织物。"},{"sentence":"Because the negotiator maintained a stubborn position on key issues, the peace talks collapsed after weeks of deadlock.","translation":"由于谈判者在关键问题上保持顽固立场，和平谈判在数周僵局后破裂。"},{"sentence":"The stubborn persistence of gender inequality in the workplace calls for comprehensive policies that address both cultural and structural barriers.","translation":"工作场所性别不平等的顽固存在要求制定全面的政策，以解决文化和结构性障碍。"},{"sentence":"While a stubborn adherence to tradition can preserve cultural heritage, it may also hinder necessary social progress.","translation":"虽然顽固坚持传统可以保护文化遗产，但也可能阻碍必要的社会进步。"}]},"arrival":{"examples":[{"sentence":"Although the arrival of the pandemic disrupted global supply chains, it also accelerated digital transformation across many industries.","translation":"尽管疫情的到来扰乱了全球供应链，但它也加速了许多行业的数字化转型。"},{"sentence":"The timely arrival of emergency aid prevented a humanitarian catastrophe, thereby saving thousands of lives.","translation":"紧急援助的及时到达避免了一场人道主义灾难，从而挽救了数千人的生命。"},{"sentence":"Because the arrival of autonomous vehicles will reshape urban planning, policymakers must prepare new regulations now.","translation":"由于自动驾驶汽车的到来将重塑城市规划，政策制定者现在必须准备新的法规。"},{"sentence":"The arrival of a new cultural trend often challenges traditional values, which can lead to intergenerational conflict.","translation":"新文化潮流的到来常常挑战传统价值观，这可能导致代际冲突。"},{"sentence":"When the arrival of monsoon rains is delayed, farmers face severe drought, which threatens food security.","translation":"当季风降雨的到来延迟时，农民面临严重干旱，这威胁到粮食安全。"}]},"job":{"examples":[{"sentence":"Although the job offers a competitive salary, it demands a high level of commitment and resilience.","translation":"尽管这份工作提供有竞争力的薪水，但它要求高度的投入和韧性。"},{"sentence":"The job, which involves coordinating international projects, requires excellent cross-cultural communication skills.","translation":"这份工作涉及协调国际项目，需要出色的跨文化沟通技巧。"},{"sentence":"Because the job market is increasingly competitive, graduates must develop both technical and soft skills to stand out.","translation":"由于就业市场竞争日益激烈，毕业生必须培养技术和软技能才能脱颖而出。"},{"sentence":"When employees find a job that aligns with their values, they tend to experience greater job satisfaction.","translation":"当员工找到一份符合其价值观的工作时，他们往往会体验到更高的工作满意度。"},{"sentence":"The job, which was created to address emerging technological challenges, attracts innovative thinkers from diverse fields.","translation":"这份工作是为应对新兴技术挑战而设立的，吸引了来自不同领域的创新思维者。"}]},"disgrace":{"examples":[{"sentence":"The politician's involvement in the corruption scandal brought disgrace upon the entire administration, thereby eroding public confidence.","translation":"该政治家卷入腐败丑闻，给整个政府带来了耻辱，从而削弱了公众信心。"},{"sentence":"Although the team had a history of success, their unsportsmanlike conduct in the final match was a disgrace to the sport.","translation":"尽管该队有着辉煌的历史，但他们在决赛中的不道德行为是对这项运动的耻辱。"},{"sentence":"Because the company's negligence led to an environmental disaster, it faced public disgrace and severe legal consequences.","translation":"由于公司的疏忽导致了环境灾难，它面临公众耻辱和严重的法律后果。"},{"sentence":"The academic community considers plagiarism a grave disgrace, which can permanently damage a scholar's reputation.","translation":"学术界认为抄袭是一种严重的耻辱，会永久损害学者的声誉。"},{"sentence":"When the historical injustices were exposed, the nation had to confront its past disgrace and work toward reconciliation.","translation":"当历史不公被揭露时，该国不得不面对过去的耻辱并努力实现和解。"}]},"desire":{"examples":[{"sentence":"While the desire for rapid economic development is strong, policymakers must ensure that it does not compromise environmental sustainability.","translation":"虽然对快速经济发展的渴望很强烈，但政策制定者必须确保它不会损害环境的可持续性。"},{"sentence":"The innate human desire for social connection, which is essential for mental well-being, drives the popularity of social media platforms.","translation":"人类与生俱来的社交渴望对心理健康至关重要，它推动了社交媒体平台的普及。"},{"sentence":"Because the desire to learn is a powerful motivator, educators should create environments that stimulate curiosity rather than relying on rote memorization.","translation":"由于学习欲望是一种强大的动力，教育者应创造激发好奇心的环境，而不是依赖死记硬背。"},{"sentence":"The desire for innovation, when combined with adequate funding, can lead to breakthroughs that transform entire industries.","translation":"当创新的渴望与充足的资金相结合时，可以带来突破，从而改变整个行业。"},{"sentence":"Although the desire for material wealth is often criticized, it has historically driven economic progress and improved living standards.","translation":"尽管对物质财富的渴望常受批评，但它在历史上推动了经济进步并提高了生活水平。"}]},"a":{"examples":[{"sentence":"Although a single vote may seem insignificant, it can determine the outcome of a close election.","translation":"尽管一张选票看似微不足道，但它可以决定一场势均力敌的选举的结果。"},{"sentence":"A comprehensive education, which fosters critical thinking, is essential for a thriving democracy.","translation":"全面的教育培养批判性思维，对繁荣的民主至关重要。"},{"sentence":"Because a healthy diet provides essential nutrients, it significantly reduces the risk of chronic diseases.","translation":"因为健康的饮食提供必需的营养素，所以它显著降低了慢性病的风险。"},{"sentence":"A sudden economic downturn can trigger a chain reaction, thereby affecting global markets.","translation":"突然的经济衰退会引发连锁反应，从而影响全球市场。"},{"sentence":"When a society invests in renewable energy, it not only reduces pollution but also creates jobs.","translation":"当一个社会投资可再生能源时，它不仅减少污染，还创造就业机会。"}]},"offset":{"examples":[{"sentence":"Although the initial cost is high, the long-term savings offset the investment in solar panels.","translation":"尽管初始成本很高，但长期节省的费用抵消了对太阳能电池板的投资。"},{"sentence":"Companies often implement green initiatives to offset their carbon footprint, which enhances their brand image.","translation":"公司经常实施绿色倡议来抵消其碳足迹，这提升了他们的品牌形象。"},{"sentence":"Because regular exercise boosts metabolism, it can offset the effects of occasional overeating.","translation":"因为定期锻炼促进新陈代谢，所以它可以抵消偶尔暴饮暴食的影响。"},{"sentence":"The government increased subsidies to offset rising fuel prices, thereby easing the burden on consumers.","translation":"政府增加了补贴以抵消不断上涨的燃料价格，从而减轻了消费者的负担。"},{"sentence":"While technological advances improve efficiency, they rarely offset the job losses caused by automation.","translation":"虽然技术进步提高了效率，但它们很少能抵消自动化造成的失业。"}]},"party":{"examples":[{"sentence":"Although the ruling party promised reforms, its policies failed to address income inequality.","translation":"尽管执政党承诺改革，但其政策未能解决收入不平等问题。"},{"sentence":"A third party, which remains neutral, can facilitate negotiations between conflicting groups.","translation":"保持中立的第三方可以促进冲突团体之间的谈判。"},{"sentence":"Because each party must adhere to the contract, disputes are less likely to arise.","translation":"因为每一方都必须遵守合同，所以争议不太可能发生。"},{"sentence":"The opposition party criticized the new law, arguing that it restricts individual freedoms.","translation":"反对党批评了新法律，认为它限制了个人自由。"},{"sentence":"When a political party prioritizes short-term gains, it often undermines long-term national interests.","translation":"当一个政党优先考虑短期利益时，它往往会损害长期的国家利益。"}]},"useful":{"examples":[{"sentence":"The statistical software proved extremely useful for analyzing large datasets, which enabled the team to identify significant trends.","translation":"该统计软件在分析大型数据集方面极为有用，这使团队能够识别出显著的趋势。"},{"sentence":"Although the theoretical framework is abstract, it provides a useful lens through which to examine complex social phenomena.","translation":"尽管该理论框架是抽象的，但它提供了一个有用的视角来审视复杂的社会现象。"},{"sentence":"Learning a second language is not only intellectually stimulating but also useful for fostering cross-cultural communication in a globalized world.","translation":"学习第二语言不仅具有智力上的启发性，而且对于在全球化世界中促进跨文化交流也很有用。"},{"sentence":"The internship offered useful hands-on experience that complemented the academic knowledge gained in university courses.","translation":"这次实习提供了有用的实践经验，补充了大学课程中学到的学术知识。"},{"sentence":"Because the guidebook contained useful tips on local customs, travelers were able to avoid cultural misunderstandings.","translation":"由于该指南包含了关于当地习俗的有用提示，旅行者得以避免文化误解。"}]},"neck":{"examples":[{"sentence":"Although the injury appeared minor, the doctor ordered an X-ray to ensure that the patient's neck was not fractured.","translation":"尽管伤势看起来轻微，医生还是要求拍X光片以确保病人的颈部没有骨折。"},{"sentence":"Because the dress had an elegant V-neck, it became the most popular design in the fashion show.","translation":"因为这条裙子有一个优雅的V领，它成为了时装秀上最受欢迎的设计。"},{"sentence":"The constant pressure from the upcoming exams became a pain in the neck, which affected the students' sleep quality.","translation":"即将到来的考试带来的持续压力成了一件烦人的事，这影响了学生的睡眠质量。"},{"sentence":"When the journalist risked her neck to expose corruption, she demonstrated a commitment to justice that inspired many.","translation":"当那位记者冒着生命危险揭露腐败时，她展现了对正义的执着，这激励了许多人。"},{"sentence":"The giraffe's long neck allows it to reach leaves high in the trees, thereby gaining access to food sources unavailable to other herbivores.","translation":"长颈鹿的长脖子使它能够吃到高处的树叶，从而获得了其他食草动物无法获取的食物来源。"}]},"zigzag":{"examples":[{"sentence":"Although the path was steep, the zigzag trail allowed hikers to ascend without excessive fatigue.","translation":"尽管小路陡峭，但之字形的小径让徒步者能够攀登而不至于过度疲劳。"},{"sentence":"The lightning bolt traced a brilliant zigzag across the sky, which illuminated the entire landscape for a split second.","translation":"闪电在天空中划出一道耀眼的之字形，瞬间照亮了整个景观。"},{"sentence":"Because the river followed a natural zigzag through the valley, it created a series of fertile floodplains that supported agriculture.","translation":"由于河流在山谷中自然形成之字形，它创造了一系列支持农业的肥沃洪泛平原。"},{"sentence":"To avoid the fallen rocks, the driver steered in a careful zigzag along the damaged road, thereby ensuring the safety of the passengers.","translation":"为了避开落石，司机在受损的道路上小心地以之字形行驶，从而确保了乘客的安全。"},{"sentence":"The artist drew a continuous zigzag that divided the canvas into dynamic sections, rather than using straight lines.","translation":"艺术家画了一条连续的之字形线条，将画布分割成充满动感的部分，而不是使用直线。"}]},"singular":{"examples":[{"sentence":"The scientist's singular dedication to her research, which often kept her working late into the night, eventually led to a breakthrough discovery.","translation":"这位科学家对研究的非凡投入，经常让她工作到深夜，最终带来了一项突破性发现。"},{"sentence":"Although the team faced many setbacks, their singular focus on the project's core objective kept them from being distracted.","translation":"尽管团队面临许多挫折，但他们对项目核心目标的专注使他们没有分心。"},{"sentence":"The architect's design was praised for its singular blend of traditional aesthetics and modern functionality, which set a new standard in the field.","translation":"建筑师的设计因其将传统美学与现代功能独特地融合而受到赞誉，这在该领域树立了新标准。"},{"sentence":"In an era of mass production, the craftsman's singular attention to detail set his work apart from that of his competitors.","translation":"在大规模生产的时代，这位工匠对细节的非凡关注使他的作品从竞争对手中脱颖而出。"},{"sentence":"The novel's singular narrative structure, which shifts between multiple timelines, challenges the reader's perception of memory.","translation":"小说独特的叙事结构在多个时间线之间切换，挑战了读者对记忆的感知。"}]},"dinner":{"examples":[{"sentence":"Although the dinner was scheduled for seven o'clock, many guests arrived early to network before the meal.","translation":"尽管晚宴定在七点，许多客人还是提前到达，以便在用餐前进行社交。"},{"sentence":"The charity dinner, which featured a keynote speech by a renowned philanthropist, raised over one million dollars for cancer research.","translation":"这场慈善晚宴以一位著名慈善家的主旨演讲为特色，为癌症研究筹集了超过一百万美元。"},{"sentence":"Because the host prepared a traditional multi-course dinner, the international guests gained a deeper appreciation for the local cuisine.","translation":"由于主人准备了传统的多道菜晚宴，国际宾客对当地美食有了更深的了解。"},{"sentence":"To ensure a productive discussion, the committee organized a working dinner where members could exchange ideas in a relaxed setting.","translation":"为了确保富有成效的讨论，委员会组织了一次工作晚宴，让成员在轻松的环境中交流想法。"},{"sentence":"While the formal dinner honored the retiring professor, it also served as an opportunity for alumni to reconnect with their alma mater.","translation":"这场正式晚宴在向退休教授致敬的同时，也为校友们提供了与母校重新建立联系的机会。"}]},"insult":{"examples":[{"sentence":"Although the comment was intended as a joke, many perceived it as a direct insult to their cultural traditions.","translation":"尽管这句话本意是开玩笑，但许多人认为这是对他们文化传统的直接侮辱。"},{"sentence":"The policy, which reduced funding for public libraries, was seen as an insult to the value of education in society.","translation":"这项削减公共图书馆资金的政策被视为对社会教育价值的侮辱。"},{"sentence":"Because the manager publicly criticized her work without justification, she felt a deep sense of insult and considered resigning.","translation":"由于经理毫无道理地公开批评她的工作，她感到深受侮辱并考虑辞职。"},{"sentence":"To add insult to injury, the company not only denied his promotion but also assigned his responsibilities to a less experienced colleague.","translation":"雪上加霜的是，公司不仅拒绝了他的晋升，还将他的职责分配给了一位经验较少的同事。"},{"sentence":"While some defended the cartoon as free speech, others argued that it was a deliberate insult to religious beliefs.","translation":"尽管一些人以言论自由为这幅漫画辩护，但其他人认为这是对宗教信仰的蓄意侮辱。"}]},"tumour":{"examples":[{"sentence":"Although the tumour was initially thought to be inoperable, a new surgical technique offered a chance for complete removal.","translation":"尽管肿瘤最初被认为无法手术，但一项新的外科技术为完全切除提供了机会。"},{"sentence":"The research team discovered that the tumour's growth could be inhibited by a specific enzyme, which opened new avenues for treatment.","translation":"研究团队发现肿瘤的生长可以被一种特定的酶抑制，这为治疗开辟了新途径。"},{"sentence":"Because the tumour was located near a major blood vessel, the surgeons had to proceed with extreme caution to avoid complications.","translation":"由于肿瘤靠近一条主要血管，外科医生必须极其谨慎地进行手术以避免并发症。"},{"sentence":"To ensure an accurate diagnosis, the pathologist examined the tumour tissue under a microscope and performed several molecular tests.","translation":"为了确保准确诊断，病理学家在显微镜下检查了肿瘤组织并进行了几项分子检测。"},{"sentence":"While chemotherapy successfully reduced the size of the tumour, the patient experienced significant side effects that required additional management.","translation":"尽管化疗成功缩小了肿瘤的大小，但患者出现了明显的副作用，需要额外的处理。"}]},"misunderstand":{"examples":[{"sentence":"Although the instructions were clearly written, many users still misunderstand the software's core functionality.","translation":"尽管说明书写得很清楚，许多用户仍然误解了该软件的核心功能。"},{"sentence":"Because nonverbal cues vary across cultures, international colleagues may misunderstand each other's intentions during meetings.","translation":"由于非语言暗示在不同文化中有所差异，国际同事在会议中可能会误解彼此的意图。"},{"sentence":"When technical jargon is used without explanation, readers often misunderstand the main findings of the research.","translation":"当技术术语未经解释就被使用时，读者常常误解研究的主要发现。"},{"sentence":"If policymakers ignore local contexts, they risk that communities misunderstand the purpose of new regulations.","translation":"如果政策制定者忽视当地背景，他们就有可能让社区误解新法规的目的。"},{"sentence":"To ensure effective collaboration, team leaders must clarify goals before members misunderstand the project scope.","translation":"为了确保有效合作，团队领导必须在成员误解项目范围之前澄清目标。"}]},"compile":{"examples":[{"sentence":"Although the data was scattered across multiple databases, the analyst managed to compile a unified report.","translation":"尽管数据分散在多个数据库中，分析师还是成功编纂了一份统一的报告。"},{"sentence":"Because the legal team needed accurate precedents, they spent weeks to compile relevant case law.","translation":"由于法律团队需要准确的先例，他们花了数周时间收集相关判例法。"},{"sentence":"When researchers compile statistics from various sources, they must verify the reliability of each dataset.","translation":"当研究人员从各种来源汇编统计数据时，他们必须核实每个数据集的可靠性。"},{"sentence":"If you compile a bibliography without proper citations, the academic integrity of your paper may be compromised.","translation":"如果你编纂参考文献时没有正确引用，你论文的学术诚信可能会受到损害。"},{"sentence":"To ensure the anthology was comprehensive, the editor decided to compile works from both established and emerging authors.","translation":"为了确保选集全面，编辑决定收集知名作家和新锐作家的作品。"}]},"official":{"examples":[{"sentence":"Although the official was new to the department, she quickly implemented reforms that improved efficiency.","translation":"尽管这位官员刚到这个部门，她迅速实施了提高效率的改革。"},{"sentence":"Because the health official provided clear guidelines, the public understood the necessity of the vaccination campaign.","translation":"由于卫生官员提供了明确的指导方针，公众理解了疫苗接种运动的必要性。"},{"sentence":"When a senior official makes a public statement, it often reflects the government's official stance on the issue.","translation":"当一位高级官员发表公开声明时，这通常反映了政府对该问题的官方立场。"},{"sentence":"If an elected official fails to disclose conflicts of interest, it undermines public trust in the institution.","translation":"如果一位民选官员未能披露利益冲突，就会削弱公众对该机构的信任。"},{"sentence":"To ensure accountability, every public official must adhere to a strict code of conduct while in office.","translation":"为了确保问责制，每位公职人员在任职期间都必须遵守严格的行为准则。"}]},"hen":{"examples":[{"sentence":"The hen, which had been brooding for weeks, finally hatched a clutch of chicks.","translation":"那只母鸡已经孵蛋数周，终于孵出了一窝小鸡。"},{"sentence":"Because the hen was kept in a spacious free-range environment, her eggs were notably richer in flavor.","translation":"由于这只母鸡被饲养在宽敞的散养环境中，她产的蛋风味明显更加浓郁。"},{"sentence":"Although the hen appeared placid, she would fiercely defend her chicks from any perceived threat.","translation":"尽管这只母鸡看起来很温和，但她会激烈地保护小鸡免受任何感知到的威胁。"},{"sentence":"The farmer observed that the hen, unlike the rooster, spent most of her day foraging quietly for insects.","translation":"农夫观察到，与公鸡不同，这只母鸡大部分时间都在安静地觅食昆虫。"},{"sentence":"To ensure a steady supply of eggs, the family decided to keep a hen that was known for its high productivity.","translation":"为了确保稳定的鸡蛋供应，这家人决定养一只以高产著称的母鸡。"}]},"infrared":{"examples":[{"sentence":"Infrared thermometers are widely used in industrial settings to measure surface temperatures without direct contact.","translation":"红外温度计在工业环境中被广泛用于非接触式测量表面温度。"},{"sentence":"Because infrared radiation is invisible to the human eye, special cameras are required to detect it.","translation":"由于红外辐射对人眼不可见，需要特殊的相机来探测它。"},{"sentence":"The satellite's infrared sensors can monitor forest fires by detecting heat signatures even through dense smoke.","translation":"卫星的红外传感器可以通过探测热信号来监测森林火灾，即使是在浓烟中。"},{"sentence":"Although infrared saunas operate at lower temperatures than traditional ones, they are believed to offer similar health benefits.","translation":"尽管红外桑拿的运行温度低于传统桑拿，但人们认为它们能提供类似的健康益处。"},{"sentence":"Researchers used infrared spectroscopy to analyze the chemical composition of the ancient artifact without causing damage.","translation":"研究人员使用红外光谱学来分析这件古代文物的化学成分，而不会造成损坏。"}]},"prayer":{"examples":[{"sentence":"Although she was not religious, she found that a moment of silent prayer each morning helped her focus throughout the day.","translation":"尽管她不信教，但她发现每天早晨片刻的默祷有助于她全天集中注意力。"},{"sentence":"The community held a prayer service, which was organized to honor the memory of those who had sacrificed their lives.","translation":"社区举行了一场祈祷仪式，旨在纪念那些牺牲生命的人。"},{"sentence":"Because the patient's family believed in the power of collective prayer, they requested that friends and relatives join them in a vigil.","translation":"由于病人家属相信集体祈祷的力量，他们请求亲友加入守夜祈祷。"},{"sentence":"In many cultures, prayer is not only a personal act of devotion but also a communal ritual that strengthens social bonds.","translation":"在许多文化中，祈祷不仅是个人的虔诚行为，也是加强社会纽带的集体仪式。"},{"sentence":"The monk dedicated his life to prayer and meditation, thereby seeking inner peace rather than worldly success.","translation":"这位僧侣将一生奉献给祈祷和冥想，从而寻求内心的平静而非世俗的成功。"}]},"than":{"examples":[{"sentence":"Investing in preventive healthcare is far more cost-effective than allocating resources to treat advanced diseases that could have been avoided.","translation":"投资于预防性医疗远比将资源用于治疗本可避免的晚期疾病更具成本效益。"},{"sentence":"The new policy proved less effective than its proponents had anticipated, largely because it failed to address the underlying structural issues.","translation":"新政策的效果不如其支持者预期的那么有效，主要是因为它未能解决根本的结构性问题。"},{"sentence":"Rather than imposing a uniform curriculum, the reform allows schools greater autonomy to adapt teaching methods to local needs.","translation":"改革没有强加统一的课程，而是赋予学校更大的自主权，以便根据当地需求调整教学方法。"},{"sentence":"Students who engage in collaborative projects often develop deeper understanding than those who study exclusively through individual assignments.","translation":"参与合作项目的学生通常比仅通过个人作业学习的学生理解得更深入。"},{"sentence":"The environmental impact of renewable energy sources is substantially lower than that of fossil fuels, even when accounting for manufacturing and disposal.","translation":"即使考虑到制造和废弃处理，可再生能源对环境的影响也远低于化石燃料。"}]},"specification":{"examples":[{"sentence":"The contract requires a detailed specification of the materials to be used, thereby avoiding any ambiguity during construction.","translation":"合同要求详细说明所用材料，从而避免施工过程中出现任何歧义。"},{"sentence":"Because the software specification lacked clarity, the developers implemented features that did not align with user expectations.","translation":"由于软件规格缺乏清晰度，开发人员实现的功能与用户期望不符。"},{"sentence":"A well-defined specification, which includes performance criteria and testing methods, is essential for quality assurance.","translation":"一份定义明确的规格书，包括性能标准和测试方法，对于质量保证至关重要。"},{"sentence":"Although the prototype met the basic specification, it failed to satisfy the stricter industry standards that were later introduced.","translation":"尽管原型符合基本规格，但未能满足后来引入的更严格的行业标准。"},{"sentence":"The engineering team revised the technical specification to incorporate new safety requirements, rather than relying on outdated guidelines.","translation":"工程团队修订了技术规格，纳入了新的安全要求，而不是依赖过时的指南。"}]},"sunday":{"examples":[{"sentence":"Although Sunday is typically reserved for rest, many graduate students use it to finalize their research proposals.","translation":"尽管周日通常用于休息，许多研究生却利用这一天来完善他们的研究计划。"},{"sentence":"The conference was scheduled on a Sunday so that international participants could attend without missing workdays.","translation":"会议安排在周日，以便国际参会者能够参加而不耽误工作日。"},{"sentence":"Because the library extends its hours on Sunday, scholars can access rare manuscripts that are otherwise unavailable.","translation":"由于图书馆在周日延长开放时间，学者们可以查阅平时无法获取的珍稀手稿。"},{"sentence":"Volunteering on Sunday not only benefits the community but also enriches one's own sense of social responsibility.","translation":"在周日做志愿者不仅有益于社区，也丰富了自己的社会责任感。"},{"sentence":"When the deadline falls on a Sunday, it is advisable to submit the assignment earlier to avoid technical issues.","translation":"当截止日期恰逢周日时，建议提前提交作业以避免技术问题。"}]},"mutton":{"examples":[{"sentence":"Although mutton is often considered a winter dish, it can be prepared in light salads for summer meals.","translation":"尽管羊肉通常被认为是冬季菜肴，但它也可以做成清淡的沙拉供夏季食用。"},{"sentence":"Because mutton has a distinct flavor, chefs often pair it with robust herbs like rosemary and thyme.","translation":"由于羊肉风味独特，厨师们常将其与迷迭香和百里香等浓郁香草搭配。"},{"sentence":"Slow-braising mutton in red wine not only tenderizes the meat but also infuses it with rich, complex notes.","translation":"用红酒慢炖羊肉不仅能嫩化肉质，还能为其注入丰富复杂的风味。"},{"sentence":"In many traditional recipes, mutton is marinated overnight to ensure the spices penetrate deeply.","translation":"在许多传统食谱中，羊肉会腌制过夜，以确保香料充分渗透。"},{"sentence":"While mutton is less common in Western diets, it remains a staple protein in parts of the Middle East and Asia.","translation":"尽管羊肉在西方饮食中不太常见，但在中东和亚洲部分地区它仍是主要的蛋白质来源。"}]},"collide":{"examples":[{"sentence":"When the interests of economic growth and environmental protection collide, policymakers must carefully weigh long-term consequences.","translation":"当经济增长与环境保护的利益发生冲突时，决策者必须仔细权衡长期后果。"},{"sentence":"In a rapidly changing society, traditional values often collide with modern lifestyles, creating tensions that require thoughtful resolution.","translation":"在快速变化的社会中，传统价值观常与现代生活方式发生冲突，产生需要深思熟虑才能解决的紧张关系。"},{"sentence":"The two research teams, working independently, discovered that their conclusions collide on a fundamental point, prompting a joint investigation.","translation":"两个独立工作的研究团队发现，他们的结论在一个基本点上相互矛盾，从而促使他们展开联合调查。"},{"sentence":"If personal ambitions collide with team objectives, a leader must find a compromise that preserves both morale and productivity.","translation":"如果个人抱负与团队目标相抵触，领导者必须找到一个既能维护士气又能保持生产力的折中方案。"},{"sentence":"The new regulation may collide with existing industry practices, so companies need to adjust their operations to ensure compliance.","translation":"新规定可能与现有行业惯例相冲突，因此企业需要调整运营以确保合规。"}]},"semiconductor":{"examples":[{"sentence":"Because semiconductor chips are essential for modern electronics, countries are investing heavily in domestic fabrication plants.","translation":"由于半导体芯片对现代电子产品至关重要，各国正在大力投资国内制造工厂。"},{"sentence":"The global semiconductor shortage, which disrupted automotive production, highlighted the fragility of just-in-time supply chains.","translation":"全球半导体短缺扰乱了汽车生产，凸显了准时制供应链的脆弱性。"},{"sentence":"Although silicon remains the dominant semiconductor material, researchers are developing alternatives like gallium nitride for higher efficiency.","translation":"尽管硅仍然是主要的半导体材料，但研究人员正在开发氮化镓等替代品以提高效率。"},{"sentence":"When semiconductor manufacturers adopt extreme ultraviolet lithography, they can produce chips with smaller transistors and greater performance.","translation":"当半导体制造商采用极紫外光刻技术时，他们可以生产具有更小晶体管和更高性能的芯片。"},{"sentence":"The semiconductor industry, which requires massive capital investment, is characterized by rapid technological obsolescence and intense competition.","translation":"半导体行业需要巨额资本投资，其特点是技术迅速过时和竞争激烈。"}]},"cut":{"examples":[{"sentence":"Although the company announced a budget cut, it managed to preserve funding for research and development to ensure long-term growth.","translation":"尽管公司宣布了预算削减，但它设法保留了研发资金以确保长期增长。"},{"sentence":"The surgeon made a precise cut along the natural skin crease, which minimized visible scarring after the operation.","translation":"外科医生沿着自然的皮肤褶皱做了一个精确的切口，从而最大限度地减少了手术后的可见疤痕。"},{"sentence":"Because the government implemented a tax cut, disposable income increased, thereby stimulating consumer spending and economic recovery.","translation":"由于政府实施了减税，可支配收入增加，从而刺激了消费支出和经济复苏。"},{"sentence":"When the editor suggested a cut in the final chapter, the author agreed, as it would tighten the narrative and enhance the story's impact.","translation":"当编辑建议删减最后一章时，作者同意了，因为这将使叙事更紧凑并增强故事的影响力。"},{"sentence":"The deep cut in public health funding, which affected preventive care programs, raised concerns about long-term community well-being.","translation":"公共卫生资金的严重削减影响了预防保健项目，引发了人们对长期社区福祉的担忧。"}]},"rain":{"examples":[{"sentence":"Although the rain fell steadily throughout the day, the outdoor festival continued as planned, which delighted the attendees.","translation":"尽管雨下了一整天，户外节日仍按计划进行，这让参加者感到高兴。"},{"sentence":"Because heavy rain often triggers landslides in mountainous regions, authorities have implemented early warning systems to ensure public safety.","translation":"由于暴雨常常引发山区山体滑坡，当局已实施预警系统以确保公共安全。"},{"sentence":"While rain is essential for agriculture, excessive precipitation can lead to flooding, thereby destroying crops and livelihoods.","translation":"虽然雨水对农业至关重要，但过量降水会导致洪水，从而毁坏庄稼和生计。"},{"sentence":"When acid rain contaminates freshwater sources, it not only harms aquatic life but also poses risks to human health.","translation":"当酸雨污染淡水源时，它不仅危害水生生物，还对人类健康构成风险。"},{"sentence":"The gentle rain that nourishes the soil is often celebrated by farmers, whereas urban dwellers may view it as a mere inconvenience.","translation":"滋养土壤的细雨常受农民欢迎，而城市居民可能只将其视为不便。"}]},"infect":{"examples":[{"sentence":"If a wound is not properly cleaned, bacteria can infect it and cause severe complications, which may require surgical intervention.","translation":"如果伤口未得到适当清洁，细菌会感染它并引起严重并发症，可能需要手术干预。"},{"sentence":"Because the virus can infect unvaccinated individuals rapidly, public health campaigns emphasize the importance of immunization to ensure herd immunity.","translation":"由于病毒能迅速感染未接种疫苗的人，公共卫生运动强调免疫接种的重要性以确保群体免疫。"},{"sentence":"Misinformation can infect public discourse, eroding trust in institutions and thereby weakening the foundations of democracy.","translation":"错误信息会侵蚀公共讨论，削弱对机构的信任，从而动摇民主的基础。"},{"sentence":"When a computer lacks robust security measures, malware can infect the system and compromise sensitive data, which often leads to financial loss.","translation":"当计算机缺乏强大的安全措施时，恶意软件会感染系统并危及敏感数据，这常常导致经济损失。"},{"sentence":"A leader's negative attitude can infect the entire team, lowering morale and productivity even when external conditions are favorable.","translation":"领导者的消极态度会感染整个团队，即使外部条件有利，也会降低士气和生产力。"}]},"calculate":{"examples":[{"sentence":"Although the data set is incomplete, we can still calculate a preliminary estimate of the project's total cost.","translation":"尽管数据集不完整，我们仍然可以计算出项目总成本的初步估计。"},{"sentence":"Engineers must calculate the load-bearing capacity of the bridge before construction begins, thereby ensuring public safety.","translation":"工程师必须在施工开始前计算出桥梁的承载能力，从而确保公共安全。"},{"sentence":"If we calculate the carbon footprint of each product, consumers can make more informed choices that benefit the environment.","translation":"如果我们计算每种产品的碳足迹，消费者就能做出更明智的选择，从而有利于环境。"},{"sentence":"Policy makers calculate the long-term benefits of investing in renewable energy against immediate economic costs, which is a complex but necessary task.","translation":"政策制定者会权衡投资可再生能源的长期收益与短期经济成本，这是一项复杂但必要的任务。"},{"sentence":"To calculate the company's annual revenue accurately, the accountant compiled data from all regional offices, rather than relying on estimates.","translation":"为了准确计算公司的年收入，会计汇总了所有地区办事处的数据，而不是依赖估算。"}]},"expansion":{"examples":[{"sentence":"The rapid expansion of urban areas has placed considerable pressure on public transportation systems, which often struggle to keep pace.","translation":"城市地区的快速扩张给公共交通系统带来了巨大压力，后者往往难以跟上步伐。"},{"sentence":"International expansion requires companies to adapt their marketing strategies to local cultures, thereby avoiding costly missteps.","translation":"国际扩张要求公司根据当地文化调整营销策略，从而避免代价高昂的失误。"},{"sentence":"While the expansion of digital infrastructure brings economic opportunities, it also raises concerns about data privacy that must be addressed.","translation":"虽然数字基础设施的扩展带来了经济机遇，但也引发了人们对数据隐私的担忧，这些问题必须得到解决。"},{"sentence":"The expansion of higher education has enabled more students from disadvantaged backgrounds to attend university, which promotes social mobility.","translation":"高等教育的扩招使更多来自弱势背景的学生能够上大学，这促进了社会流动性。"},{"sentence":"Because the expansion of the universe is accelerating, cosmologists are re-evaluating fundamental theories about dark energy.","translation":"由于宇宙的膨胀正在加速，宇宙学家正在重新评估关于暗能量的基本理论。"}]},"scope":{"examples":[{"sentence":"Although the initial study had a narrow scope, subsequent research expanded its focus to include global implications.","translation":"尽管最初的研究范围狭窄，但随后的研究将其重点扩大到包括全球影响。"},{"sentence":"The new policy provides considerable scope for innovation, which encourages companies to develop sustainable technologies.","translation":"新政策为创新提供了相当大的空间，这鼓励企业开发可持续技术。"},{"sentence":"Because the project's scope was not clearly defined, the team encountered unexpected delays and budget overruns.","translation":"由于项目范围没有明确界定，团队遇到了意外的延误和预算超支。"},{"sentence":"Understanding the full scope of the problem requires interdisciplinary collaboration, thereby ensuring comprehensive solutions.","translation":"理解问题的全部范围需要跨学科合作，从而确保全面的解决方案。"},{"sentence":"The course offers limited scope for practical application, which may hinder students' ability to transfer knowledge to real-world settings.","translation":"这门课程提供的实际应用范围有限，这可能会阻碍学生将知识迁移到现实环境中的能力。"}]},"little":{"examples":[{"sentence":"There is little evidence to support the claim that this supplement enhances cognitive function, which raises doubts about its efficacy.","translation":"几乎没有证据支持这种补充剂能增强认知功能的说法，这引发了对其功效的怀疑。"},{"sentence":"Because the committee paid little attention to public feedback, the policy faced widespread criticism when it was implemented.","translation":"由于委员会很少关注公众反馈，该政策在实施时遭到了广泛批评。"},{"sentence":"Despite having little formal education, the entrepreneur built a successful business through determination and practical experience.","translation":"尽管几乎没有受过正规教育，这位企业家通过决心和实践经验建立了一家成功的企业。"},{"sentence":"The initial investment yielded little return, which prompted the company to diversify its portfolio and reduce risk.","translation":"初始投资几乎没有产生回报，这促使公司分散投资组合以降低风险。"},{"sentence":"The report offers little insight into the root causes of the crisis, thereby limiting its usefulness for policymakers.","translation":"该报告几乎没有提供对危机根本原因的深入分析，从而限制了它对政策制定者的用处。"}]},"optional":{"examples":[{"sentence":"While the core curriculum is mandatory, students may choose from a range of optional modules to tailor their degree to specific career goals.","translation":"虽然核心课程是必修的，但学生可以从一系列选修模块中进行选择，以使他们的学位符合特定的职业目标。"},{"sentence":"The company introduced an optional remote-work policy, which allowed employees to balance productivity with personal commitments more effectively.","translation":"公司推出了一项可选的远程工作政策，使员工能够更有效地平衡工作效率与个人事务。"},{"sentence":"Because the advanced training session was optional, only those who sought to deepen their expertise attended the intensive workshop.","translation":"由于高级培训课程是可选的，只有那些寻求深化专业知识的人参加了这个密集研讨会。"},{"sentence":"Including an optional essay in the application process gives candidates an opportunity to showcase qualities that test scores cannot capture.","translation":"在申请流程中加入一篇可选的论文，让申请者有机会展示考试成绩无法体现的品质。"},{"sentence":"Although the software update was optional, users who installed it benefited from enhanced security features and a more intuitive interface.","translation":"尽管软件更新是可选的，但安装它的用户受益于增强的安全功能和更直观的界面。"}]},"warfare":{"examples":[{"sentence":"Although modern warfare increasingly relies on cyber capabilities, traditional ground forces remain essential for holding territory.","translation":"尽管现代战争越来越依赖网络能力，传统地面部队对于控制领土仍然至关重要。"},{"sentence":"Because economic warfare often involves sanctions that target entire sectors, its consequences can ripple through global supply chains for years.","translation":"由于经济战通常涉及针对整个行业的制裁，其后果可能在全球供应链中波及多年。"},{"sentence":"The development of autonomous weapons systems is reshaping the ethics of warfare, which has prompted urgent calls for international regulation.","translation":"自主武器系统的发展正在重塑战争的伦理，这引发了要求国际监管的紧急呼吁。"},{"sentence":"Psychological warfare, which aims to undermine an adversary's morale, can be as decisive as physical combat in protracted struggles.","translation":"心理战旨在削弱对手的士气，在持久斗争中可能与实际战斗一样具有决定性。"},{"sentence":"While guerrilla warfare is typically associated with asymmetric conflicts, its principles have been adapted by state actors in hybrid strategies.","translation":"尽管游击战通常与非对称冲突相关，但其原则已被国家行为体在混合战略中加以运用。"}]},"deposit":{"examples":[{"sentence":"Although the rental agreement requires a security deposit, it is refundable if no damage occurs.","translation":"虽然租赁协议要求支付押金，但如果没有损坏发生，押金是可退还的。"},{"sentence":"Because the bank offers a competitive interest rate, many customers choose to deposit their savings there.","translation":"因为银行提供有竞争力的利率，许多客户选择将储蓄存入那里。"},{"sentence":"When you book the venue, a non-refundable deposit of 20 percent is required to secure the date.","translation":"当你预订场地时，需要支付20%的不可退还定金以确保日期。"},{"sentence":"The geologists found a substantial mineral deposit that could be mined for decades.","translation":"地质学家发现了一个可开采数十年的丰富矿床。"},{"sentence":"Over time, the river leaves a deposit of silt that enriches the surrounding farmland.","translation":"随着时间的推移，河流留下淤泥堆积物，使周围的农田变得肥沃。"}]},"substantial":{"examples":[{"sentence":"Although the initial investment is substantial, the long-term benefits of solar energy justify the cost.","translation":"尽管初始投资巨大，但太阳能的长期收益证明了这笔费用的合理性。"},{"sentence":"Because the company made a substantial profit last quarter, it decided to expand its operations overseas.","translation":"因为公司上个季度获得了可观的利润，所以决定向海外扩张业务。"},{"sentence":"The research provides substantial evidence that regular exercise can reduce the risk of chronic diseases.","translation":"这项研究提供了大量证据，表明定期锻炼可以降低患慢性病的风险。"},{"sentence":"When a government allocates a substantial portion of its budget to education, it often sees improved literacy rates.","translation":"当政府将预算的很大一部分分配给教育时，通常会发现识字率有所提高。"},{"sentence":"The new policy had a substantial impact on small businesses, which forced many to adapt their strategies.","translation":"新政策对小企业产生了重大影响，这迫使许多企业调整了战略。"}]},"rear":{"examples":[{"sentence":"Although the rear of the building appears unremarkable, it houses a state-of-the-art laboratory that drives the company's innovation.","translation":"尽管建筑物的后部看起来不起眼，但它容纳了一个推动公司创新的尖端实验室。"},{"sentence":"Because the rear entrance is less congested, employees prefer to use it when arriving during peak hours.","translation":"由于后门入口不那么拥挤，员工在高峰时段到达时更喜欢使用它。"},{"sentence":"The garden at the rear of the property, which features a variety of native plants, provides a tranquil space for relaxation.","translation":"房屋后部的花园种植了多种本地植物，提供了一个宁静的休闲空间。"},{"sentence":"While the front facade was meticulously restored, the rear of the historic mansion still requires significant renovation.","translation":"虽然正面外墙被精心修复，但这座历史宅邸的后部仍需要大规模翻新。"},{"sentence":"To ensure privacy, the architect designed the master bedroom at the rear of the house, away from the street noise.","translation":"为了确保隐私，建筑师将主卧室设计在房屋后部，远离街道噪音。"}]},"nerve":{"examples":[{"sentence":"Although the experiment was risky, the young scientist had the nerve to proceed because she believed in its potential.","translation":"尽管实验有风险，这位年轻科学家还是鼓起勇气继续，因为她相信它的潜力。"},{"sentence":"It takes considerable nerve to challenge a widely accepted theory, which is why many researchers avoid doing so.","translation":"挑战一个被广泛接受的理论需要相当大的勇气，这就是为什么许多研究者避免这样做。"},{"sentence":"While others hesitated, she summoned the nerve to present her controversial findings at the international conference.","translation":"当其他人犹豫时，她鼓起勇气在国际会议上展示了她有争议的发现。"},{"sentence":"Because the policy would harm vulnerable communities, the legislator found the nerve to vote against her own party.","translation":"由于该政策会伤害弱势群体，这位立法者鼓起勇气投票反对自己的政党。"},{"sentence":"Without the nerve to question established norms, scientific progress would be severely hindered.","translation":"如果没有质疑既定规范的勇气，科学进步将受到严重阻碍。"}]},"without":{"examples":[{"sentence":"A society cannot achieve lasting prosperity without investing in the education of its younger generation.","translation":"一个社会如果不投资于年轻一代的教育，就无法实现持久的繁荣。"},{"sentence":"Researchers must not draw firm conclusions without first subjecting their data to rigorous statistical analysis.","translation":"研究人员在没有首先对数据进行严格的统计分析之前，绝不能得出确切的结论。"},{"sentence":"International cooperation often proves ineffective without a shared commitment to transparent communication and mutual accountability.","translation":"如果没有对透明沟通和相互问责的共同承诺，国际合作往往被证明是无效的。"},{"sentence":"Many traditional crafts have disappeared without adequate documentation, leaving future generations without a tangible link to their cultural heritage.","translation":"许多传统工艺在没有充分记录的情况下消失了，使后代失去了与其文化遗产的有形联系。"},{"sentence":"Without consistent enforcement of environmental regulations, even the most well-intentioned policies will fail to curb pollution.","translation":"如果没有对环境法规的持续执行，即使是最善意的政策也无法遏制污染。"}]},"gold":{"examples":[{"sentence":"Because gold retains its value over time, it is often used as a hedge against inflation in investment portfolios.","translation":"因为黄金能长期保值，它常在投资组合中被用作对冲通货膨胀的工具。"},{"sentence":"The discovery of gold in the region led to a rapid influx of settlers, which ultimately transformed the local economy and environment.","translation":"该地区黄金的发现导致定居者迅速涌入，这最终改变了当地的经济和环境。"},{"sentence":"Although gold is highly valued for its beauty, its mining process can cause severe ecological damage if not properly regulated.","translation":"尽管黄金因其美丽而备受珍视，但如果监管不当，其开采过程会造成严重的生态破坏。"},{"sentence":"Central banks hold substantial gold reserves to ensure financial stability during periods of currency volatility.","translation":"中央银行持有大量黄金储备，以确保在货币波动时期的金融稳定。"},{"sentence":"The athlete's gold medal symbolized not only her personal dedication but also the support of her coaches and family.","translation":"这位运动员的金牌不仅象征着她个人的奉献，也象征着她的教练和家人的支持。"}]},"utmost":{"examples":[{"sentence":"Researchers must exercise the utmost caution when interpreting data from small sample sizes, because such data can easily lead to misleading conclusions.","translation":"研究人员在解释小样本数据时必须极其谨慎，因为此类数据很容易导致误导性的结论。"},{"sentence":"The committee stressed that protecting participants' privacy is of the utmost importance in medical studies, which often involve sensitive personal information.","translation":"委员会强调，保护参与者隐私在医学研究中至关重要，因为这类研究通常涉及敏感的个人信息。"},{"sentence":"To preserve biodiversity, governments should do their utmost to enforce wildlife protection laws, thereby preventing the extinction of endangered species.","translation":"为了保护生物多样性，政府应尽最大努力执行野生动物保护法，从而防止濒危物种的灭绝。"},{"sentence":"In emergency situations, medical staff work to the utmost of their abilities to save lives, despite facing limited resources and high pressure.","translation":"在紧急情况下，医务人员尽最大能力挽救生命，尽管面临有限的资源和高压力。"},{"sentence":"The success of the project depends to the utmost on the cooperation of all team members, because any lack of coordination can cause significant delays.","translation":"该项目的成功极大程度上取决于所有团队成员的合作，因为任何缺乏协调都可能导致严重的延误。"}]},"inherent":{"examples":[{"sentence":"Every individual possesses inherent dignity that must be respected by society and the law, which is a fundamental principle of human rights.","translation":"每个人都拥有固有的尊严，必须受到社会与法律的尊重，这是人权的一项基本原则。"},{"sentence":"The inherent complexity of climate systems makes accurate long-term predictions extremely challenging, because numerous variables interact in nonlinear ways.","translation":"气候系统固有的复杂性使得准确的长期预测极具挑战性，因为众多变量以非线性方式相互作用。"},{"sentence":"Despite its inherent risks, nuclear energy remains a low-carbon alternative to fossil fuels, which can help mitigate climate change if managed safely.","translation":"尽管存在固有的风险，核能仍然是化石燃料的一种低碳替代方案，如果安全管理，它有助于缓解气候变化。"},{"sentence":"The inherent flexibility of online learning allows students to balance education with work and family responsibilities, thereby increasing access to higher education.","translation":"在线学习固有的灵活性使学生能够平衡教育与工作和家庭责任，从而增加了接受高等教育的机会。"},{"sentence":"Because language has an inherent connection to cultural identity, preserving minority languages is essential for cultural diversity, which enriches global heritage.","translation":"由于语言与文化认同有着固有的联系，保护少数民族语言对于文化多样性至关重要，这丰富了全球遗产。"}]},"soda":{"examples":[{"sentence":"Excessive consumption of soda has been linked to an increased risk of metabolic disorders, which has prompted many public health campaigns to advocate for reduced intake.","translation":"过量饮用苏打水与代谢紊乱风险增加有关，这促使许多公共卫生运动倡导减少摄入。"},{"sentence":"Although soda is often marketed as a refreshing beverage, its high sugar content can undermine dietary goals when consumed regularly.","translation":"尽管苏打水常被宣传为清爽饮品，但若经常饮用，其高糖分会破坏饮食目标。"},{"sentence":"Researchers who study dietary patterns have found that replacing soda with water significantly lowers daily calorie intake.","translation":"研究饮食模式的研究人员发现，用水代替苏打水能显著降低每日热量摄入。"},{"sentence":"Because soda lacks essential nutrients, nutritionists recommend that it be treated as an occasional treat rather than a daily staple.","translation":"由于苏打水缺乏必需营养素，营养学家建议将其视为偶尔的享受，而非日常必需品。"},{"sentence":"In many school districts, vending machines that sell soda have been removed in an effort to promote healthier student lifestyles.","translation":"在许多学区，售卖苏打水的自动售货机已被移除，以促进学生更健康的生活方式。"}]},"spend":{"examples":[{"sentence":"Governments that spend a higher proportion of their budget on education tend to see long-term improvements in economic competitiveness.","translation":"将更高比例预算用于教育的政府，往往会看到经济竞争力的长期提升。"},{"sentence":"While it is tempting to spend leisure time on passive entertainment, engaging in active hobbies can yield greater psychological benefits.","translation":"虽然人们容易将闲暇时间花在被动的娱乐上，但参与积极的爱好能带来更大的心理益处。"},{"sentence":"Companies that spend resources on employee well-being often experience lower turnover rates and higher productivity.","translation":"将资源用于员工福祉的公司，通常能经历更低的离职率和更高的生产力。"},{"sentence":"To master a complex skill, one must spend countless hours in deliberate practice, which involves focused repetition and immediate feedback.","translation":"要掌握一项复杂技能，必须花费无数小时进行刻意练习，这包括专注的重复和即时反馈。"},{"sentence":"Because time is a finite resource, how we choose to spend it ultimately defines the trajectory of our personal and professional lives.","translation":"因为时间是有限资源，我们选择如何花费它，最终决定了我们个人和职业生活的轨迹。"}]},"ladder":{"examples":[{"sentence":"Although the firefighter ascended the ladder swiftly, the intense heat made the rescue operation extremely perilous.","translation":"尽管消防员迅速爬上梯子，但高温使救援行动极其危险。"},{"sentence":"Because the ladder was not properly secured, it slipped on the smooth floor, which caused the painter to fall.","translation":"由于梯子没有固定好，它在光滑的地板上滑倒，导致油漆工摔了下来。"},{"sentence":"When using a ladder to reach high shelves, one should always maintain three points of contact to ensure stability.","translation":"当使用梯子够高处架子时，应始终保持三点接触以确保稳定。"},{"sentence":"The aluminum ladder, which was lightweight yet sturdy, proved indispensable for the construction workers who needed to access the roof.","translation":"这款铝制梯子轻便而坚固，对于需要上屋顶的建筑工人来说不可或缺。"},{"sentence":"If you extend the ladder beyond its recommended height, you risk compromising its structural integrity and your own safety.","translation":"如果你将梯子延伸到超过推荐高度，就可能损害其结构完整性并危及自身安全。"}]},"efficiency":{"examples":[{"sentence":"By streamlining the approval process, the agency significantly improved its operational efficiency without compromising service quality.","translation":"通过简化审批流程，该机构在未降低服务质量的情况下显著提高了运营效率。"},{"sentence":"Although automation can boost production efficiency, it also requires workers to acquire new technical skills.","translation":"虽然自动化可以提高生产效率，但它也要求工人掌握新的技术技能。"},{"sentence":"Investing in employee training is a long-term strategy that enhances overall organizational efficiency.","translation":"投资于员工培训是一项长期战略，能够提升组织的整体效能。"},{"sentence":"The new software reduced data processing time by half, demonstrating that technological upgrades can dramatically increase efficiency.","translation":"新软件将数据处理时间缩短了一半，表明技术升级可以大幅提高效率。"},{"sentence":"Because energy efficiency lowers operating costs and reduces environmental impact, many governments now offer incentives for green building design.","translation":"由于能源效率能降低运营成本并减少环境影响，许多政府现在为绿色建筑设计提供激励措施。"}]},"mysterious":{"examples":[{"sentence":"Although the ancient temple was built with remarkable precision, its purpose remains mysterious to modern archaeologists.","translation":"尽管这座古庙建造得异常精确，但其用途对现代考古学家来说仍然神秘莫测。"},{"sentence":"The company's sudden bankruptcy was caused by a series of mysterious financial transactions that auditors failed to detect.","translation":"该公司的突然破产是由一系列审计师未能发现的神秘金融交易引起的。"},{"sentence":"Because the disease spread in a mysterious pattern, epidemiologists had to employ advanced modeling to identify its source.","translation":"由于该疾病以神秘的模式传播，流行病学家不得不采用先进的建模来确定其来源。"},{"sentence":"The novelist created a mysterious atmosphere by describing the foggy streets in vivid detail, which captivated readers from the first page.","translation":"小说家通过生动地描述雾蒙蒙的街道营造出一种神秘的氛围，从第一页就吸引了读者。"},{"sentence":"While the experiment yielded consistent results, the underlying mechanism remained mysterious, prompting further investigation.","translation":"虽然实验产生了一致的结果，但其潜在机制仍然神秘，促使人们进一步研究。"}]},"trace":{"examples":[{"sentence":"Despite extensive cleaning, a faint trace of the original paint remained on the wall.","translation":"尽管进行了彻底清洁，墙上仍残留着原漆的淡淡痕迹。"},{"sentence":"The investigation uncovered a trace of financial misconduct that had been overlooked for years.","translation":"调查发现了一处多年来被忽视的财务不当行为的痕迹。"},{"sentence":"Because the sample contained only a trace of the compound, repeated experiments were required to confirm the result.","translation":"由于样本中仅含有微量的该化合物，需要重复实验来确认结果。"},{"sentence":"Although the ancient manuscript was badly damaged, scholars managed to trace its origins to a 12th-century monastery.","translation":"尽管古代手稿严重受损，学者们仍设法将其起源追溯至一座12世纪的修道院。"},{"sentence":"When researchers trace the evolution of language, they often rely on both archaeological findings and genetic data.","translation":"当研究人员追溯语言的演变时，他们通常依赖考古发现和遗传数据。"}]},"cattle":{"examples":[{"sentence":"Although cattle are often associated with pastoral landscapes, their breeding has become a highly industrialized process in many countries.","translation":"尽管牛通常与田园风光联系在一起，但在许多国家，牛的养殖已成为高度工业化的过程。"},{"sentence":"Because cattle produce significant amounts of methane, researchers are exploring dietary supplements that can reduce these emissions.","translation":"由于牛产生大量甲烷，研究人员正在探索能够减少这些排放的饲料添加剂。"},{"sentence":"The nomadic tribes relied on their cattle not only for milk and meat but also as a form of currency in trade.","translation":"游牧部落不仅依赖牛获取牛奶和肉，还将其作为贸易中的一种货币形式。"},{"sentence":"When a severe drought struck the region, many farmers were forced to sell their cattle at a loss to survive.","translation":"当严重干旱袭击该地区时，许多农民被迫亏本出售牛以求生存。"},{"sentence":"The ancient cave paintings depict cattle with remarkable detail, which suggests that these animals held great cultural significance.","translation":"古代洞穴壁画以惊人的细节描绘了牛，这表明这些动物具有重要的文化意义。"}]},"certainty":{"examples":[{"sentence":"Although the initial data suggested a clear trend, the researchers could not state with certainty that the correlation implied causation.","translation":"尽管初步数据显示出明显的趋势，但研究人员无法确定地说这种相关性意味着因果关系。"},{"sentence":"The legal requirement that evidence must establish guilt beyond a reasonable doubt reflects a societal commitment to moral certainty before depriving someone of liberty.","translation":"法律要求证据必须排除合理怀疑地证明有罪，这反映了社会在剥夺他人自由之前对道德确定性的承诺。"},{"sentence":"Because the historical record contains gaps, scholars often replace the pursuit of absolute certainty with a careful weighing of probabilities.","translation":"由于历史记录存在空白，学者们常常用对概率的仔细权衡来取代对绝对确定性的追求。"},{"sentence":"The confidence with which a forecast is issued should match the scientific certainty behind it, yet media reports frequently exaggerate the level of agreement among experts.","translation":"发布预测时的信心程度应与背后的科学确定性相匹配，然而媒体报道经常夸大专家之间的一致程度。"},{"sentence":"In an era of rapid technological change, the only certainty is that the skills valued today may become obsolete within a decade.","translation":"在技术快速变革的时代，唯一确定的是今天受重视的技能可能在十年内过时。"}]},"delay":{"examples":[{"sentence":"The construction project faced a significant delay because the geological survey revealed unstable soil that required additional reinforcement.","translation":"建设项目面临严重延误，因为地质勘测显示土壤不稳定，需要额外加固。"},{"sentence":"Although the software update was meant to improve security, the unexpected delay in its release left users vulnerable to the newly discovered exploit for several weeks.","translation":"尽管软件更新旨在提高安全性，但其发布的意外延迟让用户在新漏洞被发现后的几周内仍处于脆弱状态。"},{"sentence":"A brief delay in the supply chain can cascade into a prolonged shortage when manufacturers rely on just-in-time inventory systems.","translation":"当制造商依赖准时制库存系统时，供应链中的短暂延迟可能演变成长期的短缺。"},{"sentence":"The committee decided to delay the vote on the proposal so that members could consult with stakeholders and review the fiscal implications more thoroughly.","translation":"委员会决定推迟对该提案的投票，以便成员们能够咨询利益相关者并更彻底地审查财政影响。"},{"sentence":"While a short delay in responding to emails may seem trivial, it can erode trust in professional relationships when it becomes a consistent pattern.","translation":"虽然回复邮件的短暂延迟看似微不足道，但当它成为一种持续的模式时，可能会侵蚀职业关系中的信任。"}]},"population":{"examples":[{"sentence":"Because the global population is projected to reach nearly ten billion by 2050, sustainable food production has become an urgent priority.","translation":"由于全球人口预计到2050年将达到近100亿，可持续粮食生产已成为当务之急。"},{"sentence":"An aging population, which is a common trend in developed nations, necessitates reforms in pension systems and healthcare infrastructure.","translation":"人口老龄化是发达国家的普遍趋势，它要求对养老金制度和医疗基础设施进行改革。"},{"sentence":"Although the total population continues to grow, the rate of increase has slowed significantly in regions with higher levels of education.","translation":"尽管总人口持续增长，但在教育水平较高的地区，增长率已显著放缓。"},{"sentence":"To address the challenges of a declining working-age population, some countries have implemented policies that encourage immigration.","translation":"为了应对劳动年龄人口下降的挑战，一些国家实施了鼓励移民的政策。"},{"sentence":"The census data revealed that a substantial proportion of the rural population lacks access to clean drinking water, which exacerbates health disparities.","translation":"人口普查数据显示，相当大比例的农村人口缺乏清洁饮用水，这加剧了健康差距。"}]},"busy":{"examples":[{"sentence":"While the marketing team was busy preparing the product launch, the competitors unexpectedly released a similar device.","translation":"当营销团队忙于准备产品发布时，竞争对手出人意料地发布了一款类似设备。"},{"sentence":"The emergency room is always busy during flu season, which puts a strain on hospital resources.","translation":"流感季节急诊室总是很繁忙，这给医院资源带来了压力。"},{"sentence":"Although she is busy with her doctoral dissertation, she still volunteers at the local community center every weekend.","translation":"尽管她忙于博士论文，她每个周末仍在当地社区中心做志愿者。"},{"sentence":"The construction crew has been busy reinforcing the bridge, because the recent inspection revealed structural weaknesses.","translation":"施工队一直忙于加固桥梁，因为最近的检查发现了结构弱点。"},{"sentence":"If you are too busy to attend the meeting, please delegate your vote to a trusted colleague.","translation":"如果你太忙无法参加会议，请将你的投票权委托给一位值得信赖的同事。"}]},"financial":{"examples":[{"sentence":"The financial crisis of 2008 demonstrated that excessive risk-taking by banks can destabilize the entire global economy.","translation":"2008年的金融危机表明，银行过度冒险会破坏整个全球经济的稳定。"},{"sentence":"Because the company's financial statements were audited by an independent firm, investors regained confidence in its management.","translation":"由于公司的财务报表由独立公司审计，投资者对其管理层恢复了信心。"},{"sentence":"Many students rely on financial aid to pursue higher education, which underscores the need for accessible scholarship programs.","translation":"许多学生依靠经济援助接受高等教育，这凸显了提供可获得的奖学金项目的必要性。"},{"sentence":"The government implemented strict financial regulations to prevent money laundering, thereby enhancing the integrity of the banking system.","translation":"政府实施了严格的金融法规以防止洗钱，从而增强了银行系统的诚信。"},{"sentence":"Effective financial planning requires not only setting long-term goals but also regularly reviewing and adjusting one's budget.","translation":"有效的财务规划不仅需要设定长期目标，还需要定期审查和调整预算。"}]},"appal":{"examples":[{"sentence":"Although the committee anticipated some public resistance, the severity of the backlash continues to appal its members.","translation":"尽管委员会预料到会有一些公众抵制，但抵制的严重程度仍令其成员感到惊骇。"},{"sentence":"Because the documentary exposed systemic corruption, it will appal viewers who trusted the integrity of the institution.","translation":"因为这部纪录片揭露了系统性的腐败，它将使那些相信该机构诚信的观众感到震惊。"},{"sentence":"While the company promoted its green image, the revelation of toxic dumping will appal environmentally conscious consumers.","translation":"尽管该公司宣传其绿色形象，但有毒废物倾倒的揭露将使有环保意识的消费者感到惊骇。"},{"sentence":"The humanitarian crisis continues to appal the international community, which has struggled to deliver aid effectively.","translation":"人道主义危机持续令国际社会感到震惊，而国际社会一直在努力有效地提供援助。"},{"sentence":"If the government ignores the report on police brutality, it will appal civil rights activists who demand accountability.","translation":"如果政府忽视关于警察暴行的报告，这将使要求问责的民权活动人士感到惊骇。"}]},"director":{"examples":[{"sentence":"Although the director faced budget constraints, she managed to produce a film that won critical acclaim.","translation":"尽管导演面临预算限制，她还是成功制作了一部赢得评论界赞誉的电影。"},{"sentence":"Because the director of the institute prioritized interdisciplinary research, the team made groundbreaking discoveries.","translation":"因为研究所所长优先考虑跨学科研究，该团队取得了突破性的发现。"},{"sentence":"While the board of directors debated the merger, the managing director focused on maintaining employee morale.","translation":"当董事会讨论合并事宜时，总经理专注于保持员工士气。"},{"sentence":"The director of the nonprofit organization implemented a strategy that expanded its reach to underserved communities.","translation":"该非营利组织的负责人实施了一项战略，将其服务范围扩大到服务不足的社区。"},{"sentence":"As the director of the orchestra, she chose a program that blended traditional symphonies with modern compositions.","translation":"作为管弦乐团的指挥，她选择了一个将传统交响乐与现代作品融合的节目。"}]},"courtyard":{"examples":[{"sentence":"The courtyard, which was paved with weathered flagstones, offered a quiet retreat from the bustling city streets.","translation":"铺着风化石板的庭院为人们提供了一个远离喧嚣城市街道的安静休憩之所。"},{"sentence":"Because the courtyard garden was designed with drought-resistant plants, it required minimal irrigation even during the dry season.","translation":"由于庭院花园采用了耐旱植物设计，即使在旱季也只需很少的灌溉。"},{"sentence":"Although the building's facade appeared austere, its inner courtyard revealed an unexpected lushness of climbing roses and jasmine.","translation":"尽管建筑的外立面显得朴素，其内部庭院却展现出攀援玫瑰和茉莉意想不到的繁茂。"},{"sentence":"The courtyard served as a communal space where residents gathered for celebrations, thereby strengthening the social fabric of the neighborhood.","translation":"庭院作为一个公共空间，居民们在此聚集庆祝，从而增强了邻里的社会凝聚力。"},{"sentence":"Scholars have noted that the traditional courtyard house, by integrating open and enclosed areas, creates a microclimate that moderates temperature extremes.","translation":"学者们注意到，传统庭院住宅通过融合开放与封闭区域，创造出一种调节极端温度的微气候。"}]},"meeting":{"examples":[{"sentence":"Although the meeting was scheduled to last only one hour, it extended well into the afternoon because several critical issues required further discussion.","translation":"尽管会议原定只持续一小时，但由于几个关键问题需要进一步讨论，会议一直延长到下午。"},{"sentence":"The chairperson opened the meeting by summarizing the previous session's outcomes, which helped to ensure that all participants were aligned on the agenda.","translation":"主席在会议开始时总结了上次会议的成果，这有助于确保所有与会者对议程达成一致。"},{"sentence":"Because the quarterly review meeting revealed a significant decline in sales, the management team decided to implement a new marketing strategy immediately.","translation":"由于季度审查会议显示销售额大幅下降，管理团队决定立即实施新的营销策略。"},{"sentence":"When the international summit meeting concluded, the delegates issued a joint statement that emphasized the need for collaborative efforts to combat climate change.","translation":"当国际峰会会议结束时，代表们发表了一份联合声明，强调需要共同努力应对气候变化。"},{"sentence":"The project team held a virtual meeting to coordinate their tasks, thereby reducing the need for frequent email exchanges and improving overall efficiency.","translation":"项目团队举行了一次虚拟会议来协调任务，从而减少了频繁的电子邮件往来，提高了整体效率。"}]},"disguise":{"examples":[{"sentence":"Beneath a disguise of generosity, the policy actually served to concentrate power among a small elite, which ultimately undermined democratic processes.","translation":"在慷慨的伪装下，该政策实际上是为了将权力集中在一小部分精英手中，这最终破坏了民主进程。"},{"sentence":"The researcher argued that the so-called reform was merely a disguise for cutting essential public services, thereby harming the most vulnerable citizens.","translation":"这位研究者认为，所谓的改革只不过是削减基本公共服务的幌子，从而伤害了最脆弱的公民。"},{"sentence":"Although the proposal came in the disguise of environmental protection, its primary goal was to secure commercial advantages for a few corporations.","translation":"尽管该提案以环境保护为伪装，但其主要目标是为少数公司获取商业利益。"},{"sentence":"A thin disguise of politeness often conceals deep-seated prejudice in professional settings, which can hinder genuine collaboration and innovation.","translation":"在职业环境中，一层薄薄的礼貌伪装往往掩盖着根深蒂固的偏见，这会阻碍真正的合作与创新。"},{"sentence":"The historian noted that many authoritarian regimes use the disguise of national security to suppress dissent, while simultaneously eroding civil liberties.","translation":"这位历史学家指出，许多威权政权利用国家安全的伪装来压制异议，同时侵蚀公民自由。"}]},"disregard":{"examples":[{"sentence":"The company's persistent disregard for safety regulations eventually led to a catastrophic accident, which could have been prevented through stricter oversight.","translation":"该公司对安全法规的持续漠视最终导致了一场灾难性事故，这本可以通过更严格的监督来避免。"},{"sentence":"Because of a widespread disregard for intellectual property rights, many innovators are reluctant to share their discoveries, thereby slowing technological progress.","translation":"由于对知识产权的普遍漠视，许多创新者不愿分享他们的发现，从而减缓了技术进步。"},{"sentence":"The official's blatant disregard for ethical standards eroded public trust in the entire institution, which took years to rebuild.","translation":"该官员对道德标准的公然漠视侵蚀了公众对整个机构的信任，这花了多年时间才得以重建。"},{"sentence":"A disregard for historical context often results in policies that repeat past mistakes rather than solving current problems, as seen in several recent legislative failures.","translation":"对历史背景的漠视往往导致政策重蹈覆辙，而不是解决当前问题，这在最近的几次立法失败中可见一斑。"},{"sentence":"While some view the disregard of traditional customs as progress, others see it as a loss of cultural identity that may have long-term social consequences.","translation":"虽然有些人将漠视传统习俗视为进步，但另一些人则认为这是文化认同的丧失，可能会产生长期的社会后果。"}]},"bullet":{"examples":[{"sentence":"The forensic report confirmed that a single bullet had caused the fatal injury.","translation":"法医报告证实，一颗子弹造成了致命伤。"},{"sentence":"Although the bullet was removed successfully, the patient still required weeks of rehabilitation.","translation":"虽然子弹被成功取出，但患者仍需要数周的康复治疗。"},{"sentence":"Modern body armor is designed to stop a bullet without compromising the wearer's mobility.","translation":"现代防弹衣的设计旨在阻挡子弹而不影响穿戴者的灵活性。"},{"sentence":"Historians argue that the invention of the bullet fundamentally changed the nature of warfare.","translation":"历史学家认为，子弹的发明从根本上改变了战争的性质。"},{"sentence":"Because the bullet fragmented upon impact, surgeons had to remove multiple tiny fragments from the wound.","translation":"由于子弹在撞击时碎裂，外科医生不得不从伤口中取出多个微小碎片。"}]},"steward":{"examples":[{"sentence":"As a steward of the company's resources, the CFO must balance risk and opportunity to ensure long-term growth.","translation":"作为公司资源的管理者，首席财务官必须平衡风险与机遇，以确保长期增长。"},{"sentence":"The steward on the train efficiently managed the dining car, which enhanced the overall travel experience for passengers.","translation":"火车上的乘务员高效地管理餐车，这提升了乘客的整体旅行体验。"},{"sentence":"Because the environmental steward advocated for stricter regulations, the local ecosystem began to recover.","translation":"因为环境管理者倡导更严格的法规，当地生态系统开始恢复。"},{"sentence":"In the absence of a dedicated steward, the estate fell into disrepair, which illustrates the importance of responsible management.","translation":"由于缺乏专门的管家，庄园年久失修，这说明了负责任管理的重要性。"},{"sentence":"The chief steward coordinated the event with such precision that every guest felt welcomed and attended to.","translation":"总管事如此精确地协调了活动，以至于每位客人都感到受欢迎和照顾。"}]},"slope":{"examples":[{"sentence":"Although the slope of the hill was gentle, the loose soil made construction challenging for the engineers.","translation":"尽管山坡的坡度平缓，但松散的土壤使工程师的施工充满挑战。"},{"sentence":"The slope of the regression line indicates a strong positive correlation, which suggests that higher education leads to increased earnings.","translation":"回归线的斜率表明强烈的正相关，这表明更高的教育导致收入增加。"},{"sentence":"Because the slope faces north, it receives less sunlight, which makes it ideal for growing certain shade-tolerant crops.","translation":"因为斜坡朝北，它接收的阳光较少，这使其成为种植某些耐阴作物的理想选择。"},{"sentence":"When skiing down a steep slope, one must maintain a low center of gravity to avoid losing control.","translation":"当从陡峭的斜坡上滑雪下来时，必须保持低重心以避免失控。"},{"sentence":"The architect designed the roof with a slight slope, thereby ensuring efficient water drainage during heavy rains.","translation":"建筑师设计了带有轻微坡度的屋顶，从而确保大雨时高效排水。"}]},"exaggerate":{"examples":[{"sentence":"Although it is tempting to exaggerate one's accomplishments during a job interview, honesty tends to build more sustainable professional relationships.","translation":"尽管在求职面试中夸大自己的成就很诱人，但诚实往往能建立更可持续的职业关系。"},{"sentence":"Because some advertisements exaggerate the benefits of dietary supplements, consumers should consult scientific studies before making purchases.","translation":"由于一些广告夸大了膳食补充剂的好处，消费者在购买前应查阅科学研究。"},{"sentence":"When historians exaggerate the role of a single individual, they risk overlooking the broader social forces that shaped events.","translation":"当历史学家夸大单一个体的作用时，他们可能会忽视塑造事件的更广泛社会力量。"},{"sentence":"The tendency to exaggerate the severity of a problem can lead to unnecessary panic, which is why clear communication is essential in crisis management.","translation":"夸大问题严重性的倾向可能导致不必要的恐慌，这就是为什么在危机管理中清晰沟通至关重要。"},{"sentence":"While it is common for children to exaggerate their fears to gain attention, parents can foster resilience by acknowledging emotions without reinforcing the exaggeration.","translation":"虽然儿童常通过夸大恐惧来获取关注，但父母可以通过承认情绪而不强化这种夸大来培养韧性。"}]},"impulse":{"examples":[{"sentence":"Although the impulse to procrastinate is universal, breaking tasks into smaller steps can help maintain productivity.","translation":"尽管拖延的冲动普遍存在，但将任务分解为更小的步骤有助于保持生产力。"},{"sentence":"Because the impulse to spend often intensifies during holiday seasons, creating a budget beforehand is a prudent strategy.","translation":"由于消费冲动在节假日期间往往会加剧，提前制定预算是一种审慎的策略。"},{"sentence":"When researchers examined the neural basis of decision-making, they found that impulse control relies heavily on the prefrontal cortex.","translation":"当研究人员检查决策的神经基础时，他们发现冲动控制很大程度上依赖于前额叶皮层。"},{"sentence":"The impulse to help others in distress is a fundamental aspect of human nature, which can be strengthened through community engagement.","translation":"帮助处于困境中他人的冲动是人类本性的一个基本方面，可以通过社区参与来加强。"},{"sentence":"Rather than acting on every creative impulse, successful innovators channel their ideas through a rigorous process of testing and refinement.","translation":"成功的创新者不会对每一个创造性冲动都采取行动，而是通过严格的测试和完善过程来引导他们的想法。"}]},"generate":{"examples":[{"sentence":"Investing in renewable energy infrastructure can generate long-term economic benefits while reducing dependence on fossil fuels.","translation":"投资可再生能源基础设施可以产生长期经济效益，同时减少对化石燃料的依赖。"},{"sentence":"Although artificial intelligence can generate creative content, it still lacks the emotional depth that human artists provide.","translation":"尽管人工智能可以生成创意内容，但它仍然缺乏人类艺术家所提供的情感深度。"},{"sentence":"Effective marketing campaigns generate consumer interest by highlighting unique product features, which ultimately boosts sales.","translation":"有效的营销活动通过突出独特的产品功能来激发消费者兴趣，最终提高销售额。"},{"sentence":"Because urban green spaces generate numerous health benefits, city planners should prioritize their development in crowded areas.","translation":"由于城市绿地能产生许多健康益处，城市规划者应优先在拥挤地区发展绿地。"},{"sentence":"Collaborative research projects often generate breakthrough ideas that no single researcher could develop alone.","translation":"合作研究项目常常产生突破性的想法，这些想法是任何单个研究人员无法独自开发的。"}]},"fan":{"examples":[{"sentence":"As a devoted fan of the author, she has collected every novel that he has published.","translation":"作为这位作者的忠实粉丝，她收集了他出版的每一部小说。"},{"sentence":"The cooling system, which includes a powerful fan, ensures that the server room does not overheat.","translation":"冷却系统包括一个强力风扇，确保服务器机房不会过热。"},{"sentence":"Although he is an ardent fan of the team, he criticizes their lack of strategic planning.","translation":"尽管他是这支球队的狂热粉丝，但他批评他们缺乏战略规划。"},{"sentence":"The documentary sparked a fan movement that advocated for environmental conservation.","translation":"这部纪录片引发了一场倡导环境保护的粉丝运动。"},{"sentence":"Because the ceiling fan was not sufficient, they installed an additional air conditioning unit.","translation":"由于吊扇不够用，他们又安装了一台空调。"}]},"legal":{"examples":[{"sentence":"Although the new regulation imposes strict limits, it provides a legal framework that protects consumers from predatory lending.","translation":"尽管新规施加了严格限制，但它提供了一个保护消费者免受掠夺性贷款侵害的法律框架。"},{"sentence":"Because the company failed to obtain the necessary permits, its operations were deemed not legal and were immediately suspended.","translation":"由于该公司未能获得必要的许可证，其运营被视为不合法并被立即暂停。"},{"sentence":"The legal dispute over intellectual property rights, which lasted for years, ultimately stifled innovation in the entire industry.","translation":"这场持续多年的知识产权法律纠纷，最终扼杀了整个行业的创新。"},{"sentence":"While the practice is legal in some countries, it remains heavily regulated to prevent potential abuse and exploitation.","translation":"尽管这种做法在一些国家是合法的，但它仍受到严格监管以防止潜在的滥用和剥削。"},{"sentence":"Governments must ensure that legal aid is accessible to all citizens, thereby upholding the principle of equality before the law.","translation":"政府必须确保所有公民都能获得法律援助，从而维护法律面前人人平等的原则。"}]},"underlying":{"examples":[{"sentence":"Addressing the underlying causes of social unrest requires a comprehensive approach that goes beyond short-term measures.","translation":"解决社会动荡的根本原因需要一种超越短期措施的综合性方法。"},{"sentence":"The underlying assumption of the study is that cognitive development is shaped by both genetic and environmental factors.","translation":"该研究的基本假设是，认知发展由遗传和环境因素共同塑造。"},{"sentence":"Although the symptoms were treated effectively, the underlying disease continued to progress unnoticed.","translation":"虽然症状得到了有效治疗，但潜在的疾病仍在不知不觉中继续发展。"},{"sentence":"A thorough analysis of the data revealed an underlying pattern that had previously been overlooked.","translation":"对数据的彻底分析揭示了一个之前被忽视的潜在模式。"},{"sentence":"The underlying principle of the policy is that equal access to education can reduce long-term inequality.","translation":"该政策的基本原则是，平等的教育机会可以减少长期的不平等。"}]},"gulf":{"examples":[{"sentence":"Although the two leaders share a common goal, a deep gulf in their negotiation styles prevents them from reaching an agreement.","translation":"尽管两位领导人有着共同的目标，但谈判风格上的深刻鸿沟阻碍了他们达成协议。"},{"sentence":"The economic gulf between developed and developing nations continues to widen, which poses a threat to global stability.","translation":"发达国家与发展中国家之间的经济鸿沟继续扩大，这对全球稳定构成了威胁。"},{"sentence":"Because a cultural gulf often exists between immigrants and local residents, community integration programs are essential.","translation":"由于移民和当地居民之间常常存在文化鸿沟，社区融合项目至关重要。"},{"sentence":"The report highlights a growing gulf in educational attainment among different socioeconomic groups, thereby calling for urgent policy reforms.","translation":"报告强调了不同社会经济群体之间教育成就方面日益扩大的鸿沟，从而呼吁紧急的政策改革。"},{"sentence":"When a gulf in communication arises within a team, productivity declines unless effective mediation is introduced.","translation":"当团队内部出现沟通鸿沟时，生产力就会下降，除非引入有效的调解。"}]},"fringe":{"examples":[{"sentence":"Although fringe benefits such as flexible hours are often overlooked, they significantly improve employee satisfaction.","translation":"尽管弹性工作时间等附加福利常被忽视，但它们显著提高了员工满意度。"},{"sentence":"The company decided to invest in fringe technologies, which may not yield immediate profits but could secure long-term competitiveness.","translation":"公司决定投资于边缘技术，这些技术可能不会立即产生利润，但能确保长期竞争力。"},{"sentence":"Because the proposal originated from a fringe group within the organization, it initially faced strong resistance from senior management.","translation":"由于该提案源自组织内的一个边缘团体，它最初遭到了高级管理层的强烈抵制。"},{"sentence":"While mainstream economists dismissed the theory, a fringe of academics continued to explore its potential applications.","translation":"尽管主流经济学家否定了这一理论，但一小部分边缘学者继续探索其潜在应用。"},{"sentence":"The artist's work, which incorporates fringe elements from various cultures, challenges conventional aesthetic norms.","translation":"这位艺术家的作品融合了来自不同文化的边缘元素，挑战了传统审美规范。"}]},"leather":{"examples":[{"sentence":"Because leather is a byproduct of the meat industry, its production raises complex ethical questions about animal welfare.","translation":"由于皮革是肉类工业的副产品，其生产引发了关于动物福利的复杂伦理问题。"},{"sentence":"The durability of leather, which makes it ideal for furniture, also contributes to its environmental impact when discarded.","translation":"皮革的耐用性使其成为家具的理想材料，但废弃时也会加剧环境影响。"},{"sentence":"Although synthetic alternatives are cheaper, genuine leather remains popular among consumers who value authenticity and craftsmanship.","translation":"尽管合成替代品更便宜，但真皮在重视真实性和工艺的消费者中仍然很受欢迎。"},{"sentence":"The leather industry, which employs millions worldwide, must adopt cleaner production methods to reduce water pollution.","translation":"全球雇佣数百万人的皮革行业必须采用更清洁的生产方法以减少水污染。"},{"sentence":"When properly treated, leather can last for decades, thereby reducing the need for frequent replacements and conserving resources.","translation":"经过适当处理后，皮革可以使用数十年，从而减少频繁更换的需求并节约资源。"}]},"fancy":{"examples":[{"sentence":"Although the idea of time travel captures the public fancy, physicists argue that it remains a theoretical impossibility under current models.","translation":"尽管时间旅行的想法吸引了公众的幻想，但物理学家认为，在现有模型下它仍然在理论上不可能。"},{"sentence":"The novelist's work blends historical fact with imaginative fancy, which allows readers to explore complex themes through a captivating narrative.","translation":"这位小说家的作品将历史事实与富有想象力的幻想融合在一起，这使得读者能够通过引人入胜的叙事探索复杂的主题。"},{"sentence":"Because the startup's business plan was based on wishful fancy rather than market research, it failed to attract serious investors.","translation":"由于这家初创公司的商业计划基于一厢情愿的幻想而非市场研究，它未能吸引到认真的投资者。"},{"sentence":"While children often indulge in flights of fancy, educators can channel this creativity into productive learning experiences through structured activities.","translation":"虽然孩子们经常沉溺于天马行空的幻想，但教育工作者可以通过结构化的活动将这种创造力引导到富有成效的学习体验中。"},{"sentence":"The architect's fancy for Gothic ornamentation is evident in the building's intricate stonework, which distinguishes it from the surrounding modern structures.","translation":"建筑师对哥特式装饰的喜好体现在建筑复杂的石雕工艺上，这使其从周围的现代建筑中脱颖而出。"}]},"rib":{"examples":[{"sentence":"The X-ray revealed a hairline fracture on the fifth rib, which required the patient to avoid strenuous activity for at least six weeks.","translation":"X光片显示第五根肋骨有细微骨折，这要求患者至少六周内避免剧烈活动。"},{"sentence":"In Gothic architecture, the rib vault is a key structural element that distributes weight and allows for taller, more light-filled cathedrals.","translation":"在哥特式建筑中，肋架拱顶是一个关键的结构元素，它分散重量并允许建造更高、更明亮的教堂。"},{"sentence":"Although the chef's braised short rib was praised for its tenderness, the accompanying sauce lacked the depth of flavor expected at a fine-dining establishment.","translation":"尽管厨师的红烧牛小排因肉质鲜嫩而受到称赞，但搭配的酱汁缺乏高级餐厅所期望的风味层次。"},{"sentence":"The umbrella's broken rib made it impossible to close properly, so she had to discard it despite the otherwise durable fabric.","translation":"雨伞的伞骨断了，导致无法正常合拢，因此尽管伞布还很耐用，她也不得不把它扔掉。"},{"sentence":"During the team-building exercise, colleagues would good-naturedly rib each other about their mistakes, which fostered a sense of camaraderie and mutual trust.","translation":"在团队建设活动中，同事们会善意地互相取笑对方的错误，这培养了一种同事情谊和相互信任。"}]},"glad":{"examples":[{"sentence":"Scholars are often glad to share their findings when they believe the research can benefit the wider community.","translation":"当学者们相信研究能惠及更广泛的群体时，他们通常乐于分享自己的发现。"},{"sentence":"Although the internship was unpaid, she was glad to accept it because the experience proved invaluable for her career.","translation":"尽管实习没有报酬，她还是欣然接受了，因为这段经历对她的职业发展极为宝贵。"},{"sentence":"Local residents were glad that the new environmental policy reduced air pollution significantly within just two years.","translation":"当地居民感到高兴的是，新环保政策在短短两年内就显著减少了空气污染。"},{"sentence":"He would be glad to mentor junior colleagues, provided that they demonstrate genuine commitment to professional growth.","translation":"只要初级同事表现出对职业成长的真诚投入，他会很乐意指导他们。"},{"sentence":"The committee was glad to see that the revised proposal addressed all the concerns raised during the previous meeting.","translation":"委员会欣慰地看到，修订后的提案解决了上次会议提出的所有关切。"}]},"valid":{"examples":[{"sentence":"Although the contract was signed under pressure, the court ruled that it was not valid because mutual consent was absent.","translation":"尽管合同是在压力下签署的，法院裁定其无效，因为缺乏双方同意。"},{"sentence":"The scientist emphasized that the conclusion is valid only when the experiment is conducted under controlled conditions.","translation":"科学家强调，只有在受控条件下进行实验时，该结论才有效。"},{"sentence":"Because the passport is valid for another ten years, she can travel internationally without renewing it.","translation":"因为护照还有十年有效期，她无需续签即可国际旅行。"},{"sentence":"The coupon is valid until the end of this month, which means you should use it before it expires.","translation":"这张优惠券有效期至本月底，这意味着你应该在过期前使用它。"},{"sentence":"While the theory seems plausible, it is not scientifically valid unless it is supported by empirical evidence.","translation":"虽然该理论看似合理，但除非有实证支持，否则它在科学上不成立。"}]},"genius":{"examples":[{"sentence":"Although he was a genius in theoretical physics, his inability to communicate ideas limited his influence.","translation":"尽管他在理论物理方面是个天才，但他无法传达思想限制了他的影响力。"},{"sentence":"The company's success was driven by a collective genius that emerged when diverse experts collaborated.","translation":"公司的成功是由一种集体天才驱动的，这种天才在不同专家合作时显现。"},{"sentence":"Because her artistic genius was not confined to a single medium, she excelled in both painting and sculpture.","translation":"因为她的艺术天赋不局限于单一媒介，她在绘画和雕塑方面都表现出色。"},{"sentence":"The child's genius for languages became evident when she mastered three foreign tongues by the age of ten.","translation":"这个孩子的语言天赋在她十岁掌握三门外语时变得明显。"},{"sentence":"While many associate genius with innate talent, deliberate practice plays a crucial role in exceptional achievement.","translation":"虽然许多人将天才与先天才能联系起来，但刻意练习在卓越成就中起着关键作用。"}]},"quartz":{"examples":[{"sentence":"Geologists often rely on quartz veins to trace the thermal history of a region because this mineral remains stable under a wide range of conditions.","translation":"地质学家常常依靠石英脉来追溯一个地区的热历史，因为这种矿物在多种条件下都能保持稳定。"},{"sentence":"The precision of the laboratory balance was enhanced by a quartz crystal sensor, which minimized measurement drift over extended periods.","translation":"实验室天平的精度通过石英晶体传感器得到提升，这最大限度地减少了长时间测量中的漂移。"},{"sentence":"Although quartz is abundant in the Earth's crust, high-purity deposits suitable for semiconductor manufacturing are relatively rare.","translation":"尽管石英在地壳中含量丰富，但适用于半导体制造的高纯度矿床却相对稀少。"},{"sentence":"Engineers selected quartz glass for the optical fibers because its low thermal expansion coefficient ensures signal stability across temperature fluctuations.","translation":"工程师选择石英玻璃用于光纤，因为其低热膨胀系数确保了信号在温度波动中的稳定性。"},{"sentence":"In ancient civilizations, quartz artifacts were often crafted into ceremonial objects, suggesting that the material held symbolic as well as practical value.","translation":"在古代文明中，石英制品常被制成礼仪用品，这表明这种材料不仅具有实用价值，还具有象征意义。"}]},"wretched":{"examples":[{"sentence":"Although the government launched relief programs, the wretched poverty in the region persisted because systemic corruption diverted funds away from those in need.","translation":"尽管政府启动了救济计划，但由于系统性腐败将资金从需要帮助的人手中转移，该地区悲惨的贫困状况依然持续。"},{"sentence":"The wretched state of the infrastructure, which had been neglected for decades, not only hampered economic growth but also endangered public safety.","translation":"几十年来被忽视的糟糕基础设施状况不仅阻碍了经济增长，还危及公共安全。"},{"sentence":"While the novel depicts the protagonist's wretched circumstances with unflinching realism, it ultimately conveys a message of resilience and hope.","translation":"虽然这部小说以毫不退缩的现实主义描绘了主人公的悲惨境遇，但它最终传达了一种坚韧和希望的信息。"},{"sentence":"Because the refugees endured wretched conditions in the camp, international organizations intensified their efforts to provide medical aid and shelter.","translation":"由于难民在难民营中忍受着悲惨的条件，国际组织加大了提供医疗援助和住所的力度。"},{"sentence":"The wretched performance of the stock market, driven by investor panic, led to a vicious cycle of sell-offs that further depressed asset values.","translation":"由投资者恐慌驱动的股市惨淡表现导致了抛售的恶性循环，进一步压低了资产价值。"}]},"sofa":{"examples":[{"sentence":"Although the sofa was delivered late, its exceptional comfort made the wait worthwhile for the entire family.","translation":"尽管沙发送货延迟了，但其卓越的舒适度让全家人都觉得等待是值得的。"},{"sentence":"The interior designer recommended a sectional sofa that could be rearranged to suit different social gatherings.","translation":"室内设计师推荐了一款可重新组合的转角沙发，以适应不同的社交聚会。"},{"sentence":"Because the sofa was upholstered in stain-resistant fabric, it remained pristine despite years of daily use.","translation":"由于沙发采用了防污面料，尽管经过多年日常使用，它依然洁净如新。"},{"sentence":"A well-placed sofa not only defines the living area but also encourages conversation among guests.","translation":"摆放得当的沙发不仅能界定起居区域，还能促进客人之间的交谈。"},{"sentence":"The sofa, which converts into a bed, is an ideal solution for small apartments that lack a dedicated guest room.","translation":"这款可变成床的沙发，对于缺少专用客房的小公寓来说是一个理想的解决方案。"}]},"inflation":{"examples":[{"sentence":"Although inflation has remained moderate this year, many households still struggle with rising food and energy costs.","translation":"尽管今年通货膨胀保持温和，但许多家庭仍在为不断上涨的食品和能源成本而挣扎。"},{"sentence":"Because inflation erodes the real value of savings, financial advisors recommend investing in assets that outpace price increases.","translation":"由于通货膨胀侵蚀储蓄的实际价值，财务顾问建议投资于能跑赢物价上涨的资产。"},{"sentence":"When inflation expectations become entrenched, workers demand higher wages, which can trigger a self-reinforcing price spiral.","translation":"当通货膨胀预期变得根深蒂固时，工人会要求更高的工资，这可能引发自我强化的物价螺旋。"},{"sentence":"Central banks use monetary policy tools to keep inflation within a target range, thereby maintaining economic stability.","translation":"中央银行使用货币政策工具将通货膨胀控制在目标范围内，从而维持经济稳定。"},{"sentence":"If inflation is not properly managed, it can distort consumer behavior and lead to inefficient allocation of resources.","translation":"如果通货膨胀得不到妥善管理，它会扭曲消费者行为并导致资源配置效率低下。"}]},"settlement":{"examples":[{"sentence":"Although the initial settlement was rejected, the parties eventually reached a compromise that satisfied both sides.","translation":"尽管最初的解决方案被拒绝了，但双方最终达成了令双方都满意的妥协。"},{"sentence":"The ancient settlement, which was discovered near the river, provides valuable insights into early agricultural practices.","translation":"在河边发现的古老定居点为了解早期农业实践提供了宝贵的见解。"},{"sentence":"Because the settlement of the account was delayed, the company incurred additional interest charges.","translation":"由于账户结算延迟，公司产生了额外的利息费用。"},{"sentence":"When the colonial settlement expanded, it led to significant cultural exchanges and conflicts with indigenous populations.","translation":"当殖民定居点扩张时，导致了与土著居民的重大文化交流和冲突。"},{"sentence":"The mediator facilitated a fair settlement, thereby avoiding a lengthy and costly court battle.","translation":"调解员促成了公平的解决方案，从而避免了漫长且昂贵的法庭斗争。"}]},"facilitate":{"examples":[{"sentence":"Although the new software was designed to facilitate communication, it initially caused confusion among users.","translation":"尽管新软件旨在促进沟通，但最初在用户中引起了混乱。"},{"sentence":"The government implemented policies that facilitate small business growth, thereby boosting the economy.","translation":"政府实施了促进小企业发展的政策，从而推动了经济。"},{"sentence":"Because online platforms facilitate remote collaboration, teams can work together effectively from different locations.","translation":"由于在线平台促进了远程协作，团队可以在不同地点有效地合作。"},{"sentence":"When teachers use interactive methods, they facilitate deeper understanding among students.","translation":"当教师使用互动方法时，他们促进了学生更深入的理解。"},{"sentence":"The new trade agreement will facilitate the exchange of goods, which is expected to benefit both countries.","translation":"新的贸易协定将促进商品交换，预计将使两国受益。"}]},"circumference":{"examples":[{"sentence":"Although the circle's circumference was easy to measure, calculating its area required a more complex formula.","translation":"虽然圆的周长容易测量，但计算其面积需要更复杂的公式。"},{"sentence":"Because the tree's circumference exceeded two meters, it was designated a protected heritage specimen.","translation":"因为这棵树的周长超过了两米，它被指定为受保护的古树名木。"},{"sentence":"The engineer verified the pipe's circumference to ensure it would fit precisely within the existing framework.","translation":"工程师核实了管道的周长，以确保它能精确地安装在现有框架内。"},{"sentence":"When the waist circumference surpasses the recommended threshold, the risk of cardiovascular disease increases significantly.","translation":"当腰围超过推荐阈值时，心血管疾病的风险会显著增加。"},{"sentence":"The ancient astronomers estimated the Earth's circumference with remarkable accuracy, which demonstrated their advanced mathematical skills.","translation":"古代天文学家以惊人的准确性估算了地球的周长，这展示了他们先进的数学技能。"}]},"genetic":{"examples":[{"sentence":"Although environmental factors are important, genetic predisposition often determines an individual's susceptibility to certain diseases.","translation":"尽管环境因素很重要，但遗传易感性往往决定了个体对某些疾病的易感性。"},{"sentence":"Because genetic diversity is crucial for species survival, conservationists prioritize protecting habitats with high biodiversity.","translation":"因为遗传多样性对物种生存至关重要，环保人士优先保护生物多样性高的栖息地。"},{"sentence":"The study revealed that genetic mutations can be passed down through generations, which explains the inheritance of certain traits.","translation":"研究表明，基因突变可以代代相传，这解释了某些特征的遗传。"},{"sentence":"While genetic engineering offers potential cures for diseases, it also raises ethical concerns that must be carefully addressed.","translation":"虽然基因工程为疾病提供了潜在的治疗方法，但它也引发了必须认真对待的伦理问题。"},{"sentence":"Through genetic analysis, researchers were able to trace the evolutionary history of the species, thereby confirming its ancient origins.","translation":"通过遗传分析，研究人员能够追溯该物种的进化史，从而证实了其古老的起源。"}]},"rotten":{"examples":[{"sentence":"Because the wooden beams were rotten, the entire structure had to be reinforced to prevent collapse.","translation":"因为木梁腐烂了，整个结构必须加固以防止倒塌。"},{"sentence":"Although the apple looked perfect on the outside, its core was completely rotten, which made it inedible.","translation":"尽管苹果外表看起来很完美，但果核完全腐烂了，这使得它不能食用。"},{"sentence":"The rotten smell emanating from the garbage disposal indicated that food waste had been accumulating for weeks.","translation":"从垃圾处理器散发出的腐臭气味表明食物垃圾已经堆积了数周。"},{"sentence":"When a society tolerates rotten behavior among its leaders, public trust in institutions inevitably erodes.","translation":"当一个社会容忍其领导人的腐败行为时，公众对机构的信任不可避免地会受到侵蚀。"},{"sentence":"The investigation uncovered a rotten system in which bribes were routinely accepted, thereby undermining the rule of law.","translation":"调查揭露了一个腐败的体制，其中贿赂被例行接受，从而破坏了法治。"}]},"house":{"examples":[{"sentence":"A publishing house that neglects rigorous peer review risks losing its academic credibility over time.","translation":"一家忽视严格同行评审的出版社，随着时间的推移，有丧失其学术公信力的风险。"},{"sentence":"When a legislative house passes a bill without thorough debate, the resulting laws often contain unintended loopholes.","translation":"当立法机构在没有充分辩论的情况下通过一项法案时，由此产生的法律往往包含意想不到的漏洞。"},{"sentence":"Although the historic house was converted into a museum, its original architectural features have been carefully preserved.","translation":"尽管这座历史住宅被改造成了博物馆，但其原有的建筑特色得到了精心保护。"},{"sentence":"The opera house, which was designed by a renowned architect, has become a cultural landmark that attracts visitors from around the world.","translation":"这座由著名建筑师设计的歌剧院，已成为吸引世界各地游客的文化地标。"},{"sentence":"Because the publishing house invested in digital infrastructure, it was able to adapt quickly when demand for e-books surged.","translation":"由于该出版社投资了数字基础设施，当电子书需求激增时，它能够迅速适应。"}]},"laugh":{"examples":[{"sentence":"Although a hearty laugh can relieve stress, it may be misinterpreted in formal settings where solemnity is expected.","translation":"虽然开怀大笑可以缓解压力，但在需要庄重的正式场合中，它可能会被误解。"},{"sentence":"The child's innocent laugh, which echoed through the hallway, reminded everyone of the joy that simple moments can bring.","translation":"孩子天真的笑声在走廊里回荡，提醒了每个人简单时刻所能带来的快乐。"},{"sentence":"Because laughter is contagious, a single laugh in a tense meeting can transform the atmosphere and foster collaboration.","translation":"因为笑声具有传染性，紧张会议中的一声笑可以改变气氛并促进合作。"},{"sentence":"When the comedian delivered the punchline, the audience erupted in a collective laugh that lasted for several minutes.","translation":"当喜剧演员说出笑点时，观众爆发出持续数分钟的集体笑声。"},{"sentence":"A nervous laugh often betrays anxiety, whereas a genuine laugh signals comfort and social connection.","translation":"紧张的笑声往往暴露焦虑，而真诚的笑声则表明舒适和社交联系。"}]},"counsel":{"examples":[{"sentence":"Because the contract contained ambiguous clauses, the startup sought legal counsel to avoid future disputes.","translation":"由于合同包含模糊条款，这家初创公司寻求法律顾问以避免未来纠纷。"},{"sentence":"Although she was confident in her decision, she still valued the wise counsel of her retired professor.","translation":"尽管她对自己的决定充满信心，但她仍然重视退休教授的明智忠告。"},{"sentence":"The defendant's counsel presented a compelling argument, which ultimately swayed the jury in favor of acquittal.","translation":"被告的律师提出了令人信服的论点，最终使陪审团倾向于无罪释放。"},{"sentence":"When facing a moral dilemma, seeking counsel from a trusted friend can provide much-needed perspective.","translation":"当面临道德困境时，向可信赖的朋友寻求忠告可以提供急需的视角。"},{"sentence":"The CEO ignored the counsel of the risk management team, a decision that later resulted in significant financial loss.","translation":"首席执行官忽视了风险管理团队的忠告，这一决定后来导致了重大财务损失。"}]},"anecdote":{"examples":[{"sentence":"Although the research paper was data-driven, the author included a personal anecdote to engage the reader emotionally.","translation":"尽管这篇研究论文以数据为导向，但作者加入了一则个人轶事以在情感上吸引读者。"},{"sentence":"Because the keynote speaker shared a humorous anecdote about failure, the audience felt more connected to the message.","translation":"由于主旨演讲者分享了一则关于失败的幽默轶事，听众对信息产生了更强的共鸣。"},{"sentence":"While statistics can reveal trends, a well-chosen anecdote often makes the findings more memorable for the public.","translation":"虽然统计数据可以揭示趋势，但一则精心挑选的轶事往往能让公众对研究结果更加难忘。"},{"sentence":"The historian cautioned that an anecdote, however vivid, should not be taken as representative evidence without corroboration.","translation":"历史学家告诫说，无论轶事多么生动，在没有佐证的情况下都不应被视为代表性证据。"},{"sentence":"During the interview, the candidate recounted an anecdote from her volunteer work, which demonstrated her problem-solving skills.","translation":"在面试中，候选人讲述了她志愿者工作中的一则轶事，这展示了她的解决问题的能力。"}]},"suppose":{"examples":[{"sentence":"We often suppose that economic growth automatically improves well-being, yet the evidence suggests a more complex relationship.","translation":"我们常常以为经济增长会自动提升幸福感，然而证据表明二者关系更为复杂。"},{"sentence":"Although many people suppose that artificial intelligence will replace most jobs, historical patterns indicate that technology also creates new forms of employment.","translation":"尽管许多人认为人工智能将取代大部分工作，但历史模式表明技术也会创造新的就业形式。"},{"sentence":"When designing public policy, we cannot simply suppose that individuals will always act in their long-term best interest.","translation":"在制定公共政策时，我们不能简单地假设个人总会按照长远利益行事。"},{"sentence":"Critics of the new curriculum suppose that it neglects foundational knowledge, but proponents argue that it fosters critical thinking.","translation":"新课程的批评者认为它忽视了基础知识，但支持者辩称它培养了批判性思维。"},{"sentence":"To evaluate the proposal fairly, let us suppose for a moment that the projected costs are accurate and then examine the potential benefits.","translation":"为了公平评估该提案，让我们暂时假设预计成本是准确的，然后再审视潜在收益。"}]},"clear":{"examples":[{"sentence":"It is clear from the longitudinal data that early childhood education yields benefits which persist well into adulthood.","translation":"从纵向数据可以清楚地看出，早期儿童教育带来的益处会持续到成年期。"},{"sentence":"Before implementing the new protocol, the research team must clear every procedural ambiguity to ensure replicable results.","translation":"在实施新方案之前，研究团队必须清除所有程序上的模糊之处，以确保结果可复制。"},{"sentence":"Although the immediate causes of the conflict are clear, the underlying historical tensions require deeper investigation.","translation":"尽管冲突的直接原因很清楚，但深层的历史紧张关系需要更深入的调查。"},{"sentence":"A clear understanding of statistical methods is essential for interpreting the findings that are published in peer-reviewed journals.","translation":"清楚理解统计方法对于解读同行评审期刊上发表的研究结果至关重要。"},{"sentence":"The committee made it clear that any proposal lacking empirical support would not receive funding, which prompted researchers to strengthen their experimental designs.","translation":"委员会明确表示，任何缺乏实证支持的提案都不会获得资助，这促使研究人员加强其实验设计。"}]},"yours":{"examples":[{"sentence":"Although my thesis examines urban pollution, yours explores rural environmental degradation, which complements the broader research agenda.","translation":"虽然我的论文研究城市污染，但你的论文探讨农村环境退化，这补充了更广泛的研究议程。"},{"sentence":"Because the final report requires a comparative analysis, I will integrate your data with mine, but the interpretation remains yours.","translation":"由于最终报告需要比较分析，我会将你的数据与我的整合，但解释权仍属于你。"},{"sentence":"While our laboratory focuses on theoretical models, yours emphasizes practical applications that directly benefit industry.","translation":"我们的实验室专注于理论模型，而你们的实验室则强调直接惠及工业的实际应用。"},{"sentence":"If the committee approves the budget, the responsibility for allocating resources is yours, which ensures accountability.","translation":"如果委员会批准预算，资源分配的责任就属于你，这确保了问责制。"},{"sentence":"The methodology in my study relies on surveys, whereas yours employs in-depth interviews, thereby yielding richer qualitative data.","translation":"我研究中的方法依赖于调查，而你的研究则采用深度访谈，从而产生更丰富的定性数据。"}]},"tennis":{"examples":[{"sentence":"Regular tennis practice not only enhances physical coordination but also sharpens mental focus, which benefits academic performance.","translation":"定期练习网球不仅能提高身体协调性，还能增强注意力，这对学业表现有益。"},{"sentence":"Because tennis demands both strategic thinking and rapid reflexes, it serves as an excellent complement to sedentary study routines.","translation":"由于网球既需要策略性思维又需要快速反应，它能很好地补充久坐的学习方式。"},{"sentence":"Although tennis is often perceived as an individual sport, doubles matches require close collaboration and mutual trust between partners.","translation":"虽然网球常被视为个人运动，但双打比赛需要搭档间的密切合作和相互信任。"},{"sentence":"The university expanded its tennis facilities so that more students could engage in this low-impact yet highly aerobic activity.","translation":"大学扩建了网球设施，以便更多学生能参与这项低冲击但高有氧的运动。"},{"sentence":"Learning tennis from a qualified coach helps beginners avoid common injuries that arise from improper technique.","translation":"向合格教练学习网球有助于初学者避免因技术不当而引起的常见损伤。"}]},"compact":{"examples":[{"sentence":"Although the apartment is compact, its intelligent layout creates a sense of spaciousness that larger homes often lack.","translation":"尽管这套公寓很紧凑，但其智能布局营造出宽敞感，这是许多大户型所缺乏的。"},{"sentence":"Because the new smartphone has a compact design, it fits comfortably in small pockets while still offering a large screen.","translation":"由于这款新智能手机设计紧凑，它能舒适地放入小口袋，同时仍提供大屏幕。"},{"sentence":"The researcher presented a compact summary of the findings, which allowed the audience to grasp the key points within minutes.","translation":"研究人员对研究结果进行了简洁的总结，使听众在几分钟内就掌握了要点。"},{"sentence":"When you compact the soil before planting, you ensure that the roots have a stable base, thereby promoting healthier growth.","translation":"在种植前压实土壤，可以确保根系有稳定的基础，从而促进更健康的生长。"},{"sentence":"The compact car not only consumes less fuel but also reduces emissions, which makes it an environmentally friendly choice.","translation":"紧凑型汽车不仅油耗更低，而且减少排放，这使其成为环保的选择。"}]},"evoke":{"examples":[{"sentence":"Because the photograph captures a fleeting moment of joy, it can evoke strong emotions even in those who were not present.","translation":"因为这张照片捕捉到了转瞬即逝的快乐瞬间，即使不在场的人也能唤起强烈的情感。"},{"sentence":"The author uses vivid imagery to evoke the chaos of war, which helps readers understand its devastating impact on civilians.","translation":"作者运用生动的意象来唤起战争的混乱，这有助于读者理解其对平民的毁灭性影响。"},{"sentence":"While some advertisements evoke desire through glamorous models, others appeal to nostalgia by featuring childhood icons.","translation":"虽然一些广告通过迷人的模特唤起欲望，但另一些则通过展示童年偶像来唤起怀旧之情。"},{"sentence":"A well-designed museum exhibit can evoke curiosity and wonder, thereby encouraging visitors to explore the subject further.","translation":"精心设计的博物馆展览能唤起好奇心和惊奇感，从而鼓励参观者进一步探索该主题。"},{"sentence":"The politician's speech was crafted to evoke a sense of unity, rather than to divide the audience along partisan lines.","translation":"这位政治家的演讲旨在唤起团结感，而不是按党派路线分裂听众。"}]},"remainder":{"examples":[{"sentence":"After allocating funds for essential infrastructure, the remainder of the budget was directed toward educational programs that benefit underprivileged communities.","translation":"在为必要的基础设施分配资金后，预算的剩余部分被用于惠及贫困社区的教育项目。"},{"sentence":"The researcher spent the morning analyzing the initial data set and devoted the remainder of the day to verifying the results through independent tests.","translation":"研究人员上午分析了初始数据集，并将当天剩余的时间用于通过独立测试验证结果。"},{"sentence":"Because the first batch of samples was contaminated, the remainder had to be stored under stricter conditions to ensure the experiment's validity.","translation":"由于第一批样本受到污染，剩余样本必须在更严格的条件下储存，以确保实验的有效性。"},{"sentence":"While some team members focused on the theoretical framework, the remainder conducted fieldwork to collect empirical evidence for the study.","translation":"一些团队成员专注于理论框架，而其余成员则进行实地调查，为研究收集实证证据。"},{"sentence":"The company decided to sell the remainder of its inventory at a discount, which not only reduced storage costs but also attracted new customers.","translation":"公司决定打折出售剩余库存，这不仅降低了仓储成本，还吸引了新客户。"}]},"counterpart":{"examples":[{"sentence":"Although the Chinese education minister proposed new reforms, his foreign counterpart expressed reservations about their feasibility.","translation":"尽管中国教育部长提出了新的改革方案，但他的外国同行对其可行性表示保留。"},{"sentence":"The digital version of the document serves as the counterpart to the original paper file, which is stored in a secure archive.","translation":"该文件的数字版本与原始纸质文件相对应，后者保存在安全的档案室中。"},{"sentence":"While the northern region suffered from severe drought, its southern counterpart experienced record rainfall and devastating floods.","translation":"北方地区遭受严重干旱，而南方地区却遭遇了创纪录的降雨和毁灭性的洪水。"},{"sentence":"The new trade agreement requires each party to submit a signed counterpart to the joint committee, thereby ensuring mutual compliance.","translation":"新的贸易协定要求各方将签署的副本提交给联合委员会，从而确保双方遵守。"},{"sentence":"A university president must understand academic culture, whereas a corporate CEO may lack that counterpart in the business world.","translation":"大学校长必须了解学术文化，而企业首席执行官可能缺乏商界中的对应素养。"}]},"trumpet":{"examples":[{"sentence":"The orchestra's principal trumpet delivered a flawless solo that captivated the entire audience.","translation":"乐团的首席小号手演奏了一段完美的独奏，令全场观众着迷。"},{"sentence":"In many ancient cultures, the trumpet served as a signal for important communal gatherings, which helped coordinate large groups.","translation":"在许多古代文化中，小号被用作重要公共集会的信号，这有助于协调大群体。"},{"sentence":"Although the trumpet is often associated with jazz, it also plays a vital role in classical symphonies.","translation":"尽管小号常与爵士乐联系在一起，但它在古典交响乐中也扮演着至关重要的角色。"},{"sentence":"The researcher analyzed how the trumpet's acoustic properties enable it to project sound over long distances, thereby facilitating communication in open spaces.","translation":"研究人员分析了小号的声学特性如何使其能够将声音传播到很远的地方，从而便于在开阔空间进行通信。"},{"sentence":"Learning to play the trumpet requires disciplined breath control, which can benefit a student's overall respiratory health.","translation":"学习吹奏小号需要严格的呼吸控制，这有益于学生的整体呼吸系统健康。"}]},"ceiling":{"examples":[{"sentence":"Although the ornate ceiling in the ancient palace was carefully restored, it still retains its original hand-painted details.","translation":"尽管古代宫殿中装饰华丽的天花板经过了精心修复，但它仍保留了原始的手绘细节。"},{"sentence":"Because the government imposed a strict price ceiling on essential medicines, pharmaceutical companies reduced their investment in research.","translation":"由于政府对基本药物实施了严格的价格上限，制药公司减少了研发投资。"},{"sentence":"Installing acoustic panels on the ceiling can significantly reduce noise, which improves concentration in open-plan offices.","translation":"在天花板上安装吸音板可以显著降低噪音，从而提高开放式办公室的专注度。"},{"sentence":"When the company set a budget ceiling for the project, managers had to prioritize essential tasks to avoid overspending.","translation":"当公司为项目设定预算上限时，管理者不得不优先处理关键任务以避免超支。"},{"sentence":"A high ceiling in a classroom not only enhances air circulation but also creates a sense of spaciousness that benefits learning.","translation":"教室的高天花板不仅能改善空气流通，还能营造一种宽敞感，从而有利于学习。"}]},"straight":{"examples":[{"sentence":"After months of investigation, the journalist finally got the facts straight, which allowed her to publish a comprehensive report.","translation":"经过数月的调查，记者终于弄清了事实，这使她得以发表一份全面的报道。"},{"sentence":"To ensure fairness, the judge insisted that all parties follow the straight path of legal procedure without any deviation.","translation":"为确保公正，法官坚持要求各方遵循法律程序的直路，不得有任何偏离。"},{"sentence":"The architect designed the bridge with a straight alignment, thereby minimizing construction costs and maximizing structural efficiency.","translation":"建筑师将桥梁设计成直线走向，从而最大限度地降低了建造成本并提高了结构效率。"},{"sentence":"Although the road was long and straight, the driver remained cautious because dense fog reduced visibility significantly.","translation":"尽管道路又长又直，但由于浓雾大大降低了能见度，司机仍保持谨慎。"},{"sentence":"In geometry, a straight is the shortest distance between two points, a concept that underpins many engineering applications.","translation":"在几何学中，直线是两点之间的最短距离，这一概念是许多工程应用的基础。"}]},"cautious":{"examples":[{"sentence":"Although the initial data appears promising, the research team remains cautious about drawing premature conclusions.","translation":"尽管初步数据看起来很有希望，研究团队对过早下结论仍持谨慎态度。"},{"sentence":"Because the new medication has not been tested on a large scale, doctors are cautious when prescribing it to elderly patients.","translation":"由于新药尚未经过大规模测试，医生在给老年患者开药时很谨慎。"},{"sentence":"Investors who are cautious by nature tend to diversify their portfolios, which helps mitigate potential losses during market downturns.","translation":"天性谨慎的投资者倾向于分散投资组合，这有助于在市场低迷时减轻潜在损失。"},{"sentence":"When implementing innovative teaching methods, educators must be cautious to ensure that all students can adapt effectively.","translation":"在实施创新教学方法时，教育工作者必须谨慎，以确保所有学生都能有效适应。"},{"sentence":"A cautious interpretation of the survey results suggests that further studies are needed before any policy changes are made.","translation":"对调查结果的谨慎解读表明，在做出任何政策改变之前，还需要进一步的研究。"}]},"layoff":{"examples":[{"sentence":"Although the company cited economic downturn as the reason for the layoff, many employees suspected that poor management was the true cause.","translation":"尽管公司以经济衰退为由进行裁员，但许多员工怀疑管理不善才是真正的原因。"},{"sentence":"A sudden layoff can have a devastating psychological impact on workers, which may lead to long-term anxiety and depression.","translation":"突然被解雇会对工人产生毁灭性的心理影响，这可能导致长期的焦虑和抑郁。"},{"sentence":"Because the layoff affected the entire research division, the company lost valuable expertise that had been developed over decades.","translation":"由于裁员影响了整个研究部门，公司失去了数十年来积累的宝贵专业知识。"},{"sentence":"To mitigate the negative effects of a mass layoff, some organizations offer outplacement services that help former employees find new jobs.","translation":"为了减轻大规模裁员的负面影响，一些组织提供再就业服务，帮助前员工找到新工作。"},{"sentence":"The threat of a layoff can reduce employee morale and productivity, which ultimately harms the company's long-term performance.","translation":"裁员的威胁会降低员工士气和生产力，最终损害公司的长期业绩。"}]},"advise":{"examples":[{"sentence":"Although the market appears volatile, financial analysts advise investors to maintain a diversified portfolio to mitigate risk.","translation":"尽管市场显得动荡，金融分析师建议投资者保持多元化投资组合以降低风险。"},{"sentence":"Because early detection improves outcomes, doctors advise that adults over forty undergo annual health screenings.","translation":"由于早期发现能改善结果，医生建议四十岁以上的成年人每年进行健康检查。"},{"sentence":"When students struggle with time management, academic counselors advise them to create a structured study schedule.","translation":"当学生在时间管理上遇到困难时，学业顾问建议他们制定一个有规律的学习计划。"},{"sentence":"Legal experts advise that contracts be reviewed thoroughly before signing, which helps prevent future disputes.","translation":"法律专家建议在签署前彻底审查合同，这有助于防止未来的纠纷。"},{"sentence":"While the new software offers many features, I advise the team to test it extensively before full deployment.","translation":"虽然新软件提供了许多功能，但我建议团队在全面部署前进行广泛测试。"}]},"sue":{"examples":[{"sentence":"If the manufacturer fails to recall the defective product, consumers may sue for compensation to cover medical expenses.","translation":"如果制造商未能召回有缺陷的产品，消费者可以提起诉讼要求赔偿以支付医疗费用。"},{"sentence":"Because the contractor did not complete the work on time, the homeowner decided to sue for breach of contract.","translation":"由于承包商没有按时完成工作，房主决定以违约为由提起诉讼。"},{"sentence":"Environmental groups often sue corporations that violate pollution laws, thereby holding them accountable for ecological damage.","translation":"环保组织经常起诉违反污染法的企业，从而使它们对生态破坏负责。"},{"sentence":"Although litigation can be costly, the whistleblower chose to sue the company for wrongful termination.","translation":"尽管诉讼可能代价高昂，但举报人选择以不当解雇为由起诉公司。"},{"sentence":"When negotiations failed, the union voted to sue the employer over unfair labor practices.","translation":"当谈判失败时，工会投票决定以不公平劳动行为为由起诉雇主。"}]},"fuse":{"examples":[{"sentence":"When the fuse blew, the entire laboratory lost power, which delayed the experiment for several hours.","translation":"当保险丝烧断时，整个实验室断电，这使实验延迟了几个小时。"},{"sentence":"Although the fuse was designed to protect the circuit, using an incorrect type can lead to equipment failure.","translation":"尽管保险丝旨在保护电路，但使用不正确的类型可能导致设备故障。"},{"sentence":"The electrician checked the fuse box carefully, because a faulty fuse often causes intermittent power outages.","translation":"电工仔细检查了保险丝盒，因为有故障的保险丝经常导致间歇性停电。"},{"sentence":"If the fuse is not replaced promptly, the appliance may overheat and pose a fire risk.","translation":"如果不及时更换保险丝，电器可能过热并构成火灾风险。"},{"sentence":"The manual specifies that only a qualified technician should replace the fuse, thereby ensuring safety.","translation":"手册规定只有合格的技术人员才能更换保险丝，从而确保安全。"}]},"aural":{"examples":[{"sentence":"Because aural comprehension is critical for language acquisition, teachers often use podcasts in class.","translation":"因为听觉理解对语言习得至关重要，教师经常在课堂上使用播客。"},{"sentence":"The aural warning system, which emits a distinct tone, alerts workers to evacuate immediately.","translation":"听觉警报系统发出独特的声音，提醒工人立即撤离。"},{"sentence":"While visual learners prefer diagrams, aural learners benefit more from lectures and discussions.","translation":"虽然视觉学习者更喜欢图表，但听觉学习者从讲座和讨论中获益更多。"},{"sentence":"The musician's aural sensitivity allowed her to detect subtle nuances that others missed.","translation":"这位音乐家的听觉灵敏度使她能够察觉到其他人忽略的细微差别。"},{"sentence":"Through aural training, students can improve their ability to distinguish similar sounds in a foreign language.","translation":"通过听觉训练，学生可以提高区分外语中相似声音的能力。"}]},"evil":{"examples":[{"sentence":"Although the dictator's regime was overthrown, the evil it inflicted on the population left deep scars.","translation":"尽管独裁政权被推翻，但它对人民造成的邪恶留下了深深的伤痕。"},{"sentence":"The novel explores how ordinary people can commit evil acts when they blindly follow authority.","translation":"这部小说探讨了普通人在盲目服从权威时如何犯下邪恶行为。"},{"sentence":"Because the evil of corruption undermines public trust, governments must enforce strict anti-bribery laws.","translation":"因为腐败的邪恶破坏公众信任，政府必须执行严格的反贿赂法律。"},{"sentence":"The philosopher argued that evil is not an external force but a choice that individuals make.","translation":"这位哲学家认为，邪恶不是外部力量，而是个人做出的选择。"},{"sentence":"While some believe that evil is innate, others contend that it stems from social and environmental factors.","translation":"虽然有些人认为邪恶是与生俱来的，但其他人则认为它源于社会和环境因素。"}]},"faulty":{"examples":[{"sentence":"Although the device appeared intact, its faulty internal mechanism caused it to malfunction during the critical test.","translation":"尽管该设备外观完好，但其有缺陷的内部机制导致它在关键测试中发生故障。"},{"sentence":"Because the faulty data skewed the results, the researchers had to repeat the entire experiment to ensure accuracy.","translation":"由于错误的数据扭曲了结果，研究人员不得不重复整个实验以确保准确性。"},{"sentence":"The faulty design of the bridge, which lacked adequate support beams, ultimately led to its collapse under heavy traffic.","translation":"这座桥有缺陷的设计，即缺乏足够的支撑梁，最终导致其在繁忙交通下坍塌。"},{"sentence":"When a faulty component is detected early in the assembly line, it prevents costly recalls and protects the brand's reputation.","translation":"当装配线上及早发现有缺陷的部件时，就能避免代价高昂的召回并保护品牌声誉。"},{"sentence":"The company's faulty risk assessment, rather than market volatility, was the primary cause of its financial losses.","translation":"该公司错误的风险评估，而非市场波动，是其财务损失的主要原因。"}]},"database":{"examples":[{"sentence":"Although the database contains millions of records, its efficient indexing system allows for rapid retrieval of specific information.","translation":"尽管该数据库包含数百万条记录，但其高效的索引系统允许快速检索特定信息。"},{"sentence":"Because the database was not properly secured, sensitive customer information was exposed to unauthorized access.","translation":"由于数据库未得到妥善保护，敏感的客户信息被暴露给未经授权的访问。"},{"sentence":"The research team used a centralized database, which facilitated collaboration and ensured data consistency across multiple projects.","translation":"研究团队使用了一个中央数据库，这促进了协作并确保了多个项目间的数据一致性。"},{"sentence":"When the database is updated in real time, it enables managers to make informed decisions based on the latest available data.","translation":"当数据库实时更新时，它使管理者能够基于最新可用数据做出明智的决策。"},{"sentence":"The new database architecture, rather than simply storing data, actively supports complex analytical queries through advanced algorithms.","translation":"新的数据库架构，不仅仅是存储数据，还通过先进算法主动支持复杂的分析查询。"}]},"speed":{"examples":[{"sentence":"Although the speed of technological innovation brings many benefits, it also creates challenges for regulatory frameworks to keep pace.","translation":"尽管技术创新的速度带来了许多好处，但它也给监管框架跟上步伐带来了挑战。"},{"sentence":"Because the speed of delivery is a key competitive factor, companies invest heavily in logistics to ensure prompt service.","translation":"由于交付速度是一个关键的竞争因素，公司大力投资物流以确保及时服务。"},{"sentence":"The speed at which the virus spread, which caught many governments off guard, highlighted the need for robust early warning systems.","translation":"病毒传播的速度使许多政府措手不及，这凸显了建立强大预警系统的必要性。"},{"sentence":"When the speed of urban expansion exceeds the capacity of infrastructure, problems such as traffic congestion and pollution inevitably arise.","translation":"当城市扩张的速度超过基础设施的容量时，交通拥堵和污染等问题不可避免地出现。"},{"sentence":"The new software processes data at a remarkable speed, thereby reducing the time required for complex simulations from hours to minutes.","translation":"新软件以惊人的速度处理数据，从而将复杂模拟所需的时间从数小时缩短到数分钟。"}]},"bore":{"examples":[{"sentence":"Although he was a brilliant scholar, his monotonous delivery turned every lecture into a bore that students dreaded attending.","translation":"尽管他是一位杰出的学者，但他单调的授课方式让每堂课都变得令人厌烦，学生们都不愿去上。"},{"sentence":"The party turned out to be a bore because the host spent the entire evening discussing his obscure research with no regard for his guests' interests.","translation":"那场聚会最终令人厌烦，因为主人整晚都在讨论他晦涩的研究，丝毫不顾及客人们的兴趣。"},{"sentence":"While the documentary aimed to educate viewers about climate change, its slow pace and repetitive data made it a bore for all but the most dedicated environmentalists.","translation":"尽管这部纪录片旨在教育观众了解气候变化，但其缓慢的节奏和重复的数据使它除了最专注的环保主义者之外，对所有人都显得乏味。"},{"sentence":"Having to listen to the same bureaucratic procedures at every meeting became such a bore that several committee members eventually stopped attending.","translation":"每次会议都要听同样的官僚程序变得如此令人厌烦，以至于几位委员会成员最终不再出席。"},{"sentence":"The novel's intricate plot initially promised excitement, but the author's excessive digressions transformed the story into a bore that few readers managed to finish.","translation":"这部小说错综复杂的情节起初预示着精彩，但作者过多的离题话让故事变得乏味，很少有读者能坚持读完。"}]},"industrialize":{"examples":[{"sentence":"Although the government attempted to industrialize the rural area through tax incentives, the lack of skilled labor hindered progress significantly.","translation":"尽管政府试图通过税收优惠使农村地区工业化，但缺乏熟练劳动力严重阻碍了进展。"},{"sentence":"Because the nation chose to industrialize without enforcing environmental regulations, its rivers became so polluted that aquatic life nearly vanished.","translation":"由于该国选择工业化而不执行环境法规，其河流受到严重污染，水生生物几乎消失。"},{"sentence":"While many economists argue that developing countries must industrialize to escape poverty, others warn that automation reduces the job creation once associated with manufacturing.","translation":"尽管许多经济学家认为发展中国家必须工业化以摆脱贫困，但其他人警告说，自动化减少了曾经与制造业相关的就业机会。"},{"sentence":"The decision to industrialize the coastal region, which had relied on fishing for centuries, sparked protests from local communities who feared losing their cultural heritage.","translation":"将沿海地区工业化的决定引发了当地社区的抗议，该地区几个世纪以来一直依赖渔业，他们担心失去文化遗产。"},{"sentence":"If a country fails to industrialize its economy, it may remain dependent on volatile commodity exports, thereby exposing itself to frequent financial crises.","translation":"如果一个国家未能使其经济工业化，它可能仍然依赖不稳定的商品出口，从而使其面临频繁的金融危机。"}]},"forthcoming":{"examples":[{"sentence":"Although the author is usually forthcoming about her creative process, she has remained unusually secretive regarding her forthcoming novel.","translation":"尽管这位作家通常对她的创作过程很坦诚，但她对自己即将出版的小说却异常保密。"},{"sentence":"Because the manager was not forthcoming with the project details, the team struggled to meet the deadline, which resulted in a loss of client trust.","translation":"由于经理没有坦诚提供项目细节，团队难以在截止日期前完成，导致失去客户信任。"},{"sentence":"While the forthcoming election has generated intense debate, many voters remain undecided due to the candidates' reluctance to be forthcoming about their policies.","translation":"尽管即将到来的选举引发了激烈辩论，但由于候选人不愿坦诚说明政策，许多选民仍未做出决定。"},{"sentence":"The forthcoming changes to the tax code, which were announced without prior consultation, have caused confusion among small business owners who need time to adapt.","translation":"即将到来的税法变更在没有事先协商的情况下宣布，给小企业主造成了困惑，他们需要时间适应。"},{"sentence":"If the witness had been more forthcoming during the investigation, the case might have been solved much sooner, thereby preventing further harm.","translation":"如果证人在调查期间更坦诚，案件可能早就解决了，从而防止了进一步的伤害。"}]},"situation":{"examples":[{"sentence":"Although the situation seems dire, a well-coordinated response can mitigate the long-term consequences.","translation":"尽管情况看起来很严峻，但协调良好的应对措施可以减轻长期后果。"},{"sentence":"When a crisis situation arises, leaders must communicate clearly to maintain public trust.","translation":"当危机情况出现时，领导者必须清晰沟通以维持公众信任。"},{"sentence":"The economic situation, which has been unstable for months, requires immediate policy intervention.","translation":"已经不稳定数月的经济形势需要立即的政策干预。"},{"sentence":"Because the situation is evolving rapidly, we need to reassess our strategy on a daily basis.","translation":"由于情况迅速演变，我们需要每天重新评估我们的策略。"},{"sentence":"A thorough understanding of the situation is essential to ensure that resources are allocated effectively.","translation":"彻底了解情况对于确保资源得到有效分配至关重要。"}]},"create":{"examples":[{"sentence":"To create a more inclusive society, we must dismantle systemic barriers that perpetuate inequality.","translation":"为了创造一个更包容的社会，我们必须消除使不平等长期存在的系统性障碍。"},{"sentence":"Innovative companies create value not only through products but also through exceptional customer experiences.","translation":"创新公司不仅通过产品创造价值，还通过卓越的客户体验创造价值。"},{"sentence":"Although technology can create efficiencies, it may also lead to job displacement if not managed carefully.","translation":"尽管技术可以创造效率，但如果不谨慎管理，也可能导致工作岗位流失。"},{"sentence":"Governments should create policies that incentivize sustainable practices, thereby reducing environmental harm.","translation":"政府应制定激励可持续实践的政策，从而减少环境损害。"},{"sentence":"When teams collaborate effectively, they create synergies that drive innovation and productivity.","translation":"当团队有效协作时，他们会创造协同效应，推动创新和生产力。"}]},"year":{"examples":[{"sentence":"Although the first year of a project is often challenging, it lays the foundation for future success.","translation":"尽管项目的第一年通常充满挑战，但它为未来的成功奠定了基础。"},{"sentence":"Over the past year, the company has invested heavily in research, which has yielded several breakthroughs.","translation":"在过去一年里，公司在研究方面投入巨资，这已经产生了多项突破。"},{"sentence":"A gap year, if used productively, can provide invaluable life experience and clarify career goals.","translation":"如果利用得当，间隔年可以提供宝贵的人生经验并明确职业目标。"},{"sentence":"Because the fiscal year ends in June, all departments must submit their budget proposals by May.","translation":"由于财政年度在六月结束，所有部门必须在五月前提交预算提案。"},{"sentence":"The academic year, which typically runs from September to June, includes two semesters and a summer break.","translation":"学年通常从九月持续到六月，包括两个学期和一个暑假。"}]},"applause":{"examples":[{"sentence":"The scientist's groundbreaking discovery, which could revolutionize cancer treatment, earned her thunderous applause from the international community.","translation":"这位科学家的突破性发现可能彻底改变癌症治疗，为她赢得了国际社会的热烈掌声。"},{"sentence":"Although the new environmental regulations received applause from activists, some businesses argued that they would stifle economic growth.","translation":"尽管新的环保法规获得了活动人士的赞许，但一些企业认为它们会抑制经济增长。"},{"sentence":"When the young inventor presented her affordable water purification system, the audience broke into spontaneous applause.","translation":"当这位年轻的发明家展示她负担得起的水净化系统时，观众自发地鼓起掌来。"},{"sentence":"The government's decision to invest heavily in renewable energy, rather than fossil fuels, drew applause from environmentalists worldwide.","translation":"政府决定大力投资可再生能源而非化石燃料，赢得了世界各地环保人士的赞许。"},{"sentence":"Because the charity's transparent financial reports built public trust, its fundraising gala was met with generous donations and warm applause.","translation":"由于该慈善机构透明的财务报告建立了公众信任，其筹款晚会获得了慷慨捐赠和热烈掌声。"}]},"guilt":{"examples":[{"sentence":"Although the suspect maintained his innocence, the forensic evidence ultimately established his guilt beyond any doubt.","translation":"尽管嫌疑人坚称自己无辜，但法医证据最终毫无疑问地确定了他的罪行。"},{"sentence":"Because she had lied to her best friend, a profound sense of guilt prevented her from sleeping peacefully for weeks.","translation":"因为她对最好的朋友撒了谎，一种深深的内疚感让她几周都无法安睡。"},{"sentence":"The therapist explained that unresolved guilt, if not properly addressed, can lead to chronic anxiety and depression.","translation":"治疗师解释说，未解决的内疚如果得不到妥善处理，会导致慢性焦虑和抑郁。"},{"sentence":"In a fair judicial system, the burden of proving guilt rests with the prosecution rather than the defendant.","translation":"在一个公正的司法体系中，证明有罪的责任在于控方，而不是被告。"},{"sentence":"Survivors of the accident often experience irrational guilt, believing that they could have prevented the tragedy.","translation":"事故的幸存者常常经历非理性的内疚，认为他们本可以阻止这场悲剧。"}]},"cellar":{"examples":[{"sentence":"Because the cellar maintains a constant temperature of 12 degrees Celsius, it is perfect for aging fine wines.","translation":"由于地窖保持12摄氏度的恒温，它非常适合陈酿优质葡萄酒。"},{"sentence":"During the tornado, the family took shelter in the cellar, which had been reinforced to withstand severe storms.","translation":"龙卷风期间，这家人躲进了地窖，这个地窖经过加固，可以抵御严重的风暴。"},{"sentence":"The old mansion had a hidden cellar that was discovered only when the new owners began renovating the kitchen.","translation":"这座古老的宅邸有一个隐藏的地窖，直到新主人开始翻修厨房时才被发现。"},{"sentence":"Although the cellar was damp and musty, it provided a safe refuge for the villagers during the air raids.","translation":"尽管地窖潮湿发霉，但在空袭期间它为村民们提供了一个安全的避难所。"},{"sentence":"The restaurant's cellar, which stores over a thousand bottles of wine, is a major attraction for connoisseurs.","translation":"这家餐厅的地窖储存了一千多瓶葡萄酒，是鉴赏家们的主要吸引力。"}]},"insurance":{"examples":[{"sentence":"Although many people view insurance as a grudge purchase, it provides essential financial security when unexpected events occur.","translation":"尽管许多人认为保险是一种不情愿的购买，但当意外事件发生时，它能提供必要的财务保障。"},{"sentence":"Because health insurance premiums have risen sharply, policymakers are exploring ways to make coverage more affordable for low-income families.","translation":"由于健康保险保费大幅上涨，政策制定者正在探索使低收入家庭更能负担得起保险的方法。"},{"sentence":"To ensure that farmers can recover from crop failures, the government subsidizes agricultural insurance, which covers losses caused by drought or floods.","translation":"为了确保农民能从作物歉收中恢复，政府补贴农业保险，该保险覆盖干旱或洪水造成的损失。"},{"sentence":"While life insurance is often associated with older adults, financial advisors recommend that young professionals also consider it to protect their dependents.","translation":"虽然人寿保险常与老年人联系在一起，但财务顾问建议年轻专业人士也考虑购买，以保护其受抚养人。"},{"sentence":"The new regulation requires that all vehicles have third-party liability insurance, thereby ensuring that accident victims receive compensation.","translation":"新规定要求所有车辆必须购买第三方责任保险，从而确保事故受害者获得赔偿。"}]},"stable":{"examples":[{"sentence":"A stable democracy, which upholds the rule of law and protects civil liberties, is more likely to foster sustainable economic development.","translation":"一个稳定的民主政体，维护法治并保护公民自由，更有可能促进可持续的经济发展。"},{"sentence":"Although the patient's condition is now stable, doctors are monitoring him closely to prevent any sudden deterioration.","translation":"尽管病人的状况现在稳定，医生们仍在密切监测，以防任何突然恶化。"},{"sentence":"To maintain a stable supply chain, companies must diversify their suppliers rather than relying on a single source.","translation":"为了维持稳定的供应链，公司必须使其供应商多样化，而不是依赖单一来源。"},{"sentence":"Because a stable income allows families to plan for the future, job security is often valued more than a high salary.","translation":"由于稳定的收入使家庭能够规划未来，工作保障往往比高薪更受重视。"},{"sentence":"The chemical compound is remarkably stable under high temperatures, which makes it suitable for use in industrial processes.","translation":"这种化合物在高温下非常稳定，这使其适用于工业过程。"}]},"preface":{"examples":[{"sentence":"In the preface to her memoir, the author reflects on the transformative power of education, which shaped her journey from poverty to success.","translation":"在她的回忆录序言中，作者反思了教育的变革力量，这塑造了她从贫困走向成功的历程。"},{"sentence":"Although the preface is often the last part of a book to be written, it serves as a crucial guide for readers to understand the author's intent.","translation":"尽管序言通常是书中最后写成的部分，但它作为读者理解作者意图的关键指南。"},{"sentence":"To preface his argument, the scholar cited several historical precedents that illustrate the long-term consequences of environmental neglect.","translation":"为了引出他的论点，这位学者引用了几个历史先例，说明忽视环境的长期后果。"},{"sentence":"The editor's preface not only summarizes the key themes of the anthology but also explains the selection criteria for the included works.","translation":"编辑的序言不仅总结了选集的关键主题，还解释了入选作品的选择标准。"},{"sentence":"Because a thoughtful preface can establish credibility and engage the audience, authors should invest time in crafting a compelling opening.","translation":"由于一篇深思熟虑的序言能建立可信度并吸引读者，作者应投入时间撰写一个引人入胜的开篇。"}]},"example":{"examples":[{"sentence":"Although a single example cannot prove a theory, it can effectively illustrate a complex concept in a classroom setting.","translation":"尽管一个例子不能证明一个理论，但它可以在课堂环境中有效地说明一个复杂的概念。"},{"sentence":"The textbook provides a clear example of how supply and demand interact, which helps students grasp fundamental economic principles.","translation":"教科书提供了一个清晰的例子，说明供给和需求如何相互作用，这有助于学生掌握基本的经济原理。"},{"sentence":"Because the researcher included a concrete example in her presentation, the audience understood the abstract methodology more easily.","translation":"因为研究者在她的演讲中包含了一个具体的例子，所以听众更容易理解抽象的方法论。"},{"sentence":"When writing an academic essay, you should support each argument with a relevant example to enhance the credibility of your claims.","translation":"在写学术论文时，你应该用相关的例子来支持每个论点，以提高你主张的可信度。"},{"sentence":"The historical example of the Industrial Revolution demonstrates that technological advancements can profoundly transform societal structures.","translation":"工业革命的历史例子表明，技术进步可以深刻地改变社会结构。"}]},"brown":{"examples":[{"sentence":"Although brown is often perceived as a dull color, it can evoke a sense of warmth and comfort in interior design.","translation":"尽管褐色常被认为是一种沉闷的颜色，但它可以在室内设计中唤起温暖和舒适的感觉。"},{"sentence":"The leaves turned a rich brown in autumn, which created a picturesque landscape that attracted many photographers.","translation":"秋天树叶变成了浓郁的褐色，这创造了一幅如画的风景，吸引了许多摄影师。"},{"sentence":"Because the soil had a dark brown hue, the farmers knew it was fertile and suitable for growing organic vegetables.","translation":"因为土壤呈深褐色，农民们知道它很肥沃，适合种植有机蔬菜。"},{"sentence":"The artist mixed yellow and purple to produce a subtle brown, thereby achieving the desired earthy tone for the portrait background.","translation":"艺术家混合黄色和紫色来产生一种微妙的褐色，从而为肖像背景实现了理想的土色调。"},{"sentence":"When exposed to air, the cut surface of the apple gradually turned brown, which is a natural oxidation process.","translation":"当暴露在空气中时，苹果的切面逐渐变成褐色，这是一个自然的氧化过程。"}]},"reflection":{"examples":[{"sentence":"Although the initial data seemed promising, a deeper reflection on the methodology revealed significant flaws.","translation":"尽管初步数据看起来很有希望，但对方法的深入反思揭示了重大缺陷。"},{"sentence":"The artist's work is a direct reflection of the social turmoil that characterized the era.","translation":"这位艺术家的作品是那个时代社会动荡的直接反映。"},{"sentence":"Because the lake was perfectly calm, the reflection of the mountains appeared as a flawless mirror image.","translation":"因为湖面异常平静，群山的倒影呈现出完美的镜像。"},{"sentence":"Through quiet reflection, she realized that her career goals no longer aligned with her personal values.","translation":"通过安静的沉思，她意识到自己的职业目标不再与个人价值观一致。"},{"sentence":"The polished surface provided a clear reflection, which allowed the technician to inspect the underside of the device.","translation":"抛光表面提供了清晰的映像，使技术人员能够检查设备的底部。"}]},"punish":{"examples":[{"sentence":"Although the court decided to punish the offender with a prison sentence, many believed that rehabilitation would have been more effective.","translation":"尽管法院决定判处罪犯监禁，但许多人认为改造会更有效。"},{"sentence":"Because the company violated environmental regulations, the agency chose to punish it by revoking its operating license.","translation":"由于该公司违反了环境法规，该机构选择吊销其营业执照以示惩罚。"},{"sentence":"When schools punish students solely through suspension, they risk exacerbating behavioral problems rather than resolving them.","translation":"当学校仅通过停学来惩罚学生时，他们可能会加剧行为问题，而不是解决问题。"},{"sentence":"The new policy aims to punish tax evasion more severely, thereby deterring potential offenders from engaging in fraudulent activities.","translation":"新政策旨在更严厉地惩罚逃税行为，从而阻止潜在违法者从事欺诈活动。"},{"sentence":"If a government fails to punish corruption effectively, public trust in institutions will inevitably erode over time.","translation":"如果政府未能有效惩治腐败，公众对机构的信任将不可避免地随着时间的推移而削弱。"}]},"leaflet":{"examples":[{"sentence":"Although the leaflet was printed on recycled paper, its design was so appealing that many people kept it as a reference.","translation":"尽管传单是用再生纸印刷的，但其设计非常吸引人，许多人将其作为参考保留下来。"},{"sentence":"Because the leaflet contained detailed diagrams, it helped residents understand the new recycling guidelines more clearly.","translation":"由于传单包含详细的图表，它帮助居民更清楚地了解了新的回收指南。"},{"sentence":"The campaign distributed a leaflet that explained the benefits of vaccination, which significantly increased public participation.","translation":"该活动分发了一份解释疫苗接种益处的传单，这显著提高了公众参与度。"},{"sentence":"When the charity designed a leaflet with compelling stories, donations rose sharply, demonstrating the power of effective communication.","translation":"当慈善机构设计了一份包含感人故事的传单时，捐款急剧增加，展示了有效沟通的力量。"},{"sentence":"A leaflet can be a cost-effective tool for raising awareness, provided that it is distributed in high-traffic areas.","translation":"传单可以成为一种提高意识的成本效益工具，前提是它在人流量大的区域分发。"}]},"nitrogen":{"examples":[{"sentence":"Although nitrogen is abundant in the atmosphere, plants can only absorb it after it has been fixed by soil bacteria.","translation":"尽管大气中氮含量丰富，但植物只有在土壤细菌固氮后才能吸收它。"},{"sentence":"Because excessive nitrogen runoff causes algal blooms, many countries have imposed strict limits on fertilizer use.","translation":"由于过量的氮径流导致藻类大量繁殖，许多国家对肥料使用施加了严格限制。"},{"sentence":"Nitrogen is a key component of amino acids, which are the building blocks of proteins essential for all living organisms.","translation":"氮是氨基酸的关键组成部分，氨基酸是构成所有生物体必需蛋白质的基石。"},{"sentence":"When liquid nitrogen is used in cryopreservation, it maintains biological samples at temperatures low enough to halt all metabolic activity.","translation":"当液氮用于低温保存时，它将生物样本保持在足够低的温度下，以停止所有代谢活动。"},{"sentence":"The Haber-Bosch process, which synthesizes ammonia from nitrogen and hydrogen, revolutionized agriculture by enabling mass production of fertilizers.","translation":"哈伯-博斯法通过从氮和氢合成氨，使肥料的大规模生产成为可能，从而彻底改变了农业。"}]},"reconcile":{"examples":[{"sentence":"Although the two departments had conflicting priorities, the manager helped them reconcile their goals through a series of collaborative workshops.","translation":"尽管两个部门的优先事项存在冲突，但经理通过一系列协作研讨会帮助他们协调了目标。"},{"sentence":"Because the financial records did not match, the accountant had to reconcile the bank statements with the company's internal accounts.","translation":"由于财务记录不符，会计师不得不将银行对账单与公司内部账目进行核对。"},{"sentence":"While many find it challenging to reconcile personal beliefs with professional obligations, ethical training can provide a framework for decision-making.","translation":"尽管许多人发现很难调和个人信仰与职业义务，但道德培训可以为决策提供一个框架。"},{"sentence":"When the research findings contradicted the established theory, the scientist sought to reconcile the discrepancy by proposing a new hypothesis.","translation":"当研究结果与既定理论相矛盾时，这位科学家试图通过提出新假设来调和这一差异。"},{"sentence":"If communities fail to reconcile historical grievances, long-term peace remains elusive despite superficial agreements.","translation":"如果社区未能化解历史积怨，那么即使有表面协议，长期和平仍遥不可及。"}]},"repeat":{"examples":[{"sentence":"Because the initial survey produced ambiguous results, a repeat of the study with a larger sample size was deemed necessary.","translation":"由于初步调查结果模糊不清，因此认为有必要用更大的样本量重复这项研究。"},{"sentence":"Although the television series was popular, the network decided against a repeat of the show due to high production costs.","translation":"尽管这部电视剧很受欢迎，但由于制作成本高昂，电视台决定不重播该剧。"},{"sentence":"When a repeat of the error occurred in the manufacturing process, the quality control team implemented stricter inspection protocols.","translation":"当制造过程中再次出现错误时，质量控制团队实施了更严格的检查规程。"},{"sentence":"The repeat of the annual conference attracted more attendees than the original event, which indicates growing interest in the field.","translation":"年度会议的再次举办吸引了比首届更多的与会者，这表明对该领域的兴趣日益增长。"},{"sentence":"If a repeat of the security breach happens, the company will face severe penalties under the new data protection regulations.","translation":"如果再次发生安全漏洞，该公司将根据新的数据保护法规面临严厉处罚。"}]},"knit":{"examples":[{"sentence":"Although she learned to knit as a child, she only recently mastered the intricate Fair Isle technique through online tutorials.","translation":"尽管她小时候就学会了编织，但直到最近才通过在线教程掌握了复杂的费尔岛编织技法。"},{"sentence":"Because the community project encouraged residents to knit blankets for the homeless, it fostered a strong sense of solidarity among neighbors.","translation":"由于社区项目鼓励居民为无家可归者编织毯子，它培养了邻里间强烈的团结感。"},{"sentence":"While the broken bone took several months to knit completely, the patient followed the physiotherapy regimen diligently to ensure proper healing.","translation":"虽然断骨花了几个月才完全愈合，但患者勤奋地遵循理疗方案以确保正常康复。"},{"sentence":"When team members from diverse backgrounds collaborate effectively, their unique skills knit together to form a highly innovative unit.","translation":"当来自不同背景的团队成员有效合作时，他们独特的技能会紧密结合，形成一个高度创新的整体。"},{"sentence":"If you knit the scarf using a thicker yarn, it will be warmer but may lack the delicate texture of the original design.","translation":"如果你用更粗的纱线编织这条围巾，它会更暖和，但可能缺乏原设计的精致质感。"}]},"editorial":{"examples":[{"sentence":"Although the editorial criticized the new policy, it acknowledged that the government had made a genuine effort to address the housing crisis.","translation":"尽管这篇社论批评了新政策，但它承认政府为解决住房危机做出了真正的努力。"},{"sentence":"The editorial board decided to publish a series of articles on climate change, which they hoped would raise public awareness and prompt legislative action.","translation":"编辑委员会决定发表一系列关于气候变化的文章，他们希望这能提高公众意识并促使立法行动。"},{"sentence":"Because the editorial was written by a leading expert in public health, its recommendations on pandemic preparedness were widely cited by policymakers.","translation":"由于这篇评论由一位公共卫生领域的顶尖专家撰写，其关于大流行防范的建议被政策制定者广泛引用。"},{"sentence":"While some readers found the editorial too radical, others praised its bold call for systemic reform in the education sector.","translation":"虽然一些读者认为这篇社论过于激进，但其他人赞扬它对教育部门系统性改革的大胆呼吁。"},{"sentence":"The newspaper's editorial argued that investing in renewable energy would not only reduce carbon emissions but also create long-term economic benefits.","translation":"该报社论认为，投资可再生能源不仅能减少碳排放，还能创造长期经济效益。"}]},"trip":{"examples":[{"sentence":"Although the business trip was exhausting, it allowed her to establish valuable connections with industry leaders, which later proved crucial for her career.","translation":"尽管这次出差令人疲惫，但它让她与行业领袖建立了宝贵的联系，这对她后来的职业生涯至关重要。"},{"sentence":"Because the research trip to the Arctic was funded by a government grant, the team had to submit a detailed report upon their return.","translation":"由于这次北极研究之旅由政府拨款资助，团队返回后必须提交一份详细报告。"},{"sentence":"While a trip abroad can broaden one's horizons, it also requires careful planning to ensure that the experience is both educational and safe.","translation":"虽然出国旅行可以开阔视野，但也需要精心规划，以确保这次经历既有教育意义又安全。"},{"sentence":"The school organized a field trip to the museum, which gave students a hands-on understanding of ancient civilizations that textbooks could not provide.","translation":"学校组织了一次博物馆实地考察，这让学生们对古代文明有了课本无法提供的亲身体验。"},{"sentence":"If you plan a trip during peak season, you should book accommodations well in advance to avoid inflated prices and limited availability.","translation":"如果你计划在旺季旅行，你应该提前预订住宿，以避免价格上涨和房源有限。"}]},"invisible":{"examples":[{"sentence":"Although the benefits of regular exercise are invisible in the short term, they significantly reduce long-term health risks.","translation":"尽管定期锻炼的好处短期内看不见，但它们能显著降低长期健康风险。"},{"sentence":"Because emotional labor is often invisible, its contribution to workplace harmony is frequently undervalued.","translation":"由于情绪劳动常常是看不见的，它对职场和谐的贡献经常被低估。"},{"sentence":"While the digital divide remains invisible to many urban residents, it severely limits educational opportunities in rural areas.","translation":"尽管数字鸿沟对许多城市居民来说仍然是看不见的，但它严重限制了农村地区的教育机会。"},{"sentence":"The gradual erosion of privacy is an invisible process that only becomes apparent when personal data is misused.","translation":"隐私的逐渐侵蚀是一个看不见的过程，只有当个人数据被滥用时才会变得明显。"},{"sentence":"Without careful analysis, the invisible biases embedded in algorithms can perpetuate social inequalities.","translation":"如果不进行仔细分析，算法中嵌入的无形偏见可能会使社会不平等长期存在。"}]},"simulate":{"examples":[{"sentence":"To ensure accurate predictions, climate scientists simulate complex interactions between the atmosphere and ocean currents.","translation":"为了确保预测准确，气候科学家模拟大气与洋流之间复杂的相互作用。"},{"sentence":"Although computer models can simulate economic downturns, they often fail to capture irrational human behavior.","translation":"尽管计算机模型可以模拟经济衰退，但它们往往无法捕捉非理性的人类行为。"},{"sentence":"Medical students use high-fidelity mannequins to simulate emergency procedures, thereby improving their clinical skills without risking patient safety.","translation":"医学生使用高仿真人体模型来模拟急救程序，从而在不危及患者安全的情况下提高临床技能。"},{"sentence":"Because field trials are expensive, agronomists simulate crop yields under various climate scenarios using sophisticated software.","translation":"由于田间试验成本高昂，农学家使用复杂的软件模拟各种气候情景下的作物产量。"},{"sentence":"When engineers simulate stress on a bridge design, they can identify potential weaknesses before construction begins.","translation":"当工程师模拟桥梁设计上的应力时，他们可以在施工开始前发现潜在的弱点。"}]},"if":{"examples":[{"sentence":"If governments invest more in renewable energy, the long-term benefits for the environment will be substantial.","translation":"如果政府在可再生能源上投入更多，对环境的长期利益将是巨大的。"},{"sentence":"Students often wonder if the knowledge they acquire in university will be applicable to their future careers.","translation":"学生经常想知道他们在大学获得的知识是否适用于未来的职业。"},{"sentence":"Even if a policy is well-intentioned, it may fail to achieve its goals if it does not consider local conditions.","translation":"即使一项政策意图良好，如果不考虑当地条件，也可能无法实现其目标。"},{"sentence":"Researchers must determine if the new drug is safe before proceeding to large-scale clinical trials.","translation":"研究人员必须确定新药是否安全，然后才能进行大规模临床试验。"},{"sentence":"If we are to address the challenges of climate change, international cooperation is not just desirable but essential.","translation":"如果我们要应对气候变化的挑战，国际合作不仅是可取的，而且是必要的。"}]},"dictionary":{"examples":[{"sentence":"A comprehensive dictionary, which includes etymologies and usage notes, is an indispensable tool for advanced language learners.","translation":"一本包含词源和用法说明的综合词典是高级语言学习者不可或缺的工具。"},{"sentence":"Although online dictionaries are easily accessible, a printed dictionary can provide a distraction-free learning experience.","translation":"尽管在线词典易于访问，但印刷版词典可以提供无干扰的学习体验。"},{"sentence":"When compiling a dictionary, lexicographers must carefully analyze vast corpora to determine accurate definitions.","translation":"在编纂词典时，词典编纂者必须仔细分析大量语料库以确定准确的定义。"},{"sentence":"Because a bilingual dictionary bridges two languages, it must account for cultural nuances that affect word meaning.","translation":"由于双语词典连接两种语言，它必须考虑影响词义的文化细微差别。"},{"sentence":"The historical dictionary project, which documents the evolution of vocabulary, reveals how societal changes shape language.","translation":"记录词汇演变的历史词典项目揭示了社会变迁如何塑造语言。"}]},"your":{"examples":[{"sentence":"To enhance your career prospects, it is advisable to acquire skills that are in high demand within your industry.","translation":"为了提升你的职业前景，建议你获取所在行业中需求高的技能。"},{"sentence":"Although your initial hypothesis may be disproven, the process of testing it can yield valuable insights.","translation":"尽管你最初的假设可能被推翻，但检验它的过程可以产生有价值的见解。"},{"sentence":"When you present your research findings, ensure that your methodology is transparent so that others can replicate the study.","translation":"当你展示你的研究发现时，确保你的方法是透明的，以便他人可以复制这项研究。"},{"sentence":"Because your credit score affects loan eligibility, it is wise to monitor your financial behavior regularly.","translation":"由于你的信用评分影响贷款资格，定期监控你的财务行为是明智的。"},{"sentence":"By volunteering in your community, you not only contribute to social welfare but also broaden your own perspective.","translation":"通过在社区做志愿者，你不仅为社会福利做出贡献，还拓宽了你自己的视野。"}]},"bake":{"examples":[{"sentence":"Although the recipe seems simple, you must bake the cake at exactly 180 degrees to ensure it rises properly.","translation":"虽然食谱看起来简单，但你必须以恰好180度烘烤蛋糕，以确保它正常膨胀。"},{"sentence":"Because the dough contains yeast, you should let it rest before you bake it, which allows the bread to develop a lighter texture.","translation":"因为面团含有酵母，你应该在烘烤前让它静置，这使面包形成更轻盈的质地。"},{"sentence":"When you bake cookies with butter instead of margarine, the flavor becomes richer, thereby enhancing the overall taste.","translation":"当你用黄油而不是人造黄油烤饼干时，味道变得更浓郁，从而提升了整体口感。"},{"sentence":"To avoid a soggy bottom, you should bake the pie on a preheated stone, which distributes heat more evenly.","translation":"为了避免底部湿软，你应该在预热的石板上烤馅饼，这使热量分布更均匀。"},{"sentence":"If you bake the vegetables at a high temperature, they caramelize quickly, which intensifies their natural sweetness.","translation":"如果你在高温下烤蔬菜，它们会迅速焦糖化，这增强了它们的天然甜味。"}]},"lord":{"examples":[{"sentence":"Although the lord owned vast estates, his power was often limited by the customs that governed feudal obligations.","translation":"虽然领主拥有广阔的庄园，但他的权力常常受到管理封建义务的习俗的限制。"},{"sentence":"Because the lord chancellor is appointed by the monarch, the role carries significant political influence, which can shape judicial reforms.","translation":"由于大法官由君主任命，该职位具有重大的政治影响力，这可以塑造司法改革。"},{"sentence":"In the prayer, they addressed God as Lord, which reflects a deep sense of reverence and submission to divine authority.","translation":"在祈祷中，他们称上帝为主，这反映了对神圣权威的深深敬畏和顺服。"},{"sentence":"When the feudal lord demanded excessive taxes, the peasants revolted, thereby challenging the established social hierarchy.","translation":"当封建领主征收过高的税收时，农民们起义了，从而挑战了既定的社会等级制度。"},{"sentence":"The lord of the manor held court every month, which ensured that local disputes were resolved without resorting to violence.","translation":"庄园领主每月开庭，这确保了地方纠纷在不诉诸暴力的情况下得到解决。"}]},"amend":{"examples":[{"sentence":"Although the policy was initially effective, the board voted to amend it because new data revealed unintended consequences.","translation":"尽管该政策最初有效，但董事会投票修改它，因为新数据揭示了意想不到的后果。"},{"sentence":"To ensure compliance with international standards, the government must amend the existing legislation before the trade agreement takes effect.","translation":"为确保符合国际标准，政府必须在贸易协定生效前修改现行立法。"},{"sentence":"The committee decided to amend the proposal after receiving feedback, which highlighted several critical flaws in the original plan.","translation":"委员会在收到反馈后决定修改提案，该反馈指出了原计划中的几个关键缺陷。"},{"sentence":"Because the contract contained ambiguous terms, both parties agreed to amend it, thereby avoiding potential disputes.","translation":"由于合同包含模糊条款，双方同意修改它，从而避免了潜在的争议。"},{"sentence":"If the organization fails to amend its outdated practices, it risks losing relevance in a rapidly changing market.","translation":"如果该组织未能修改其过时的做法，它就有可能在快速变化的市场中失去相关性。"}]},"indoor":{"examples":[{"sentence":"Because the outdoor air quality was hazardous, the school relocated all physical education classes to the indoor gymnasium.","translation":"由于室外空气质量有害，学校将所有体育课转移到室内体育馆。"},{"sentence":"The new office design emphasizes indoor greenery, which not only enhances aesthetics but also improves employee well-being.","translation":"新的办公室设计强调室内绿化，这不仅提升了美感，还改善了员工的幸福感。"},{"sentence":"Although the conference was originally planned for the garden, unexpected rain forced the organizers to move it to an indoor venue.","translation":"尽管会议原计划在花园举行，但突如其来的降雨迫使组织者将其移至室内场地。"},{"sentence":"To minimize energy loss, the building uses advanced insulation that maintains a stable indoor temperature throughout the year.","translation":"为了最大限度地减少能量损失，该建筑采用先进的隔热材料，全年保持稳定的室内温度。"},{"sentence":"Public health experts recommend improving indoor ventilation systems, which can significantly reduce the transmission of respiratory viruses.","translation":"公共卫生专家建议改善室内通风系统，这可以显著减少呼吸道病毒的传播。"}]},"polish":{"examples":[{"sentence":"Although the essay had strong arguments, the student took extra time to polish the prose, thereby making it more persuasive.","translation":"尽管文章论点有力，但学生额外花时间润色文笔，从而使其更具说服力。"},{"sentence":"To prepare for the job interview, she decided to polish her public speaking skills through intensive practice sessions.","translation":"为了准备求职面试，她决定通过强化练习来提升公开演讲技巧。"},{"sentence":"The craftsman used a special compound to polish the silverware, which restored its original luster and removed tarnish.","translation":"工匠使用一种特殊的化合物来擦亮银器，这恢复了其原有的光泽并去除了锈蚀。"},{"sentence":"Because the software interface felt clunky, the developers worked overtime to polish the user experience before the launch.","translation":"由于软件界面感觉笨拙，开发人员加班加点在发布前完善用户体验。"},{"sentence":"If you polish your manuscript carefully, you can eliminate errors that might otherwise undermine your credibility as a researcher.","translation":"如果你仔细润色手稿，就能消除那些可能损害你作为研究人员可信度的错误。"}]},"engagement":{"examples":[{"sentence":"Because their engagement was announced during the annual family reunion, it became a cherished memory for all who attended.","translation":"因为他们的订婚是在年度家庭团聚时宣布的，所以它成为了所有出席者珍贵的回忆。"},{"sentence":"The couple's engagement, which followed a romantic proposal in Paris, symbolized their commitment to a shared future.","translation":"这对夫妇的订婚是在巴黎浪漫求婚后进行的，它象征着他们对共同未来的承诺。"},{"sentence":"Although they had a long engagement, it allowed them to save enough money for a wedding that reflected their personal values.","translation":"尽管他们订婚时间很长，但这让他们能够攒够钱举办一场反映他们个人价值观的婚礼。"},{"sentence":"Her engagement ring, a vintage piece passed down through generations, not only represented their love but also honored family heritage.","translation":"她的订婚戒指是一件代代相传的古董，不仅代表了他们的爱情，也尊重了家族遗产。"},{"sentence":"When they announced their engagement, friends and colleagues expressed heartfelt congratulations, thereby strengthening their social bonds.","translation":"当他们宣布订婚时，朋友和同事表达了衷心的祝贺，从而加强了他们的社会联系。"}]},"compensate":{"examples":[{"sentence":"To compensate for the reduced natural light, the architect incorporated reflective surfaces that brightened the entire interior space.","translation":"为了弥补自然光的减少，建筑师采用了反射表面，使整个室内空间明亮起来。"},{"sentence":"Although the company could not restore the lost data, it agreed to compensate clients with free services for an extended period.","translation":"尽管公司无法恢复丢失的数据，但它同意用延长免费服务期来补偿客户。"},{"sentence":"Because the drought severely damaged crops, the government implemented a program to compensate farmers for their financial losses.","translation":"因为干旱严重损害了庄稼，政府实施了一项计划来补偿农民的经济损失。"},{"sentence":"Her strong analytical skills compensate for her lack of experience, which makes her a valuable asset to the research team.","translation":"她强大的分析能力弥补了经验的不足，这使她成为研究团队的宝贵财富。"},{"sentence":"The new policy aims to compensate employees for overtime through additional leave days rather than monetary payments.","translation":"新政策旨在通过额外的休假日而非货币支付来补偿员工的加班。"}]},"imaginary":{"examples":[{"sentence":"Although the threat was entirely imaginary, the government still allocated substantial funds to address public concerns.","translation":"尽管威胁完全是虚构的，政府仍然拨出大量资金来应对公众的担忧。"},{"sentence":"The imaginary line that divides the two communities has no legal basis, yet it profoundly shapes their daily interactions.","translation":"划分这两个社区的假想界线没有法律依据，却深刻影响着他们的日常交往。"},{"sentence":"Because the child's imaginary companion provided emotional support, psychologists studied the phenomenon to understand coping mechanisms.","translation":"因为孩子的假想伙伴提供了情感支持，心理学家研究这一现象以理解应对机制。"},{"sentence":"The novel's imaginary world, which mirrors our own societal flaws, challenges readers to reflect on real-world injustices.","translation":"小说中映射我们自身社会缺陷的虚构世界，促使读者反思现实中的不公。"},{"sentence":"While the danger proved imaginary, the evacuation drill demonstrated the community's preparedness for genuine emergencies.","translation":"虽然危险被证明是虚构的，但疏散演习展示了社区对真实紧急情况的准备程度。"}]},"tradition":{"examples":[{"sentence":"Although the tradition of arranged marriages is declining in urban areas, it still persists in many rural communities where family ties remain strong.","translation":"尽管包办婚姻的传统在城市地区正在减少，但在许多家庭纽带依然牢固的农村社区，它仍然存在。"},{"sentence":"The tradition of celebrating the Lunar New Year with elaborate feasts and fireworks, which dates back thousands of years, continues to unite families across generations.","translation":"用丰盛的宴席和烟花庆祝农历新年的传统可以追溯到几千年前，它继续将几代人团结在一起。"},{"sentence":"Because the oral tradition of passing down folk tales is fading, many cultural organizations are now recording these stories to preserve them for future generations.","translation":"由于口述民间故事的传统正在消失，许多文化组织现在正在记录这些故事，以便为后代保存它们。"},{"sentence":"While some view tradition as a barrier to progress, others argue that it provides a sense of identity and continuity in an ever-changing world.","translation":"虽然有些人认为传统是进步的障碍，但其他人则认为，它在不断变化的世界中提供了一种认同感和连续性。"},{"sentence":"The university's tradition of holding an annual research symposium not only fosters academic exchange but also encourages interdisciplinary collaboration among scholars.","translation":"该大学举办年度研究研讨会的传统不仅促进了学术交流，还鼓励了学者之间的跨学科合作。"}]},"ticket":{"examples":[{"sentence":"Because the concert ticket included a backstage pass, the fans were able to meet the performers after the show, which made the experience unforgettable.","translation":"由于音乐会门票包含后台通行证，歌迷们得以在演出后与表演者见面，这使得这次经历令人难忘。"},{"sentence":"The introduction of a single electronic ticket for all public transport in the city has simplified commuting, thereby reducing the need for multiple paper tickets.","translation":"该市所有公共交通采用单一电子客票简化了通勤，从而减少了对多种纸质车票的需求。"},{"sentence":"Although the ticket price for the charity gala was high, attendees knew that their contribution would support vital medical research, which justified the expense.","translation":"尽管慈善晚会的门票价格很高，但与会者知道他们的捐款将支持重要的医学研究，这证明了这笔费用的合理性。"},{"sentence":"When purchasing a ticket online, customers must provide accurate personal information to ensure that the booking is processed without any delays.","translation":"在线购票时，客户必须提供准确的个人信息，以确保预订处理不会出现任何延误。"},{"sentence":"The museum offers a discounted ticket to students, which encourages young people to engage with art and history while making cultural education more accessible.","translation":"博物馆为学生提供折扣门票，这鼓励年轻人接触艺术和历史，同时使文化教育更容易获得。"}]},"gramme":{"examples":[{"sentence":"Although a single gramme of salt seems negligible, its cumulative effect on blood pressure can be significant over time.","translation":"尽管一克盐看似微不足道，但随着时间的推移，它对血压的累积影响可能很大。"},{"sentence":"The jeweler used a scale that could measure to the nearest gramme, which ensured accurate pricing of precious metals.","translation":"珠宝商使用了一台可以精确到克的秤，这确保了贵金属的准确定价。"},{"sentence":"Because each gramme of fuel adds weight to the spacecraft, engineers strive to minimize every component's mass.","translation":"由于每克燃料都会增加航天器的重量，工程师们努力将每个部件的质量降至最低。"},{"sentence":"When preparing the chemical solution, adding an extra gramme of the reagent can alter the reaction rate dramatically.","translation":"在制备化学溶液时，多加一克试剂会显著改变反应速率。"},{"sentence":"The nutrition label indicates that the product contains less than one gramme of sugar per serving, making it suitable for diabetics.","translation":"营养标签显示该产品每份含糖量不到一克，因此适合糖尿病患者食用。"}]},"visible":{"examples":[{"sentence":"Although the stars are always present, they become visible only when the sky is sufficiently dark.","translation":"尽管星星始终存在，但只有在天空足够黑暗时它们才变得可见。"},{"sentence":"The economic downturn made the flaws in the company's strategy visible, which prompted a comprehensive restructuring.","translation":"经济衰退使公司战略中的缺陷暴露无遗，这促使了全面的重组。"},{"sentence":"Because the bacteria are not visible to the naked eye, proper hygiene practices are essential to prevent infection.","translation":"由于细菌肉眼不可见，正确的卫生习惯对于预防感染至关重要。"},{"sentence":"When the artist added the final highlights, the subject's expression became more visible and emotionally resonant.","translation":"当艺术家添加最后的亮部时，主题的表情变得更加明显且富有情感共鸣。"},{"sentence":"The new telescope makes distant galaxies visible, thereby expanding our understanding of the universe.","translation":"新型望远镜使遥远的星系可见，从而拓展了我们对宇宙的理解。"}]},"jealous":{"examples":[{"sentence":"Although she felt jealous of her colleague's success, she used that emotion as motivation to improve her own skills.","translation":"尽管她嫉妒同事的成功，但她将这种情绪作为提高自身技能的动力。"},{"sentence":"A manager who is jealous of talented employees may hinder their growth, which ultimately harms the organization.","translation":"嫉妒有才华员工的经理可能会阻碍他们的成长，这最终会损害组织。"},{"sentence":"Because he was jealous of his brother's achievements, he worked harder to prove his own worth.","translation":"因为他嫉妒哥哥的成就，所以他更加努力地工作以证明自己的价值。"},{"sentence":"When nations become jealous of each other's resources, diplomatic tensions can escalate into conflict.","translation":"当各国相互嫉妒对方的资源时，外交紧张局势可能升级为冲突。"},{"sentence":"The company's jealous protection of its patents prevented competitors from copying its technology, thereby maintaining its market lead.","translation":"该公司对其专利的谨慎保护防止了竞争对手抄袭其技术，从而保持了市场领先地位。"}]},"wear":{"examples":[{"sentence":"Although the new fabric is designed to resist wear, prolonged exposure to sunlight may still cause fading.","translation":"尽管这种新面料旨在抗磨损，但长时间暴露在阳光下仍可能导致褪色。"},{"sentence":"Engineers must monitor the wear of critical components, which can lead to catastrophic failure if left unchecked.","translation":"工程师必须监测关键部件的磨损，因为如果不加以检查，可能会导致灾难性故障。"},{"sentence":"In formal settings, individuals often wear attire that reflects their cultural heritage, thereby preserving tradition.","translation":"在正式场合，人们经常穿着反映其文化遗产的服装，从而保留传统。"},{"sentence":"Because the machine shows excessive wear after only six months, the manufacturer has issued a recall.","translation":"由于该机器仅六个月后就出现过度磨损，制造商已发出召回通知。"},{"sentence":"Athletes who wear high-quality footwear reduce the risk of injury, which is essential for maintaining peak performance.","translation":"穿着高质量鞋类的运动员能降低受伤风险，这对于保持最佳表现至关重要。"}]},"manuscript":{"examples":[{"sentence":"Although the manuscript was incomplete, the editor recognized its potential and offered a contract.","translation":"尽管手稿尚未完成，编辑还是看出了它的潜力并提供了合同。"},{"sentence":"The researcher spent months deciphering the ancient manuscript, which contained valuable historical records.","translation":"研究人员花了数月时间破译这份古代手稿，其中包含宝贵的历史记录。"},{"sentence":"Because the manuscript was handwritten, the publisher required a digital version before typesetting.","translation":"由于手稿是手写的，出版社在排版前要求提供电子版。"},{"sentence":"The author donated the original manuscript to the library, thereby ensuring its preservation for future generations.","translation":"作者将原始手稿捐赠给图书馆，从而确保其为后代保存。"},{"sentence":"When the manuscript was finally published, it received critical acclaim for its innovative narrative structure.","translation":"当手稿最终出版时，因其创新的叙事结构而获得评论界的好评。"}]},"medieval":{"examples":[{"sentence":"Although medieval castles were primarily built for defense, their imposing structures now attract millions of tourists each year.","translation":"尽管中世纪城堡最初主要用于防御，但其雄伟的建筑如今每年吸引数百万游客。"},{"sentence":"Because medieval trade routes connected distant regions, they facilitated not only economic exchange but also cultural diffusion.","translation":"由于中世纪的贸易路线连接了遥远的地区，它们不仅促进了经济交流，还推动了文化传播。"},{"sentence":"The medieval concept of chivalry, which emphasized honor and courtesy, continues to influence modern ideals of gentlemanly behavior.","translation":"中世纪强调荣誉和礼貌的骑士精神概念，至今仍影响着现代绅士行为的理想。"},{"sentence":"While medieval scholars preserved classical knowledge, they also made original contributions to fields such as astronomy and medicine.","translation":"虽然中世纪的学者保存了古典知识，但他们也在天文学和医学等领域做出了原创性贡献。"},{"sentence":"The decline of the medieval feudal system, which was accelerated by the Black Death, led to profound social and economic transformations.","translation":"中世纪封建制度的衰落，因黑死病而加速，导致了深刻的社会和经济变革。"}]},"outlook":{"examples":[{"sentence":"A global outlook is essential for business leaders, because it enables them to navigate cross-cultural challenges effectively.","translation":"全球视野对商业领袖至关重要，因为它使他们能够有效应对跨文化挑战。"},{"sentence":"The long-term outlook for renewable energy remains positive, despite short-term fluctuations in oil prices.","translation":"尽管油价短期波动，可再生能源的长期前景依然乐观。"},{"sentence":"Her optimistic outlook on life, which she developed through years of volunteer work, inspires everyone around her.","translation":"她通过多年志愿工作培养的乐观人生观，激励着身边的每一个人。"},{"sentence":"The report provides a comprehensive outlook on the housing market, thereby helping investors make informed decisions.","translation":"该报告提供了对房地产市场的全面展望，从而帮助投资者做出明智的决策。"},{"sentence":"When students adopt a growth outlook, they are more likely to embrace challenges and persist through difficulties.","translation":"当学生采取成长型心态时，他们更有可能接受挑战并在困难中坚持。"}]},"cigaret":{"examples":[{"sentence":"Although a single cigaret may seem harmless, its toxic chemicals can initiate cellular damage that accumulates over time.","translation":"尽管一支香烟看似无害，但其有毒化学物质可能引发细胞损伤，并随时间累积。"},{"sentence":"Because the tobacco industry once marketed the cigaret as a symbol of sophistication, many people were misled about its dangers.","translation":"由于烟草业曾将香烟宣传为成熟的象征，许多人被误导而忽视了其危害。"},{"sentence":"When a person lights a cigaret, the combustion releases thousands of compounds, many of which are carcinogenic.","translation":"当一个人点燃一支香烟时，燃烧会释放数千种化合物，其中许多是致癌物。"},{"sentence":"If governments ban the sale of single cigarettes, they can reduce youth experimentation, which often starts with just one cigaret.","translation":"如果政府禁止销售单支香烟，就能减少青少年的尝试行为，而这种行为往往始于一支香烟。"},{"sentence":"While nicotine patches help smokers quit, the ritual of holding a cigaret remains a psychological barrier that is difficult to overcome.","translation":"虽然尼古丁贴片有助于戒烟，但手持香烟的仪式感仍是一个难以克服的心理障碍。"}]},"give":{"examples":[{"sentence":"The fabric's natural give ensures comfort during movement, which is why it is preferred for athletic wear.","translation":"这种面料的天然弹性确保了运动时的舒适度，这就是它被运动服装所青睐的原因。"},{"sentence":"Although the policy showed little give initially, public pressure eventually forced a compromise that satisfied both sides.","translation":"尽管该政策最初几乎没有让步，但公众压力最终迫使双方达成了妥协。"},{"sentence":"Because the rope has enough give, it can absorb sudden tension without snapping, thereby preventing accidents.","translation":"因为绳子有足够的弹性，它能吸收突然的拉力而不会断裂，从而防止事故。"},{"sentence":"In structural engineering, the give of materials must be calculated precisely to ensure that buildings can withstand earthquakes.","translation":"在结构工程中，必须精确计算材料的弹性，以确保建筑物能承受地震。"},{"sentence":"While some rigidity is necessary in rules, a certain give allows for adaptation to unforeseen circumstances, which promotes fairness.","translation":"虽然规则需要一定的刚性，但某种程度的弹性允许适应不可预见的情况，这促进了公平性。"}]},"labor":{"examples":[{"sentence":"Although manual labor is often undervalued, it forms the backbone of many industries that rely on physical work.","translation":"尽管体力劳动常常被低估，但它构成了许多依赖体力工作的行业的支柱。"},{"sentence":"Because the cost of labor has risen in developed countries, many companies have outsourced production to regions with lower wages.","translation":"由于发达国家劳动力成本上升，许多公司已将生产外包到工资较低的地区。"},{"sentence":"When labor unions negotiate collectively, they can secure better working conditions, which benefits not only members but also the wider workforce.","translation":"当工会集体谈判时，他们能争取到更好的工作条件，这不仅惠及会员，也惠及更广泛的劳动力。"},{"sentence":"If child labor is to be eradicated, governments must enforce strict laws while providing educational alternatives to impoverished families.","translation":"如果要根除童工，政府必须执行严格的法律，同时为贫困家庭提供教育替代方案。"},{"sentence":"The division of labor allows workers to specialize, thereby increasing efficiency, but it can also lead to monotonous tasks that reduce job satisfaction.","translation":"劳动分工使工人能够专业化，从而提高效率，但也可能导致单调的任务，降低工作满意度。"}]},"suspicious":{"examples":[{"sentence":"Although the transaction appeared legitimate, the bank flagged it as suspicious because the amount deviated significantly from the customer's usual pattern.","translation":"尽管交易看似合法，但银行因其金额明显偏离客户惯常模式而将其标记为可疑。"},{"sentence":"The auditor became suspicious when several invoices lacked proper documentation, which suggested a possible breach of protocol.","translation":"审计员发现多张发票缺少适当凭证时起了疑心，这表明可能存在违规行为。"},{"sentence":"Because the experiment produced results inconsistent with established theory, the researchers remained suspicious of the data until they replicated the findings.","translation":"由于实验结果与既有理论不一致，研究人员在重复验证之前始终对数据持怀疑态度。"},{"sentence":"A sudden surge in website traffic from an unfamiliar region made the security team suspicious of a potential cyberattack, thereby prompting an immediate investigation.","translation":"来自陌生地区的网站流量突然激增，让安全团队怀疑可能发生了网络攻击，从而促使立即展开调查。"},{"sentence":"The public remains suspicious of claims that the new policy will reduce inequality, given the lack of transparent implementation plans.","translation":"鉴于缺乏透明的实施计划，公众仍然怀疑新政策能减少不平等这一说法。"}]},"fax":{"examples":[{"sentence":"Because the contract required a signature, we had to send it by fax rather than by email.","translation":"由于合同需要签名，我们不得不通过传真而不是电子邮件发送它。"},{"sentence":"Although digital communication has become dominant, many law firms still rely on fax for transmitting sensitive documents.","translation":"尽管数字通信已占主导地位，许多律师事务所仍然依赖传真传输敏感文件。"},{"sentence":"The university requires applicants to submit their transcripts via fax if the online portal is unavailable.","translation":"如果在线门户不可用，大学要求申请人通过传真提交成绩单。"},{"sentence":"In order to ensure timely delivery, the medical report was sent by fax directly to the specialist's office.","translation":"为了确保及时送达，医疗报告通过传真直接发送到了专家办公室。"},{"sentence":"While email is faster, a fax provides a legally recognized transmission record that is often required in formal disputes.","translation":"虽然电子邮件更快，但传真提供了法律认可的传输记录，这在正式纠纷中常常是必需的。"}]},"no":{"examples":[{"sentence":"There is no evidence that reducing class sizes alone significantly improves student achievement.","translation":"没有证据表明仅仅缩小班级规模就能显著提高学生成绩。"},{"sentence":"Without adequate funding, there is no guarantee that the public health initiative will succeed.","translation":"没有足够的资金，就无法保证公共卫生倡议能够成功。"},{"sentence":"The committee found no justification for continuing a policy that had yielded no measurable benefits.","translation":"委员会认为没有理由继续一项未产生可衡量效益的政策。"},{"sentence":"In many rural areas, there is no access to high-speed internet, which limits educational and economic opportunities.","translation":"在许多农村地区，没有高速互联网接入，这限制了教育和经济机会。"},{"sentence":"A society that provides no support for lifelong learning risks widening the skills gap over time.","translation":"一个不为终身学习提供支持的社会，随着时间的推移，可能会扩大技能差距。"}]},"prefer":{"examples":[{"sentence":"Although many commuters prefer driving for its convenience, others choose public transport to reduce their carbon footprint.","translation":"尽管许多通勤者因为便利而更喜欢开车，但其他人选择公共交通以减少碳足迹。"},{"sentence":"When selecting a university, students often prefer institutions that offer strong internship programs, which can enhance their employability.","translation":"在选择大学时，学生往往更喜欢提供强大实习项目的院校，这能提高他们的就业能力。"},{"sentence":"Because remote work eliminates commuting time, many employees now prefer it over traditional office arrangements.","translation":"由于远程工作消除了通勤时间，许多员工现在更喜欢它而非传统的办公室安排。"},{"sentence":"While some investors prefer high-risk stocks for potential gains, others favor bonds to ensure a stable income.","translation":"虽然一些投资者为了潜在收益而更喜欢高风险股票，但其他人青睐债券以确保稳定收入。"},{"sentence":"To maintain a healthy lifestyle, nutritionists recommend that people prefer whole grains over refined carbohydrates.","translation":"为了保持健康的生活方式，营养学家建议人们更喜欢全谷物而非精制碳水化合物。"}]},"pyramid":{"examples":[{"sentence":"The Great Pyramid of Giza, which was constructed as a royal tomb, continues to fascinate archaeologists with its precise alignment.","translation":"吉萨大金字塔是作为皇家陵墓建造的，其精确的排列至今仍令考古学家着迷。"},{"sentence":"Because the food pyramid visually represents nutritional guidelines, it helps people make healthier dietary choices.","translation":"由于食物金字塔直观地展示了营养指南，它帮助人们做出更健康的饮食选择。"},{"sentence":"In corporate hierarchies, the pyramid structure often concentrates decision-making power at the top, thereby slowing innovation.","translation":"在公司等级制度中，金字塔结构往往将决策权集中在顶层，从而减缓创新。"},{"sentence":"Although the population pyramid of Japan shows a shrinking base, indicating an aging society, some African nations have a youthful profile.","translation":"尽管日本的人口金字塔显示底部收缩，表明老龄化社会，但一些非洲国家呈现出年轻化特征。"},{"sentence":"To understand ancient Egyptian society, scholars study the social pyramid, which placed the pharaoh at the apex and slaves at the bottom.","translation":"为了理解古埃及社会，学者们研究社会金字塔，它将法老置于顶端，奴隶置于底层。"}]},"journey":{"examples":[{"sentence":"Although the journey was fraught with unexpected delays, the travelers maintained their optimism by focusing on the destination.","translation":"尽管旅程充满了意外的延误，但旅行者们通过专注于目的地保持了乐观。"},{"sentence":"The journey toward mastering a new language requires consistent practice, which ultimately reshapes cognitive patterns.","translation":"掌握一门新语言的旅程需要持续练习，这最终会重塑认知模式。"},{"sentence":"Because the journey through the desert tested their endurance, the explorers emerged with a deeper appreciation for resourcefulness.","translation":"因为穿越沙漠的旅程考验了他们的耐力，探险者们对足智多谋有了更深的体会。"},{"sentence":"While the journey of scientific discovery is often nonlinear, each setback provides valuable data that refines the hypothesis.","translation":"虽然科学发现的旅程往往是非线性的，但每次挫折都提供了完善假设的宝贵数据。"},{"sentence":"The journey from novice to expert is marked by deliberate practice, without which true proficiency remains elusive.","translation":"从新手到专家的旅程以刻意练习为标志，没有它，真正的熟练仍然难以企及。"}]},"fairy":{"examples":[{"sentence":"Although fairy tales are often dismissed as mere entertainment, they encode cultural wisdom that shapes moral development.","translation":"尽管童话故事常被视为纯粹的娱乐，但它们编码了塑造道德发展的文化智慧。"},{"sentence":"The fairy tale, which has been retold across generations, adapts its motifs to reflect contemporary societal anxieties.","translation":"这个童话故事经过代代相传，调整其主题以反映当代社会的焦虑。"},{"sentence":"Because fairy tales employ archetypal characters, they resonate universally, thereby transcending linguistic and cultural barriers.","translation":"因为童话故事使用原型人物，它们能引起普遍共鸣，从而超越语言和文化障碍。"},{"sentence":"While the fairy tale appears simplistic, its layered symbolism offers profound insights into human psychology.","translation":"虽然这个童话故事看似简单，但其多层次的象征意义为人类心理提供了深刻的洞见。"},{"sentence":"The fairy tale, rather than presenting a naive worldview, often subverts expectations to critique social norms.","translation":"这个童话故事并没有呈现天真的世界观，而是常常颠覆预期以批判社会规范。"}]},"mystery":{"examples":[{"sentence":"Although the mystery of the lost city captivated archaeologists for centuries, recent satellite imagery finally revealed its location.","translation":"尽管失落之城的奥秘吸引了考古学家几个世纪，但最近的卫星图像终于揭示了它的位置。"},{"sentence":"The mystery surrounding the sudden market shift prompted analysts to reexamine their models, which had overlooked key variables.","translation":"围绕市场突然转变的谜团促使分析师重新审视他们的模型，这些模型忽略了关键变量。"},{"sentence":"Because the mystery of the disease's origin remained unsolved, researchers adopted a multidisciplinary approach to identify the pathogen.","translation":"因为疾病起源的谜团仍未解开，研究人员采用了多学科方法来识别病原体。"},{"sentence":"While the mystery of dark energy challenges fundamental physics, it also drives the development of innovative observational technologies.","translation":"虽然暗能量的奥秘挑战着基础物理学，但它也推动了创新观测技术的发展。"},{"sentence":"The mystery of how ancient civilizations achieved such precision in construction continues to inspire engineering studies, thereby bridging past and present.","translation":"古代文明如何在建筑中达到如此精确的谜团继续激发工程研究，从而连接了过去与现在。"}]},"artistic":{"examples":[{"sentence":"Although the gallery is small, it showcases an artistic diversity that attracts visitors from around the world.","translation":"尽管画廊很小，但它展示的艺术多样性吸引了来自世界各地的游客。"},{"sentence":"The architect's artistic vision, which blends modern and classical elements, has redefined the city's skyline.","translation":"建筑师的艺术愿景融合了现代与古典元素，重新定义了城市的天际线。"},{"sentence":"Because she received early exposure to various art forms, her artistic talent developed rapidly during childhood.","translation":"由于她早期接触了多种艺术形式，她的艺术才能在童年时期迅速发展。"},{"sentence":"The film's artistic merit lies not only in its stunning visuals but also in its profound narrative structure.","translation":"这部电影的艺术价值不仅在于其令人惊叹的视觉效果，还在于其深刻的叙事结构。"},{"sentence":"While some critics dismissed the work as overly abstract, its artistic significance has grown over time.","translation":"尽管一些评论家认为该作品过于抽象，但其艺术意义随着时间的推移而增长。"}]},"publicity":{"examples":[{"sentence":"The company launched a publicity campaign that emphasized environmental sustainability, thereby attracting eco-conscious consumers.","translation":"该公司发起了一场强调环境可持续性的宣传活动，从而吸引了具有环保意识的消费者。"},{"sentence":"Although the celebrity tried to avoid publicity, the media scrutiny intensified after the incident.","translation":"尽管这位名人试图避免宣传，但事件发生后媒体的审查更加严格。"},{"sentence":"Effective publicity strategies, which often involve social media influencers, can significantly boost product sales.","translation":"有效的宣传策略通常涉及社交媒体影响者，可以显著提高产品销量。"},{"sentence":"Because the research breakthrough had global implications, the scientists sought widespread publicity to inform the public.","translation":"由于这一研究突破具有全球影响，科学家们寻求广泛宣传以告知公众。"},{"sentence":"Negative publicity, if not addressed promptly, can erode consumer trust and damage brand reputation.","translation":"负面宣传如果不及时处理，会侵蚀消费者信任并损害品牌声誉。"}]},"practice":{"examples":[{"sentence":"Deliberate practice, which involves focused repetition and immediate feedback, is essential for mastering complex skills.","translation":"刻意练习涉及专注的重复和即时反馈，对于掌握复杂技能至关重要。"},{"sentence":"Although the policy appears sound in theory, its implementation in practice often encounters unforeseen obstacles.","translation":"尽管该政策在理论上看似合理，但在实践中实施时常常遇到无法预见的障碍。"},{"sentence":"Regular practice not only reinforces knowledge but also cultivates the discipline required for long-term academic success.","translation":"定期练习不仅能巩固知识，还能培养长期学业成功所需的纪律性。"},{"sentence":"The company adopted a sustainable practice of recycling waste materials, thereby reducing its environmental footprint.","translation":"该公司采取了回收废料的可持续做法，从而减少了环境足迹。"},{"sentence":"In many professions, ethical practice demands that practitioners prioritize client welfare over personal gain.","translation":"在许多行业中，合乎道德的实践要求从业者将客户福祉置于个人利益之上。"}]},"conservative":{"examples":[{"sentence":"Although the committee proposed a conservative budget, it still allocated sufficient funds for essential research programs.","translation":"尽管委员会提出了一个保守的预算，但它仍为必要的研究项目分配了足够的资金。"},{"sentence":"A conservative investment portfolio, which prioritizes bonds over stocks, can provide stability during market volatility.","translation":"一个优先考虑债券而非股票的保守投资组合，可以在市场波动期间提供稳定性。"},{"sentence":"Because the engineer used a conservative safety factor, the bridge withstood forces far beyond the expected load.","translation":"由于工程师使用了保守的安全系数，这座桥承受了远超预期负荷的力量。"},{"sentence":"While the startup embraced disruptive innovation, the established firm maintained a conservative approach to product development.","translation":"虽然初创公司拥抱颠覆性创新，但老牌公司在产品开发上保持了保守的方法。"},{"sentence":"The doctor recommended a conservative treatment plan, thereby avoiding unnecessary surgery and allowing the body to heal naturally.","translation":"医生推荐了一个保守的治疗方案，从而避免了不必要的手术，让身体自然愈合。"}]},"stair":{"examples":[{"sentence":"Although the stair was steep and narrow, the elderly professor climbed it daily to maintain his health.","translation":"尽管楼梯又陡又窄，这位年迈的教授每天爬楼梯以保持健康。"},{"sentence":"Because the elevator was under repair, all employees had to use the stair, which caused a brief delay.","translation":"由于电梯正在维修，所有员工不得不走楼梯，这导致了短暂的延误。"},{"sentence":"The architect designed a spiral stair that not only saved space but also added an artistic element to the lobby.","translation":"建筑师设计了一个螺旋楼梯，不仅节省了空间，还为大厅增添了艺术元素。"},{"sentence":"Installing a handrail along the stair is essential to ensure the safety of elderly residents in the building.","translation":"沿着楼梯安装扶手对于确保楼内老年居民的安全至关重要。"},{"sentence":"When the fire alarm sounded, the crowd descended the stair in an orderly manner, thereby avoiding panic.","translation":"当火警响起时，人群有序地走下楼梯，从而避免了恐慌。"}]},"tail":{"examples":[{"sentence":"Although the peacock's tail is a burden in flight, it serves as a powerful signal of genetic fitness to potential mates.","translation":"尽管孔雀的尾巴在飞行中是一种负担，但它向潜在配偶传递了强大的遗传适应性信号。"},{"sentence":"The comet's tail, which consists of dust and ionized gas, always points away from the sun due to solar wind pressure.","translation":"彗星的尾巴由尘埃和电离气体组成，由于太阳风的压力，它总是背向太阳。"},{"sentence":"In statistical distributions, a long tail indicates that rare events occur more frequently than a normal distribution would predict.","translation":"在统计分布中，长尾表明罕见事件的发生频率高于正态分布的预测。"},{"sentence":"Because the detective needed solid evidence, he decided to tail the suspect through the crowded market without being noticed.","translation":"由于侦探需要确凿的证据，他决定在拥挤的市场中跟踪嫌疑人而不被发现。"},{"sentence":"The aircraft's tail section, which houses the auxiliary power unit, sustained severe damage during the emergency landing.","translation":"飞机的尾部装有辅助动力装置，在紧急迫降中遭受了严重损坏。"}]},"angry":{"examples":[{"sentence":"When the committee ignored the evidence that had been carefully collected over several months, many researchers became understandably angry.","translation":"当委员会忽视了经过数月精心收集的证据时，许多研究人员变得愤怒是可以理解的。"},{"sentence":"Because the policy failed to address the root causes of inequality, citizens grew increasingly angry and demanded a more comprehensive reform.","translation":"由于该政策未能解决不平等的根本原因，公民们变得越来越愤怒，并要求进行更全面的改革。"},{"sentence":"Although the manager’s decision was based on short-term profits, it made the long-term employees angry enough to consider collective action.","translation":"尽管经理的决定基于短期利润，但它让长期员工愤怒到考虑采取集体行动。"},{"sentence":"The public became angry after learning that the company had concealed safety risks for years, which ultimately led to stricter regulations.","translation":"在得知该公司多年来隐瞒安全风险后，公众变得愤怒，这最终导致了更严格的监管。"},{"sentence":"He was not angry about the criticism itself, but about the fact that it was delivered without any constructive suggestions.","translation":"他生气的不是批评本身，而是批评时没有提出任何建设性建议。"}]},"twinkle":{"examples":[{"sentence":"Although the night was overcast, a single star managed to twinkle through a break in the clouds.","translation":"尽管夜晚多云，一颗星星还是透过云层的缝隙闪烁。"},{"sentence":"The child's eyes would twinkle with delight whenever she saw the colorful balloons, which reminded her of the carnival.","translation":"每当看到那些让她想起嘉年华的彩色气球时，孩子的眼睛就会闪烁着喜悦。"},{"sentence":"Because the old lighthouse lamp continued to twinkle reliably, ships could navigate safely through the treacherous channel.","translation":"因为那座旧灯塔的灯持续可靠地闪烁，船只得以安全通过那条危险的航道。"},{"sentence":"The diamond on her finger seemed to twinkle more brilliantly under the chandelier's light, thereby drawing everyone's attention.","translation":"她手指上的钻石在吊灯下似乎闪烁得更加耀眼，从而吸引了所有人的注意。"},{"sentence":"While the city slept, the neon signs continued to twinkle, casting a colorful glow on the empty streets.","translation":"当城市沉睡时，霓虹灯继续闪烁，在空旷的街道上投下彩色的光芒。"}]},"warn":{"examples":[{"sentence":"Although the initial symptoms seem mild, doctors warn that the disease can progress rapidly if left untreated.","translation":"尽管初期症状看似轻微，医生警告说如果不治疗，这种疾病会迅速恶化。"},{"sentence":"The teacher felt compelled to warn the students about the consequences of plagiarism, which could result in expulsion.","translation":"老师觉得有必要警告学生抄袭的后果，这可能导致开除。"},{"sentence":"Because the dam showed signs of structural weakness, engineers had to warn the downstream communities of a potential breach.","translation":"因为大坝出现了结构薄弱的迹象，工程师不得不警告下游社区有溃坝的可能。"},{"sentence":"Financial experts warn that investing in volatile markets without proper research can lead to significant losses.","translation":"金融专家警告说，在没有充分研究的情况下投资于动荡的市场可能导致重大损失。"},{"sentence":"The sign at the cliff's edge was placed to warn hikers of the steep drop, thereby preventing accidents.","translation":"悬崖边的标志是为了警告徒步者注意陡峭的落差，从而防止事故。"}]},"despatch":{"examples":[{"sentence":"Because the humanitarian crisis worsened, the United Nations decided to despatch an emergency relief team to the region.","translation":"由于人道主义危机恶化，联合国决定向该地区派遣一支紧急救援队。"},{"sentence":"The editor will despatch a journalist to cover the summit, which is expected to yield significant policy changes.","translation":"编辑将派遣一名记者去报道这次峰会，预计峰会将产生重大的政策变化。"},{"sentence":"To ensure the parts arrived on time, the manufacturer had to despatch them via express courier rather than standard mail.","translation":"为确保零件准时到达，制造商不得不通过快递而非普通邮件发送它们。"},{"sentence":"Although the weather was deteriorating, the captain chose to despatch the rescue boat immediately to save the stranded sailors.","translation":"尽管天气正在恶化，船长还是选择立即派出救援船去营救被困的水手。"},{"sentence":"The general ordered his officers to despatch the reconnaissance unit at dawn, thereby gaining a tactical advantage.","translation":"将军命令他的军官们在黎明时派遣侦察部队，从而获得战术优势。"}]},"gross":{"examples":[{"sentence":"Although the company's gross income appeared impressive, the net profit was significantly reduced by operational expenses.","translation":"尽管公司的总收入看起来令人印象深刻，但净利润因运营开支而大幅减少。"},{"sentence":"The gross negligence of the safety protocols resulted in a severe accident, which prompted a thorough investigation.","translation":"对安全规程的严重疏忽导致了一起严重事故，这促使了彻底调查。"},{"sentence":"When calculating the gross domestic product, economists must account for all goods and services produced within the country.","translation":"在计算国内生产总值时，经济学家必须考虑该国境内生产的所有商品和服务。"},{"sentence":"The report revealed a gross overestimation of the project's benefits, which led to a reallocation of resources.","translation":"报告显示对项目收益的严重高估，这导致了资源的重新分配。"},{"sentence":"Because the gross weight of the package exceeded the carrier's limit, additional shipping charges were applied.","translation":"由于包裹的毛重超过了承运人的限制，因此产生了额外的运费。"}]},"relax":{"examples":[{"sentence":"Although the government decided to relax import restrictions, domestic industries feared a surge in foreign competition.","translation":"尽管政府决定放宽进口限制，但国内产业担心外国竞争激增。"},{"sentence":"To ensure long-term productivity, companies should encourage employees to relax during breaks rather than work continuously.","translation":"为了确保长期生产力，公司应鼓励员工在休息时放松，而不是持续工作。"},{"sentence":"When the central bank decided to relax monetary policy, it aimed to stimulate economic growth through lower interest rates.","translation":"当中央银行决定放松货币政策时，其目标是通过降低利率来刺激经济增长。"},{"sentence":"Because the strict regulations were hindering innovation, the agency chose to relax certain rules for startups.","translation":"由于严格的法规阻碍了创新，该机构选择为初创企业放宽某些规定。"},{"sentence":"While it is important to maintain discipline, teachers should sometimes relax classroom rules to create a more engaging environment.","translation":"虽然保持纪律很重要，但教师有时应放宽课堂规则，以创造一个更有吸引力的环境。"}]},"call":{"examples":[{"sentence":"Although the call for volunteers attracted hundreds of applicants, only a few possessed the required technical skills.","translation":"尽管招募志愿者的号召吸引了数百名申请者，但只有少数人具备所需的技术技能。"},{"sentence":"The professor issued a call for papers that specifically addressed the ethical implications of artificial intelligence.","translation":"教授发出了征集论文的号召，专门探讨人工智能的伦理影响。"},{"sentence":"Because the international call lasted over an hour, the company implemented a stricter policy on personal phone usage.","translation":"因为那通国际电话持续了一个多小时，公司对个人电话使用实施了更严格的政策。"},{"sentence":"When the prime minister made a call for national unity, it was seen as a strategic move to consolidate political power.","translation":"当首相发出民族团结的号召时，这被视为巩固政治权力的战略举措。"},{"sentence":"The unexpected call from the funding agency, which confirmed the grant approval, brought immense relief to the research team.","translation":"资助机构打来的意外电话确认了拨款批准，这给研究团队带来了巨大的安慰。"}]},"humor":{"examples":[{"sentence":"Because the diplomat used self-deprecating humor during the negotiation, the tense atmosphere gradually eased.","translation":"因为外交官在谈判中使用了自嘲式的幽默，紧张的气氛逐渐缓和。"},{"sentence":"A sense of humor, which is often undervalued in professional settings, can significantly enhance team cohesion and morale.","translation":"幽默感在职业环境中常被低估，但它能显著增强团队凝聚力和士气。"},{"sentence":"Although dark humor may offend some audiences, it can serve as a powerful tool for critiquing social injustices.","translation":"尽管黑色幽默可能会冒犯一些观众，但它可以作为批判社会不公的有力工具。"},{"sentence":"When the teacher used humor to explain complex theories, students demonstrated a deeper understanding of the material.","translation":"当老师用幽默来解释复杂的理论时，学生们对材料表现出了更深刻的理解。"},{"sentence":"The author's subtle humor, which pervades the entire novel, invites readers to question societal norms without feeling lectured.","translation":"作者微妙的幽默贯穿整部小说，引导读者质疑社会规范而不会感到被说教。"}]},"rebellion":{"examples":[{"sentence":"The rebellion, which was fueled by widespread corruption, ultimately led to the establishment of a more transparent government.","translation":"这场由普遍腐败引发的叛乱，最终导致了一个更透明的政府的建立。"},{"sentence":"Although the rebellion failed to overthrow the regime, it exposed the deep-seated discontent among the rural population.","translation":"尽管叛乱未能推翻政权，但它暴露了农村人口中根深蒂固的不满。"},{"sentence":"Because the rebellion disrupted trade routes, neighboring countries experienced severe economic repercussions.","translation":"因为叛乱中断了贸易路线，邻国遭受了严重的经济影响。"},{"sentence":"The student rebellion of 1968, which challenged authoritarian educational policies, remains a pivotal moment in academic history.","translation":"1968年的学生反抗挑战了威权教育政策，至今仍是学术史上的关键时刻。"},{"sentence":"When the rebellion was finally quelled, the government implemented reforms to address the underlying social inequalities.","translation":"当叛乱最终被平息时，政府实施了改革以解决潜在的社会不平等。"}]},"scent":{"examples":[{"sentence":"Although the scent of jasmine is subtle, it can create a calming atmosphere in any room.","translation":"尽管茉莉花的香味很淡，但它能在任何房间营造出平静的氛围。"},{"sentence":"Because the scent of freshly baked bread evokes feelings of comfort, bakeries often use it to attract customers.","translation":"因为新鲜出炉的面包香味唤起舒适感，面包店经常用它来吸引顾客。"},{"sentence":"When the scent of pine fills the air, many people are reminded of winter holidays and family gatherings.","translation":"当松树的香味弥漫在空气中时，许多人会想起冬季假期和家庭聚会。"},{"sentence":"The scent of rain on dry earth, which is known as petrichor, results from a combination of plant oils and bacterial compounds.","translation":"雨水落在干燥泥土上的气味，被称为潮土油，是由植物油和细菌化合物共同作用产生的。"},{"sentence":"Dogs have an extraordinary sense of smell, which allows them to detect a scent from several kilometers away.","translation":"狗拥有非凡的嗅觉，这使它们能够从几公里外察觉到气味。"}]},"scissors":{"examples":[{"sentence":"Although scissors are simple tools, using them correctly requires proper hand positioning to avoid injury.","translation":"尽管剪刀是简单的工具，但正确使用它们需要适当的手部定位以避免受伤。"},{"sentence":"Because the scissors were made of high-carbon steel, they remained sharp even after extensive use.","translation":"因为剪刀是由高碳钢制成的，即使经过大量使用，它们仍然保持锋利。"},{"sentence":"When children learn to use scissors, they develop fine motor skills that are essential for writing.","translation":"当儿童学习使用剪刀时，他们会发展出对写作至关重要的精细运动技能。"},{"sentence":"The surgeon selected a pair of curved scissors, which allowed for precise cutting during the delicate procedure.","translation":"外科医生选择了一把弯头剪刀，这允许在精细的手术过程中进行精确切割。"},{"sentence":"In many cultures, giving scissors as a gift is considered unlucky because it symbolizes cutting ties.","translation":"在许多文化中，赠送剪刀被视为不吉利，因为它象征着切断关系。"}]},"oral":{"examples":[{"sentence":"The oral examination requires students to articulate complex arguments under time pressure, which can be more challenging than written tests.","translation":"口试要求学生在时间压力下清晰阐述复杂的论点，这可能比笔试更具挑战性。"},{"sentence":"Researchers often rely on oral histories to reconstruct the lived experiences of communities that left few written records.","translation":"研究人员常常依赖口述历史来重建那些几乎没有留下文字记录的社区的生活经历。"},{"sentence":"Because oral communication skills are essential for effective teamwork, many universities now incorporate presentations into their curricula.","translation":"由于口头沟通技能对有效的团队合作至关重要，许多大学现在都将演讲纳入课程。"},{"sentence":"The oral tradition of storytelling, which predates written literature, remains a vital means of preserving cultural identity in many societies.","translation":"口头讲故事的传统早于书面文学，在许多社会中仍然是保存文化认同的重要方式。"},{"sentence":"Although oral agreements can be legally binding, they are often difficult to enforce due to the lack of tangible evidence.","translation":"尽管口头协议具有法律约束力，但由于缺乏有形证据，往往难以执行。"}]},"hug":{"examples":[{"sentence":"Although a simple hug may seem trivial, research shows that it can significantly lower cortisol levels and reduce anxiety.","translation":"尽管一个简单的拥抱可能看似微不足道，但研究表明它能显著降低皮质醇水平并减少焦虑。"},{"sentence":"When the long-lost siblings reunited at the airport, they exchanged a tearful hug that spoke louder than any words could.","translation":"当失散多年的兄弟姐妹在机场重逢时，他们含泪相拥，这比任何言语都更有力量。"},{"sentence":"The therapist emphasized that a consensual hug, when offered with genuine compassion, can foster a sense of security in trauma survivors.","translation":"治疗师强调，一个经同意的拥抱，当带着真诚的同情给予时，能在创伤幸存者中培养安全感。"},{"sentence":"Because physical touch is a fundamental human need, a warm hug from a loved one can alleviate feelings of loneliness and isolation.","translation":"由于身体接触是人类的基本需求，来自亲人的温暖拥抱能缓解孤独和隔离感。"},{"sentence":"The charity worker offered not only practical support but also a comforting hug to the refugees, which helped them feel welcomed and valued.","translation":"慈善工作者不仅提供了实际支持，还给难民一个安慰的拥抱，这让他们感到被欢迎和重视。"}]},"thin":{"examples":[{"sentence":"The thin ice on the pond poses a serious hazard, because it cannot support the weight of even a small child.","translation":"池塘上的薄冰构成严重危险，因为它甚至无法承受一个小孩的重量。"},{"sentence":"Although the patient appeared thin and frail, her determination to recover was remarkably strong, which inspired the entire medical team.","translation":"尽管病人看起来瘦弱不堪，但她康复的决心异常坚定，这鼓舞了整个医疗团队。"},{"sentence":"The thin atmosphere at high altitudes contains less oxygen, thereby making it difficult for unacclimatized climbers to breathe.","translation":"高海拔地区稀薄的大气含氧量较低，从而使未适应的登山者呼吸困难。"},{"sentence":"The author's argument was built on thin evidence, which ultimately undermined the credibility of the entire research paper.","translation":"作者的论点建立在薄弱的证据上，这最终损害了整个研究论文的可信度。"},{"sentence":"While the company's profit margins remain thin, its innovative marketing strategy has helped it gain a competitive edge in the market.","translation":"尽管公司的利润率仍然微薄，但其创新的营销策略帮助它在市场上获得了竞争优势。"}]},"dark":{"examples":[{"sentence":"In the dark of the night, the city's skyline is illuminated by thousands of lights, which creates a stunning view.","translation":"在夜晚的黑暗中，城市的天际线被数千盏灯照亮，形成了壮观的景色。"},{"sentence":"Because the power outage plunged the hospital into dark, backup generators were activated immediately to ensure patient safety.","translation":"因为停电使医院陷入黑暗，备用发电机立即启动以确保病人安全。"},{"sentence":"The dark of ignorance can be dispelled only through education, which empowers individuals to think critically.","translation":"无知的黑暗只能通过教育来驱散，教育使个人能够批判性地思考。"},{"sentence":"While the dark of the forest seemed intimidating, the hikers pressed on, relying on their flashlights and compass.","translation":"虽然森林的黑暗看起来令人生畏，但徒步旅行者们依靠手电筒和指南针继续前进。"},{"sentence":"The dark of the deep ocean remains largely unexplored, despite advances in underwater technology.","translation":"尽管水下技术有所进步，深海的黑暗仍然大部分未被探索。"}]},"distinguish":{"examples":[{"sentence":"Although both species appear similar, biologists can distinguish them by examining their genetic markers.","translation":"尽管这两个物种看起来相似，生物学家可以通过检查它们的遗传标记来区分它们。"},{"sentence":"Because the two concepts are often conflated, it is essential to distinguish between equality and equity in policy discussions.","translation":"由于这两个概念经常被混淆，在政策讨论中区分平等与公平至关重要。"},{"sentence":"A reliable algorithm must distinguish genuine user behavior from fraudulent activity to ensure security.","translation":"一个可靠的算法必须区分真实的用户行为和欺诈活动，以确保安全。"},{"sentence":"While both artists use vibrant colors, critics can distinguish their styles through brushwork and composition.","translation":"虽然两位艺术家都使用鲜艳的色彩，评论家可以通过笔触和构图来区分他们的风格。"},{"sentence":"To distinguish fact from fiction, readers should evaluate sources rather than accept claims at face value.","translation":"为了区分事实与虚构，读者应该评估信息来源，而不是只看表面就接受说法。"}]},"prince":{"examples":[{"sentence":"Although the prince was born into royalty, he chose to serve as a military officer to understand his people's struggles.","translation":"尽管王子出身皇室，他选择担任军官以了解人民的疾苦。"},{"sentence":"The prince, who had studied environmental science, advocated for sustainable policies when he became king.","translation":"这位曾学习环境科学的王子在成为国王后倡导可持续政策。"},{"sentence":"Because the prince was known for his diplomatic skills, he was often sent to negotiate treaties with neighboring kingdoms.","translation":"因为王子以外交技巧闻名，他经常被派去与邻国谈判条约。"},{"sentence":"In the fairy tale, the prince broke the curse by demonstrating true love, thereby saving the entire kingdom.","translation":"在童话中，王子通过展现真爱打破了诅咒，从而拯救了整个王国。"},{"sentence":"While the prince enjoyed the privileges of his position, he also bore the heavy responsibility of upholding the monarchy's reputation.","translation":"虽然王子享有其地位的特权，他也承担着维护君主制声誉的重任。"}]},"orbit":{"examples":[{"sentence":"Because the satellite was placed in a geostationary orbit, it remains fixed above the same point on Earth.","translation":"由于卫星被放置在地球静止轨道上，它固定在地球上方的同一点。"},{"sentence":"The moon's orbit around the Earth is elliptical, which causes variations in its apparent size and brightness.","translation":"月球绕地球的轨道是椭圆形的，这导致其视大小和亮度发生变化。"},{"sentence":"Although the asteroid's orbit is currently stable, scientists continue to monitor it for any potential shifts.","translation":"尽管这颗小行星的轨道目前是稳定的，但科学家们继续监测它是否有任何潜在的偏移。"},{"sentence":"A spacecraft must achieve a specific velocity to enter orbit, which requires precise calculations and powerful engines.","translation":"航天器必须达到特定速度才能进入轨道，这需要精确的计算和强大的引擎。"},{"sentence":"While planets orbit the sun in predictable paths, comets often follow highly elongated trajectories.","translation":"虽然行星以可预测的路径绕太阳运行，但彗星通常遵循高度拉长的轨迹。"}]},"space":{"examples":[{"sentence":"Although outer space appears empty, it contains vast amounts of dark matter that influence galaxy formation.","translation":"尽管外太空看起来空无一物，但它包含大量影响星系形成的暗物质。"},{"sentence":"Urban planners must allocate sufficient green space, which can significantly improve residents' mental health.","translation":"城市规划者必须分配足够的绿地空间，这可以显著改善居民的心理健康。"},{"sentence":"Because the museum's exhibition space was redesigned, visitors now follow a more coherent narrative journey.","translation":"由于博物馆的展览空间被重新设计，参观者现在能经历一个更连贯的叙事旅程。"},{"sentence":"The efficient use of office space can enhance productivity, whereas a cluttered environment often leads to distraction.","translation":"有效利用办公空间可以提高生产力，而杂乱的环境往往导致分心。"},{"sentence":"When scientists explore deep space, they rely on advanced telescopes that can detect faint light from distant galaxies.","translation":"当科学家探索深空时，他们依赖能够探测到遥远星系微弱光线的先进望远镜。"}]},"moon":{"examples":[{"sentence":"Although the moon lacks an atmosphere, its surface still preserves a detailed record of early solar system impacts.","translation":"尽管月球没有大气层，但其表面仍然保存着早期太阳系撞击的详细记录。"},{"sentence":"Because the moon's gravitational pull stabilizes Earth's axial tilt, it plays a crucial role in maintaining our planet's long-term climate stability.","translation":"由于月球的引力稳定了地球的轴倾角，它在维持地球长期气候稳定方面起着关键作用。"},{"sentence":"The moon's synchronous rotation means that one side remains permanently hidden from Earth-based observers.","translation":"月球的同步自转意味着有一面永远不为地球上的观测者所见。"},{"sentence":"When a full moon rises above the horizon, its apparent size is often magnified by an optical illusion that scientists still debate.","translation":"当满月从地平线升起时，其视尺寸常常被一种科学家仍在争论的光学错觉所放大。"},{"sentence":"Lunar samples returned by the Apollo missions revealed that the moon's composition closely resembles Earth's mantle, supporting the giant-impact hypothesis.","translation":"阿波罗任务带回的月球样本显示，月球的成分与地球的地幔非常相似，这支持了大碰撞假说。"}]},"whistle":{"examples":[{"sentence":"Although the referee blew the whistle to stop play, the players continued arguing about the controversial decision.","translation":"尽管裁判吹哨暂停了比赛，球员们仍在争论那个有争议的判罚。"},{"sentence":"Because the steam whistle echoed through the valley, the workers knew it was time to end their shift and return home.","translation":"由于蒸汽汽笛声在山谷中回荡，工人们知道该结束轮班回家了。"},{"sentence":"When the lifeguard's whistle pierced the air, swimmers immediately returned to shore, aware of the potential danger.","translation":"当救生员的哨声划破空气时，游泳者立即返回岸边，意识到潜在的危险。"},{"sentence":"The coach's whistle not only signaled the start of the drill but also reminded the athletes to maintain their focus throughout the session.","translation":"教练的哨声不仅标志着训练的开始，还提醒运动员在整个训练过程中保持专注。"},{"sentence":"A sharp whistle from the conductor prompted the orchestra to begin the symphony, which filled the hall with a majestic sound.","translation":"指挥的一声尖锐哨响促使管弦乐队开始演奏交响乐，乐声充满了整个大厅。"}]},"lease":{"examples":[{"sentence":"Although the lease seemed straightforward, the tenant discovered hidden fees that significantly increased the overall cost.","translation":"尽管租约看似简单明了，但租户发现了隐藏费用，大大增加了总成本。"},{"sentence":"Because the commercial lease included a renewal option, the business owner could plan for long-term growth without fear of displacement.","translation":"由于商业租约包含续租选项，企业主可以规划长期发展，而不必担心被迁走。"},{"sentence":"When the lease expired, the landlord proposed a substantial rent increase, which forced the tenant to consider alternative housing.","translation":"当租约到期时，房东提出大幅涨租，这迫使租户考虑其他住房。"},{"sentence":"Negotiating a lease with favorable terms requires not only legal knowledge but also an understanding of the local real estate market.","translation":"谈判一份条款有利的租约不仅需要法律知识，还需要了解当地的房地产市场。"},{"sentence":"A long-term lease provides stability for families, whereas a short-term lease offers flexibility for those with uncertain plans.","translation":"长期租约为家庭提供稳定性，而短期租约为计划不确定的人提供灵活性。"}]},"reporter":{"examples":[{"sentence":"The investigative reporter uncovered a series of financial irregularities that had been concealed by the company for years.","translation":"这位调查记者揭露了公司多年来一直隐瞒的一系列财务违规行为。"},{"sentence":"Because the reporter had built a strong network of local contacts, she was able to report on the conflict with remarkable depth.","translation":"由于这位记者建立了强大的当地关系网，她能够以非凡的深度报道这场冲突。"},{"sentence":"A responsible reporter must verify facts from multiple sources before publishing a story that could influence public opinion.","translation":"一位负责任的记者在发表可能影响公众舆论的报道之前，必须从多个来源核实事实。"},{"sentence":"Although the reporter faced considerable pressure from authorities, she refused to reveal the identity of her confidential source.","translation":"尽管这位记者面临来自当局的巨大压力，但她拒绝透露机密消息来源的身份。"},{"sentence":"The science reporter explained the complex research findings in a way that was accessible to a general audience.","translation":"这位科学记者以一种普通观众都能理解的方式解释了复杂的研究发现。"}]},"recovery":{"examples":[{"sentence":"Although the patient's recovery was initially slow, consistent physical therapy eventually restored her mobility.","translation":"尽管患者的康复起初很慢，但持续的物理治疗最终恢复了她的活动能力。"},{"sentence":"Because the company implemented a robust disaster recovery plan, it resumed operations within hours of the cyberattack.","translation":"由于公司实施了强大的灾难恢复计划，它在网络攻击后数小时内就恢复了运营。"},{"sentence":"The recovery of the stolen artifacts, which had been missing for decades, brought immense relief to the museum's curators.","translation":"追回失踪数十年的被盗文物，给博物馆馆长们带来了巨大的安慰。"},{"sentence":"While economic recovery remains fragile, targeted government subsidies have helped small businesses survive the downturn.","translation":"虽然经济复苏依然脆弱，但有针对性的政府补贴帮助小企业度过了低迷期。"},{"sentence":"Researchers emphasize that mental recovery after trauma requires not only professional counseling but also a supportive social network.","translation":"研究人员强调，创伤后的心理恢复不仅需要专业咨询，还需要支持性的社交网络。"}]},"odd":{"examples":[{"sentence":"Although the sum of two odd numbers is always even, their product remains odd.","translation":"尽管两个奇数之和总是偶数，但它们的乘积仍为奇数。"},{"sentence":"Because his odd approach to problem-solving often yields breakthroughs, the team has learned to value his unconventional ideas.","translation":"由于他解决问题的古怪方法常常带来突破，团队已经学会重视他非常规的想法。"},{"sentence":"She collected odd pieces of driftwood, which she later transformed into a striking sculpture.","translation":"她收集了零散的浮木碎片，后来将其变成了一件引人注目的雕塑。"},{"sentence":"While most participants followed the standard procedure, one odd response pattern emerged that required further investigation.","translation":"虽然大多数参与者遵循了标准程序，但出现了一种奇特的反应模式，需要进一步调查。"},{"sentence":"If an odd number of errors is detected, the system automatically initiates a corrective protocol to ensure data integrity.","translation":"如果检测到奇数个错误，系统会自动启动纠正协议以确保数据完整性。"}]},"energy":{"examples":[{"sentence":"Because renewable energy sources such as solar and wind are intermittent, developing efficient storage systems is crucial for grid stability.","translation":"由于太阳能和风能等可再生能源是间歇性的，开发高效的存储系统对电网稳定至关重要。"},{"sentence":"Although she had expended considerable energy on the project, the breakthrough discovery made all her efforts worthwhile.","translation":"尽管她在这个项目上耗费了大量精力，但突破性的发现使她的所有努力都值得。"},{"sentence":"Governments must invest in clean energy infrastructure, which will not only reduce emissions but also create sustainable jobs.","translation":"政府必须投资清洁能源基础设施，这不仅会减少排放，还会创造可持续的就业机会。"},{"sentence":"The athlete conserved his energy during the early stages of the race, thereby ensuring a powerful sprint at the finish.","translation":"运动员在比赛早期保存了体力，从而确保了终点前的有力冲刺。"},{"sentence":"When energy prices fluctuate dramatically, industries that rely heavily on power face significant operational challenges.","translation":"当能源价格剧烈波动时，高度依赖电力的行业面临重大的运营挑战。"}]},"moisture":{"examples":[{"sentence":"Because excessive moisture accelerates metal corrosion, engineers apply protective coatings to extend the lifespan of bridges.","translation":"由于过多的水分会加速金属腐蚀，工程师们使用保护涂层来延长桥梁的使用寿命。"},{"sentence":"The seeds require consistent moisture to germinate, which is why farmers often use drip irrigation in arid regions.","translation":"种子需要持续的水分才能发芽，这就是为什么农民在干旱地区经常使用滴灌。"},{"sentence":"Although the desert air lacks moisture, certain beetles harvest water from fog through specialized body surfaces.","translation":"尽管沙漠空气缺乏水分，某些甲虫通过特殊的体表从雾中收集水分。"},{"sentence":"When indoor moisture levels are too high, mold growth can occur, posing health risks to occupants.","translation":"当室内湿度过高时，可能会滋生霉菌，对居住者构成健康风险。"},{"sentence":"The new packaging material absorbs excess moisture, thereby keeping food products fresh for a longer period.","translation":"这种新型包装材料吸收多余的水分，从而使食品保鲜更长时间。"}]},"strain":{"examples":[{"sentence":"Although the bridge was designed to withstand heavy loads, the constant strain from traffic eventually caused cracks to appear.","translation":"尽管这座桥的设计能够承受重载，但交通带来的持续应力最终导致裂缝出现。"},{"sentence":"The financial strain of supporting a family while pursuing a degree forced her to seek additional scholarships.","translation":"在攻读学位的同时养家糊口的经济压力迫使她寻求额外的奖学金。"},{"sentence":"Because the athlete ignored the early signs of muscle strain, a minor injury developed into a chronic condition.","translation":"由于运动员忽视了肌肉拉伤的早期迹象，小伤发展成了慢性病。"},{"sentence":"The new software placed an unexpected strain on the server, which led to frequent crashes during peak hours.","translation":"新软件给服务器带来了意想不到的负担，导致高峰时段频繁崩溃。"},{"sentence":"To reduce the strain on healthcare workers, the hospital implemented a rotating shift system that ensured adequate rest.","translation":"为了减轻医护人员的压力，医院实施了轮班制以确保充足的休息。"}]},"small":{"examples":[{"sentence":"Although the initial investment was small, the compound interest over thirty years turned it into a substantial retirement fund.","translation":"尽管初始投资很小，但三十年的复利使其变成了一笔可观的退休基金。"},{"sentence":"Because the small village lacked a secondary school, students had to commute to the nearest town every day.","translation":"由于这个小村庄没有中学，学生们不得不每天通勤到最近的城镇。"},{"sentence":"The researcher discovered that even a small change in temperature could significantly affect the chemical reaction rate.","translation":"研究人员发现，即使温度的微小变化也能显著影响化学反应速率。"},{"sentence":"Small businesses, which are often more agile than large corporations, can adapt quickly to shifting market demands.","translation":"小企业通常比大公司更灵活，能够迅速适应不断变化的市场需求。"},{"sentence":"To foster innovation, the government provided grants to small startups that focused on renewable energy solutions.","translation":"为了促进创新，政府向专注于可再生能源解决方案的小型初创企业提供了资助。"}]},"plain":{"examples":[{"sentence":"The vast plain stretched endlessly under a sky that seemed to merge with the horizon.","translation":"广阔的平原在仿佛与地平线融为一体的天空下无尽延伸。"},{"sentence":"Although her dress was plain, its elegant cut revealed a sophisticated sense of style.","translation":"尽管她的连衣裙很朴素，但其优雅的剪裁展现出一种精致的时尚感。"},{"sentence":"The professor used plain language to explain the complex theory so that every student could follow.","translation":"教授用平实的语言解释复杂的理论，以便每个学生都能听懂。"},{"sentence":"Because the soil on the flood plain was exceptionally fertile, farmers cultivated high-yield crops there for centuries.","translation":"由于泛滥平原上的土壤异常肥沃，农民们几个世纪以来一直在那里种植高产作物。"},{"sentence":"The report's plain conclusion, which surprised many experts, was that the investment had yielded no measurable benefit.","translation":"报告直白的结论令许多专家感到惊讶，即这项投资没有产生任何可衡量的收益。"}]},"pretend":{"examples":[{"sentence":"Some politicians pretend to support environmental policies while quietly accepting donations from polluting industries.","translation":"一些政客假装支持环保政策，同时却暗中接受污染行业的捐款。"},{"sentence":"To avoid hurting his colleague's feelings, he had to pretend that he admired the flawed proposal.","translation":"为了避免伤害同事的感情，他不得不假装欣赏那份有缺陷的提案。"},{"sentence":"Although the company tried to pretend that the data breach was minor, leaked documents revealed a massive loss of customer information.","translation":"尽管该公司试图假装数据泄露事件很小，但泄露的文件显示客户信息大量丢失。"},{"sentence":"In academic writing, one should never pretend to understand a theory without thoroughly examining the evidence.","translation":"在学术写作中，一个人绝不应该在没有彻底审查证据的情况下假装理解一个理论。"},{"sentence":"When the funding cuts were announced, the director could no longer pretend that the project was financially sustainable.","translation":"当资金削减宣布时，主任再也无法假装该项目在财务上是可持续的。"}]},"steady":{"examples":[{"sentence":"A steady decline in the unemployment rate indicates that the economy is recovering from the recession.","translation":"失业率的稳步下降表明经济正在从衰退中复苏。"},{"sentence":"Because she maintained a steady study schedule throughout the semester, she felt confident and well-prepared for the final exams.","translation":"因为她在整个学期保持了稳定的学习计划，所以她对期末考试感到自信且准备充分。"},{"sentence":"The steady growth of renewable energy sources is essential if we are to reduce our dependence on fossil fuels.","translation":"可再生能源的稳定增长对于减少我们对化石燃料的依赖至关重要。"},{"sentence":"Although the project encountered numerous setbacks, the team's steady commitment to quality ensured its eventual success.","translation":"尽管项目遇到了许多挫折，但团队对质量的坚定承诺确保了其最终的成功。"},{"sentence":"Investors prefer companies with a steady dividend payout, which signals financial stability and reliable management.","translation":"投资者偏好有稳定股息支付的公司，这标志着财务稳定和可靠的管理。"}]},"strive":{"examples":[{"sentence":"Although resources are limited, educators must strive to provide equitable learning opportunities for all students.","translation":"尽管资源有限，教育者必须努力为所有学生提供公平的学习机会。"},{"sentence":"Companies that strive for innovation often invest heavily in research and development, which drives long-term growth.","translation":"努力创新的公司通常在研发上投入巨资，这推动了长期增长。"},{"sentence":"While governments strive to reduce unemployment, structural changes in the economy can hinder progress.","translation":"虽然政府努力降低失业率，但经济结构的变化可能阻碍进展。"},{"sentence":"To ensure sustainable development, nations must strive to balance economic growth with environmental protection.","translation":"为了确保可持续发展，各国必须努力平衡经济增长与环境保护。"},{"sentence":"Individuals who strive for personal excellence often set challenging goals, thereby pushing beyond their comfort zones.","translation":"追求个人卓越的人通常设定具有挑战性的目标，从而超越自己的舒适区。"}]},"beach":{"examples":[{"sentence":"Because the beach provides a natural buffer against storm surges, coastal communities invest heavily in its preservation.","translation":"由于海滩为风暴潮提供了天然缓冲，沿海社区投入大量资金进行保护。"},{"sentence":"Although the beach attracts millions of tourists each year, local authorities have implemented strict regulations to prevent environmental degradation.","translation":"尽管海滩每年吸引数百万游客，当地政府已实施严格法规以防止环境退化。"},{"sentence":"Researchers who study coastal erosion often select this beach as a field site because its dynamic landscape offers valuable data.","translation":"研究海岸侵蚀的研究人员经常选择这片海滩作为野外考察点，因为其动态地貌提供了宝贵数据。"},{"sentence":"To foster a sense of community, the town council organizes monthly clean-up events on the beach, which have significantly reduced litter.","translation":"为了培养社区意识，镇议会每月在海滩组织清洁活动，这显著减少了垃圾。"},{"sentence":"The beach, once a neglected stretch of sand, has been transformed into a vibrant public space through careful urban planning.","translation":"这片海滩曾是一片被忽视的沙地，通过精心的城市规划已转变为充满活力的公共空间。"}]},"skeleton":{"examples":[{"sentence":"The museum's dinosaur skeleton, which was assembled from fossils found on three continents, illustrates the global distribution of prehistoric species.","translation":"博物馆的恐龙骨架由三大洲发现的化石组装而成，展示了史前物种的全球分布。"},{"sentence":"Because the skeleton provides structural support for the body, any damage to it can severely impair mobility and overall health.","translation":"由于骨骼为身体提供结构支撑，任何损伤都可能严重损害活动能力和整体健康。"},{"sentence":"Although the research proposal was only a skeleton, it outlined the key objectives and methodology clearly enough to secure funding.","translation":"尽管研究提案只是一个梗概，但它足够清晰地概述了关键目标和方法，从而获得了资助。"},{"sentence":"The forensic team used the skeleton to determine the victim's age and cause of death, which proved crucial for the investigation.","translation":"法医团队利用骨骼确定了受害者的年龄和死因，这对调查至关重要。"},{"sentence":"Engineers examined the steel skeleton of the collapsed bridge to identify the structural weaknesses that led to the disaster.","translation":"工程师检查了坍塌桥梁的钢骨架，以确定导致灾难的结构弱点。"}]},"knob":{"examples":[{"sentence":"Although the door knob was made of brass, it had tarnished over time due to exposure to humidity.","translation":"尽管门把手是黄铜制的，但由于暴露在潮湿环境中，它随着时间的推移失去了光泽。"},{"sentence":"By turning the knob slowly, you can adjust the flame on the stove to ensure precise cooking temperatures.","translation":"通过缓慢转动旋钮，你可以调节炉子上的火焰，以确保精确的烹饪温度。"},{"sentence":"The volume knob, which is located on the front panel, allows users to control the sound output without using the remote.","translation":"位于前面板的音量旋钮使用户无需遥控器即可控制声音输出。"},{"sentence":"When the technician replaced the broken knob, the machine resumed normal operation immediately.","translation":"当技术员更换了损坏的旋钮后，机器立即恢复了正常运行。"},{"sentence":"A small knob on the microscope enables researchers to focus the lens precisely, thereby improving image clarity.","translation":"显微镜上的一个小旋钮使研究人员能够精确聚焦镜头，从而提高图像清晰度。"}]},"wisdom":{"examples":[{"sentence":"Although conventional wisdom suggests that early specialization is beneficial, a broad education often fosters greater adaptability.","translation":"尽管传统智慧表明早期专业化是有益的，但广泛的教育往往能培养更强的适应能力。"},{"sentence":"The wisdom of investing in renewable energy becomes evident when we consider the long-term environmental costs of fossil fuels.","translation":"当我们考虑化石燃料的长期环境成本时，投资可再生能源的明智之处就变得显而易见。"},{"sentence":"Because she sought the wisdom of experienced mentors, she was able to navigate the complex negotiation successfully.","translation":"因为她寻求了经验丰富的导师的智慧，所以她能够成功地驾驭复杂的谈判。"},{"sentence":"Historical records offer accumulated wisdom that can guide policymakers in addressing contemporary social issues.","translation":"历史记录提供了积累的智慧，可以指导决策者解决当代社会问题。"},{"sentence":"To cultivate wisdom, one must not only acquire knowledge but also reflect critically on personal experiences.","translation":"要培养智慧，一个人不仅需要获取知识，还必须批判性地反思个人经历。"}]},"nonsense":{"examples":[{"sentence":"The claim that climate change is a hoax is scientific nonsense, as it contradicts overwhelming empirical evidence.","translation":"气候变化是骗局的说法是科学上的无稽之谈，因为它与压倒性的经验证据相矛盾。"},{"sentence":"Dismissing the entire theory as nonsense without examining the data is intellectually dishonest, because it ignores rigorous research.","translation":"不审查数据就将整个理论斥为无稽之谈是思想上的不诚实，因为它忽视了严谨的研究。"},{"sentence":"Although the proposal sounded like nonsense at first, it contained a kernel of innovative thinking that later proved valuable.","translation":"尽管该提议起初听起来像是胡说八道，但它包含了一点创新思维的核心，后来被证明是有价值的。"},{"sentence":"The editorial rightly condemned the politician's speech as dangerous nonsense that misleads the public, thereby undermining democratic discourse.","translation":"那篇社论正确地谴责了那位政治家的演讲是误导公众的危险谬论，从而破坏了民主话语。"},{"sentence":"To avoid spreading nonsense, journalists should verify sources before publishing sensational stories, which can cause unnecessary panic.","translation":"为了避免传播无稽之谈，记者在发表耸人听闻的报道之前应该核实消息来源，这些报道可能引起不必要的恐慌。"}]},"wide":{"examples":[{"sentence":"Although the river is wide, engineers constructed a suspension bridge that now connects the two remote villages.","translation":"尽管这条河很宽，工程师们建造了一座悬索桥，现在连接了两个偏远的村庄。"},{"sentence":"The university offers a wide range of interdisciplinary courses, which allows students to tailor their education to their interests.","translation":"这所大学提供广泛的跨学科课程，这使得学生可以根据自己的兴趣定制教育。"},{"sentence":"Because the new drug has a wide spectrum of activity against bacteria, it is considered a breakthrough in medical research.","translation":"由于这种新药具有广泛的抗菌活性，它被认为是医学研究的一项突破。"},{"sentence":"When analyzing the data, the researchers found a wide disparity in income levels between urban and rural areas.","translation":"在分析数据时，研究人员发现城乡之间的收入水平存在巨大差距。"},{"sentence":"The organization's campaign received wide media coverage, thereby raising public awareness about the endangered species.","translation":"该组织的活动得到了媒体的广泛报道，从而提高了公众对濒危物种的认识。"}]},"dedicate":{"examples":[{"sentence":"Many researchers dedicate years to a single project in order to produce findings that can genuinely advance their field.","translation":"许多研究人员将多年时间投入单一项目，以便得出能够真正推动其领域发展的发现。"},{"sentence":"Governments that dedicate substantial resources to early childhood education often see long-term improvements in social equity.","translation":"将大量资源投入早期儿童教育的政府，往往会看到社会公平方面的长期改善。"},{"sentence":"Although she had a demanding full-time job, she chose to dedicate her weekends to mentoring disadvantaged students.","translation":"尽管她有一份要求苛刻的全职工作，她还是选择将周末用于辅导弱势学生。"},{"sentence":"Companies that dedicate a portion of their profits to environmental causes can strengthen both their reputation and customer loyalty.","translation":"将部分利润投入环保事业的公司，既能提升声誉，也能增强客户忠诚度。"},{"sentence":"If more volunteers dedicate their time to community health programs, the overall well-being of the population is likely to improve.","translation":"如果更多志愿者将时间投入社区健康项目，人口的整体福祉很可能会得到改善。"}]},"bold":{"examples":[{"sentence":"Although bold leadership can inspire innovation, it must be tempered with careful risk assessment to ensure sustainable growth.","translation":"尽管大胆的领导力能激发创新，但必须辅以谨慎的风险评估，以确保可持续增长。"},{"sentence":"The company made a bold move by investing heavily in green technology, which not only reduced its carbon footprint but also attracted environmentally conscious consumers.","translation":"该公司采取大胆举措，大力投资绿色技术，这不仅减少了碳足迹，还吸引了具有环保意识的消费者。"},{"sentence":"Because the researcher proposed a bold theory that challenged conventional wisdom, her work sparked intense debate within the scientific community.","translation":"由于这位研究人员提出了一个挑战传统观念的大胆理论，她的工作在科学界引发了激烈辩论。"},{"sentence":"When writing academic papers, it is advisable to use bold type for section headings, thereby improving the overall readability of the document.","translation":"在撰写学术论文时，建议使用粗体字标注章节标题，从而提高文档的整体可读性。"},{"sentence":"If policymakers fail to take bold action against climate change, future generations will face severe environmental consequences that could have been avoided.","translation":"如果政策制定者未能采取大胆行动应对气候变化，后代将面临本可避免的严重环境后果。"}]},"marital":{"examples":[{"sentence":"While financial disagreements are a common source of marital conflict, couples who establish transparent budgeting practices often experience greater harmony.","translation":"尽管财务分歧是婚姻冲突的常见根源，但建立透明预算做法的夫妻往往能体验到更大的和谐。"},{"sentence":"The study found that marital satisfaction tends to decline after the birth of the first child, unless both partners actively share caregiving responsibilities.","translation":"研究发现，第一个孩子出生后婚姻满意度往往会下降，除非双方积极分担育儿责任。"},{"sentence":"Because marital property laws vary significantly across jurisdictions, international couples should seek legal advice to protect their assets.","translation":"由于婚姻财产法在不同司法管辖区差异很大，跨国夫妻应寻求法律建议以保护其资产。"},{"sentence":"Through marital counseling, many couples learn to communicate more effectively, which in turn strengthens their emotional bond and mutual respect.","translation":"通过婚姻咨询，许多夫妻学会了更有效地沟通，这反过来又加强了他们的情感纽带和相互尊重。"},{"sentence":"Although societal attitudes toward marital roles have evolved, traditional expectations still influence the division of household labor in many families.","translation":"尽管社会对婚姻角色的态度已经演变，但传统期望仍然影响着许多家庭的家务分工。"}]},"corrode":{"examples":[{"sentence":"Although stainless steel is resistant to many chemicals, prolonged exposure to chloride ions can still corrode its surface.","translation":"尽管不锈钢耐多种化学物质，但长期暴露于氯离子仍会腐蚀其表面。"},{"sentence":"Because the ancient coins were buried in acidic soil for centuries, the metal began to corrode, obscuring the inscriptions.","translation":"由于这些古钱币在酸性土壤中埋藏了几个世纪，金属开始腐蚀，使铭文变得模糊。"},{"sentence":"When industrial emissions combine with moisture in the atmosphere, they form acids that corrode marble statues and buildings.","translation":"当工业排放物与大气中的水分结合时，会形成酸，腐蚀大理石雕像和建筑。"},{"sentence":"The constant friction from the moving parts can corrode the protective coating, which eventually leads to mechanical failure.","translation":"运动部件的持续摩擦会腐蚀保护涂层，最终导致机械故障。"},{"sentence":"If we fail to address the underlying issues, resentment will slowly corrode the team's morale, despite superficial harmony.","translation":"如果我们未能解决根本问题，尽管表面和谐，怨恨会慢慢侵蚀团队的士气。"}]},"criterion":{"examples":[{"sentence":"Although profitability is a key criterion for investment, venture capitalists also consider the founding team's expertise and vision.","translation":"尽管盈利能力是投资的关键标准，但风险投资家也会考虑创始团队的专业知识和愿景。"},{"sentence":"Because the scholarship committee uses academic merit as the primary criterion, applicants must submit their transcripts and test scores.","translation":"由于奖学金委员会将学业成绩作为主要标准，申请人必须提交成绩单和考试分数。"},{"sentence":"The new environmental regulation sets a strict criterion for emissions, which will force factories to adopt cleaner technologies.","translation":"新的环境法规为排放设定了严格标准，这将迫使工厂采用更清洁的技术。"},{"sentence":"When selecting a location for the new facility, the company applied a multi-factor criterion that included logistics costs and labor availability.","translation":"在选择新设施的地点时，公司应用了包括物流成本和劳动力可用性在内的多因素标准。"},{"sentence":"In peer review, the main criterion for acceptance is the originality of the research, rather than the reputation of the authors.","translation":"在同行评审中，接受的主要标准是研究的原创性，而不是作者的声誉。"}]},"additional":{"examples":[{"sentence":"Although the initial budget was approved, the project manager requested additional funding to cover unforeseen expenses.","translation":"尽管初始预算已获批准，项目经理仍要求追加资金以支付意外开支。"},{"sentence":"Because the survey sample was too small, the researchers collected additional data to ensure statistical significance.","translation":"由于调查样本太小，研究人员收集了额外数据以确保统计显著性。"},{"sentence":"The university offers additional workshops, which help students develop practical skills beyond the standard curriculum.","translation":"该大学提供额外的研讨会，这有助于学生培养标准课程之外的实用技能。"},{"sentence":"When a company expands into new markets, it often needs to hire additional staff with local expertise.","translation":"当公司向新市场扩张时，通常需要雇用具有当地专业知识的额外员工。"},{"sentence":"The policy introduced additional taxes on luxury goods, thereby discouraging excessive consumption.","translation":"该政策对奢侈品征收额外税费，从而抑制了过度消费。"}]},"equipment":{"examples":[{"sentence":"Because the laboratory equipment was outdated, the experiments yielded inconsistent results that delayed the project.","translation":"由于实验室设备过时，实验产生了不一致的结果，延误了项目。"},{"sentence":"The hospital invested in state-of-the-art diagnostic equipment, which allows doctors to detect diseases at an early stage.","translation":"医院投资了最先进的诊断设备，这使得医生能够在早期发现疾病。"},{"sentence":"When heavy equipment is operated without proper training, the risk of workplace accidents increases significantly.","translation":"当重型设备在未经适当培训的情况下操作时，工作场所事故的风险会显著增加。"},{"sentence":"The construction company leased additional equipment to ensure that the project would be completed on schedule.","translation":"建筑公司租赁了额外设备，以确保项目能按期完成。"},{"sentence":"Although the initial cost of energy-efficient equipment is high, it reduces long-term operational expenses substantially.","translation":"尽管节能设备的初始成本很高，但它能大幅降低长期运营费用。"}]},"harbor":{"examples":[{"sentence":"Because the natural harbor is deep and well-sheltered, it has become a major hub for international trade.","translation":"由于这个天然港口水深且遮蔽良好，它已成为国际贸易的主要枢纽。"},{"sentence":"The city developed a new industrial zone near the harbor, which attracted numerous manufacturing companies.","translation":"该市在港口附近开发了一个新的工业区，吸引了众多制造企业。"},{"sentence":"When a harbor lacks modern cargo-handling facilities, ships may choose to dock at competing ports instead.","translation":"当港口缺乏现代化的货物装卸设施时，船只可能会选择停靠在竞争港口。"},{"sentence":"The government invested in expanding the harbor, thereby increasing its capacity to accommodate larger vessels.","translation":"政府投资扩建港口，从而提高了其容纳更大型船只的能力。"},{"sentence":"Although the harbor was damaged by the storm, the rapid repair efforts minimized disruption to shipping activities.","translation":"尽管港口被风暴损坏，但迅速的修复工作将航运活动的中断降到了最低。"}]},"actor":{"examples":[{"sentence":"An actor who thoroughly researches a role can deliver a performance that resonates deeply with audiences.","translation":"一个深入研究角色的演员能够呈现出与观众产生深刻共鸣的表演。"},{"sentence":"Because the actor had trained in classical theater, he brought a unique depth to the film.","translation":"由于这位演员受过古典戏剧训练，他为电影带来了独特的深度。"},{"sentence":"The actor, whose career spanned five decades, became a cultural icon through his diverse roles.","translation":"这位演员的职业生涯跨越了五十年，通过其多样化的角色成为了文化偶像。"},{"sentence":"When an actor chooses socially relevant projects, they can influence public discourse beyond entertainment.","translation":"当演员选择与社会相关的项目时，他们可以在娱乐之外影响公共话语。"},{"sentence":"A skilled actor not only memorizes lines but also embodies the character's inner conflicts.","translation":"一个熟练的演员不仅要记住台词，还要体现角色的内心冲突。"}]},"christ":{"examples":[{"sentence":"Although the historical Christ remains a subject of scholarly debate, his ethical teachings continue to shape modern moral philosophy.","translation":"尽管历史上的基督仍是学术争论的话题，但他的伦理教义继续塑造着现代道德哲学。"},{"sentence":"The figure of Christ, which has been reinterpreted across cultures, serves as a universal symbol of sacrifice and redemption.","translation":"基督的形象在不同文化中被重新诠释，成为牺牲与救赎的普遍象征。"},{"sentence":"Because early Christians emphasized the divinity of Christ, they developed creeds that defined orthodox belief for centuries.","translation":"由于早期基督徒强调基督的神性，他们制定了信条，这些信条定义了数个世纪的正统信仰。"},{"sentence":"When artists depict Christ in contemporary settings, they often aim to make his message relevant to modern audiences.","translation":"当艺术家在当代背景下描绘基督时，他们通常旨在使他的信息与现代观众相关。"},{"sentence":"The concept of Christ as a revolutionary figure, rather than a passive martyr, has inspired numerous social movements throughout history.","translation":"基督作为革命人物而非被动殉道者的概念，在历史上激发了无数社会运动。"}]},"youth":{"examples":[{"sentence":"While youth is often idealized as a carefree period, it is also a critical time for developing resilience and identity.","translation":"虽然青春常被理想化为无忧无虑的时期，但它也是培养韧性和身份认同的关键时期。"},{"sentence":"The youth of today, who are digital natives, navigate a complex media landscape that profoundly influences their worldviews.","translation":"今天的青年是数字原住民，他们在复杂的媒体环境中游走，这深刻影响了他们的世界观。"},{"sentence":"Because youth unemployment can lead to long-term economic stagnation, governments must invest in vocational training programs.","translation":"由于青年失业可能导致长期经济停滞，政府必须投资于职业培训项目。"},{"sentence":"When societies fail to engage their youth in decision-making, they risk alienating a generation that craves meaningful participation.","translation":"当社会未能让青年参与决策时，他们可能会疏远渴望有意义参与的一代人。"},{"sentence":"The energy and idealism of youth, if channeled through mentorship, can drive innovation and social progress.","translation":"青年的精力和理想主义，如果通过指导加以引导，可以推动创新和社会进步。"}]},"suicide":{"examples":[{"sentence":"When a society fails to provide adequate mental health support, the suicide rate among vulnerable groups tends to rise.","translation":"当一个社会未能提供足够的心理健康支持时，弱势群体的自杀率往往会上升。"},{"sentence":"Researchers have found that prolonged economic hardship can significantly increase the risk of suicide, especially among middle-aged men.","translation":"研究人员发现，长期的经济困难会显著增加自杀风险，尤其是在中年男性中。"},{"sentence":"Although suicide is often linked to depression, not everyone who takes their own life has a diagnosed mental illness.","translation":"尽管自杀常与抑郁症相关，但并非每个结束自己生命的人都患有确诊的精神疾病。"},{"sentence":"Public health campaigns that reduce the stigma around seeking help are essential for suicide prevention.","translation":"减少求助羞耻感的公共卫生宣传对于预防自杀至关重要。"},{"sentence":"Because suicide can have a profound impact on families and communities, postvention support is just as important as prevention.","translation":"由于自杀会对家庭和社区产生深远影响，事后干预支持与预防同样重要。"}]},"decade":{"examples":[{"sentence":"Although the city has undergone rapid urbanization over the past decade, it has managed to preserve many of its historic neighborhoods.","translation":"尽管这座城市在过去十年经历了快速的城市化，但它设法保留了许多历史街区。"},{"sentence":"Because a decade of consistent investment in public transportation can significantly reduce traffic congestion, many governments are prioritizing such projects.","translation":"由于对公共交通的十年持续投资可以显著减少交通拥堵，许多政府正在优先考虑此类项目。"},{"sentence":"The scientist's groundbreaking research, which spanned nearly a decade, ultimately led to a vaccine that saved millions of lives.","translation":"这位科学家历时近十年的开创性研究，最终促成了一种拯救了数百万生命的疫苗。"},{"sentence":"While a decade may seem like a long time, it often passes quickly when one is fully engaged in meaningful work.","translation":"虽然十年看似漫长，但当一个人全身心投入有意义的工作时，它往往转瞬即逝。"},{"sentence":"If current trends continue, the next decade will witness a dramatic shift toward renewable energy sources worldwide.","translation":"如果当前趋势持续下去，未来十年全球将见证向可再生能源的急剧转变。"}]},"wooden":{"examples":[{"sentence":"Although the temple's wooden structure appears fragile, it has withstood earthquakes for centuries due to its ingenious bracket system.","translation":"尽管这座寺庙的木结构看似脆弱，但由于其巧妙的斗拱系统，它历经数百年地震而屹立不倒。"},{"sentence":"Because wooden toys are durable and free of harmful chemicals, they are often preferred by environmentally conscious parents.","translation":"由于木制玩具耐用且不含有害化学物质，它们常受环保意识强的父母青睐。"},{"sentence":"The actor's wooden performance, which lacked any emotional depth, drew sharp criticism from both audiences and critics.","translation":"这位演员呆板的表演缺乏任何情感深度，招致了观众和评论家的尖锐批评。"},{"sentence":"When the old wooden bridge was finally replaced by a modern steel one, the villagers felt a mix of relief and nostalgia.","translation":"当那座老木桥最终被一座现代钢桥取代时，村民们既感到如释重负，又有些怀旧。"},{"sentence":"To ensure the longevity of the wooden artifacts, the museum maintains a strictly controlled environment with stable humidity and temperature.","translation":"为了确保木制文物的长久保存，博物馆维持着严格受控的环境，湿度和温度保持稳定。"}]},"episode":{"examples":[{"sentence":"Although the episode of political turmoil was brief, it left a lasting impact on the nation's economy.","translation":"尽管那段政治动荡的插曲很短暂，但它对该国经济留下了持久的影响。"},{"sentence":"The patient experienced a sudden episode of memory loss, which prompted doctors to conduct further neurological tests.","translation":"病人经历了一次突然的记忆丧失发作，这促使医生进行了进一步的神经学检查。"},{"sentence":"Because the historical episode was poorly documented, scholars continue to debate its true significance.","translation":"由于这段历史插曲记录不全，学者们仍在争论其真正的重要性。"},{"sentence":"The documentary series dedicates an entire episode to the environmental crisis, thereby raising public awareness.","translation":"这部纪录片系列用一整集来讲述环境危机，从而提高了公众意识。"},{"sentence":"While the first episode of the podcast was unpolished, it successfully introduced the core themes of the series.","translation":"虽然播客的第一集不够精炼，但它成功地介绍了该系列的核心主题。"}]},"know":{"examples":[{"sentence":"Although we know that exercise benefits health, many people fail to maintain a regular routine.","translation":"尽管我们知道锻炼有益健康，但许多人仍未能保持规律的锻炼习惯。"},{"sentence":"To ensure accurate diagnosis, doctors must know the patient's complete medical history.","translation":"为了确保准确诊断，医生必须了解患者的完整病史。"},{"sentence":"Because researchers do not yet know the underlying mechanism, further studies are required.","translation":"由于研究人员尚未了解其潜在机制，因此需要进一步的研究。"},{"sentence":"Effective leaders know that listening to feedback is crucial for continuous improvement.","translation":"有效的领导者知道，倾听反馈对于持续改进至关重要。"},{"sentence":"When students know the purpose of an assignment, they tend to engage more deeply with the material.","translation":"当学生了解作业的目的时，他们往往会更深入地参与学习材料。"}]},"tell":{"examples":[{"sentence":"Although the two theories seem similar, a careful analysis can tell them apart.","translation":"尽管这两种理论看似相似，但仔细分析可以区分它们。"},{"sentence":"To ensure public trust, officials should tell citizens how decisions are made.","translation":"为了确保公众信任，官员应当告知公民决策是如何做出的。"},{"sentence":"Because the symptoms overlap, it is often difficult to tell which disease is present.","translation":"由于症状重叠，通常很难断定是哪种疾病。"},{"sentence":"The survey results tell us that most consumers prefer sustainable products.","translation":"调查结果告诉我们，大多数消费者更喜欢可持续产品。"},{"sentence":"When experts tell a compelling story, complex data becomes accessible to a wider audience.","translation":"当专家讲述一个引人入胜的故事时，复杂的数据变得更容易被更广泛的受众理解。"}]},"put":{"examples":[{"sentence":"To ensure fairness, the committee decided to put the new policy into effect only after a thorough review.","translation":"为了确保公平，委员会决定在彻底审查后才实施新政策。"},{"sentence":"Although the proposal was controversial, the board chose to put it to a vote rather than dismiss it outright.","translation":"尽管该提案有争议，但董事会选择将其付诸表决，而不是直接否决。"},{"sentence":"Effective leaders put the needs of their team first, which in turn fosters loyalty and productivity.","translation":"有效的领导者把团队的需求放在首位，这反过来又培养了忠诚度和生产力。"},{"sentence":"Because the evidence was inconclusive, the judge decided to put off the trial until additional witnesses could be called.","translation":"因为证据不确凿，法官决定推迟审判，直到能传唤更多证人。"},{"sentence":"The government must put stricter regulations on pollution if it hopes to achieve its environmental targets.","translation":"如果政府希望实现其环境目标，就必须对污染实施更严格的法规。"}]},"single":{"examples":[{"sentence":"Although the team proposed multiple solutions, they ultimately adopted a single strategy to ensure consistency.","translation":"尽管团队提出了多种解决方案，但他们最终采用单一策略以确保一致性。"},{"sentence":"Because a single error in the code can crash the entire system, developers must test each module rigorously.","translation":"因为代码中的一个错误就可能导致整个系统崩溃，开发人员必须严格测试每个模块。"},{"sentence":"The policy, which focuses on a single demographic group, has sparked debate about its fairness.","translation":"这项专注于单一人群的政策引发了关于其公平性的辩论。"},{"sentence":"When a single company dominates the market, innovation often stagnates due to lack of competition.","translation":"当单一公司主导市场时，由于缺乏竞争，创新往往会停滞。"},{"sentence":"Rather than relying on a single source of income, the family diversified their investments to reduce risk.","translation":"这个家庭没有依赖单一收入来源，而是通过多元化投资来降低风险。"}]},"outset":{"examples":[{"sentence":"At the outset of the project, the team established clear milestones to ensure timely progress.","translation":"在项目开始时，团队确立了明确的里程碑以确保及时推进。"},{"sentence":"Because the objectives were ambiguous from the outset, the initiative failed to gain stakeholder support.","translation":"由于目标从一开始就模糊不清，该倡议未能获得利益相关者的支持。"},{"sentence":"The contract, which was poorly drafted at the outset, led to numerous disputes between the parties.","translation":"这份合同从一开始就起草不当，导致双方之间产生了许多争议。"},{"sentence":"When researchers define their methodology at the outset, they can avoid biases that compromise the study.","translation":"当研究人员在开始时明确其方法时，他们可以避免影响研究的偏差。"},{"sentence":"Despite the enthusiasm at the outset, the campaign lost momentum due to inadequate funding.","translation":"尽管一开始热情高涨，但由于资金不足，这场运动失去了势头。"}]},"tedious":{"examples":[{"sentence":"Although the data entry process is tedious, it is indispensable for building a reliable database.","translation":"尽管数据录入过程繁琐，但它对于构建可靠的数据库是不可或缺的。"},{"sentence":"Because the legal review involved tedious scrutiny of every clause, the team worked overtime to meet the deadline.","translation":"由于法律审查涉及对每个条款的繁琐审查，团队加班加点以赶上截止日期。"},{"sentence":"The researcher automated the tedious calculations, which saved weeks of manual effort.","translation":"研究人员将繁琐的计算自动化，这节省了数周的手工劳动。"},{"sentence":"When students engage in tedious rote learning, they often lose interest in the subject matter.","translation":"当学生进行枯燥的死记硬背时，他们往往会对学科内容失去兴趣。"},{"sentence":"Rather than performing tedious repetitive tasks, employees can now focus on strategic planning.","translation":"员工现在可以专注于战略规划，而不是执行繁琐的重复性任务。"}]},"alone":{"examples":[{"sentence":"Although she prefers to work alone, she acknowledges that collaboration often yields more innovative solutions.","translation":"尽管她更喜欢独自工作，但她承认合作往往能产生更具创新性的解决方案。"},{"sentence":"The evidence alone is insufficient to prove the hypothesis, because the sample size was too small to draw reliable conclusions.","translation":"仅凭证据不足以证明该假设，因为样本量太小，无法得出可靠的结论。"},{"sentence":"When a child is left alone for extended periods, emotional development may be adversely affected, which can lead to long-term behavioral issues.","translation":"当孩子长时间被独自留下时，情感发展可能会受到不利影响，这可能导致长期的行为问题。"},{"sentence":"The decision to travel alone can foster self-reliance, provided that one takes necessary safety precautions to ensure a secure journey.","translation":"独自旅行的决定可以培养自力更生的能力，前提是要采取必要的安全预防措施以确保旅途安全。"},{"sentence":"Economic prosperity alone does not guarantee happiness, as numerous studies have shown that social connections play a more critical role.","translation":"经济繁荣本身并不能保证幸福，因为许多研究表明，社会关系起着更关键的作用。"}]},"rectify":{"examples":[{"sentence":"Although the company acknowledged the accounting error, it took immediate steps to rectify the discrepancy before the audit.","translation":"尽管公司承认了会计错误，但它立即采取措施在审计前纠正了差异。"},{"sentence":"To rectify the imbalance in resource allocation, the committee proposed a new policy that prioritizes underserved communities.","translation":"为了纠正资源分配的不平衡，委员会提出了一项优先考虑服务不足社区的新政策。"},{"sentence":"Because the experimental data contained anomalies, the researchers had to rectify the calibration of the instruments before proceeding.","translation":"由于实验数据包含异常，研究人员在继续之前必须纠正仪器的校准。"},{"sentence":"The government launched a campaign to rectify public misconceptions about vaccination, which had led to a decline in immunization rates.","translation":"政府发起了一场运动来纠正公众对疫苗接种的误解，这些误解导致了免疫接种率的下降。"},{"sentence":"While the software patch was intended to rectify security flaws, it inadvertently introduced new vulnerabilities that required further attention.","translation":"虽然软件补丁旨在修复安全漏洞，但它无意中引入了需要进一步关注的新漏洞。"}]},"sunrise":{"examples":[{"sentence":"Because the sunrise over the ocean was particularly stunning, the couple decided to extend their vacation by another day.","translation":"由于海上的日出特别壮观，这对夫妇决定将假期再延长一天。"},{"sentence":"The photographer captured the sunrise from the mountain peak, which required a strenuous hike that began at midnight.","translation":"摄影师从山顶捕捉到了日出，这需要从午夜开始的艰苦徒步。"},{"sentence":"Although the sunrise symbolizes new beginnings, it also reminds us that each day brings its own challenges.","translation":"尽管日出象征着新的开始，但它也提醒我们每一天都会带来自己的挑战。"},{"sentence":"When the first rays of sunrise illuminated the ancient ruins, the archaeologists felt a deep connection to the civilization that once thrived there.","translation":"当日出的第一缕阳光照亮古代遗址时，考古学家们对曾经在那里繁荣的文明产生了深刻的联系。"},{"sentence":"The tradition of watching the sunrise on the first day of the year is believed to bring good luck, which explains why crowds gather at scenic spots.","translation":"在新年第一天观看日出的传统被认为能带来好运，这解释了为什么人群聚集在风景名胜区。"}]},"upgrade":{"examples":[{"sentence":"Although the software upgrade was costly, it ultimately improved productivity by automating repetitive tasks.","translation":"尽管软件升级成本高昂，但它最终通过自动化重复任务提高了生产力。"},{"sentence":"The city's infrastructure upgrade, which included new bridges and roads, significantly reduced traffic congestion during peak hours.","translation":"城市的基础设施升级，包括新的桥梁和道路，显著减少了高峰时段的交通拥堵。"},{"sentence":"Because the hotel offered a complimentary room upgrade, the guests enjoyed a suite with a panoramic view of the coastline.","translation":"由于酒店提供了免费的房间升级，客人享受到了可以俯瞰海岸线全景的套房。"},{"sentence":"To ensure compatibility with the latest operating system, users must perform an upgrade that requires backing up their data first.","translation":"为了确保与最新操作系统的兼容性，用户必须进行升级，这需要首先备份他们的数据。"},{"sentence":"While the upgrade to the laboratory equipment was expensive, it enabled researchers to conduct experiments that were previously impossible.","translation":"虽然实验室设备的升级很昂贵，但它使研究人员能够进行以前不可能的实验。"}]},"contest":{"examples":[{"sentence":"Because the contest required interdisciplinary collaboration, it produced innovative solutions to urban problems.","translation":"由于比赛要求跨学科合作，它产生了解决城市问题的创新方案。"},{"sentence":"Although the contest was open to amateurs, the winning entry demonstrated professional-level expertise.","translation":"尽管比赛对业余爱好者开放，但获奖作品展示了专业水平的专业知识。"},{"sentence":"The contest, which was judged by a panel of industry experts, emphasized practical impact over theoretical elegance.","translation":"由行业专家小组评审的比赛强调实际影响而非理论上的优雅。"},{"sentence":"By entering the contest, participants not only gained recognition but also received mentorship from established professionals.","translation":"通过参加比赛，参与者不仅获得了认可，还得到了资深专业人士的指导。"},{"sentence":"The contest rules stipulated that all submissions must be original, thereby ensuring a fair evaluation process.","translation":"比赛规则规定所有提交作品必须为原创，从而确保了公平的评审过程。"}]},"lovely":{"examples":[{"sentence":"Although the weather was gloomy, the lovely melody of the street musician lifted everyone's spirits.","translation":"尽管天气阴沉，街头艺人动人的旋律却提振了每个人的精神。"},{"sentence":"The garden, which was filled with lovely roses in full bloom, became a favorite spot for quiet reflection.","translation":"花园里盛开着可爱的玫瑰，成为静思的好去处。"},{"sentence":"Because the children's laughter was so lovely, the elderly residents felt a renewed sense of joy.","translation":"因为孩子们的笑声如此可爱，老年居民们重新感受到了快乐。"},{"sentence":"The documentary captured the lovely bond between the couple, which had deepened over six decades of shared life.","translation":"这部纪录片捕捉到了这对夫妇之间美好的情感纽带，这种纽带在六十多年的共同生活中不断加深。"},{"sentence":"While the cottage was modest, its lovely view of the rolling hills made it a perfect retreat.","translation":"虽然小屋很简朴，但窗外连绵起伏的山丘美景使它成为一个完美的休憩之所。"}]},"bounce":{"examples":[{"sentence":"The ball's unpredictable bounce on the uneven surface made the game more challenging, which tested the players' adaptability.","translation":"球在不平整表面上不可预测的弹跳使比赛更具挑战性，这考验了球员的适应能力。"},{"sentence":"After a brief dip, the stock market showed a strong bounce, thereby restoring investor confidence in the economy.","translation":"在短暂下跌后，股市出现了强劲反弹，从而恢复了投资者对经济的信心。"},{"sentence":"The child's natural bounce and energy were evident as she explored the new playground, which delighted her parents.","translation":"孩子在探索新游乐场时，天生的活力和朝气显而易见，这让她的父母很高兴。"},{"sentence":"Email servers sometimes reject messages, causing a bounce that notifies the sender of delivery failure, which can be frustrating.","translation":"电子邮件服务器有时会拒收邮件，导致退信通知发件人投递失败，这可能令人沮丧。"},{"sentence":"The gymnast's powerful bounce on the trampoline allowed her to perform a complex series of flips, which earned her a high score.","translation":"体操运动员在蹦床上有力的弹跳使她能够完成一系列复杂的空翻，这为她赢得了高分。"}]},"behind":{"examples":[{"sentence":"Because the country invested heavily in technology, it left its competitors behind, which secured its position as a market leader.","translation":"由于该国在技术上投入巨资，它将竞争对手甩在了后面，从而巩固了其市场领导者的地位。"},{"sentence":"Although the student worked diligently, she fell behind in her studies due to a prolonged illness, which required her to seek extra help.","translation":"尽管这名学生学习勤奋，但由于长期患病，她在学业上落后了，这需要她寻求额外帮助。"},{"sentence":"When we examine the reasons behind the policy failure, we find that a lack of public consultation was a major contributing factor.","translation":"当我们审视政策失败背后的原因时，我们发现缺乏公众咨询是一个主要的促成因素。"},{"sentence":"The company's outdated infrastructure lagged behind industry standards, thereby reducing its ability to compete effectively.","translation":"该公司过时的基础设施落后于行业标准，从而降低了其有效竞争的能力。"},{"sentence":"Leaving behind a legacy of environmental destruction is not only unethical but also imposes long-term costs on future generations.","translation":"留下环境破坏的遗产不仅不道德，而且会给后代带来长期成本。"}]},"appropriate":{"examples":[{"sentence":"Although the initial proposal was rejected, the committee eventually approved a more appropriate plan that addressed all concerns.","translation":"尽管最初的提案被否决了，委员会最终批准了一个更合适的计划，解决了所有问题。"},{"sentence":"Because the software lacked appropriate security measures, the company suffered a significant data breach.","translation":"由于该软件缺乏适当的安全措施，公司遭受了严重的数据泄露。"},{"sentence":"When selecting an appropriate research methodology, scholars must consider both the nature of the data and the study's objectives.","translation":"在选择合适的研究方法时，学者必须考虑数据的性质和研究的目標。"},{"sentence":"The government allocated appropriate funds to support renewable energy projects, thereby reducing carbon emissions.","translation":"政府拨出适当的资金支持可再生能源项目，从而减少了碳排放。"},{"sentence":"Teachers should provide appropriate feedback that encourages students to reflect on their learning process, rather than simply praising them.","translation":"教师应提供适当的反馈，鼓励学生反思学习过程，而不是简单地表扬他们。"}]},"motion":{"examples":[{"sentence":"Although the perpetual motion machine defies the laws of physics, it continues to fascinate inventors.","translation":"尽管永动机违反了物理定律，但它仍然吸引着发明家。"},{"sentence":"Once the engine was set in motion, the entire assembly line began to operate smoothly, which increased productivity.","translation":"一旦发动机启动，整个装配线就开始平稳运行，从而提高了生产率。"},{"sentence":"The documentary used slow motion to emphasize the athlete's precise movements, thereby highlighting years of training.","translation":"这部纪录片使用慢动作来强调运动员的精准动作，从而突显了多年的训练。"},{"sentence":"Because the motion to increase funding was well argued, it gained majority support despite initial opposition.","translation":"由于增加资金的动议论证充分，尽管最初有反对意见，它还是获得了多数支持。"},{"sentence":"The board reviewed the motion carefully before voting, ensuring that all implications were considered.","translation":"董事会在投票前仔细审议了这项动议，确保所有影响都得到了考虑。"}]},"slice":{"examples":[{"sentence":"To prepare the stir-fry, slice the beef against the grain into thin strips, which ensures tenderness after cooking.","translation":"准备炒菜时，将牛肉逆着纹理切成薄片，这样能保证烹饪后口感嫩滑。"},{"sentence":"Although a single slice of whole-grain bread contains fewer calories than a bowl of rice, it provides more dietary fiber and essential nutrients.","translation":"虽然一片全麦面包的热量比一碗米饭少，但它能提供更多的膳食纤维和必需营养素。"},{"sentence":"The chef demonstrated how to slice the salmon at a precise angle, which maximizes the surface area for even marination.","translation":"厨师演示了如何以精确的角度切三文鱼，这样可以最大化表面积以便均匀腌制。"},{"sentence":"When analyzing the data, researchers often take a representative slice of the population to draw valid conclusions without surveying everyone.","translation":"在分析数据时，研究人员通常会选取人口中的一个代表性部分，以便在不调查所有人的情况下得出有效结论。"},{"sentence":"By using a sharp mandoline, you can slice vegetables uniformly, which not only improves presentation but also ensures consistent cooking times.","translation":"使用锋利的切片器可以将蔬菜均匀切片，这不仅提升了外观，还确保了烹饪时间一致。"}]},"rotary":{"examples":[{"sentence":"Although the rotary engine offers a high power-to-weight ratio, its widespread adoption is limited by sealing challenges and fuel efficiency concerns.","translation":"尽管旋转式发动机具有高功率重量比，但其广泛应用受到密封难题和燃油效率问题的限制。"},{"sentence":"Because the rotary kiln operates at extreme temperatures, it is essential to use refractory linings that can withstand thermal stress.","translation":"由于回转窑在极端温度下运行，使用能够承受热应力的耐火衬里至关重要。"},{"sentence":"Rotary clubs, which are part of a global service organization, focus on projects that promote peace and fight disease in local communities.","translation":"扶轮社是全球服务组织的一部分，专注于促进和平和抗击当地社区疾病的项目。"},{"sentence":"The rotary evaporator, a device that uses rotation to increase evaporation surface area, is indispensable in chemical laboratories for solvent removal.","translation":"旋转蒸发仪是一种利用旋转增加蒸发表面积的设备，在化学实验室中用于去除溶剂不可或缺。"},{"sentence":"While the rotary dial mechanism was once a marvel of engineering, it has been entirely replaced by touch-tone and digital interfaces in modern telephony.","translation":"虽然旋转拨号机制曾是工程学上的奇迹，但在现代电话中已被按键和数字界面完全取代。"}]},"recognition":{"examples":[{"sentence":"Although the algorithm achieved high accuracy, its lack of facial recognition in low-light conditions limited its practical use.","translation":"尽管该算法达到了很高的准确率，但它在低光条件下缺乏面部识别能力，限制了其实际应用。"},{"sentence":"The scientist received formal recognition for her contributions, which not only boosted her career but also inspired young researchers.","translation":"这位科学家因其贡献获得了正式认可，这不仅推动了她的事业，也激励了年轻研究人员。"},{"sentence":"Because early recognition of a stroke can save lives, public health campaigns stress the importance of knowing the warning signs.","translation":"由于早期识别中风可以挽救生命，公共卫生运动强调了解警示信号的重要性。"},{"sentence":"The company's brand recognition grew significantly after it launched a clever marketing campaign that resonated with younger consumers.","translation":"该公司在推出了一项引起年轻消费者共鸣的巧妙营销活动后，品牌认知度显著提升。"},{"sentence":"While voice recognition technology has improved, it still struggles with regional accents, thereby frustrating many users.","translation":"尽管语音识别技术有所改进，但它仍然难以处理地方口音，从而使许多用户感到沮丧。"}]},"superiority":{"examples":[{"sentence":"The company's technological superiority in battery design has allowed it to dominate the electric vehicle market, which is rapidly expanding.","translation":"该公司在电池设计方面的技术优势使其主导了快速扩张的电动汽车市场。"},{"sentence":"Although some educators claim the superiority of traditional lectures, interactive methods often lead to deeper understanding.","translation":"尽管一些教育工作者声称传统讲座的优越性，但互动式方法往往能带来更深刻的理解。"},{"sentence":"The debate over the superiority of renewable energy over fossil fuels is central to climate policy, because it affects investment decisions.","translation":"关于可再生能源相对于化石燃料的优越性的辩论是气候政策的核心，因为它影响投资决策。"},{"sentence":"His air of superiority alienated his colleagues, which ultimately hindered collaboration and slowed the project's progress.","translation":"他的优越感使同事们疏远，最终阻碍了合作并减缓了项目进展。"},{"sentence":"To demonstrate the superiority of their new drug, the researchers conducted a double-blind trial, thereby providing robust evidence.","translation":"为了证明其新药的优越性，研究人员进行了双盲试验，从而提供了有力的证据。"}]},"nuclear":{"examples":[{"sentence":"Although nuclear energy offers a low-carbon alternative to fossil fuels, the disposal of radioactive waste remains a significant challenge.","translation":"尽管核能提供了一种低碳的化石燃料替代品，但放射性废物的处置仍然是一个重大挑战。"},{"sentence":"Because nuclear reactors require stringent safety protocols, operators undergo extensive training to prevent accidents.","translation":"由于核反应堆需要严格的安全规程，操作员要接受广泛的培训以防止事故。"},{"sentence":"The treaty aims to curb nuclear proliferation, which poses a threat to global security if left unchecked.","translation":"该条约旨在遏制核扩散，如果不加控制，这将对全球安全构成威胁。"},{"sentence":"While nuclear medicine uses radioactive isotopes for diagnosis, it also demands careful handling to minimize patient exposure.","translation":"虽然核医学使用放射性同位素进行诊断，但它也需要小心处理以尽量减少患者的暴露。"},{"sentence":"A nuclear family, which consists of parents and their children, has become the norm in many industrialized nations.","translation":"由父母及其子女组成的核心家庭已成为许多工业化国家的常态。"}]},"crane":{"examples":[{"sentence":"The construction crew used a massive crane to lift the steel beams into place, which significantly accelerated the building process.","translation":"施工队使用一台巨型起重机将钢梁吊装到位，这大大加快了建造进程。"},{"sentence":"Because the red-crowned crane is a symbol of longevity in Chinese culture, it frequently appears in traditional paintings and poetry.","translation":"由于丹顶鹤在中国文化中是长寿的象征，它经常出现在传统绘画和诗歌中。"},{"sentence":"To inspect the intricate machinery, the engineer had to crane his neck over the safety railing, a posture that soon caused discomfort.","translation":"为了检查复杂的机械，工程师不得不伸长脖子越过安全栏杆，这个姿势很快就让他感到不适。"},{"sentence":"Although the operator controlled the crane with precision, the load swayed slightly in the gusting wind, prompting a temporary halt.","translation":"尽管操作员精准地控制着起重机，但负载在阵风中轻微摇摆，导致暂时停工。"},{"sentence":"The ornithologist observed that the crane, unlike most migratory birds, establishes lifelong pair bonds, which contributes to its stable population.","translation":"鸟类学家观察到，与大多数候鸟不同，鹤会建立终生的配偶关系，这有助于其种群稳定。"}]},"objective":{"examples":[{"sentence":"The primary objective of the longitudinal study was to identify the socioeconomic factors that influence early childhood development.","translation":"这项纵向研究的主要目标是确定影响儿童早期发展的社会经济因素。"},{"sentence":"To achieve the objective of carbon neutrality by 2050, governments must implement policies that incentivize renewable energy adoption and penalize excessive emissions.","translation":"为了在2050年前实现碳中和的目标，各国政府必须实施激励可再生能源使用并惩罚过度排放的政策。"},{"sentence":"Although the team encountered unforeseen technical challenges, they remained focused on the core objective and eventually delivered a functional prototype.","translation":"尽管团队遇到了意料之外的技术挑战，但他们始终专注于核心目标，最终交付了一个可用的原型。"},{"sentence":"A well-defined objective not only guides decision-making but also serves as a benchmark against which progress can be measured.","translation":"一个明确的目标不仅指导决策，而且作为衡量进展的基准。"},{"sentence":"The committee emphasized that maintaining an objective perspective is essential when evaluating conflicting research findings, as personal bias can distort conclusions.","translation":"委员会强调，在评估相互矛盾的研究结果时保持客观视角至关重要，因为个人偏见会扭曲结论。"}]},"melon":{"examples":[{"sentence":"Although the melon is often enjoyed fresh, it can also be dried or pickled to extend its shelf life.","translation":"虽然瓜通常新鲜食用，但也可以晒干或腌制以延长保质期。"},{"sentence":"Because the melon thrives in well-drained sandy soil, farmers in coastal regions achieve higher yields than those in clay-heavy areas.","translation":"由于瓜在排水良好的沙质土壤中茁壮成长，沿海地区的农民比黏土地区的农民获得更高的产量。"},{"sentence":"The chef demonstrated that a perfectly ripe melon, when paired with prosciutto, creates a harmonious balance of sweet and savory flavors.","translation":"厨师演示，一个完全成熟的瓜与意大利熏火腿搭配时，能创造出甜咸风味的和谐平衡。"},{"sentence":"Researchers have discovered that the melon's rind contains compounds with anti-inflammatory properties, which could lead to new dietary supplements.","translation":"研究人员发现，瓜皮含有具有抗炎特性的化合物，这可能会带来新的膳食补充剂。"},{"sentence":"If the melon is harvested too early, its sugar content remains low, thereby diminishing its market value and consumer appeal.","translation":"如果瓜收获过早，其糖分含量仍然很低，从而降低其市场价值和消费者吸引力。"}]},"intermediate":{"examples":[{"sentence":"Although the course is designed for intermediate learners, it also provides foundational review for those who need it.","translation":"尽管该课程是为中级学习者设计的，但它也为需要的人提供基础复习。"},{"sentence":"The intermediate phase of the project requires careful coordination between departments to ensure that deadlines are met.","translation":"项目的中间阶段需要各部门之间仔细协调，以确保按时完成。"},{"sentence":"Because the software serves as an intermediate between different operating systems, it enables seamless data transfer.","translation":"由于该软件充当不同操作系统之间的中间件，它实现了无缝数据传输。"},{"sentence":"Students who reach an intermediate level of proficiency often struggle with idiomatic expressions, which are rarely taught in textbooks.","translation":"达到中级水平的学生常常在惯用表达上遇到困难，而这些在教科书中很少教授。"},{"sentence":"When an intermediate product is contaminated, the entire manufacturing batch must be discarded to ensure safety.","translation":"当中间产品受到污染时，必须丢弃整个生产批次以确保安全。"}]},"tackle":{"examples":[{"sentence":"Although the government has implemented new policies to tackle unemployment, the results remain uncertain.","translation":"尽管政府实施了新政策来解决失业问题，但结果仍不确定。"},{"sentence":"Because the team failed to tackle the technical challenges early, the project was delayed by several months.","translation":"由于团队未能及早解决技术挑战，项目被推迟了几个月。"},{"sentence":"When communities work together to tackle pollution, they often achieve more sustainable outcomes than top-down regulations.","translation":"当社区共同努力解决污染问题时，他们往往比自上而下的法规取得更可持续的成果。"},{"sentence":"The company adopted a new strategy to tackle declining sales, which involved diversifying its product line.","translation":"公司采取了一项新策略来应对销售额下降，该策略涉及产品线的多样化。"},{"sentence":"If we do not tackle the root causes of poverty, any short-term aid will be ineffective.","translation":"如果我们不解决贫困的根本原因，任何短期援助都将是无效的。"}]},"battery":{"examples":[{"sentence":"Although the battery was fully charged, the device failed to power on because of a faulty connection.","translation":"尽管电池已充满电，但由于连接故障，设备无法开机。"},{"sentence":"The electric vehicle's battery, which uses advanced lithium-ion technology, provides a range of over 300 miles.","translation":"这辆电动汽车的电池采用先进的锂离子技术，续航里程超过300英里。"},{"sentence":"Because the battery had corroded, the technician had to clean the terminals before installing a new one.","translation":"因为电池已经腐蚀，技术人员在安装新电池前必须清洁端子。"},{"sentence":"When the battery runs low, the system automatically switches to power-saving mode to extend operation.","translation":"当电池电量不足时，系统会自动切换到省电模式以延长运行时间。"},{"sentence":"The defendant was convicted of battery after evidence showed that he struck the victim without provocation.","translation":"证据显示被告无故殴打受害者后，他被判殴打罪成立。"}]},"halt":{"examples":[{"sentence":"The research project came to a halt when the lead scientist resigned, leaving the team without direction.","translation":"当首席科学家辞职时，研究项目陷入停顿，团队失去了方向。"},{"sentence":"Because of the severe storm, the authorities ordered a halt to all outdoor activities to ensure public safety.","translation":"由于暴风雨严重，当局下令停止所有户外活动以确保公共安全。"},{"sentence":"After a brief halt to allow passengers to board, the train continued its journey through the scenic countryside.","translation":"短暂停靠让乘客上车后，火车继续穿越风景如画的乡村。"},{"sentence":"The sudden halt in production, which was caused by a supply chain disruption, led to significant financial losses.","translation":"由供应链中断导致的生产突然停止，造成了重大经济损失。"},{"sentence":"Unless both parties agree to a ceasefire, the peace talks will grind to a halt, prolonging the conflict.","translation":"除非双方同意停火，否则和谈将陷入停顿，延长冲突。"}]},"chaos":{"examples":[{"sentence":"Although the emergency plan was activated promptly, the sudden evacuation still caused chaos because many exits were blocked.","translation":"尽管紧急预案迅速启动，但突然的疏散仍然造成了混乱，因为许多出口被堵塞。"},{"sentence":"When the lead actor fell ill, the backstage area descended into chaos as the crew scrambled to find a replacement.","translation":"当主角生病时，后台区域陷入混乱，工作人员急忙寻找替代者。"},{"sentence":"The financial market experienced chaos after the unexpected interest rate hike, which triggered a massive sell-off.","translation":"金融市场在意外加息后经历了混乱，这引发了大规模抛售。"},{"sentence":"Without a clear chain of command, the rescue operation turned into chaos, thereby delaying critical aid to survivors.","translation":"没有明确的指挥链，救援行动陷入混乱，从而延误了对幸存者的关键援助。"},{"sentence":"Because the software update contained a major bug, it introduced chaos into the company's database, corrupting thousands of records.","translation":"由于软件更新包含一个重大漏洞，它给公司数据库带来了混乱，损坏了数千条记录。"}]},"pebble":{"examples":[{"sentence":"Although the pebble was small, it caused the bicycle to skid, which resulted in a minor accident.","translation":"尽管那颗鹅卵石很小，但它导致自行车打滑，从而引发了一场小事故。"},{"sentence":"The artist used a pebble to create texture on the sculpture, rather than relying on traditional tools.","translation":"艺术家用一颗鹅卵石在雕塑上制造纹理，而不是依赖传统工具。"},{"sentence":"When the hiker removed a pebble from his boot, he realized that such a tiny object could cause immense discomfort.","translation":"当徒步者从靴子里取出一颗鹅卵石时，他意识到如此微小的物体竟能造成巨大的不适。"},{"sentence":"The geologist explained that a pebble's smooth surface indicates a long history of erosion by water.","translation":"地质学家解释说，鹅卵石光滑的表面表明其经历了漫长的水流侵蚀。"},{"sentence":"Because the pebble was lodged in the machinery, the entire production line halted, thereby costing the company thousands of dollars.","translation":"因为那颗鹅卵石卡在了机器里，整条生产线停了下来，从而使公司损失了数千美元。"}]},"substitute":{"examples":[{"sentence":"Although honey is often used as a natural substitute for sugar, it still affects blood glucose levels significantly.","translation":"尽管蜂蜜常被用作糖的天然替代品，但它仍会显著影响血糖水平。"},{"sentence":"The coach decided to bring in a substitute when the star player was injured, which changed the team's dynamics.","translation":"当明星球员受伤时，教练决定换上一名替补，这改变了球队的态势。"},{"sentence":"Because the original ingredient was unavailable, the chef used tofu as a substitute, thereby creating a unique fusion dish.","translation":"由于原始食材缺货，厨师用豆腐作为替代品，从而创造出一道独特的融合菜肴。"},{"sentence":"While video calls are a convenient substitute for meetings, they cannot fully replicate the nuances of in-person communication.","translation":"虽然视频通话是会议的便捷替代品，但它们无法完全复制面对面交流的细微差别。"},{"sentence":"There is no substitute for hard work when it comes to achieving long-term success, despite the allure of shortcuts.","translation":"在取得长期成功方面，尽管捷径诱人，但努力工作是无可替代的。"}]},"bruise":{"examples":[{"sentence":"Because the bruise was accompanied by severe pain, the doctor suspected a fracture rather than a simple contusion.","translation":"由于瘀伤伴有剧烈疼痛，医生怀疑是骨折而不是单纯的挫伤。"},{"sentence":"The child's bruise, which appeared after a minor fall, healed quickly with the application of ice.","translation":"孩子轻微摔倒后出现的瘀伤，通过冰敷迅速愈合了。"},{"sentence":"Although the bruise seemed superficial, it indicated deeper tissue damage that required medical attention.","translation":"尽管瘀伤看似表浅，但它表明有更深层的组织损伤，需要医疗处理。"},{"sentence":"When the boxer sustained a bruise above his eye, the referee stopped the match to prevent further injury.","translation":"当拳击手眼睛上方出现瘀伤时，裁判停止了比赛以防止进一步受伤。"},{"sentence":"The fruit developed a bruise during transport, which reduced its market value significantly.","translation":"水果在运输过程中出现了擦伤，这大大降低了其市场价值。"}]},"interview":{"examples":[{"sentence":"The interview, which was conducted by a panel of experts, focused on the candidate's problem-solving abilities.","translation":"由专家小组进行的面试，重点考察了候选人的解决问题能力。"},{"sentence":"Although she was nervous during the interview, her thorough preparation allowed her to answer each question confidently.","translation":"尽管她在面试时很紧张，但充分的准备使她能够自信地回答每个问题。"},{"sentence":"The journalist secured an exclusive interview with the prime minister, thereby gaining insight into the new policy.","translation":"记者获得了对首相的独家采访，从而深入了解了新政策。"},{"sentence":"Because the interview was rescheduled twice, the applicant began to doubt the company's professionalism.","translation":"由于面试被重新安排了两次，申请人开始怀疑公司的专业性。"},{"sentence":"A successful interview requires not only strong qualifications but also effective communication skills.","translation":"成功的面试不仅需要强大的资历，还需要有效的沟通技巧。"}]},"somehow":{"examples":[{"sentence":"Despite the lack of formal training, the team somehow managed to complete the complex project on schedule.","translation":"尽管缺乏正规培训，团队不知何故还是设法按时完成了这个复杂的项目。"},{"sentence":"The researcher found that the new policy, though widely criticized, somehow led to a measurable improvement in public health.","translation":"研究人员发现，这项新政策虽然广受批评，但不知何故却使公共健康有了显著改善。"},{"sentence":"Even after the funding was cut, the community program somehow sustained its services through volunteer efforts.","translation":"即使在资金削减之后，社区项目不知何故仍通过志愿者的努力维持了服务。"},{"sentence":"The ancient manuscript, which had been damaged by fire, was somehow restored to a legible condition by the conservators.","translation":"这份被火烧毁的古代手稿，不知何故被修复人员恢复到了可辨认的状态。"},{"sentence":"Although the experiment failed repeatedly, the scientist somehow remained optimistic about the underlying hypothesis.","translation":"尽管实验屡次失败，这位科学家不知何故仍对基本假设保持乐观。"}]},"married":{"examples":[{"sentence":"Although they are married, the couple maintains separate bank accounts to ensure financial independence.","translation":"尽管他们已婚，这对夫妇仍保持独立的银行账户以确保财务独立。"},{"sentence":"The study found that married employees, who often have greater family responsibilities, tend to prioritize job stability over rapid advancement.","translation":"研究发现，已婚员工通常有更多的家庭责任，因此往往优先考虑工作稳定而非快速晋升。"},{"sentence":"Because she got married at a young age, she had to balance her academic pursuits with domestic duties.","translation":"由于她年纪轻轻就结了婚，她不得不在学业追求和家庭责任之间取得平衡。"},{"sentence":"In many societies, married women still face societal pressure to conform to traditional gender roles, which can limit their career opportunities.","translation":"在许多社会中，已婚女性仍然面临遵从传统性别角色的社会压力，这可能会限制她们的职业机会。"},{"sentence":"The married couple, despite their busy schedules, always make time for a weekly date night to strengthen their relationship.","translation":"这对已婚夫妇尽管日程繁忙，但总是抽出时间进行每周一次的约会之夜，以巩固他们的关系。"}]},"juvenile":{"examples":[{"sentence":"The juvenile justice system aims to rehabilitate young offenders rather than simply punish them, which reflects a progressive approach.","translation":"少年司法系统旨在改造少年犯，而不仅仅是惩罚他们，这反映了一种进步的方法。"},{"sentence":"Because juvenile delinquency is often linked to family environment and peer influence, early intervention programs are essential.","translation":"由于青少年犯罪往往与家庭环境和同伴影响有关，早期干预计划至关重要。"},{"sentence":"Although the novel is marketed for adults, its simplistic plot makes it feel rather juvenile, which disappointed many readers.","translation":"尽管这部小说面向成人市场，但其简单的情节使其显得相当幼稚，这让许多读者失望。"},{"sentence":"The library expanded its collection of juvenile literature to encourage reading habits from an early age, thereby fostering literacy.","translation":"图书馆扩大了少年读物的馆藏，以鼓励从小养成阅读习惯，从而培养读写能力。"},{"sentence":"Many juvenile birds rely on their parents for food until they develop the skills needed to forage independently, which ensures their survival.","translation":"许多幼鸟依赖父母提供食物，直到它们发展出独立觅食所需的技能，这确保了它们的生存。"}]},"agency":{"examples":[{"sentence":"The environmental protection agency issued new regulations to reduce industrial emissions by 30 percent, which will improve air quality.","translation":"环境保护机构发布了新法规，旨在将工业排放减少30%，这将改善空气质量。"},{"sentence":"Through the agency of social media, grassroots movements can now mobilize support far more quickly than in the past, thereby amplifying their impact.","translation":"通过社交媒体的中介作用，草根运动现在能比过去快得多地动员支持，从而扩大其影响。"},{"sentence":"Because individuals who believe in their own agency are more likely to take proactive steps, they often achieve greater career success.","translation":"由于相信自身能动性的人更有可能采取积极步骤，他们往往取得更大的职业成功。"},{"sentence":"The advertising agency developed a creative campaign that significantly boosted the brand's visibility, which attracted new investors.","translation":"广告公司开发了一个创意活动，显著提升了品牌知名度，这吸引了新的投资者。"},{"sentence":"A reputable travel agency can handle complex itineraries, ensuring that all logistics are managed efficiently, which reduces traveler stress.","translation":"一家信誉良好的旅行社可以处理复杂的行程，确保所有后勤工作得到高效管理，这减轻了旅行者的压力。"}]},"acquisition":{"examples":[{"sentence":"The acquisition of a new language requires consistent practice, which is why immersion programs often yield better results than traditional classroom instruction.","translation":"习得一门新语言需要持续练习，这就是为什么沉浸式项目通常比传统课堂教学效果更好。"},{"sentence":"Although the acquisition of the startup was costly, it provided the tech giant with cutting-edge artificial intelligence technology that accelerated its product development.","translation":"尽管收购这家初创公司代价高昂，但它为这家科技巨头提供了尖端的人工智能技术，加速了其产品开发。"},{"sentence":"Because knowledge acquisition is a lifelong endeavor, professionals must engage in continuous learning to stay relevant in a rapidly evolving job market.","translation":"由于知识获取是终身事业，专业人士必须不断学习，才能在快速变化的就业市场中保持竞争力。"},{"sentence":"The museum's acquisition of the ancient sculpture was made possible through a generous donation, which ensures that the artifact remains accessible to the public.","translation":"博物馆获得这件古代雕塑得益于一笔慷慨的捐赠，这确保了该文物仍对公众开放。"},{"sentence":"When a company pursues an acquisition, it must conduct thorough due diligence to assess potential risks, thereby avoiding costly post-merger integration problems.","translation":"当一家公司进行收购时，必须进行彻底的尽职调查以评估潜在风险，从而避免代价高昂的合并后整合问题。"}]},"therefore":{"examples":[{"sentence":"The experiment yielded consistent results across multiple trials; therefore, the hypothesis can be considered valid.","translation":"该实验在多次试验中得出了一致的结果，因此可以认为该假设是有效的。"},{"sentence":"Online learning offers flexible schedules; therefore, it has become increasingly popular among working professionals.","translation":"在线学习提供了灵活的时间安排，因此在在职专业人士中越来越受欢迎。"},{"sentence":"The city has invested heavily in public transportation; therefore, traffic congestion has noticeably decreased.","translation":"该市在公共交通上投入了大量资金，因此交通拥堵明显减少。"},{"sentence":"Regular exercise improves cardiovascular health; therefore, doctors recommend at least 150 minutes of moderate activity per week.","translation":"定期锻炼能改善心血管健康，因此医生建议每周至少进行150分钟的中等强度活动。"},{"sentence":"The company failed to adapt to market changes; therefore, it lost its competitive edge.","translation":"该公司未能适应市场变化，因此失去了竞争优势。"}]},"direct":{"examples":[{"sentence":"Although his feedback was direct, it helped the team identify critical flaws in the project plan.","translation":"尽管他的反馈很直接，但它帮助团队识别了项目计划中的关键缺陷。"},{"sentence":"The new manager chose to direct the team's efforts toward innovation rather than routine maintenance.","translation":"新经理选择将团队的努力引向创新，而不是日常维护。"},{"sentence":"Because the instructions were direct and unambiguous, the assembly process was completed without errors.","translation":"因为说明直接且明确，装配过程毫无差错地完成了。"},{"sentence":"The documentary seeks to direct public attention to environmental issues, which are often overlooked in policy debates.","translation":"这部纪录片试图引导公众关注环境问题，这些问题在政策辩论中常被忽视。"},{"sentence":"While a direct approach may seem harsh, it often prevents misunderstandings in professional communication.","translation":"虽然直接的方式可能显得生硬，但它往往能防止职业沟通中的误解。"}]},"joy":{"examples":[{"sentence":"Although the project encountered numerous setbacks, the team's joy upon its successful completion was immeasurable.","translation":"尽管项目遇到了许多挫折，但团队在成功完成时的喜悦是无法估量的。"},{"sentence":"The joy that comes from helping others often proves more lasting than the pleasure derived from material possessions.","translation":"帮助他人所带来的快乐往往比物质财富带来的愉悦更持久。"},{"sentence":"Because she had dedicated years to mastering the piano, the joy of performing at the concert hall was deeply fulfilling.","translation":"由于她多年来致力于掌握钢琴，在音乐厅表演的喜悦让她深感满足。"},{"sentence":"When communities come together to celebrate cultural festivals, a shared sense of joy strengthens social bonds.","translation":"当社区聚集在一起庆祝文化节日时，共同的喜悦感加强了社会纽带。"},{"sentence":"The discovery of a long-lost manuscript brought immense joy to the literary world, which had considered it permanently destroyed.","translation":"一份遗失已久的手稿被发现，给文学界带来了巨大的喜悦，此前人们认为它已被永久毁坏。"}]},"diverse":{"examples":[{"sentence":"A diverse team, which includes members from various disciplines, is more likely to generate groundbreaking ideas.","translation":"一个包含不同学科成员的多元化团队更有可能产生突破性的想法。"},{"sentence":"Although the city is known for its diverse culinary scene, it lacks affordable housing for low-income residents.","translation":"尽管这座城市以其多样化的美食闻名，但它缺乏面向低收入居民的负担得起的住房。"},{"sentence":"Because the curriculum incorporates diverse perspectives, students develop a more comprehensive understanding of global issues.","translation":"由于课程融入了多元视角，学生们对全球问题有了更全面的理解。"},{"sentence":"Ecosystems with diverse species are better equipped to withstand environmental changes, thereby ensuring long-term stability.","translation":"物种多样的生态系统更能抵御环境变化，从而确保长期稳定。"},{"sentence":"The conference attracted a diverse audience, ranging from seasoned professionals to enthusiastic newcomers, which enriched the discussions.","translation":"会议吸引了多元化的听众，从经验丰富的专业人士到热情的新人，这丰富了讨论。"}]},"apparatus":{"examples":[{"sentence":"The laboratory apparatus, which includes spectrometers and centrifuges, requires regular calibration to ensure accurate measurements.","translation":"实验室的仪器，包括光谱仪和离心机，需要定期校准以确保测量准确。"},{"sentence":"A well-functioning state apparatus is essential for implementing public policies that promote social welfare and economic stability.","translation":"一个运转良好的国家机器对于实施促进社会福利和经济稳定的公共政策至关重要。"},{"sentence":"The breathing apparatus used by firefighters must be rigorously tested because any malfunction could prove fatal in a rescue operation.","translation":"消防员使用的呼吸器具必须经过严格测试，因为在救援行动中任何故障都可能是致命的。"},{"sentence":"Modern educational apparatus, such as interactive whiteboards and online platforms, can enhance student engagement when integrated thoughtfully into the curriculum.","translation":"现代教育设备，如交互式白板和在线平台，在深思熟虑地融入课程时能够提高学生的参与度。"},{"sentence":"The legal apparatus of a democratic society should safeguard individual rights while maintaining public order, a balance that is often difficult to achieve.","translation":"民主社会的法律机构应该在维护公共秩序的同时保障个人权利，这种平衡往往难以实现。"}]},"beware":{"examples":[{"sentence":"Although the proposal appears promising, we must beware of hidden costs that could undermine its feasibility.","translation":"尽管该提案看起来很有前景，但我们必须谨防可能破坏其可行性的隐藏成本。"},{"sentence":"When evaluating online sources, beware of confirmation bias, which can lead you to accept false information uncritically.","translation":"在评估网络信息时，要谨防确认偏误，因为它可能导致你不加批判地接受虚假信息。"},{"sentence":"Beware of implementing drastic reforms without pilot testing, because unintended consequences may outweigh the benefits.","translation":"要谨防在没有试点测试的情况下实施激进改革，因为意外后果可能大于收益。"},{"sentence":"While competition can drive innovation, companies must beware of sacrificing ethical standards to gain a short-term advantage.","translation":"虽然竞争能推动创新，但公司必须谨防为了短期优势而牺牲道德标准。"},{"sentence":"Beware of assuming that correlation implies causation, a fallacy that frequently distorts research conclusions.","translation":"要谨防假设相关性意味着因果关系，这是一种经常扭曲研究结论的谬误。"}]},"ruler":{"examples":[{"sentence":"Although the ruler claimed to act in the people's interest, his policies primarily benefited the elite.","translation":"尽管这位统治者声称为了人民的利益行事，但他的政策主要惠及精英阶层。"},{"sentence":"Because the ruler failed to address the economic crisis, public trust in the government eroded rapidly.","translation":"由于统治者未能应对经济危机，公众对政府的信任迅速削弱。"},{"sentence":"When using a ruler to measure the dimensions of a room, it is important to keep it level to avoid errors.","translation":"使用直尺测量房间尺寸时，保持其水平以避免误差是很重要的。"},{"sentence":"The carpenter relied on a steel ruler, which provided greater accuracy than a plastic one, for his intricate work.","translation":"木匠依靠一把钢直尺来完成精细的工作，它比塑料直尺提供了更高的精确度。"},{"sentence":"While a benevolent ruler can inspire loyalty, a despotic one often sows the seeds of rebellion.","translation":"虽然仁慈的统治者能激发忠诚，但暴虐的统治者往往会埋下叛乱的种子。"}]},"collar":{"examples":[{"sentence":"Although the white-collar sector has grown rapidly, many economies still depend heavily on blue-collar industries.","translation":"尽管白领行业增长迅速，但许多经济体仍然严重依赖蓝领产业。"},{"sentence":"The detective managed to collar the thief after a high-speed chase through the city streets.","translation":"侦探在城市街道上高速追逐后，终于抓住了小偷。"},{"sentence":"Because the dog's collar was too loose, it slipped off during the walk, which caused a moment of panic.","translation":"因为狗的项圈太松，散步时它滑脱了，这引起了一阵恐慌。"},{"sentence":"A crisp white collar, which contrasts sharply with a dark suit, is a classic symbol of corporate attire.","translation":"与深色西装形成鲜明对比的挺括白领，是职业装的经典标志。"},{"sentence":"When the shirt collar became frayed, she decided to replace it rather than discard the entire garment.","translation":"当衬衫领子磨损时，她决定更换领子而不是丢弃整件衣服。"}]},"static":{"examples":[{"sentence":"Although static electricity is often harmless, it can ignite flammable gases in industrial settings.","translation":"尽管静电通常无害，但在工业环境中它可能点燃易燃气体。"},{"sentence":"A static website, which lacks interactive features, may not engage users as effectively as a dynamic one.","translation":"缺乏交互功能的静态网站可能不如动态网站那样有效吸引用户。"},{"sentence":"Because the population remained static for decades, the government introduced incentives to encourage growth.","translation":"由于人口几十年来保持不变，政府推出了激励措施以鼓励增长。"},{"sentence":"When a character remains static throughout a novel, readers may find the story less compelling.","translation":"当角色在整部小说中保持静止不变时，读者可能会觉得故事不那么引人入胜。"},{"sentence":"Engineers must consider static loads, which include the weight of the structure itself, to ensure stability.","translation":"工程师必须考虑包括结构自身重量在内的静荷载，以确保稳定性。"}]},"conference":{"examples":[{"sentence":"The international conference on climate change, which was held in Paris, resulted in a landmark agreement.","translation":"在巴黎举行的国际气候变化会议达成了一项具有里程碑意义的协议。"},{"sentence":"Although the conference was scheduled for three days, the keynote speeches were condensed into one morning.","translation":"尽管会议原定三天，但主题演讲被压缩到了一个上午。"},{"sentence":"She presented her research at the conference, thereby gaining valuable feedback from leading experts.","translation":"她在会议上展示了她的研究，从而获得了顶尖专家的宝贵反馈。"},{"sentence":"Because the conference attracted a diverse audience, the organizers provided simultaneous translation services.","translation":"由于会议吸引了多元化的听众，组织者提供了同声传译服务。"},{"sentence":"The annual industry conference, which features workshops and panel discussions, fosters collaboration among professionals.","translation":"年度行业会议以研讨会和小组讨论为特色，促进了专业人士之间的合作。"}]},"excuse":{"examples":[{"sentence":"The professor refused to excuse the late submission, because the student had not provided a valid reason.","translation":"教授拒绝原谅迟交，因为该学生没有提供正当理由。"},{"sentence":"While cultural differences may excuse minor faux pas, they cannot justify intentional disrespect.","translation":"虽然文化差异或许可以原谅小的失礼，但不能为故意的不尊重开脱。"},{"sentence":"The company policy does not excuse employees from attending mandatory training, unless they have a medical emergency.","translation":"公司政策不免除员工参加强制培训，除非他们有医疗紧急情况。"},{"sentence":"To excuse plagiarism would undermine academic integrity, which is essential for scholarly work.","translation":"原谅抄袭会破坏学术诚信，而学术诚信对学术工作至关重要。"},{"sentence":"If a student presents a documented illness, the school may excuse their absence from the exam.","translation":"如果学生出示有记录的病情，学校可能会原谅他们缺席考试。"}]},"gate":{"examples":[{"sentence":"Because the ancient city gate had withstood centuries of conflict, it became a powerful symbol of resilience for later generations.","translation":"因为这座古老的城门经受住了几个世纪的战乱，它成为了后代坚韧不拔的有力象征。"},{"sentence":"Although the garden gate was merely a simple wooden structure, it marked the boundary between public chaos and private tranquility.","translation":"尽管花园的大门只是一个简单的木结构，但它标志着公共喧嚣与私人宁静之间的界限。"},{"sentence":"The university installed an electronic gate to regulate campus access, which significantly improved security after a series of incidents.","translation":"大学安装了一个电子门禁来管理校园出入，这在一系列事件后显著提高了安全性。"},{"sentence":"When the floodwaters rose unexpectedly, the sluice gate was closed to prevent the river from inundating nearby farmland.","translation":"当洪水意外上涨时，水闸被关闭以防止河流淹没附近的农田。"},{"sentence":"The ornate iron gate, crafted by a local artisan, serves as an entrance that reflects the community's cultural heritage.","translation":"由当地工匠打造的精美铁门，作为一个入口，反映了社区的文化遗产。"}]},"actual":{"examples":[{"sentence":"While theoretical models predict steady growth, the actual economic data reveal a more volatile pattern that policymakers must address.","translation":"虽然理论模型预测稳定增长，但实际经济数据揭示了一种更不稳定的模式，决策者必须加以应对。"},{"sentence":"The actual cost of implementing the new curriculum was far higher than the initial estimate, which forced the school board to seek additional funding.","translation":"实施新课程的实际成本远高于最初的估算，这迫使学校董事会寻求额外资金。"},{"sentence":"Because the actual benefits of the program were not documented until the third year, early critics dismissed it as ineffective.","translation":"由于该项目的实际收益直到第三年才被记录下来，早期的批评者认为它无效。"},{"sentence":"Although the prototype performed well in simulations, the actual device encountered numerous unforeseen challenges during field tests.","translation":"尽管原型在模拟中表现良好，但实际设备在现场测试中遇到了许多无法预见的挑战。"},{"sentence":"To understand the actual impact of climate change on agriculture, researchers must analyze long-term data rather than rely on short-term observations.","translation":"为了理解气候变化对农业的实际影响，研究人员必须分析长期数据，而不是依赖短期观察。"}]},"empire":{"examples":[{"sentence":"Although the empire expanded rapidly through military conquest, its cultural achievements ultimately proved more enduring than its territorial gains.","translation":"尽管帝国通过军事征服迅速扩张，但其文化成就最终比其领土扩张更为持久。"},{"sentence":"Because the empire's legal code was systematically applied across diverse provinces, it fostered a sense of unity that outlasted the political structure itself.","translation":"由于帝国的法典在各省得到系统应用，它培养了一种比政治结构本身更持久的团结感。"},{"sentence":"The empire, which had once controlled vital trade routes, gradually declined when maritime technology shifted economic power to coastal nations.","translation":"这个曾控制重要贸易路线的帝国，在航海技术将经济力量转移到沿海国家时逐渐衰落。"},{"sentence":"While the empire's monumental architecture still inspires awe, it was built through the labor of subjugated peoples whose stories are often overlooked.","translation":"尽管帝国的宏伟建筑仍令人敬畏，但它们是通过被征服人民的劳动建成的，而这些人的故事往往被忽视。"},{"sentence":"To ensure the empire's stability, the rulers implemented a complex bureaucracy that, paradoxically, became a source of inefficiency and corruption.","translation":"为了确保帝国的稳定，统治者实施了一套复杂的官僚体系，但矛盾的是，这反而成了低效和腐败的根源。"}]},"editor":{"examples":[{"sentence":"The editor insisted that every claim be supported by credible evidence before publication.","translation":"编辑坚持要求在发表前，每一项主张都必须有可靠证据支持。"},{"sentence":"A skilled editor can transform a disjointed draft into a coherent argument that persuades readers.","translation":"一位熟练的编辑能将杂乱无章的草稿转化为说服读者的连贯论述。"},{"sentence":"Because the editor recognized the manuscript's potential, she worked closely with the author to refine its structure.","translation":"由于编辑认识到了手稿的潜力，她与作者密切合作以完善其结构。"},{"sentence":"Although the editor faced tight deadlines, she meticulously verified every statistic in the report.","translation":"尽管编辑面临紧迫的截止日期，她仍一丝不苟地核实了报告中的每一项统计数据。"},{"sentence":"The editor decided to remove the ambiguous paragraph so that the article would convey a clearer message.","translation":"编辑决定删除那段含糊的文字，以便文章传达更清晰的信息。"}]},"hysterical":{"examples":[{"sentence":"When the fire alarm sounded without warning, several people became hysterical and struggled to follow the evacuation instructions.","translation":"当火灾警报毫无预兆地响起时，几个人变得歇斯底里，难以遵从疏散指示。"},{"sentence":"Although the media coverage was often hysterical, the actual risk to public health remained minimal according to the official report.","translation":"尽管媒体报道常常夸大其词，但根据官方报告，对公共健康的实际风险仍然很小。"},{"sentence":"The professor warned that hysterical reactions to new technologies can delay beneficial innovations that would otherwise improve people's lives.","translation":"教授警告说，对新技术的过度反应可能会推迟那些本可改善人们生活的有益创新。"},{"sentence":"Investors who grow hysterical during market downturns often sell their assets at a loss, which undermines their long-term financial goals.","translation":"在市场低迷时期变得恐慌的投资者常常亏本抛售资产，这损害了他们的长期财务目标。"},{"sentence":"A hysterical fear of failure can prevent students from taking the intellectual risks that are essential for deep learning.","translation":"对失败的过度恐惧会阻碍学生进行深度学习所必需的智力冒险。"}]},"pharmacy":{"examples":[{"sentence":"Although the hospital pharmacy operates 24 hours a day, it still struggles to meet the demand for certain specialized medications.","translation":"尽管医院药房24小时营业，但仍然难以满足某些特殊药物的需求。"},{"sentence":"Because the new pharmacy is located within a supermarket, customers can conveniently pick up their prescriptions while shopping for groceries.","translation":"由于新药房位于超市内，顾客可以在购买杂货的同时方便地取药。"},{"sentence":"The field of pharmacy has evolved significantly, which now encompasses not only drug dispensing but also patient counseling and clinical services.","translation":"药学领域已经发生了显著演变，现在不仅包括配药，还包括患者咨询和临床服务。"},{"sentence":"When the pharmacy technician noticed a potential drug interaction, she immediately consulted the pharmacist to ensure patient safety.","translation":"当药房技师注意到潜在的药物相互作用时，她立即咨询了药剂师以确保患者安全。"},{"sentence":"The government introduced stricter regulations for the pharmacy industry, thereby reducing the circulation of counterfeit drugs in the market.","translation":"政府对制药业引入了更严格的法规，从而减少了市场上假药的流通。"}]},"tape":{"examples":[{"sentence":"Although the cassette tape is now obsolete, it played a crucial role in the spread of popular music during the late twentieth century.","translation":"尽管盒式磁带现在已经过时，但它在二十世纪后期流行音乐的传播中发挥了关键作用。"},{"sentence":"The athlete wrapped adhesive tape around her ankle before the competition, which provided extra support and reduced the risk of injury.","translation":"运动员在比赛前用胶带缠住脚踝，这提供了额外的支撑并降低了受伤风险。"},{"sentence":"Because the old tape had degraded over time, the archivists had to use specialized equipment to recover the recorded interview.","translation":"由于旧磁带随着时间的推移已经退化，档案管理员不得不使用专门设备来恢复录制的采访内容。"},{"sentence":"The tailor used a measuring tape to take precise measurements, thereby ensuring that the custom suit would fit the client perfectly.","translation":"裁缝用卷尺进行精确测量，从而确保定制的西装完美合身。"},{"sentence":"When the police reviewed the security tape, they identified the suspect entering the building shortly before the incident occurred.","translation":"当警方查看监控录像时，他们发现嫌疑人在事件发生前不久进入了建筑物。"}]},"joint":{"examples":[{"sentence":"Although the joint venture faced initial regulatory hurdles, it eventually became a model for international cooperation.","translation":"尽管这家合资企业最初面临监管障碍，但它最终成为了国际合作的典范。"},{"sentence":"The surgeon explained that the artificial joint would restore mobility, which had been severely limited by arthritis.","translation":"外科医生解释说，人造关节将恢复因关节炎而严重受限的活动能力。"},{"sentence":"Because the joint statement was carefully worded, it managed to satisfy both parties without conceding core principles.","translation":"由于这份联合声明措辞谨慎，它成功地让双方都满意，而没有在核心原则上让步。"},{"sentence":"Engineers applied a special adhesive to the joint, thereby ensuring a watertight seal that could withstand extreme pressure.","translation":"工程师们在接合处涂上了一种特殊的粘合剂，从而确保了能够承受极端压力的防水密封。"},{"sentence":"When the joint research project concluded, the findings were published in a prestigious journal, which attracted further funding.","translation":"当这个联合研究项目结束时，其发现发表在一家著名期刊上，这吸引了更多的资金。"}]},"warehouse":{"examples":[{"sentence":"Because the warehouse management system was upgraded, inventory accuracy improved significantly, which reduced costly stockouts.","translation":"由于仓库管理系统升级了，库存准确性显著提高，从而减少了代价高昂的缺货现象。"},{"sentence":"The company decided to warehouse its raw materials near the factory, thereby minimizing transportation delays during peak production.","translation":"公司决定将原材料储存在工厂附近，从而在高峰生产期间最大限度地减少运输延误。"},{"sentence":"Although the warehouse was damaged by the storm, the backup generators kept the refrigeration units running, which saved the perishable goods.","translation":"尽管仓库被暴风雨损坏，但备用发电机使制冷设备继续运转，从而挽救了易腐货物。"},{"sentence":"When the e-commerce giant built a fully automated warehouse, it was able to process orders three times faster than before.","translation":"当这家电子商务巨头建造了一个全自动化仓库时，它处理订单的速度比以前快了三倍。"},{"sentence":"The historic warehouse was converted into a cultural center, which not only preserved the architecture but also revitalized the neighborhood.","translation":"这座历史悠久的仓库被改造成了一个文化中心，这不仅保护了建筑，还振兴了该街区。"}]},"complement":{"examples":[{"sentence":"A balanced diet should include vegetables that complement the nutritional value of staple foods.","translation":"均衡的饮食应包括能补充主食营养价值的蔬菜。"},{"sentence":"While the new policy aims to boost economic growth, it must complement environmental protection efforts.","translation":"虽然新政策旨在促进经济增长，但它必须与环境保护工作相辅相成。"},{"sentence":"The online resources are designed to complement the textbook, thereby enhancing the learning experience.","translation":"这些在线资源旨在补充教科书，从而提升学习体验。"},{"sentence":"Because her analytical skills complement his creative thinking, they form an ideal partnership.","translation":"由于她的分析能力与他的创造性思维相辅相成，他们形成了理想的合作关系。"},{"sentence":"In grammar, a subject complement follows a linking verb to describe the subject, which is essential for sentence clarity.","translation":"在语法中，主语补足语跟在系动词之后描述主语，这对句子清晰度至关重要。"}]},"revenge":{"examples":[{"sentence":"Although revenge may offer a fleeting sense of justice, it often perpetuates a cycle of retaliation that harms all involved.","translation":"尽管复仇可能带来短暂的正义感，但它往往会使报复循环持续下去，伤害所有相关的人。"},{"sentence":"Because revenge is driven by anger rather than reason, decisions made in its pursuit frequently lead to unintended consequences.","translation":"由于复仇是由愤怒而非理性驱动的，在追求复仇时做出的决定常常会导致意想不到的后果。"},{"sentence":"While the desire for revenge is a natural human response to betrayal, channeling that energy into personal growth proves more constructive.","translation":"虽然复仇的欲望是对背叛的自然人类反应，但将这种能量用于个人成长则更具建设性。"},{"sentence":"Historical conflicts show that revenge rarely resolves disputes, whereas diplomatic negotiations can achieve lasting peace.","translation":"历史冲突表明，复仇很少能解决争端，而外交谈判则能实现持久的和平。"},{"sentence":"If societies prioritize revenge over rehabilitation, they risk entrenching a culture of violence that undermines social cohesion.","translation":"如果社会将复仇置于改造之上，就有可能巩固一种破坏社会凝聚力的暴力文化。"}]},"privilege":{"examples":[{"sentence":"Access to quality education is often considered a privilege rather than a universal right, which perpetuates social inequality in many regions.","translation":"获得优质教育往往被视为一种特权而非普遍权利，这在许多地区使社会不平等长期存在。"},{"sentence":"Because privilege can blind individuals to the struggles of others, those who benefit from it should cultivate empathy and awareness to foster a more just society.","translation":"由于特权可能使人忽视他人的挣扎，受益于特权者应当培养同理心和意识，以促进一个更公正的社会。"},{"sentence":"The privilege of working with renowned researchers gave the young scientist invaluable insights into cutting-edge methodologies, which accelerated her career.","translation":"与知名研究人员共事的特权让这位年轻科学家对前沿方法有了宝贵的见解，从而加速了她的职业生涯。"},{"sentence":"Although he enjoyed the privilege of a stable upbringing, he never took his advantages for granted, choosing instead to advocate for underprivileged communities.","translation":"尽管他享有稳定成长环境的特权，但他从不认为自己的优势是理所当然的，而是选择为弱势群体发声。"},{"sentence":"Recognizing one's own privilege is the first step toward advocating for more equitable social structures, which requires both humility and courage.","translation":"认识到自身的特权是倡导更公平社会结构的第一步，这既需要谦逊也需要勇气。"}]},"poet":{"examples":[{"sentence":"A poet who draws on personal suffering often produces work that resonates across generations.","translation":"一位从个人痛苦中汲取灵感的诗人，常常能创作出跨越世代引起共鸣的作品。"},{"sentence":"Although she is primarily recognized as a novelist, her skill as a poet has gradually gained critical acclaim.","translation":"尽管她主要以小说家身份为人所知，但她作为诗人的才华已逐渐获得评论界的赞誉。"},{"sentence":"The Romantic poet believed that nature could restore the human spirit in an age of rapid industrialization.","translation":"这位浪漫主义诗人相信，在快速工业化的时代，自然能够恢复人类的精神。"},{"sentence":"Because a poet condenses complex emotions into a few lines, every word must carry significant weight.","translation":"由于诗人将复杂的情感浓缩在寥寥数行之中，每个词都必须承载重要的分量。"},{"sentence":"A true poet observes the ordinary world with such intensity that familiar objects become extraordinary.","translation":"真正的诗人以如此强烈的专注观察平凡的世界，以至于熟悉的事物变得非凡。"}]},"progress":{"examples":[{"sentence":"Although economic progress has lifted many out of poverty, it has also widened inequality in some regions.","translation":"尽管经济进步使许多人摆脱了贫困，但在一些地区也加剧了不平等。"},{"sentence":"Because the research team shared data openly, progress in vaccine development accelerated dramatically.","translation":"由于研究团队公开共享数据，疫苗研发的进展大大加快。"},{"sentence":"When governments invest in early childhood education, the long-term progress of society becomes evident.","translation":"当政府投资于早期儿童教育时，社会的长期进步就会显现出来。"},{"sentence":"Technological progress, while beneficial, must be guided by ethical considerations to avoid unintended harm.","translation":"技术进步虽然有益，但必须以伦理考量为指导，以避免意外伤害。"},{"sentence":"The progress of gender equality requires not only legislative changes but also shifts in cultural attitudes.","translation":"性别平等的进步不仅需要立法变革，还需要文化态度的转变。"}]},"square":{"examples":[{"sentence":"The town square, which dates back to the medieval period, remains the heart of community life.","translation":"这个城镇广场可追溯到中世纪时期，至今仍是社区生活的中心。"},{"sentence":"To ensure fairness, the mediator insisted on a square distribution of resources among all parties.","translation":"为了确保公平，调解人坚持在所有各方之间公平分配资源。"},{"sentence":"The new park covers an area of 10,000 square meters, thereby providing ample space for recreation.","translation":"新公园占地1万平方米，从而为休闲娱乐提供了充足的空间。"},{"sentence":"If you draw a square with sides of equal length, you can easily calculate its perimeter.","translation":"如果你画一个边长相等的正方形，就能轻松计算其周长。"},{"sentence":"His lavish lifestyle does not square with his modest income, which raises suspicions about his finances.","translation":"他奢侈的生活方式与他微薄的收入不符，这引起了对其财务状况的怀疑。"}]},"dove":{"examples":[{"sentence":"Although the dove is often seen as a symbol of peace, its role in ancient mythology was sometimes associated with war.","translation":"虽然鸽子常被视为和平的象征，但它在古代神话中的角色有时与战争相关。"},{"sentence":"Because the dove possesses a remarkable homing instinct, it was used to carry messages during both world wars.","translation":"由于鸽子具有非凡的归巢本能，它在两次世界大战期间被用来传递信息。"},{"sentence":"The white dove, which is released at many ceremonies, represents hope and new beginnings across various cultures.","translation":"在许多仪式上放飞的白鸽，在不同文化中代表着希望和新的开始。"},{"sentence":"While the dove is generally gentle, it will aggressively defend its territory when an intruder approaches the nest.","translation":"虽然鸽子通常很温和，但当入侵者靠近巢穴时，它会积极地保卫自己的领地。"},{"sentence":"Through careful breeding, scientists have developed a dove that can navigate more accurately than its wild counterparts.","translation":"通过精心育种，科学家培育出了一种比野生同类导航更准确的鸽子。"}]},"compress":{"examples":[{"sentence":"To ensure efficient data transmission, engineers compress large files before sending them over the network.","translation":"为了确保高效的数据传输，工程师在通过网络发送之前压缩大文件。"},{"sentence":"When you compress a spring, it stores potential energy that can be released to perform work.","translation":"当你压缩弹簧时，它储存了势能，这些势能可以释放出来做功。"},{"sentence":"Although modern algorithms can compress video without visible quality loss, the process requires significant computing power.","translation":"尽管现代算法可以压缩视频而无明显质量损失，但该过程需要大量的计算能力。"},{"sentence":"Because the report was too lengthy, the editor had to compress it into a concise summary for the executive board.","translation":"由于报告太长，编辑不得不将其压缩成一份简洁的摘要供执行委员会使用。"},{"sentence":"The new software can compress a terabyte of data into a few gigabytes, thereby revolutionizing storage solutions.","translation":"这款新软件可以将一太字节的数据压缩到几千兆字节，从而彻底改变了存储解决方案。"}]},"conventional":{"examples":[{"sentence":"While conventional wisdom suggests that hard work guarantees success, luck and timing also play crucial roles.","translation":"虽然传统观念认为努力工作能保证成功，但运气和时机也起着至关重要的作用。"},{"sentence":"Because conventional farming relies heavily on pesticides, it often harms beneficial insects and soil health.","translation":"由于传统农业严重依赖杀虫剂，它常常危害益虫和土壤健康。"},{"sentence":"The architect rejected conventional designs, instead creating a building that mimics the form of a seashell.","translation":"建筑师摒弃了传统设计，转而创造了一座模仿贝壳形状的建筑。"},{"sentence":"Although conventional energy sources are still dominant, renewable alternatives are becoming increasingly cost-competitive.","translation":"尽管传统能源仍占主导地位，但可再生替代能源在成本上正变得越来越有竞争力。"},{"sentence":"In contrast to conventional teaching methods, which emphasize rote learning, the new approach fosters critical thinking.","translation":"与强调死记硬背的传统教学方法相比，新方法培养了批判性思维。"}]},"plague":{"examples":[{"sentence":"Although the plague decimated the population, it also accelerated the end of feudalism by creating a labor shortage.","translation":"尽管瘟疫使人口锐减，但它也通过造成劳动力短缺加速了封建制度的终结。"},{"sentence":"The plague of corruption that infiltrated the government eroded public trust, which took decades to rebuild.","translation":"渗透进政府的腐败祸患侵蚀了公众信任，这花了数十年才得以重建。"},{"sentence":"Because a plague of locusts can destroy crops within hours, farmers in the region live in constant fear of infestation.","translation":"因为蝗灾能在数小时内摧毁庄稼，该地区的农民一直生活在虫害的持续恐惧中。"},{"sentence":"When a plague of misinformation spreads through social media, it undermines the very foundation of democratic discourse.","translation":"当错误信息的瘟疫通过社交媒体传播时，它破坏了民主话语的根基。"},{"sentence":"The historian noted that the plague of war not only caused immediate suffering but also left lasting scars on the national psyche.","translation":"历史学家指出，战争的祸患不仅造成了直接的苦难，还给民族心理留下了持久的创伤。"}]},"tentative":{"examples":[{"sentence":"The committee reached a tentative agreement, but several members insisted that the final vote be postponed until further data was available.","translation":"委员会达成了初步协议，但几位成员坚持将最终投票推迟到有进一步数据可用时。"},{"sentence":"Because the evidence was inconclusive, the scientist offered only a tentative hypothesis, which required rigorous testing.","translation":"因为证据不确凿，科学家只提出了一个初步假设，这需要严格的检验。"},{"sentence":"The startup's tentative business model evolved rapidly once they received feedback from early adopters, thereby increasing their market share.","translation":"这家初创公司的试验性商业模式在收到早期用户的反馈后迅速演变，从而增加了市场份额。"},{"sentence":"After months of negotiation, the two sides established a tentative timeline for the phased withdrawal of troops, which was subject to change.","translation":"经过数月的谈判，双方为分阶段撤军制定了一个暂定的时间表，这可能会改变。"},{"sentence":"Her tentative steps toward a career change included enrolling in a part-time course, which allowed her to explore the field without quitting her job.","translation":"她向职业转型迈出的试探性步骤包括报名参加兼职课程，这使她能在不辞职的情况下探索该领域。"}]},"thorough":{"examples":[{"sentence":"Although the initial draft was promising, a thorough revision revealed several logical inconsistencies.","translation":"尽管初稿很有希望，但彻底的修订揭示了几个逻辑不一致之处。"},{"sentence":"Because the experiment required a thorough understanding of quantum mechanics, the team consulted several experts.","translation":"因为实验需要对量子力学有透彻的理解，团队咨询了几位专家。"},{"sentence":"The auditor conducted a thorough examination of the financial records, which uncovered a pattern of fraudulent transactions.","translation":"审计员对财务记录进行了彻底检查，这发现了一系列欺诈交易。"},{"sentence":"While a thorough analysis of the data is time-consuming, it is essential to ensure the validity of the conclusions.","translation":"虽然对数据进行彻底分析很耗时，但这对确保结论的有效性至关重要。"},{"sentence":"A thorough knowledge of international law is required for diplomats, thereby enabling them to negotiate complex treaties effectively.","translation":"外交官需要具备国际法的全面知识，从而使他们能够有效地谈判复杂的条约。"}]},"monetary":{"examples":[{"sentence":"Although monetary policy can stimulate economic growth, it may also lead to inflationary pressures if not carefully managed.","translation":"尽管货币政策可以刺激经济增长，但如果管理不善，也可能导致通胀压力。"},{"sentence":"The government provided monetary assistance to low-income families, which helped alleviate the immediate financial burden.","translation":"政府向低收入家庭提供了金钱援助，这有助于减轻眼前的经济负担。"},{"sentence":"Because the project required substantial monetary investment, the board conducted a rigorous cost-benefit analysis.","translation":"因为该项目需要大量资金投入，董事会进行了严格的成本效益分析。"},{"sentence":"International monetary cooperation is crucial for maintaining global financial stability, whereas unilateral actions can trigger currency wars.","translation":"国际货币合作对于维护全球金融稳定至关重要，而单边行动可能引发货币战争。"},{"sentence":"While monetary incentives can boost short-term performance, they often fail to foster long-term employee engagement.","translation":"虽然金钱激励可以提高短期绩效，但它们往往无法培养长期的员工敬业度。"}]},"number":{"examples":[{"sentence":"Although the number of applicants has risen sharply, the selection criteria remain unchanged.","translation":"尽管申请人数急剧增加，但选拔标准保持不变。"},{"sentence":"The number of students who choose to study abroad increases annually, which reflects a growing demand for global education.","translation":"选择出国留学的学生数量每年都在增加，这反映出对全球教育的需求日益增长。"},{"sentence":"Because the number of available parking spaces is limited, employees are encouraged to use public transport.","translation":"由于可用停车位数量有限，鼓励员工使用公共交通。"},{"sentence":"When the number of reported cases exceeds a certain threshold, health authorities must issue a public warning.","translation":"当报告病例数超过一定阈值时，卫生部门必须发布公共警告。"},{"sentence":"The government has invested heavily in digital infrastructure, thereby reducing the number of households without internet access.","translation":"政府大力投资数字基础设施，从而减少了没有互联网接入的家庭数量。"}]},"specific":{"examples":[{"sentence":"Although the general principles are widely accepted, the specific implementation details require further discussion.","translation":"尽管一般原则已被广泛接受，但具体的实施细节仍需进一步讨论。"},{"sentence":"The research team identified a specific protein that plays a crucial role in cell regeneration, which could lead to new treatments.","translation":"研究小组发现了一种在细胞再生中起关键作用的特定蛋白质，这可能会带来新的治疗方法。"},{"sentence":"Because the instructions were not specific enough, many participants misunderstood the task requirements.","translation":"由于指示不够具体，许多参与者误解了任务要求。"},{"sentence":"When applying for the grant, you must outline the specific objectives that your project aims to achieve.","translation":"申请资助时，你必须概述项目旨在实现的具体目标。"},{"sentence":"The new software allows users to filter data according to specific criteria, thereby improving efficiency.","translation":"新软件允许用户根据特定标准筛选数据，从而提高了效率。"}]},"recover":{"examples":[{"sentence":"Although the economy is beginning to recover, many small businesses still face significant challenges.","translation":"尽管经济开始复苏，但许多小企业仍面临重大挑战。"},{"sentence":"The patient was able to recover quickly because she followed the doctor's advice and maintained a positive attitude.","translation":"病人能够迅速康复，因为她遵循了医生的建议并保持积极的态度。"},{"sentence":"If the company fails to recover its investment within five years, the project will be considered a financial loss.","translation":"如果公司未能在五年内收回投资，该项目将被视为财务损失。"},{"sentence":"Efforts to recover the stolen artifacts have intensified, which demonstrates the government's commitment to cultural preservation.","translation":"追回被盗文物的努力已经加强，这表明政府对文化保护的承诺。"},{"sentence":"The forest ecosystem can recover naturally over time, provided that human interference is minimized.","translation":"只要尽量减少人为干扰，森林生态系统可以随着时间的推移自然恢复。"}]},"intuition":{"examples":[{"sentence":"Her intuition told her that the proposal, though superficially attractive, contained hidden risks.","translation":"她的直觉告诉她，这项提议虽然表面上很有吸引力，但隐藏着风险。"},{"sentence":"Experienced teachers often rely on intuition to sense when a student is struggling, even before test results confirm it.","translation":"经验丰富的教师常常依靠直觉来察觉学生何时遇到困难，甚至在考试成绩证实之前就能感觉到。"},{"sentence":"While data analysis is essential for decision-making, intuition can guide researchers toward promising hypotheses that algorithms might overlook.","translation":"虽然数据分析对决策至关重要，但直觉可以引导研究人员找到算法可能忽视的有前景的假设。"},{"sentence":"Because his intuition about market trends had proved accurate in the past, the manager decided to trust his gut feeling once more.","translation":"由于他过去对市场趋势的直觉被证明是准确的，经理决定再次相信自己的直觉。"},{"sentence":"Although intuition can sometimes lead to biased judgments, it remains a valuable cognitive tool when combined with critical reflection.","translation":"尽管直觉有时会导致有偏见的判断，但当与批判性反思相结合时，它仍然是一种宝贵的认知工具。"}]},"acceptance":{"examples":[{"sentence":"Although the theory initially faced skepticism, its gradual acceptance by the scientific community transformed modern physics.","translation":"尽管该理论最初面临质疑，但科学界逐渐接受它，从而改变了现代物理学。"},{"sentence":"Because social acceptance is crucial for mental well-being, schools should implement programs that foster inclusive environments.","translation":"由于社会接纳对心理健康至关重要，学校应实施促进包容性环境的计划。"},{"sentence":"The widespread acceptance of remote work, which accelerated during the pandemic, has reshaped urban economic structures.","translation":"远程工作的广泛接受在疫情期间加速，重塑了城市经济结构。"},{"sentence":"While public acceptance of genetically modified foods remains low in some regions, scientific consensus supports their safety.","translation":"虽然公众对转基因食品的接受度在某些地区仍然很低，但科学共识支持其安全性。"},{"sentence":"Her acceptance of the award, which recognized decades of volunteer service, inspired many to contribute to their communities.","translation":"她接受该奖项，表彰了数十年的志愿服务，激励了许多人为社区做贡献。"}]},"squeeze":{"examples":[{"sentence":"The budget squeeze on public libraries, which resulted from reduced municipal funding, threatens access to educational resources.","translation":"公共图书馆的预算紧缩源于市政资金减少，威胁到教育资源的获取。"},{"sentence":"Because a credit squeeze restricts business expansion, policymakers must balance inflation control with economic growth.","translation":"由于信贷紧缩限制企业扩张，政策制定者必须在控制通胀与经济增长之间取得平衡。"},{"sentence":"Although the profit squeeze in the retail sector is intense, companies that adopt innovative technologies can survive.","translation":"尽管零售业的利润挤压很严重，但采用创新技术的公司能够生存。"},{"sentence":"The time squeeze experienced by working parents, which often leads to burnout, necessitates flexible workplace policies.","translation":"在职父母经历的时间紧张常常导致倦怠，因此需要灵活的工作场所政策。"},{"sentence":"When a liquidity squeeze occurs in financial markets, central banks may intervene to prevent systemic collapse.","translation":"当金融市场发生流动性紧缩时，央行可能会干预以防止系统性崩溃。"}]},"intense":{"examples":[{"sentence":"The intense competition for limited graduate school placements forces applicants to distinguish themselves through research experience.","translation":"研究生院有限名额的激烈竞争迫使申请者通过研究经历来脱颖而出。"},{"sentence":"Because the debate touched on deeply held beliefs, the atmosphere in the lecture hall grew increasingly intense.","translation":"由于辩论触及了根深蒂固的信念，报告厅里的气氛变得越来越紧张。"},{"sentence":"An intense focus on renewable energy is essential if we are to mitigate the effects of climate change.","translation":"如果我们要减轻气候变化的影响，对可再生能源的高度关注是必不可少的。"},{"sentence":"The researcher felt an intense sense of responsibility to ensure that her findings were both accurate and ethically obtained.","translation":"这位研究者感到一种强烈的责任感，要确保她的发现既准确又符合伦理。"},{"sentence":"Despite the intense heat, the volunteers continued to plant trees in the deforested area, demonstrating remarkable dedication.","translation":"尽管酷热难耐，志愿者们仍继续在砍伐区植树，展现了非凡的奉献精神。"}]},"advantage":{"examples":[{"sentence":"One significant advantage of bilingual education is that it enhances cognitive flexibility, which benefits problem-solving skills.","translation":"双语教育的一个显著优势是它能增强认知灵活性，这有益于解决问题的能力。"},{"sentence":"Companies that invest in employee training often gain a competitive advantage by fostering a more skilled and loyal workforce.","translation":"投资于员工培训的公司通常通过培养更熟练和忠诚的员工队伍而获得竞争优势。"},{"sentence":"Although online learning offers the advantage of flexibility, it requires a high degree of self-discipline to be effective.","translation":"尽管在线学习具有灵活性的优势，但它需要高度的自律才能有效。"},{"sentence":"Policymakers should take full advantage of technological innovations to improve public services without compromising privacy.","translation":"政策制定者应充分利用技术创新来改善公共服务，同时不损害隐私。"},{"sentence":"The ability to analyze data critically is an advantage that will serve graduates well in virtually any profession.","translation":"批判性地分析数据的能力是一项优势，几乎在任何职业中都会对毕业生大有裨益。"}]},"dim":{"examples":[{"sentence":"Although the dim lighting in the library created a calm atmosphere, it made reading small print difficult for many students.","translation":"尽管图书馆昏暗的灯光营造了宁静的氛围，但让许多学生难以阅读小字。"},{"sentence":"Because the memory of that distant summer had grown dim over the years, she could only recall fragments of the conversation.","translation":"由于那个遥远夏日的记忆多年来已变得模糊，她只能回忆起对话的片段。"},{"sentence":"The company decided to dim the office lights after hours, thereby reducing energy consumption without affecting daytime productivity.","translation":"公司决定在下班后调暗办公室灯光，从而在不影响白天生产力的情况下减少能源消耗。"},{"sentence":"While the old photograph was dim and faded, it still evoked a strong sense of nostalgia among the family members.","translation":"虽然那张旧照片暗淡褪色，但它仍然在家庭成员中唤起强烈的怀旧之情。"},{"sentence":"If the projector bulb becomes too dim, the audience will struggle to see the presentation, which could undermine the speaker's message.","translation":"如果投影仪灯泡变得太暗，观众将难以看清演示内容，这可能会削弱演讲者的信息传达。"}]},"hook":{"examples":[{"sentence":"Although the advertisement initially seemed dull, its clever slogan served as a hook that captured the attention of millions of viewers.","translation":"尽管这则广告起初显得乏味，但其巧妙的广告语成为了吸引数百万观众注意力的钩子。"},{"sentence":"Because the opening anecdote acted as an effective hook, the audience remained engaged throughout the lengthy presentation.","translation":"由于开场的轶事起到了有效的引子作用，观众在冗长的演讲中始终保持专注。"},{"sentence":"While many novels begin slowly, a strong narrative hook can compel readers to continue turning the pages.","translation":"虽然许多小说开头进展缓慢，但一个强有力的叙事钩子能促使读者继续翻阅。"},{"sentence":"The marketing team designed a free trial as a hook, which allowed potential customers to experience the product before committing to a purchase.","translation":"营销团队设计了免费试用作为诱饵，让潜在客户在决定购买前体验产品。"},{"sentence":"If a research paper lacks a compelling hook in its introduction, it may fail to interest peer reviewers despite its rigorous methodology.","translation":"如果一篇研究论文在引言中缺乏引人入胜的钩子，即使方法严谨，也可能无法引起同行评审的兴趣。"}]},"envelope":{"examples":[{"sentence":"Because the scholarship application required a sealed envelope, the student carefully placed all documents inside before mailing them.","translation":"由于奖学金申请要求使用密封信封，该学生仔细地将所有文件放入信封后才寄出。"},{"sentence":"Although the building envelope was designed to maximize energy efficiency, the architects also ensured it allowed ample natural light.","translation":"尽管建筑围护结构旨在最大限度地提高能效，建筑师也确保其能引入充足的自然光。"},{"sentence":"The invitation arrived in a luxurious envelope, which immediately conveyed the formality of the upcoming gala.","translation":"邀请函装在一个奢华的信封中送达，立刻传达出即将举行的盛会的正式性。"},{"sentence":"When engineers push the aircraft beyond its flight envelope, they risk structural failure that could compromise safety.","translation":"当工程师将飞机推向其飞行包线之外时，他们冒着可能导致安全受损的结构失效风险。"},{"sentence":"In cryptography, the digital envelope ensures that sensitive data remains confidential by encrypting it with a symmetric key.","translation":"在密码学中，数字信封通过使用对称密钥加密敏感数据，确保其机密性。"}]},"specialize":{"examples":[{"sentence":"Because she wanted to contribute to cancer research, she decided to specialize in molecular biology during her doctoral studies.","translation":"因为她想为癌症研究做出贡献，她在博士学习期间决定专攻分子生物学。"},{"sentence":"Although the law firm handles various cases, it tends to specialize in intellectual property disputes that involve technology startups.","translation":"尽管这家律师事务所处理各类案件，但它倾向于专门处理涉及科技初创企业的知识产权纠纷。"},{"sentence":"To ensure accurate diagnoses, the hospital recruited physicians who specialize in rare neurological disorders.","translation":"为确保准确诊断，医院招募了专门研究罕见神经系统疾病的医生。"},{"sentence":"While some universities offer broad curricula, others encourage students to specialize early in fields such as artificial intelligence.","translation":"虽然一些大学提供广泛的课程，但其他大学鼓励学生尽早专攻人工智能等领域。"},{"sentence":"The company chose to specialize in eco-friendly packaging, which not only reduced waste but also attracted environmentally conscious consumers.","translation":"该公司选择专门生产环保包装，这不仅减少了浪费，还吸引了具有环保意识的消费者。"}]},"slight":{"examples":[{"sentence":"A slight increase in interest rates can significantly affect the housing market, which is sensitive to borrowing costs.","translation":"利率的轻微上升可能会对房地产市场产生重大影响，因为该市场对借贷成本很敏感。"},{"sentence":"The researcher found only a slight correlation between the two variables, suggesting that other factors are at play.","translation":"研究人员发现这两个变量之间只有微弱的相关性，这表明还有其他因素在起作用。"},{"sentence":"Despite a slight delay caused by supply chain disruptions, the construction project was completed on schedule.","translation":"尽管供应链中断造成了轻微的延误，但建设项目还是按时完成了。"},{"sentence":"His slight frame concealed a remarkable capacity for endurance, which allowed him to excel in long-distance running.","translation":"他纤细的身躯掩盖了非凡的耐力，这使他在长跑中表现出色。"},{"sentence":"The diplomat took the casual remark as a slight and demanded an apology, rather than letting the matter drop.","translation":"这位外交官把那句随意的评论视为轻蔑并要求道歉，而不是让事情就此过去。"}]},"intrude":{"examples":[{"sentence":"When journalists intrude into private grief, they often cause lasting emotional harm.","translation":"当记者闯入私人悲痛时，他们往往会造成持久的情感伤害。"},{"sentence":"Although the new regulation aims to protect consumers, it may intrude upon individual autonomy.","translation":"尽管新规旨在保护消费者，但它可能侵犯个人自主权。"},{"sentence":"Governments must ensure that surveillance measures do not intrude on citizens' legitimate expectations of privacy.","translation":"政府必须确保监控措施不侵犯公民对隐私的合理期望。"},{"sentence":"Because constant notifications intrude into focused work, many professionals disable them during deep tasks.","translation":"由于持续的通知会干扰专注工作，许多专业人士在进行深度任务时会将其关闭。"},{"sentence":"The court ruled that the company's data collection practices intrude upon fundamental rights.","translation":"法院裁定该公司的数据收集行为侵犯了基本权利。"}]},"literary":{"examples":[{"sentence":"Although literary criticism often focuses on thematic depth, stylistic elegance is equally vital to a work's enduring appeal.","translation":"尽管文学批评通常关注主题深度，但文体优雅对作品的持久吸引力同样至关重要。"},{"sentence":"Because literary awards can significantly boost an author's visibility, publishers invest heavily in promoting nominated titles.","translation":"由于文学奖项能显著提升作者的知名度，出版商大力投资推广提名作品。"},{"sentence":"While some readers prefer literary fiction for its nuanced character development, others are drawn to genre fiction for its plot-driven narratives.","translation":"虽然一些读者偏爱文学小说因其细腻的人物塑造，但另一些读者则被类型小说以情节驱动的叙事所吸引。"},{"sentence":"The literary festival, which attracts renowned authors from around the world, fosters cross-cultural dialogue through panel discussions and readings.","translation":"这个文学节吸引了来自世界各地的知名作家，通过小组讨论和朗读会促进跨文化对话。"},{"sentence":"When a literary work is adapted into a film, the screenplay must capture the essence of the original while making necessary cinematic adjustments.","translation":"当一部文学作品被改编成电影时，剧本必须捕捉原著的精髓，同时做出必要的电影化调整。"}]},"food":{"examples":[{"sentence":"Although fast food is often criticized for its low nutritional value, its affordability makes it a staple for many low-income families.","translation":"尽管快餐常因营养价值低而受到批评，但其可负担性使其成为许多低收入家庭的主食。"},{"sentence":"Because food security is threatened by climate change, governments must invest in resilient agricultural practices to ensure stable supplies.","translation":"由于气候变化威胁到粮食安全，政府必须投资于具有韧性的农业实践以确保稳定供应。"},{"sentence":"While organic food is perceived as healthier, scientific evidence regarding its superior nutrient content remains inconclusive.","translation":"虽然有机食品被认为更健康，但关于其营养含量更高的科学证据仍无定论。"},{"sentence":"The food industry, which is a major contributor to the global economy, faces increasing pressure to adopt sustainable production methods.","translation":"作为全球经济的主要贡献者，食品行业面临着采用可持续生产方式的日益增长的压力。"},{"sentence":"When traditional food cultures are preserved, they not only maintain culinary heritage but also promote biodiversity through the use of local ingredients.","translation":"当传统饮食文化得到保护时，它们不仅维护了烹饪遗产，还通过使用当地食材促进了生物多样性。"}]},"slaughter":{"examples":[{"sentence":"Although international laws prohibit the slaughter of endangered species, illegal poaching continues to threaten biodiversity in many regions.","translation":"尽管国际法律禁止屠杀濒危物种，但非法偷猎仍在许多地区威胁着生物多样性。"},{"sentence":"The documentary revealed that the slaughter of livestock in industrial farms often occurs under inhumane conditions, which has sparked widespread ethical debates.","translation":"这部纪录片揭示，工业化农场中牲畜的屠宰往往发生在不人道的条件下，这引发了广泛的伦理辩论。"},{"sentence":"Because the slaughter of civilians during the conflict was widely condemned, the international community imposed sanctions on the regime responsible.","translation":"由于冲突期间对平民的屠杀受到广泛谴责，国际社会对负有责任的政权实施了制裁。"},{"sentence":"Historians argue that the senseless slaughter of World War I resulted from a failure of diplomacy, rather than from inevitable historical forces.","translation":"历史学家认为，第一次世界大战中无谓的屠杀源于外交的失败，而非不可避免的历史力量。"},{"sentence":"To prevent the slaughter of migratory birds, conservationists have established protected corridors that ensure safe passage during their annual journeys.","translation":"为了防止候鸟被屠杀，环保人士建立了受保护的走廊，以确保它们在年度迁徙中的安全通行。"}]},"lucky":{"examples":[{"sentence":"Although she was lucky to survive the accident, the experience taught her to value every moment of life.","translation":"尽管她幸运地在事故中幸存，但这次经历教会她珍惜生命中的每一刻。"},{"sentence":"Students who are lucky enough to have supportive families often perform better academically, because they receive encouragement and resources at home.","translation":"那些足够幸运拥有支持性家庭的学生往往学业表现更好，因为他们在家中得到了鼓励和资源。"},{"sentence":"While some people attribute success to hard work, others acknowledge that being lucky in seizing opportunities plays a crucial role.","translation":"虽然有些人将成功归因于努力工作，但其他人承认，在抓住机遇方面幸运起着至关重要的作用。"},{"sentence":"The researcher was lucky to discover a rare manuscript in the archives, which provided key evidence for her groundbreaking theory.","translation":"这位研究员幸运地在档案中发现了一份罕见的手稿，这为她的突破性理论提供了关键证据。"},{"sentence":"If you are lucky enough to find a mentor who guides your career, you can avoid many common pitfalls and accelerate your professional growth.","translation":"如果你足够幸运找到一位指导你职业生涯的导师，你就能避免许多常见的陷阱，加速你的职业成长。"}]},"northern":{"examples":[{"sentence":"Because the northern hemisphere experiences more extreme seasonal variations, its ecosystems are particularly vulnerable to climate change.","translation":"由于北半球经历更极端的季节变化，其生态系统特别容易受到气候变化的影响。"},{"sentence":"The northern regions of the country, which are rich in natural resources, have attracted significant investment in mining and energy projects.","translation":"该国北部地区自然资源丰富，吸引了大量对采矿和能源项目的投资。"},{"sentence":"Although the northern lights are a breathtaking spectacle, viewing them requires traveling to remote areas with clear, dark skies.","translation":"尽管北极光是一种令人叹为观止的奇观，但观看它们需要前往拥有清澈黑暗天空的偏远地区。"},{"sentence":"To promote economic development in the northern provinces, the government has implemented tax incentives that encourage businesses to relocate there.","translation":"为促进北方省份的经济发展，政府实施了税收优惠政策，鼓励企业迁往那里。"},{"sentence":"The cultural heritage of the northern tribes, which includes unique crafts and oral traditions, is being preserved through dedicated museum programs.","translation":"北方部落的文化遗产，包括独特的手工艺和口头传统，正通过专门的博物馆项目得到保护。"}]},"whale":{"examples":[{"sentence":"Although the blue whale is the largest animal on Earth, it feeds almost exclusively on tiny krill.","translation":"尽管蓝鲸是地球上最大的动物，但它几乎只以微小的磷虾为食。"},{"sentence":"Because whale songs can travel for hundreds of miles underwater, they are crucial for long-distance communication.","translation":"由于鲸的歌声能在水下传播数百英里，它们对于长距离交流至关重要。"},{"sentence":"The humpback whale, which is known for its acrobatic breaches, attracts thousands of tourists each year.","translation":"座头鲸以其杂技般的跃身击浪而闻名，每年吸引成千上万的游客。"},{"sentence":"While some whale species migrate thousands of miles annually, others remain in the same region throughout the year.","translation":"虽然一些鲸类每年迁徙数千英里，但其他鲸类全年都留在同一区域。"},{"sentence":"If whale populations continue to decline, the balance of marine ecosystems could be severely disrupted.","translation":"如果鲸类种群继续减少，海洋生态系统的平衡可能会被严重破坏。"}]},"counter":{"examples":[{"sentence":"Although the customer waited patiently at the counter, the cashier was busy restocking shelves.","translation":"尽管顾客在柜台前耐心等待，但收银员正忙于补货。"},{"sentence":"The digital counter, which records the number of steps taken, helps users monitor their daily physical activity.","translation":"数字计数器记录行走的步数，帮助用户监测日常身体活动。"},{"sentence":"Because the initial plan faced strong opposition, the team developed a counter proposal to address the concerns.","translation":"由于最初的计划遭到强烈反对，团队制定了一个反提案来解决这些担忧。"},{"sentence":"When the Geiger counter detected elevated radiation levels, the workers immediately evacuated the area.","translation":"当盖革计数器检测到辐射水平升高时，工人们立即撤离了该区域。"},{"sentence":"The government implemented a counter inflation policy, thereby stabilizing the economy and restoring public confidence.","translation":"政府实施了反通货膨胀政策，从而稳定了经济并恢复了公众信心。"}]},"oriental":{"examples":[{"sentence":"Although oriental philosophy emphasizes harmony with nature, its principles are increasingly adopted in Western environmental policies.","translation":"尽管东方哲学强调与自然的和谐，但其原则正越来越多地被西方环境政策所采纳。"},{"sentence":"The oriental art exhibition, which features rare calligraphy and paintings, attracted scholars from around the world.","translation":"这场东方艺术展览展出了罕见的书法和绘画，吸引了来自世界各地的学者。"},{"sentence":"Because oriental medicine focuses on holistic healing, it often complements conventional treatments in modern healthcare.","translation":"由于东方医学注重整体治疗，它常常在现代医疗中补充传统疗法。"},{"sentence":"Oriental architectural designs, which prioritize symmetry and natural light, have influenced contemporary sustainable buildings.","translation":"东方建筑设计注重对称和自然光，已经影响了当代可持续建筑。"},{"sentence":"While oriental cuisines vary greatly across regions, they share a common emphasis on fresh ingredients and balanced flavors.","translation":"虽然东方菜肴在不同地区差异很大，但它们都共同注重新鲜食材和平衡的口味。"}]},"disable":{"examples":[{"sentence":"To ensure network security, administrators must disable unused ports that could be exploited by attackers.","translation":"为了确保网络安全，管理员必须禁用可能被攻击者利用的未使用端口。"},{"sentence":"A severe stroke can disable a person's motor functions, thereby requiring long-term rehabilitation and care.","translation":"严重的中风可能使人丧失运动功能，从而需要长期的康复和护理。"},{"sentence":"Because the software update may disable legacy features, users are advised to back up their data beforehand.","translation":"由于软件更新可能会禁用旧功能，建议用户事先备份数据。"},{"sentence":"The new policy will disable automatic renewal for subscriptions, which gives consumers more control over their expenses.","translation":"新政策将禁用订阅的自动续订，这让消费者对自己的支出有了更多控制。"},{"sentence":"If a virus infects the system, it could disable critical security protocols, leaving sensitive data vulnerable.","translation":"如果病毒感染系统，它可能会禁用关键的安全协议，使敏感数据易受攻击。"}]},"amuse":{"examples":[{"sentence":"Although the lecture was on a serious topic, the professor's humorous examples managed to amuse the entire class.","translation":"尽管讲座主题严肃，但教授幽默的例子成功地逗乐了全班同学。"},{"sentence":"The comedian's ability to amuse audiences stems from his keen observations of everyday life, which he transforms into witty anecdotes.","translation":"这位喜剧演员娱乐观众的能力源于他对日常生活的敏锐观察，并将其转化为诙谐的轶事。"},{"sentence":"Because the children were restless during the long journey, their parents told funny stories to amuse them.","translation":"由于孩子们在长途旅行中焦躁不安，他们的父母讲有趣的故事来逗乐他们。"},{"sentence":"To amuse her colleagues at the office party, she performed a clever magic trick that left everyone guessing.","translation":"为了在办公室聚会上逗乐同事，她表演了一个巧妙的魔术，让所有人都猜不透。"},{"sentence":"While the documentary aimed to educate viewers about marine life, its playful narration also served to amuse a younger audience.","translation":"虽然这部纪录片旨在教育观众了解海洋生物，但其俏皮的叙述也有助于娱乐年轻观众。"}]},"whereas":{"examples":[{"sentence":"Traditional classrooms emphasize rote memorization, whereas progressive educational models prioritize critical thinking and collaborative problem-solving.","translation":"传统课堂强调死记硬背，而进步的教育模式则优先考虑批判性思维和协作解决问题。"},{"sentence":"Public transportation systems in many European cities are highly efficient, whereas those in numerous American suburbs remain heavily dependent on private cars.","translation":"许多欧洲城市的公共交通系统非常高效，而美国众多郊区的公共交通仍然严重依赖私家车。"},{"sentence":"Some scholars argue that economic growth inevitably harms the environment, whereas others contend that technological innovation can decouple prosperity from ecological damage.","translation":"一些学者认为经济增长不可避免地损害环境，而另一些学者则主张技术创新能够使繁荣与生态破坏脱钩。"},{"sentence":"In collectivist cultures, group harmony often takes precedence over individual expression, whereas individualistic societies tend to celebrate personal autonomy and self-assertion.","translation":"在集体主义文化中，群体和谐通常优先于个人表达，而个人主义社会则倾向于颂扬个人自主和自我主张。"},{"sentence":"Renewable energy sources such as solar and wind power are intermittent by nature, whereas fossil fuels provide a stable but environmentally costly supply of energy.","translation":"太阳能和风能等可再生能源本质上是间歇性的，而化石燃料则提供稳定但环境代价高昂的能源供应。"}]},"exciting":{"examples":[{"sentence":"Although the research process can be tedious, the moment of discovery is undeniably exciting for scientists who have dedicated years to a single question.","translation":"尽管研究过程可能枯燥乏味，但对于那些为单一问题奉献多年的科学家来说，发现的那一刻无疑是激动人心的。"},{"sentence":"The prospect of studying abroad is exciting, because it offers students a chance to immerse themselves in a new culture while pursuing academic goals.","translation":"出国留学的前景令人兴奋，因为它为学生提供了在追求学术目标的同时沉浸于新文化的机会。"},{"sentence":"While technological breakthroughs bring exciting possibilities, they also raise ethical concerns that society must address through careful regulation.","translation":"虽然技术突破带来了令人兴奋的可能性，但它们也引发了伦理问题，社会必须通过谨慎的监管来解决。"},{"sentence":"Starting a new business is an exciting venture, which requires not only a solid plan but also the resilience to overcome unforeseen challenges.","translation":"创办新企业是一项激动人心的事业，它不仅需要扎实的计划，还需要克服不可预见挑战的韧性。"},{"sentence":"The rapid evolution of digital media creates exciting opportunities for artists, provided that they adapt their skills to emerging platforms.","translation":"数字媒体的快速发展为艺术家创造了令人兴奋的机会，前提是他们能调整技能以适应新兴平台。"}]},"maintain":{"examples":[{"sentence":"To maintain a healthy ecosystem, governments must enforce strict environmental regulations that limit industrial pollution and protect natural habitats.","translation":"为了维持健康的生态系统，政府必须执行严格的环境法规，以限制工业污染并保护自然栖息地。"},{"sentence":"Although it is difficult to maintain a consistent exercise routine, doing so is crucial for preventing chronic diseases and enhancing overall well-being.","translation":"尽管保持规律的锻炼习惯很困难，但这样做对于预防慢性疾病和提升整体健康至关重要。"},{"sentence":"Effective leaders maintain team morale by recognizing individual contributions, which fosters a sense of belonging and drives collective success.","translation":"有效的领导者通过认可个人贡献来维持团队士气，这能培养归属感并推动集体成功。"},{"sentence":"Historians maintain that primary sources are indispensable for accurate research, because they provide unfiltered insights into past events.","translation":"历史学家坚持认为原始资料对于准确研究不可或缺，因为它们提供了对过去事件未经过滤的洞见。"},{"sentence":"International organizations must maintain neutrality in conflict zones to ensure that humanitarian aid reaches those in need without political interference.","translation":"国际组织必须在冲突地区保持中立，以确保人道主义援助能够不受政治干预地送达需要的人手中。"}]},"similar":{"examples":[{"sentence":"The economic challenges faced by developing nations today are remarkably similar to those that industrialized countries encountered a century ago.","translation":"当今发展中国家面临的经济挑战与一个世纪前工业化国家所遇到的非常相似。"},{"sentence":"Although the two theories originate from different paradigms, they yield strikingly similar predictions under specific conditions.","translation":"尽管这两种理论源于不同的范式，但在特定条件下它们会产生惊人相似的预测。"},{"sentence":"Researchers found that the neural responses to social rejection are similar to those triggered by physical pain.","translation":"研究人员发现，对社会排斥的神经反应与由身体疼痛引发的反应相似。"},{"sentence":"Because the two species occupy similar ecological niches, they have evolved analogous adaptations despite their distant genetic relationship.","translation":"由于这两个物种占据相似的生态位，尽管亲缘关系较远，它们却进化出了类似的适应性。"},{"sentence":"A comparative analysis revealed that the fiscal policies adopted after the crisis were similar across countries with different political systems.","translation":"一项比较分析显示，危机后采取的财政政策在政治体制不同的国家间是相似的。"}]},"fourteen":{"examples":[{"sentence":"The study tracked students from age fourteen to eighteen and found that consistent study habits significantly improved academic outcomes.","translation":"这项研究追踪了学生从十四岁到十八岁的情况，发现持续的学习习惯显著提高了学业成绩。"},{"sentence":"Because she started learning programming at fourteen, she had a solid foundation by the time she entered university.","translation":"因为她从十四岁开始学习编程，所以进入大学时已经有了扎实的基础。"},{"sentence":"The policy requires that all children under fourteen be accompanied by an adult when visiting the museum, which ensures their safety.","translation":"该政策要求所有十四岁以下的儿童参观博物馆时必须有成人陪同，这确保了他们的安全。"},{"sentence":"After fourteen years of dedicated research, the team finally developed a vaccine that could prevent the disease.","translation":"经过十四年的专注研究，该团队终于开发出一种能够预防这种疾病的疫苗。"},{"sentence":"Although the project was originally planned to last fourteen months, unexpected delays extended it by another half year.","translation":"尽管该项目原计划持续十四个月，但意外的延误使其又延长了半年。"}]},"malignant":{"examples":[{"sentence":"Although the initial biopsy suggested a benign growth, subsequent imaging revealed a malignant tumor that required immediate surgical intervention.","translation":"尽管最初的活检提示为良性增生，但随后的影像学检查显示为恶性肿瘤，需要立即进行手术干预。"},{"sentence":"Because malignant rumors can irreparably damage a person's reputation, journalists must verify facts before publishing sensitive stories.","translation":"由于恶意谣言可能对个人声誉造成不可挽回的损害，记者在发表敏感报道前必须核实事实。"},{"sentence":"The oncologist explained that malignant cells often metastasize through the lymphatic system, which makes early detection crucial for effective treatment.","translation":"肿瘤科医生解释说，恶性细胞常通过淋巴系统转移，这使得早期发现对有效治疗至关重要。"},{"sentence":"When a malignant ideology takes root in a community, it can erode social trust and lead to widespread discrimination, thereby undermining public harmony.","translation":"当一种有害的意识形态在社区中扎根时，它会侵蚀社会信任并导致广泛的歧视，从而破坏公共和谐。"},{"sentence":"Despite advances in targeted therapy, treating malignant melanoma remains challenging because the cancer can develop resistance to drugs over time.","translation":"尽管靶向治疗取得了进展，但治疗恶性黑色素瘤仍然具有挑战性，因为癌症会随时间对药物产生耐药性。"}]},"human":{"examples":[{"sentence":"Although human beings possess remarkable cognitive abilities, our decision-making is often influenced by unconscious biases that can lead to errors.","translation":"尽管人类拥有非凡的认知能力，但我们的决策常常受到无意识偏见的影响，这可能导致错误。"},{"sentence":"Because human societies depend on cooperation, the development of language was a pivotal evolutionary step that enabled complex social structures.","translation":"由于人类社会依赖合作，语言的发展是一个关键的进化步骤，它使复杂的社会结构成为可能。"},{"sentence":"The study of human psychology reveals that resilience is not a fixed trait but a skill that can be cultivated through deliberate practice.","translation":"人类心理学研究表明，韧性不是一种固定特质，而是一种可以通过刻意练习培养的技能。"},{"sentence":"While artificial intelligence can process vast amounts of data, it still lacks the nuanced understanding of human emotions that is essential for empathetic communication.","translation":"虽然人工智能可以处理大量数据，但它仍然缺乏对人类情感的细致理解，而这种理解对于共情沟通至关重要。"},{"sentence":"The preservation of cultural heritage is a human responsibility, which ensures that future generations can learn from the achievements and mistakes of the past.","translation":"保护文化遗产是人类的共同责任，这确保了后代能够从过去的成就和错误中学习。"}]},"discern":{"examples":[{"sentence":"Experienced teachers can quickly discern which students need extra support by observing subtle changes in their classroom behavior.","translation":"经验丰富的教师通过观察学生课堂行为的细微变化，能迅速辨别哪些学生需要额外帮助。"},{"sentence":"Although the two research proposals appeared similar at first glance, the review committee was able to discern significant methodological differences upon closer examination.","translation":"尽管这两份研究计划乍看相似，但评审委员会经过仔细审查后，能够辨别出方法上的显著差异。"},{"sentence":"To make informed investment decisions, analysts must discern genuine market trends from short-term fluctuations that are driven by speculation.","translation":"为了做出明智的投资决策，分析师必须从投机驱动的短期波动中辨别出真正的市场趋势。"},{"sentence":"Because the ancient manuscript was badly faded, scholars used multispectral imaging to discern the original text that had been invisible to the naked eye.","translation":"由于这份古代手稿褪色严重，学者们利用多光谱成像来辨别肉眼无法看到的原始文本。"},{"sentence":"Effective leaders discern the underlying concerns of their team members even when those concerns are not explicitly voiced.","translation":"高效的领导者即使团队成员没有明确表达，也能了解他们潜在的担忧。"}]},"plural":{"examples":[{"sentence":"Although the word 'sheep' remains unchanged in its plural form, most English nouns require an added suffix to indicate multiplicity.","translation":"尽管单词'sheep'的复数形式保持不变，但大多数英语名词需要添加后缀来表示复数。"},{"sentence":"Because the data clearly show a plural distribution of values, the researchers rejected the hypothesis of a single underlying cause.","translation":"由于数据清楚地显示出数值的多元分布，研究人员否定了单一根本原因的假设。"},{"sentence":"When a society embraces a plural legal system, it must carefully reconcile customary laws with statutory regulations to ensure justice for all.","translation":"当一个社会采用多元法律体系时，必须谨慎调和习惯法与成文法，以确保所有人的正义。"},{"sentence":"The plural executive model, which divides authority among several independently elected officials, can prevent the concentration of power in a single individual.","translation":"多元行政模式将权力分散给多名独立选举的官员，可以防止权力集中于一人。"},{"sentence":"While singular pronouns refer to one entity, plural pronouns such as 'they' can now be used to refer to a single person whose gender is nonbinary.","translation":"单数代词指代一个实体，而复数代词如'they'现在可用于指代性别非二元的一个个体。"}]},"nail":{"examples":[{"sentence":"Because the carpenter used a galvanized nail rather than a common iron one, the outdoor deck withstood years of rain without rusting.","translation":"因为木匠使用了镀锌钉子而不是普通铁钉，户外平台经受多年雨水而没有生锈。"},{"sentence":"Although she kept her nail polish immaculate, the pianist's short nails allowed her to play rapid passages with precision.","translation":"尽管她的指甲油保持得完美无瑕，但这位钢琴家的短指甲使她能够精准地演奏快速乐段。"},{"sentence":"When the startup lost its lead investor, that setback became the final nail in the coffin for a venture already struggling with cash flow.","translation":"当这家初创公司失去主要投资者时，这一挫折成为本已现金流紧张的企业的最后一根稻草。"},{"sentence":"To hang the heavy painting securely, he hammered a masonry nail into the concrete wall, which provided a much stronger hold than an adhesive hook.","translation":"为了牢固地挂起沉重的画作，他将一颗砖石钉敲入混凝土墙，这比粘钩提供了更强的支撑力。"},{"sentence":"Chronic nail biting, which is medically termed onychophagia, can damage the nail bed and lead to infections that require professional treatment.","translation":"慢性咬指甲在医学上称为咬甲癖，会损伤甲床并导致需要专业治疗的感染。"}]},"plan":{"examples":[{"sentence":"Although the committee approved the plan, several members expressed reservations about its feasibility.","translation":"尽管委员会批准了该计划，但几位成员对其可行性表示了保留意见。"},{"sentence":"The architect presented a detailed plan that incorporated sustainable materials and energy-efficient systems.","translation":"建筑师展示了一份详细的平面图，其中融入了可持续材料和节能系统。"},{"sentence":"Because the contingency plan was activated promptly, the company minimized losses during the supply chain disruption.","translation":"由于应急计划被迅速启动，公司在供应链中断期间将损失降到了最低。"},{"sentence":"A five-year strategic plan, which aligns with national development goals, was unveiled at the annual conference.","translation":"一项与国家发展目标相一致的五年战略计划在年度会议上公布。"},{"sentence":"Without a clear evacuation plan, residents would have faced greater danger when the earthquake struck.","translation":"如果没有明确的疏散方案，当地震来袭时居民将面临更大的危险。"}]},"saint":{"examples":[{"sentence":"Although the saint lived centuries ago, her teachings on compassion remain relevant in modern society.","translation":"尽管这位圣人生活在几个世纪前，但她关于慈悲的教诲在现代社会仍然具有现实意义。"},{"sentence":"The cathedral's stained-glass window depicts the saint performing a miracle that healed the sick.","translation":"大教堂的彩色玻璃窗描绘了这位圣人施行奇迹治愈病人的场景。"},{"sentence":"Because the saint dedicated his life to serving the poor, he became a symbol of selflessness and charity.","translation":"由于这位圣人毕生致力于服务穷人，他成为了无私和慈善的象征。"},{"sentence":"The legend of the saint, which has been passed down through generations, inspires people to act with kindness.","translation":"这位圣人的传说代代相传，激励着人们以善良行事。"},{"sentence":"In the painting, the saint is portrayed with a halo, thereby emphasizing his divine status and purity.","translation":"在这幅画中，圣人被描绘成带有光环，从而强调了他的神圣地位和纯洁。"}]},"hound":{"examples":[{"sentence":"Although the journalist continued to hound the politician with difficult questions, he refused to admit any wrongdoing.","translation":"尽管那位记者不断用尖锐的问题追逼那位政治家，他仍拒绝承认任何不当行为。"},{"sentence":"Unscrupulous debt collectors often hound vulnerable individuals with relentless phone calls, which can cause severe psychological distress.","translation":"不道德的讨债人经常用无休止的电话追逼弱势群体，这会造成严重的心理困扰。"},{"sentence":"If managers constantly hound employees over minor errors, they risk undermining morale and reducing overall productivity.","translation":"如果管理者不断为小错误追逼员工，他们可能会损害士气并降低整体生产力。"},{"sentence":"The hound's exceptional sense of smell enables it to detect substances that even advanced machines cannot identify.","translation":"猎犬非凡的嗅觉使它能够探测到连先进机器都无法识别的物质。"},{"sentence":"A skilled hound can track a fugitive across varied terrain for hours without losing the scent, thereby aiding law enforcement.","translation":"一只训练有素的猎犬可以在多变的地形中追踪逃犯数小时而不丢失气味，从而协助执法。"}]},"system":{"examples":[{"sentence":"Because the education system emphasizes rote memorization, many students lack the critical thinking skills required for advanced research.","translation":"因为教育系统强调死记硬背，许多学生缺乏高级研究所需的批判性思维能力。"},{"sentence":"Although the current healthcare system provides basic coverage, it struggles to meet the demands of an aging population.","translation":"虽然当前的医疗系统提供基本保障，但它难以满足人口老龄化的需求。"},{"sentence":"To enhance efficiency, the company implemented a new inventory management system that automates stock tracking and reduces waste.","translation":"为了提高效率，公司实施了一套新的库存管理系统，该系统可自动跟踪库存并减少浪费。"},{"sentence":"A well-designed public transportation system not only alleviates traffic congestion but also contributes to environmental sustainability.","translation":"一个设计良好的公共交通系统不仅能缓解交通拥堵，还有助于环境可持续性。"},{"sentence":"The legal system must balance the rights of individuals with the need to maintain social order, which often leads to complex ethical debates.","translation":"法律系统必须平衡个人权利与维护社会秩序的需要，这常常引发复杂的伦理辩论。"}]},"terror":{"examples":[{"sentence":"The sudden realization that she had lost her passport filled her with a paralyzing terror that made it difficult to think clearly.","translation":"突然意识到护照丢失，她陷入了一种令人麻痹的恐惧，难以清晰思考。"},{"sentence":"Governments must balance national security with civil liberties when enacting laws to combat terror, as overly broad measures can erode public trust.","translation":"政府在制定反恐法律时，必须在国家安全与公民自由之间取得平衡，因为过于宽泛的措施会侵蚀公众信任。"},{"sentence":"The terror that gripped the community after the earthquake was gradually replaced by a collective determination to rebuild their lives.","translation":"地震后笼罩社区的恐惧逐渐被重建生活的集体决心所取代。"},{"sentence":"Although the film relied on psychological terror rather than graphic violence, it left the audience deeply unsettled for days afterward.","translation":"尽管这部电影依靠心理恐怖而非血腥暴力，但它让观众在之后的日子里深感不安。"},{"sentence":"Historians argue that the Reign of Terror during the French Revolution demonstrates how revolutionary ideals can be corrupted by unchecked power.","translation":"历史学家认为，法国大革命期间的恐怖统治表明，革命理想如何可能因不受制约的权力而腐化。"}]},"comparison":{"examples":[{"sentence":"A detailed comparison of the two investment portfolios shows that the diversified fund carries less risk, although it offers slightly lower returns.","translation":"对两个投资组合的详细比较表明，尽管多元化基金的回报略低，但其风险较小。"},{"sentence":"In comparison with fossil fuels, renewable energy sources provide a sustainable alternative that can reduce carbon emissions over the long term.","translation":"与化石燃料相比，可再生能源提供了一种可持续的替代方案，从长远来看可以减少碳排放。"},{"sentence":"The researcher drew a compelling comparison between the human brain and a computer, noting that both process information through complex networks.","translation":"研究人员将人脑与计算机进行了引人注目的比较，指出两者都通过复杂的网络处理信息。"},{"sentence":"By making a cross-cultural comparison of educational systems, we can identify which practices best promote critical thinking and creativity.","translation":"通过对教育体系进行跨文化比较，我们可以确定哪些做法最能促进批判性思维和创造力。"},{"sentence":"While a quick comparison might suggest that the two policies are similar, a thorough analysis reveals significant differences in their implementation.","translation":"虽然快速比较可能表明这两项政策相似，但深入分析揭示了它们在实施上的显著差异。"}]},"acclaim":{"examples":[{"sentence":"Although the novel initially sold poorly, it eventually earned widespread acclaim for its profound social commentary.","translation":"尽管这部小说最初销量不佳，但它最终因其深刻的社会评论而赢得了广泛赞誉。"},{"sentence":"The scientist's groundbreaking research garnered international acclaim, which led to numerous invitations to speak at global conferences.","translation":"这位科学家的开创性研究获得了国际赞誉，这导致他收到了许多在全球会议上发言的邀请。"},{"sentence":"Because the film addressed a taboo subject with sensitivity, it received critical acclaim from reviewers worldwide.","translation":"因为这部电影敏感地处理了一个禁忌话题，它获得了全球评论家的好评。"},{"sentence":"The chef's innovative fusion cuisine won acclaim, thereby attracting a loyal following of food enthusiasts.","translation":"这位厨师的创新融合菜赢得了赞誉，从而吸引了一群忠实的美食爱好者。"},{"sentence":"While the artist's early works were ignored, her later paintings achieved acclaim for their bold use of color and form.","translation":"虽然这位艺术家的早期作品被忽视，但她后期的画作因其对色彩和形式的大胆运用而获得赞誉。"}]},"transition":{"examples":[{"sentence":"The transition from fossil fuels to renewable energy is essential, because it mitigates the adverse effects of climate change.","translation":"从化石燃料向可再生能源的过渡至关重要，因为它减轻了气候变化的不利影响。"},{"sentence":"A smooth transition to a new software system requires comprehensive training, which ensures that employees can adapt quickly.","translation":"向新软件系统的平稳过渡需要全面的培训，这确保员工能够快速适应。"},{"sentence":"Although the transition to democracy was fraught with challenges, the country ultimately established a stable political system.","translation":"尽管向民主的过渡充满了挑战，该国最终建立了稳定的政治制度。"},{"sentence":"The company managed the transition to remote work effectively, thereby maintaining productivity during the pandemic.","translation":"该公司有效地管理了向远程工作的过渡，从而在大流行期间保持了生产力。"},{"sentence":"When a caterpillar undergoes its transition into a butterfly, it exemplifies a remarkable biological transformation.","translation":"当毛毛虫经历向蝴蝶的转变时，它展示了一个非凡的生物转化。"}]},"radiant":{"examples":[{"sentence":"The bride looked radiant in her white gown, which was adorned with delicate lace and pearls.","translation":"新娘穿着白色礼服显得容光焕发，礼服上装饰着精致的蕾丝和珍珠。"},{"sentence":"Because the sun emits radiant energy, it drives the Earth's weather systems and supports all life.","translation":"因为太阳发出辐射能，它驱动着地球的天气系统并支持所有生命。"},{"sentence":"Despite the overcast sky, her radiant smile brightened the entire room and lifted everyone's spirits.","translation":"尽管天空阴沉，她灿烂的笑容照亮了整个房间，提振了每个人的精神。"},{"sentence":"The radiant heat from the fireplace created a cozy atmosphere, which made the cabin feel like a true winter retreat.","translation":"壁炉的辐射热营造出舒适的氛围，使小屋感觉像一个真正的冬季度假胜地。"},{"sentence":"While the flowers in the garden were beautiful, the radiant colors of the sunset over the hills were truly breathtaking.","translation":"虽然花园里的花很美，但山丘上日落的绚丽色彩确实令人叹为观止。"}]},"reason":{"examples":[{"sentence":"Although the initial results were promising, the primary reason for discontinuing the trial was an unexpected rise in adverse events.","translation":"尽管初步结果令人鼓舞，但终止试验的主要原因是意外不良事件的增加。"},{"sentence":"Because the reason for the discrepancy was not immediately apparent, the team conducted a thorough review of the experimental protocol.","translation":"由于差异的原因并不明显，团队对实验方案进行了彻底审查。"},{"sentence":"The reason that renewable energy adoption lags in some regions, despite its environmental benefits, is often the high initial infrastructure cost.","translation":"尽管可再生能源具有环境效益，但在一些地区采用滞后的原因往往是高昂的初始基础设施成本。"},{"sentence":"When evaluating a candidate, employers should consider not only their technical skills but also the reason they are drawn to the organization's mission.","translation":"在评估候选人时，雇主不仅应考虑其技术技能，还应考虑他们被组织使命吸引的原因。"},{"sentence":"A compelling reason to invest in early childhood education is that it yields long-term societal benefits, which include reduced crime rates and higher productivity.","translation":"投资早期儿童教育的一个令人信服的理由是它能带来长期的社会效益，其中包括降低犯罪率和提高生产力。"}]},"unfortunately":{"examples":[{"sentence":"Unfortunately, the policy that was designed to reduce inequality has inadvertently widened the gap, because it failed to account for regional disparities.","translation":"不幸的是，旨在减少不平等的政策无意中扩大了差距，因为它未能考虑到地区差异。"},{"sentence":"Although the research team worked diligently, unfortunately, the data set was compromised by a technical glitch, which rendered years of work unusable.","translation":"尽管研究团队勤奋工作，但不幸的是，数据集因技术故障受损，导致多年的工作无法使用。"},{"sentence":"Unfortunately, the lack of standardized protocols in the field means that results from different studies are often incomparable, thereby hindering meta-analysis.","translation":"不幸的是，该领域缺乏标准化协议意味着不同研究的结果往往无法比较，从而阻碍了荟萃分析。"},{"sentence":"When funding is cut, unfortunately, the first programs to suffer are those that serve the most vulnerable populations, which exacerbates social inequities.","translation":"当资金被削减时，不幸的是，首先受损的是那些服务于最弱势群体的项目，这加剧了社会不平等。"},{"sentence":"Unfortunately, despite the clear scientific consensus on climate change, political will to implement necessary measures remains insufficient, which delays critical action.","translation":"不幸的是，尽管在气候变化上科学共识明确，但实施必要措施的政治意愿仍然不足，这拖延了关键行动。"}]},"programme":{"examples":[{"sentence":"Although the programme was initially underfunded, it eventually achieved remarkable results through community support.","translation":"尽管该计划最初资金不足，但通过社区支持，最终取得了显著成果。"},{"sentence":"The university launched a scholarship programme that targets students from disadvantaged backgrounds.","translation":"大学启动了一项针对贫困背景学生的奖学金计划。"},{"sentence":"Because the training programme incorporated hands-on workshops, participants gained practical skills more effectively.","translation":"由于培训计划包含了实践工作坊，参与者更有效地获得了实用技能。"},{"sentence":"The government's new housing programme, which prioritizes low-income families, has significantly reduced homelessness.","translation":"政府的新住房计划优先考虑低收入家庭，显著减少了无家可归现象。"},{"sentence":"Researchers developed an intervention programme to improve literacy, thereby enhancing overall academic performance.","translation":"研究人员制定了一项干预计划以提高读写能力，从而提升了整体学业表现。"}]},"leaf":{"examples":[{"sentence":"Although a single leaf may appear fragile, its intricate vein network efficiently transports water and nutrients.","translation":"尽管一片叶子看似脆弱，但其复杂的叶脉网络能高效地输送水分和养分。"},{"sentence":"When the botanist pressed the rare leaf between sheets of absorbent paper, she preserved its delicate structure for future study.","translation":"当植物学家将那片稀有叶子压在吸水纸之间时，她保存了其精细结构以供未来研究。"},{"sentence":"Because the ancient manuscript's pages were made of vellum rather than paper, each leaf required careful handling to avoid tearing.","translation":"由于古代手稿的书页由羊皮纸而非普通纸制成，每一页都需要小心处理以免撕裂。"},{"sentence":"The caterpillar consumed the entire leaf, thereby depriving the plant of a vital source of energy.","translation":"毛毛虫吃掉了整片叶子，从而剥夺了植物重要的能量来源。"},{"sentence":"If you turn over a new leaf and adopt healthier habits, you will likely see improvements in your overall well-being.","translation":"如果你翻开新的一页，养成更健康的习惯，你很可能会看到整体健康状况的改善。"}]},"quantify":{"examples":[{"sentence":"Although it is difficult to quantify the long-term benefits of education, economists have developed models that estimate its impact on GDP.","translation":"尽管量化教育的长期收益很困难，但经济学家已经开发出模型来估算其对GDP的影响。"},{"sentence":"To ensure accurate resource allocation, the project manager must quantify the risks associated with each phase of development.","translation":"为了确保资源分配准确，项目经理必须量化每个开发阶段的相关风险。"},{"sentence":"Because the survey used a Likert scale, researchers could quantify participants' attitudes toward climate change policies.","translation":"由于调查采用了李克特量表，研究人员能够量化参与者对气候变化政策的态度。"},{"sentence":"The new software can quantify customer engagement by tracking metrics such as click-through rates and time spent on page.","translation":"新软件可以通过追踪点击率和页面停留时间等指标来量化客户参与度。"},{"sentence":"While we can quantify the financial costs of pollution, the loss of biodiversity remains largely immeasurable.","translation":"虽然我们可以量化污染的财务成本，但生物多样性的丧失在很大程度上仍然无法衡量。"}]},"cite":{"examples":[{"sentence":"When writing a literature review, you must cite seminal works that have shaped the current understanding of the topic.","translation":"在撰写文献综述时，你必须引用那些塑造了当前对该主题理解的奠基性著作。"},{"sentence":"The lawyer chose to cite a precedent from a similar case, which strengthened her argument before the jury.","translation":"律师选择引用一个类似案件的先例，这加强了她在陪审团面前的论点。"},{"sentence":"Although the journalist failed to cite her sources, the editor insisted on verifying the facts before publication.","translation":"尽管记者没有注明她的信息来源，但编辑坚持在发表前核实事实。"},{"sentence":"To support his theory, the scientist will cite data from multiple experiments that demonstrate consistent results.","translation":"为了支持他的理论，科学家将引用多个实验的数据，这些数据显示出一致的结果。"},{"sentence":"The professor warned that students who do not cite their references properly may face accusations of academic dishonesty.","translation":"教授警告说，不恰当引用参考文献的学生可能会面临学术不端的指控。"}]},"compass":{"examples":[{"sentence":"Although the compass was invented centuries ago, it remains a fundamental tool for outdoor navigation.","translation":"尽管指南针是几个世纪前发明的，但它仍然是户外导航的基本工具。"},{"sentence":"Because the compass needle aligns with the Earth's magnetic field, it reliably indicates the north-south direction.","translation":"因为指南针的指针与地球磁场对齐，所以它能可靠地指示南北方向。"},{"sentence":"The project fell within the compass of the committee's responsibilities, which included environmental oversight.","translation":"该项目属于委员会的职责范围，其中包括环境监督。"},{"sentence":"A strong moral compass is essential for leaders, as it guides them through complex ethical dilemmas.","translation":"坚定的道德指南针对领导者至关重要，因为它能引导他们度过复杂的道德困境。"},{"sentence":"While the compass is simple in design, its impact on exploration and trade was profound.","translation":"虽然指南针设计简单，但它对探险和贸易的影响却是深远的。"}]},"symptom":{"examples":[{"sentence":"Although a fever is a common symptom of infection, it can also indicate other underlying conditions.","translation":"虽然发烧是感染的常见症状，但它也可能表明其他潜在疾病。"},{"sentence":"Because chronic fatigue is a symptom of many illnesses, doctors must conduct thorough examinations to identify the cause.","translation":"由于慢性疲劳是许多疾病的症状，医生必须进行全面检查以确定病因。"},{"sentence":"When a patient reports chest pain, which is a classic symptom of heart disease, immediate medical intervention is crucial.","translation":"当患者报告胸痛这一心脏病的典型症状时，立即进行医疗干预至关重要。"},{"sentence":"Rising unemployment is often a symptom of economic recession, thereby prompting governments to implement stimulus policies.","translation":"失业率上升往往是经济衰退的征兆，从而促使政府实施刺激政策。"},{"sentence":"If a persistent cough is the only symptom, it may not be serious, but it still warrants a medical consultation.","translation":"如果持续咳嗽是唯一的症状，可能并不严重，但仍需就医咨询。"}]},"sensation":{"examples":[{"sentence":"The new virtual reality game created a global sensation, because it offered an unprecedented immersive experience.","translation":"这款新的虚拟现实游戏引起了全球轰动，因为它提供了前所未有的沉浸式体验。"},{"sentence":"Although the artist's work caused a sensation at first, critics later dismissed it as lacking depth.","translation":"尽管这位艺术家的作品最初引起了轰动，但评论家后来认为它缺乏深度。"},{"sentence":"When the athlete broke the world record, the stadium erupted in a sensation of joy and disbelief.","translation":"当运动员打破世界纪录时，体育场爆发出一种喜悦和难以置信的轰动。"},{"sentence":"A tingling sensation in the limbs can be a warning sign of nerve damage, which requires prompt medical attention.","translation":"四肢的刺痛感可能是神经损伤的警示信号，需要及时就医。"},{"sentence":"The sudden sensation of falling while asleep, known as a hypnic jerk, is a common and harmless phenomenon.","translation":"入睡时突然的坠落感，即入睡抽动，是一种常见且无害的现象。"}]},"eternal":{"examples":[{"sentence":"The pursuit of knowledge is an eternal endeavor that drives human progress across generations.","translation":"对知识的追求是一项永恒的事业，推动着人类一代又一代的进步。"},{"sentence":"While technological tools evolve rapidly, the eternal principles of logic and critical thinking remain indispensable in education.","translation":"虽然技术工具迅速发展，但逻辑和批判性思维的永恒原则在教育中仍然不可或缺。"},{"sentence":"The philosopher argued that art offers a glimpse into eternal truths that transcend the limitations of our daily existence.","translation":"这位哲学家认为，艺术让我们得以一窥超越日常生活局限的永恒真理。"},{"sentence":"Environmental degradation poses an eternal challenge that requires sustained cooperation among nations to safeguard the planet for future generations.","translation":"环境退化构成了一个永恒的挑战，需要各国持续合作，为子孙后代保护地球。"},{"sentence":"Despite the transient nature of fame, the scientist's contributions have earned her an eternal place in the history of medicine.","translation":"尽管名声转瞬即逝，但这位科学家的贡献为她在医学史上赢得了永恒的地位。"}]},"dynamic":{"examples":[{"sentence":"Although the economy is dynamic, policymakers must anticipate shifts to ensure stable growth.","translation":"尽管经济是动态的，政策制定者必须预见变化以确保稳定增长。"},{"sentence":"A dynamic leader inspires teams through adaptability, which is crucial in times of rapid change.","translation":"一位有活力的领导者通过适应能力激励团队，这在快速变化的时期至关重要。"},{"sentence":"Because ecosystems are dynamic, conservation strategies require continuous monitoring to remain effective.","translation":"由于生态系统是动态的，保护策略需要持续监测才能保持有效。"},{"sentence":"The dynamic nature of technology demands that professionals engage in lifelong learning to stay relevant.","translation":"技术的动态本质要求专业人士进行终身学习以保持相关性。"},{"sentence":"While some prefer stability, a dynamic work environment fosters innovation and personal growth.","translation":"虽然有些人更喜欢稳定，但动态的工作环境能促进创新和个人成长。"}]},"forest":{"examples":[{"sentence":"Although the forest appears tranquil, it is actually a complex ecosystem where countless species interact.","translation":"尽管森林看似宁静，它实际上是一个无数物种相互作用的复杂生态系统。"},{"sentence":"Because the forest absorbs vast amounts of carbon dioxide, its preservation is vital for mitigating climate change.","translation":"由于森林吸收大量二氧化碳，保护森林对于缓解气候变化至关重要。"},{"sentence":"The government implemented strict regulations to protect the forest, which had been severely damaged by illegal logging.","translation":"政府实施了严格的法规来保护这片因非法砍伐而严重受损的森林。"},{"sentence":"While the forest provides essential resources such as timber and medicine, overexploitation threatens its long-term survival.","translation":"虽然森林提供了木材和药材等基本资源，但过度开发威胁着它的长期存续。"},{"sentence":"To ensure the forest remains a carbon sink, many countries have launched ambitious reforestation projects.","translation":"为了确保森林继续作为碳汇，许多国家启动了雄心勃勃的重新造林项目。"}]},"belt":{"examples":[{"sentence":"Although the conveyor belt is essential for efficient packaging, it requires regular maintenance to prevent unexpected breakdowns.","translation":"尽管传送带对于高效包装至关重要，但它需要定期维护以防止意外故障。"},{"sentence":"Because the asteroid belt contains numerous rocky fragments, spacecraft must navigate carefully to avoid collisions.","translation":"由于小行星带包含大量岩石碎片，航天器必须小心导航以避免碰撞。"},{"sentence":"The government plans to develop a green belt around the city, which will help reduce pollution and provide recreational space.","translation":"政府计划在城市周围开发绿化带，这将有助于减少污染并提供休闲空间。"},{"sentence":"While the rust belt faces economic decline, investment in technology and education can revitalize its manufacturing sector.","translation":"尽管铁锈地带面临经济衰退，但对技术和教育的投资可以重振其制造业。"},{"sentence":"To ensure safety, all passengers must fasten their seat belt before the vehicle starts moving.","translation":"为确保安全，所有乘客必须在车辆启动前系好安全带。"}]},"feed":{"examples":[{"sentence":"Because the feed contained essential nutrients, the livestock grew faster and remained healthier throughout the season.","translation":"由于饲料含有必需营养素，牲畜在整个季节生长更快且保持更健康。"},{"sentence":"Although the organic feed was more expensive, it improved the quality of the dairy products and attracted health-conscious consumers.","translation":"尽管有机饲料更贵，但它提高了乳制品的质量，并吸引了注重健康的消费者。"},{"sentence":"The farm switched to a feed that includes insect protein, which is a sustainable alternative to traditional soy-based feed.","translation":"该农场改用含有昆虫蛋白的饲料，这是传统大豆饲料的可持续替代品。"},{"sentence":"To ensure food safety, the company tests every batch of animal feed for contaminants before distribution.","translation":"为确保食品安全，该公司在分发前检测每批动物饲料的污染物。"},{"sentence":"While the feed additive promoted growth, its overuse led to antibiotic resistance, prompting stricter regulations.","translation":"尽管饲料添加剂促进了生长，但其过度使用导致了抗生素耐药性，从而促使更严格的监管。"}]},"bloom":{"examples":[{"sentence":"Although the garden is meticulously maintained, the roses only reach full bloom when the soil is enriched with organic compost.","translation":"尽管花园被精心维护，但玫瑰只有在土壤富含有机堆肥时才会完全盛开。"},{"sentence":"Because the cherry blossoms bloom for just a few days each spring, tourists flock to the park to witness their fleeting beauty.","translation":"因为樱花每年春天只开放几天，游客们涌向公园去目睹它们转瞬即逝的美丽。"},{"sentence":"The desert landscape transforms dramatically when the cacti bloom after a rare rainfall, attracting pollinators from miles away.","translation":"当仙人掌在罕见的降雨后开花时，沙漠景观发生巨大变化，吸引了数英里外的传粉者。"},{"sentence":"Her artistic talent began to bloom after she enrolled in a mentorship program that provided constructive feedback and encouragement.","translation":"在她参加了一个提供建设性反馈和鼓励的导师计划后，她的艺术天赋开始绽放。"},{"sentence":"In high-altitude regions, alpine flowers bloom later in the summer due to the prolonged snow cover that delays the growing season.","translation":"在高海拔地区，由于积雪覆盖延长了生长季节，高山花卉在夏季较晚时开放。"}]},"mess":{"examples":[{"sentence":"The sudden resignation of the CEO left the company in a financial mess that took years to resolve.","translation":"首席执行官的突然辞职使公司陷入财务混乱，花了多年时间才解决。"},{"sentence":"If we do not reform the outdated bureaucratic procedures, the entire administrative system will become an unmanageable mess.","translation":"如果我们不改革过时的官僚程序，整个行政系统将变得无法收拾的混乱。"},{"sentence":"Although the project started with clear objectives, poor communication among team members turned it into a complete mess.","translation":"尽管项目开始时目标明确，但团队成员之间的沟通不畅使其变得一团糟。"},{"sentence":"The kitchen was in such a mess after the party that it required several hours of cleaning to restore order.","translation":"聚会后厨房一片狼藉，需要几个小时的清洁才能恢复秩序。"},{"sentence":"Leaving environmental problems for future generations to handle will only create a bigger mess that is harder to clean up.","translation":"把环境问题留给后代处理只会造成更大的烂摊子，更难收拾。"}]},"aspire":{"examples":[{"sentence":"Although many students aspire to study abroad, they must first overcome language barriers and financial constraints.","translation":"尽管许多学生渴望出国留学，但他们必须首先克服语言障碍和经济限制。"},{"sentence":"Because young professionals often aspire to leadership positions, they actively seek mentorship and skill-building opportunities.","translation":"因为年轻的专业人士常常渴望担任领导职务，他们积极寻求指导和技能提升的机会。"},{"sentence":"While not everyone can become a renowned artist, we can all aspire to express ourselves creatively in daily life.","translation":"虽然不是每个人都能成为著名艺术家，但我们都可以渴望在日常生活中创造性地表达自己。"},{"sentence":"A society that encourages its citizens to aspire to lifelong learning is better equipped to handle rapid technological changes.","translation":"一个鼓励公民渴望终身学习的社会，能更好地应对快速的技术变革。"},{"sentence":"When individuals aspire to make a positive impact, they often volunteer for community service projects that address local needs.","translation":"当个人渴望产生积极影响时，他们常常参加满足当地需求的社区服务项目。"}]}}};
